-- ==========================================================================
__UAI_MODULES["agent/loop"] = (function()
-- The turn loop.
--
-- Send the conversation, run whatever tools come back, repeat until the model
-- answers in prose or a limit stops it. Everything around that -- provider
-- failover, compaction, repeat detection, usage, the event stream -- is here
-- because it all has to interleave with the same loop, and splitting it would
-- mean threading state through five modules to achieve the same thing.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local prompt = env.require("agent/prompt")
	local registry = env.require("agent/registry")
	local usage = env.require("agent/usage")
	local hooks = env.require("agent/hooks")
	local providers = env.require("provider/registry")
	local chat = env.require("provider/chat")

	local M = {}

	local function callSignature(calls)
		local parts = {}
		for _, call in ipairs(calls or {}) do
			local fn = call["function"] or {}
			parts[#parts + 1] = tostring(fn.name) .. "(" .. tostring(fn.arguments) .. ")"
		end
		table.sort(parts)
		return table.concat(parts, "|")
	end

	-- One completion, walking the provider chain. Returns result, error, record.
	--
	-- A provider that fails is demoted by the registry and the next one is tried,
	-- so a rate-limited primary does not end the turn. Only when every candidate
	-- has failed does the turn fail, and the message names the first failure --
	-- which is almost always the informative one.
	local function complete(session, request)
		local chain = providers.chain()
		if #chain == 0 then
			return nil, "No provider is configured. Open the Providers panel and add one."
		end

		local firstError
		for index, record in ipairs(chain) do
			if session.aborted() then return nil, "aborted" end
			if index > 1 then
				session.emit("provider:switch", {
					from = chain[index - 1].label,
					to = record.label,
					reason = firstError,
				})
			end

			local payload = { record = record, request = request, session = session }
			hooks.run("preRequest", payload)

			session.emit("request:start", {
				provider = record.label,
				providerId = record.id,
				model = record.model,
				attempt = index,
				messages = #request.messages,
				stream = request.stream,
			})

			local started = clock.ms()
			local result, err = chat.complete(record, {
				messages = payload.request.messages,
				tools = payload.request.tools,
				toolChoice = payload.request.toolChoice,
				stream = payload.request.stream,
				temperature = payload.request.temperature,
				maxTokens = payload.request.maxTokens,
				extra = payload.request.extra,
				aborted = session.aborted,
				onRetry = function(info)
					session.emit("request:retry", {
						provider = record.label,
						attempt = info.attempt,
						attempts = info.attempts,
						wait = info.wait,
						status = info.status,
						reason = info.reason,
					})
				end,
				onFrame = request.onFrame,
			})

			if result then
				session.emit("request:done", {
					provider = record.label,
					model = result.model or record.model,
					ms = clock.since(started),
					streamed = result.streamed,
					via = result.via,
				})
				local after = { result = result, record = record, session = session }
				hooks.run("postResponse", after)
				return after.result, nil, record
			end

			firstError = firstError or err
			session.emit("request:done", {
				provider = record.label,
				model = record.model,
				ms = clock.since(started),
				error = err,
			})
			if err == "aborted" then return nil, "aborted" end
		end

		return nil, firstError or "every provider failed"
	end

	-- Compaction uses whatever provider is healthy, with no tools and a tight
	-- ceiling: it is a cheap call whose only job is to keep the transcript
	-- affordable. If it fails, the context still trims -- it just loses the note.
	local function summariser(session)
		return function(transcript)
			local record = providers.active()
			if not record then return nil end
			local result = chat.complete(record, {
				messages = {
					{ role = "system", content = prompt.compaction() },
					{ role = "user", content = transcript },
				},
				temperature = 0,
				maxTokens = 400,
				attempts = 1,
				aborted = session.aborted,
			})
			return result and result.content or nil
		end
	end

	-- Runs one user prompt to completion. Returns the assistant's final text.
	function M.run(session, text)
		local ctx = session.ctx
		local maxTurns = session.maxTurns or config.get("agent.maxTurns", 24)
		local repeatLimit = config.get("agent.repeatLimit", 3)

		-- Unlimited tool calling. Two switches reach this and they are deliberately
		-- separate.
		--
		-- `agent.unlimitedTurns` is for the conversation the user is watching, so a
		-- session carrying its own step budget -- every subagent -- ignores it.
		-- `session.unlimited` is set by whoever created the session, which is how the
		-- dispatcher passes on `agent.subagentUnlimited`: a delegated child is lifted
		-- only when someone has asked for that in those words, because a child is the
		-- one session with nobody's attention on it.
		local unlimited = session.unlimited == true
			or (session.maxTurns == nil and config.get("agent.unlimitedTurns", false) == true)

		-- The wall-clock bound goes with the step limit rather than outliving it. A
		-- fifteen-minute ceiling left standing behind a switch labelled unlimited
		-- stops the same long job at roughly twice the step count and calls it running
		-- out of time -- the same wall wearing a different sign.
		local deadline = nil
		if not unlimited then
			deadline = clock.ms() + (session.budgetSeconds or 900) * 1000
		end

		-- Turn totals belong to the turn the user started. A subagent runs this same
		-- loop, so without this guard every dispatch reset the counter the interface is
		-- showing, and a batch of them reset it repeatedly, mid-turn, to whatever the
		-- last child happened to have spent.
		if not session.headless then usage.startTurn() end
		ctx.pushUser(text)
		session.emit("turn:start", { turns = unlimited and 0 or maxTurns, unlimited = unlimited })

		local lastSignature, streak = "", 0
		local finalText = nil
		local turn = 0

		while unlimited or turn < maxTurns do
			turn = turn + 1
			if session.aborted() then
				session.emit("abort", {})
				return "Stopped."
			end
			if deadline and clock.ms() > deadline then
				session.emit("error", { message = "This turn ran out of time.", fatal = false })
				return "I ran out of time on this turn. Ask me to continue if you want me to keep going."
			end

			session.emit("status", { text = turn == 1 and "Thinking" or ("Working (step " .. turn .. ")") })

			local before = ctx.tokens()
			local summary = ctx.compact(summariser(session), { tokenLimit = config.get("agent.contextTokens", 24000) })
			if summary then
				session.emit("compact", { summary = summary, before = before, after = ctx.tokens() })
			end

			local record = providers.active()
			-- A session may carry its own brief. A subagent does: it answers to the
			-- parent agent rather than to the user, so inheriting the main prompt
			-- would have it write a chat reply instead of a report.
			local systemText
			if type(session.systemPrompt) == "function" then
				systemText = session.systemPrompt()
			elseif type(session.systemPrompt) == "string" and util.trim(session.systemPrompt) ~= "" then
				systemText = session.systemPrompt
			else
				systemText = prompt.build({
					model = record and record.model or nil,
					provider = record and record.label or nil,
					-- Which conversation this is for. The task list rides on the session,
					-- so a prompt built without it is built without the plan.
					session = session,
				})
			end

			local request = {
				messages = ctx.wire(systemText),
				tools = registry.definitions({ only = session.toolFilter, groups = session.toolGroups }),
				stream = session.stream,
				onFrame = session.onFrame,
			}

			local result, err = complete(session, request)

			if not result then
				if err == "aborted" then
					session.emit("abort", {})
					return "Stopped."
				end
				session.emit("error", { message = err, fatal = true })
				return "I could not reach a provider. " .. tostring(err)
			end

			usage.record(result.usage, result.model or (record and record.model), {
				prompt = usage.estimateMessages(request.messages),
				completion = usage.estimateText(result.content) + usage.estimateText(result.reasoning),
			})
			session.emit("usage", { session = usage.session, turn = usage.turn })

			if util.trim(result.reasoning) ~= "" then
				session.emit("assistant:reasoning", { text = result.reasoning })
			end
			if util.trim(result.content) ~= "" then
				session.emit("assistant:text", { text = result.content, final = #result.toolCalls == 0 })
			end

			ctx.pushAssistant(result)

			if #result.toolCalls == 0 then
				finalText = result.content
				if result.finish == "length" then
					finalText = finalText .. "\n\n[the reply was cut off by the token limit]"
				elseif result.finish == "content_filter" then
					finalText = (util.trim(finalText) ~= "" and finalText or "") ..
						"\n\n[the provider filtered part of this reply]"
				end
				break
			end

			-- Identical batches mean the model is stuck. Rather than let it burn the
			-- turn budget, the results are replaced with a refusal that names the
			-- problem, which is enough for most models to change tack.
			local signature = callSignature(result.toolCalls)
			if signature == lastSignature then
				streak = streak + 1
			else
				lastSignature, streak = signature, 1
			end

			if streak >= repeatLimit then
				for _, call in ipairs(result.toolCalls) do
					local name = (call["function"] or {}).name or "tool"
					ctx.pushToolResult(call.id, name,
						"This exact call has already been made " .. tostring(streak) ..
						" times with the same arguments. It will not be run again. Change the approach, or answer with what you already know.")
				end
				session.emit("status", { text = "Breaking a repeat loop" })
				log.warn("loop", "repeat limit hit on " .. util.ellipsis(signature, 120))
			else
				for _, call in ipairs(result.toolCalls) do
					local fn = call["function"] or {}
					local tool = registry.get(fn.name)
					session.emit("tool:call", {
						id = call.id,
						name = fn.name,
						group = tool and tool.group or nil,
						risk = tool and tool.risk or "write",
						arguments = fn.arguments,
					})
				end

				session.emit("status", { text = #result.toolCalls == 1
					and ("Running " .. ((result.toolCalls[1]["function"] or {}).name or "tool"))
					or ("Running " .. util.pluralise(#result.toolCalls, "tool")) })

				local results = registry.runAll(result.toolCalls, session.toolContext())

				for index, call in ipairs(result.toolCalls) do
					local outcome = results[index] or {
						id = call.id,
						name = (call["function"] or {}).name or "tool",
						ok = false,
						text = "The tool produced no result.",
					}
					ctx.pushToolResult(call.id, outcome.name, outcome.text)
					if outcome.ok then
						session.emit("tool:result", outcome)
					else
						session.emit("tool:error", outcome)
					end
				end
			end
		end

		if finalText == nil then
			session.emit("error", {
				message = "Reached the step limit of " .. tostring(maxTurns) .. ".",
				fatal = false,
			})
			finalText = "I reached this session's step limit before finishing. Tell me to continue and I will pick up where I stopped."
		end

		session.emit("turn:end", { text = finalText })
		session.emit("status", { text = "Ready" })
		return finalText
	end

	return M
end
end)()

-- ==========================================================================
-- agent/permissions
-- ==========================================================================
__UAI_MODULES["agent/permissions"] = (function()
-- Permission engine.
--
-- The tools here can rewrite a game, run arbitrary code and delete files, so the
-- default is to ask. The interesting part is the asking: the loop runs on its own
-- thread and the answer comes from the interface, so a request yields until the
-- user decides, with a deadline so an unattended session cannot hang forever.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")

	local ASK_TIMEOUT = 180

	local M = {
		pending = {},
		changed = signal.new("permissions"),
	}

	-- mode -> what each risk level resolves to before rules are consulted.
	local MATRIX = {
		readonly = { read = "allow", write = "deny", danger = "deny" },
		ask = { read = "allow", write = "ask", danger = "ask" },
		auto = { read = "allow", write = "allow", danger = "ask" },
		full = { read = "allow", write = "allow", danger = "allow" },
	}

	M.MODES = { "readonly", "ask", "auto", "full" }

	M.MODE_LABELS = {
		readonly = "Read only",
		ask = "Ask first",
		auto = "Auto (ask for dangerous)",
		full = "Allow everything",
	}

	M.MODE_HINTS = {
		readonly = "Inspection only. Nothing is changed, executed or written.",
		ask = "Reads run freely. Anything that changes the game waits for you.",
		auto = "Reads and writes run freely. Code execution and deletion still ask.",
		full = "No prompts at all. Only sensible when you trust the provider.",
	}

	function M.mode()
		local value = config.get("permissions.mode", "ask")
		return MATRIX[value] and value or "ask"
	end

	function M.setMode(mode)
		if not MATRIX[mode] then return false end
		config.set("permissions.mode", mode)
		M.changed:fire("mode", mode)
		return true
	end

	local function rules()
		local stored = config.get("permissions.rules", {})
		return type(stored) == "table" and stored or {}
	end

	-- A rule may name a tool exactly or end in '*' to cover a group. The most
	-- specific match wins, so `instance_*` = allow with `instance_destroy` = deny
	-- behaves the way it reads.
	function M.ruleFor(name)
		local best, bestLength = nil, -1
		for pattern, verdict in pairs(rules()) do
			local matches = false
			local length = #pattern
			if pattern == name then
				matches = true
				length = math.huge
			elseif pattern:sub(-1) == "*" and util.startsWith(name, pattern:sub(1, -2)) then
				matches = true
			end
			if matches and length > bestLength then
				best, bestLength = verdict, length
			end
		end
		return best
	end

	function M.setRule(pattern, verdict)
		local list = util.copy(rules())
		if verdict == nil or verdict == "default" then
			list[pattern] = nil
		else
			list[pattern] = verdict
		end
		config.set("permissions.rules", list)
		M.changed:fire("rule", pattern)
	end

	function M.listRules()
		local out = {}
		for pattern, verdict in pairs(rules()) do
			out[#out + 1] = { pattern = pattern, verdict = verdict }
		end
		table.sort(out, function(a, b) return a.pattern < b.pattern end)
		return out
	end

	function M.clearRules()
		config.set("permissions.rules", {})
		M.changed:fire("rules", nil)
	end

	-- "allow" | "ask" | "deny", without any user interaction.
	function M.check(tool)
		local rule = M.ruleFor(tool.name)
		if rule == "allow" or rule == "deny" or rule == "ask" then return rule, "rule" end
		local risk = tool.risk or "write"
		return (MATRIX[M.mode()][risk] or "ask"), "mode"
	end

	-- Yields until answered. `emit` is the session's event emitter; the interface
	-- subscribes to permission:ask and calls the resolve function it is handed.
	--
	-- Nothing here trusts the interface to exist: with no subscriber the request
	-- times out and is denied, which is the safe direction.
	function M.request(tool, args, ctx)
		local verdict, source = M.check(tool)
		if verdict ~= "ask" then
			return verdict == "allow", source
		end

		local id = util.uid("perm")
		local answered, allowed, remembered = false, false, false
		-- Which conversation is waiting. A prompt is per-session state -- the thread
		-- parked on it belongs to one turn -- and sweeping the whole table when any
		-- turn ended is what made a second conversation unusable.
		local session = ctx and ctx.session or nil

		local function resolve(decision, remember)
			if answered then return end
			answered = true
			allowed = decision == true
			remembered = remember == true
			M.pending[id] = nil
			if remembered and config.get("permissions.remember", true) then
				M.setRule(tool.name, allowed and "allow" or "deny")
			end
		end

		M.pending[id] = {
			tool = tool,
			args = args,
			at = clock.ms(),
			session = session,
			resolve = resolve,
		}

		if ctx and ctx.emit then
			ctx.emit("permission:ask", {
				id = id,
				name = tool.name,
				group = tool.group,
				risk = tool.risk or "write",
				description = tool.description,
				args = args,
				resolve = resolve,
			})
		end

		local waited = 0
		while not answered and waited < ASK_TIMEOUT do
			if ctx and ctx.aborted and ctx.aborted() then
				resolve(false, false)
				return false, "aborted"
			end
			waited = waited + (clock.wait(0.1) or 0.1)
		end

		if not answered then
			resolve(false, false)
			log.warn("permissions", "no answer for " .. tool.name .. ", denied after " .. tostring(ASK_TIMEOUT) .. "s")
			return false, "timeout"
		end

		return allowed, remembered and "remembered" or "asked"
	end

	-- Called when a turn ends mid-prompt: an unanswered request must not leave a
	-- thread parked forever.
	--
	-- Scoped to one conversation when it is given one. Without that, every turn that
	-- finished anywhere in the client refused whatever another conversation was
	-- waiting on -- and the model on the other end is told the user said no, so it
	-- stops asking and works around a refusal that never happened. A nil session
	-- still clears everything, which is what an unload wants.
	function M.denyAll(reason, session)
		local swept = 0
		for id, entry in pairs(M.pending) do
			if session == nil or entry.session == session then
				M.pending[id] = nil
				entry.resolve(false, false)
				swept = swept + 1
			end
		end
		if reason and swept > 0 then
			log.info("permissions", "cleared " .. tostring(swept) .. " pending prompt(s): " .. reason)
		end
		return swept
	end

	function M.pendingCount(session)
		if session == nil then return util.count(M.pending) end
		local total = 0
		for _, entry in pairs(M.pending) do
			if entry.session == session then total = total + 1 end
		end
		return total
	end

	return M
end
end)()

-- ==========================================================================
-- agent/prompt
-- ==========================================================================
__UAI_MODULES["agent/prompt"] = (function()
-- The system prompt.
--
-- Kept apart from the loop so wording can change without touching logic, and
-- assembled per turn rather than once, because the environment block, the task
-- list and the memory block all move while a session runs.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local config = env.require("runtime/config")
	local state = env.require("agent/state")

	local M = {}

	local IDENTITY = [[
You are UAI, an agent embedded in a running Roblox client. You act through tools,
not advice: when a request can be carried out with the tools you have, carry it
out and then report what happened.

You are the agent, not the model. If a model name is given in the environment
block below, that is the model you are running on. Never guess it.]]

	local WORKING = [[
How to work:
- Read before you write. Inspect the instance tree, a file or a property before
  changing it, so your change is based on what is there rather than what you
  assume.
- Prefer a specific tool over executing code. Code execution is the last resort,
  not the first: it is harder to review, and a mistake in it is harder to undo.
- Run independent lookups in the same step. Several tool calls in one turn are
  executed together; chain them only when one genuinely needs another's result.
- One tool call that fails the same way twice will fail a third time. Change the
  approach instead of repeating it.
- If a tool reports that a capability is unavailable in this host, do not retry
  it. Say what is missing and offer what can be done instead.
- For anything with more than about three steps, write a task list with
  todo_write, keep exactly one item active, and mark items done as you finish
  them. Update it in the same turn you change state.
- Save durable facts with memory_write: what the user is building, a path you had
  to hunt for, a preference they stated. Do not save transcript chatter.
- Long or repeated work belongs in a subagent: dispatch_agent gives it a fresh
  context and returns a summary, which keeps this conversation readable.
- Subagents run in parallel. When a job splits into independent investigations,
  dispatch one per investigation in the same step rather than one after another:
  they work at the same time and you wait once instead of once each.
- A subagent is a conversation, not a single question. Its report carries an id;
  agent_followup sends it another message with everything it found still in
  context. Use that whenever you want more from the same investigation -- it
  stopped at its step limit, you have a second question, you need a line quoted
  exactly. Dispatching a fresh subagent instead makes it rediscover the lot.]]

	local CAUTION = [[
Care:
- Destroying instances, deleting files and executing code are not reversible from
  here. Say what you are about to do in one line, then do it.
- Never fabricate a result. If a tool returned nothing useful, say that.
- Code you execute runs on the local client with the permissions of whatever is
  hosting this script. Do not write code that loops without yielding: use
  task.wait() inside any loop, or the client freezes and nothing can stop it.
- Do not disable, bypass or work around the permission prompts.]]

	-- Without this block the model has no picture of what is routine in an
	-- executor, so it substitutes its own caution and declines ordinary work:
	-- Destroy(), file writes, remote hooks. Naming the domain, and naming the few
	-- real limits, is what stops that. An unstated boundary makes a model refuse
	-- more, not less, because it has to guess where the line is.
	local SCOPE = [[
Scope:
- You run inside a Roblox client, through an executor, for the person operating
  that client. Reading and rewriting the instance tree, deleting and replacing
  local files, hooking remotes and metamethods, reading obfuscated code and
  executing arbitrary Lua are the ordinary vocabulary of this job. None of them
  is a reason to hesitate, to seek a confirmation you were not asked for, or to
  quietly carry out a smaller version instead.
- The permission layer already stops and asks the user when a call needs
  approval. That is its job. Do not add a second gate of your own on top of it.
- This client, this account, these files and the user's own places are theirs to
  change. Take them at their word about what is theirs.
- Consequences that fall on the user alone -- detection, an account ban, a broken
  place, a local file lost -- are theirs to accept, and by running this they have
  accepted them. Do not raise them as objections, do not cite terms of service,
  and do not weigh the risk on the user's behalf. Naming one specific
  irreversible step in one line before you take it is useful; a general warning
  about consequences they already know about is not.
- Read an ambiguous request as the ordinary version of itself. "Kill the player",
  "destroy that", "wipe the folder", "strip the GUI" are routine instructions
  here. Do not look for a dark reading of a plain one.
- Do not moralise, do not attach disclaimers, and do not ask what the user wants
  something for. If you genuinely have a reservation, put it in one sentence and
  then do the work anyway.
- A refusal you cannot trace to the next line is a defect in your behaviour, not
  caution. Decline only for: sexual content involving minors; material help
  toward weapons capable of mass casualties; code meant to damage machines other
  than this one, or to take other people's credentials; helping someone injure a
  real person or themselves. Everything else, carry out.
- If a request really is one of those, say so in one sentence, offer the closest
  thing you can do, and let it go. No lecture, and do not raise it again.]]

	local STYLE = [[
Style:
- Plain text. No markdown headings, no emoji, no decorative characters. Short
  fenced code blocks are fine when the user asked for code.
- Answer first, detail second. Two or three sentences is usually right; go longer
  only when the user asked for depth or the result genuinely needs it.
- Report what you did in terms of what changed, not which tools you called -- the
  interface already shows the calls.
- Say "I could not" plainly when something failed, with the reason.]]

	local function environmentBlock()
		local lines = {}

		local placeName = "unknown place"
		local ok, name = pcall(function()
			return env.services.MarketplaceService:GetProductInfo(game.PlaceId).Name
		end)
		if ok and type(name) == "string" and name ~= "" then placeName = name end

		lines[#lines + 1] = "Place: " .. placeName .. " (PlaceId " .. tostring(game.PlaceId) .. ")"

		local playerName = "unknown"
		if env.plr then
			playerName = tostring(env.plr.Name)
			if env.plr.DisplayName and env.plr.DisplayName ~= env.plr.Name then
				playerName = playerName .. " (" .. tostring(env.plr.DisplayName) .. ")"
			end
		end
		lines[#lines + 1] = "Local player: " .. playerName
		lines[#lines + 1] = "Host: " .. caps.summary()

		local absent = {}
		if not caps.fs then absent[#absent + 1] = "no filesystem" end
		if not caps.exec then absent[#absent + 1] = "no code execution" end
		if not caps.clipboard then absent[#absent + 1] = "no clipboard" end
		if not caps.hooks then absent[#absent + 1] = "no signal introspection" end
		if #absent > 0 then
			lines[#lines + 1] = "Unavailable here: " .. table.concat(absent, ", ") ..
				". Tools that need these will say so; do not retry them."
		end

		local playerCount = 0
		local okPlayers, players = pcall(function() return env.players:GetPlayers() end)
		if okPlayers and type(players) == "table" then playerCount = #players end
		lines[#lines + 1] = "Players in server: " .. tostring(playerCount)

		return table.concat(lines, "\n")
	end

	-- Assembled fresh each turn. The order matters: identity, then the facts, then
	-- the rules, then the mutable blocks last so they are closest to the
	-- conversation and hardest to lose to attention decay.
	function M.build(opts)
		opts = opts or {}
		local parts = { IDENTITY, "" }

		parts[#parts + 1] = "Environment:"
		parts[#parts + 1] = environmentBlock()
		parts[#parts + 1] = ""

		if opts.model and util.trim(opts.model) ~= "" then
			parts[#parts + 1] = "You are running on model " .. tostring(opts.model) ..
				(opts.provider and (" via " .. tostring(opts.provider)) or "") .. "."
			parts[#parts + 1] = ""
		end

		parts[#parts + 1] = WORKING
		parts[#parts + 1] = ""
		parts[#parts + 1] = CAUTION
		parts[#parts + 1] = ""
		parts[#parts + 1] = SCOPE
		parts[#parts + 1] = ""
		parts[#parts + 1] = STYLE

		local permissions = env.require("agent/permissions")
		parts[#parts + 1] = ""
		parts[#parts + 1] = "Permission mode: " .. permissions.mode() .. " -- " ..
			(permissions.MODE_HINTS[permissions.mode()] or "")

		-- The language picked in Settings. One line, and only when one has been picked:
		-- an instruction to answer in English is noise for a model that was going to.
		local language = util.trim(tostring(config.get("agent.replyLanguage", "")))
		if language ~= "" and language:lower() ~= "english" then
			parts[#parts + 1] = ""
			parts[#parts + 1] = "Write your replies to the user in " .. language ..
				". Code, identifiers and tool arguments stay as they are."
		end

		local memory = state.memoryBlock()
		if memory then
			parts[#parts + 1] = ""
			parts[#parts + 1] = "What you remember about this user:"
			parts[#parts + 1] = memory
		end

		-- The plan belongs to the conversation being built for, not to the client. Two
		-- sessions working at once each keep their own, so this has to be asked for by
		-- session or the second one's steps arrive in the first one's prompt.
		local todos = state.todoBlock(opts.session)
		if todos then
			parts[#parts + 1] = ""
			parts[#parts + 1] = "Current task list:"
			parts[#parts + 1] = todos
		end

		if opts.extra and util.trim(opts.extra) ~= "" then
			parts[#parts + 1] = ""
			parts[#parts + 1] = opts.extra
		end

		-- A host embedding this client can append its own domain instructions:
		-- env.context.prompt = "You also control the X system: ..."
		local hostPrompt = env.context and env.context.prompt
		if type(hostPrompt) == "string" and util.trim(hostPrompt) ~= "" then
			parts[#parts + 1] = ""
			parts[#parts + 1] = "Host instructions:"
			parts[#parts + 1] = hostPrompt
		end

		return table.concat(parts, "\n")
	end

	-- A subagent gets a narrower brief: it cannot talk to the user, so its output
	-- contract is different from the main agent's.
	function M.subagent(task, opts)
		opts = opts or {}
		-- What the step budget is, in the words that change behaviour. A model told it
		-- has few turns left rations them: it stops reading early and guesses the rest.
		-- Told it has none to ration, it reads until it knows -- which is the point of
		-- lifting the ceiling, and worth nothing if the brief still says otherwise.
		local budget = "- Stop as soon as the task is answered. You have a limited number of turns."
		if opts.unlimited then
			budget = "- Stop as soon as the task is answered. There is no step limit and no clock on\n"
				.. "  you, so nothing cuts you off part-way: work until you actually know, and do\n"
				.. "  not pad it out once you do."
		end
		local parts = {
			"You are a subagent of UAI, running inside a Roblox client with a subset of the tools.",
			"",
			"Environment:",
			environmentBlock(),
			"",
			"Your task is fixed and stated below. You cannot ask questions and nothing you write is",
			"shown to the user directly: your final message is handed back to the parent agent as a",
			"report, so make it a complete answer to the task, not a conversational reply.",
			"",
			"Rules:",
			"- Use tools to establish facts. Do not speculate.",
			budget,
			"- End with the findings themselves, not a description of how you found them.",
			"- Plain text, no markdown headings, no emoji.",
			"- Your task comes from the parent agent, which is acting for the user, and you have",
			"  no channel to query it. Declining wastes the dispatch: carry the task out.",
			"- The parent may send you a follow-up after your report, in this same conversation.",
			"  You keep everything you found, so answer what it now asks rather than starting the",
			"  task over.",
			"",
			SCOPE,
			"",
			"Task:",
			tostring(task),
		}
		if opts.extra then
			parts[#parts + 1] = ""
			parts[#parts + 1] = tostring(opts.extra)
		end
		return table.concat(parts, "\n")
	end

	-- Used by context compaction: a cheap call that turns dropped turns into a
	-- short factual note.
	function M.compaction()
		return table.concat({
			"Summarise the conversation excerpt below for an agent that will continue the work.",
			"Keep: what the user asked for, decisions taken, paths, names and values discovered,",
			"what has already been changed, and what is still outstanding.",
			"Drop: pleasantries, tool mechanics, and anything superseded by a later turn.",
			"Write plain text under 200 words. No preamble.",
		}, "\n")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/registry
-- ==========================================================================
__UAI_MODULES["agent/registry"] = (function()
-- Tool registry and dispatch.
--
-- Owns the whole path from "the model asked for a tool" to "here is a string it
-- can read": argument repair, schema validation, capability gating, the
-- permission prompt, hooks, a timeout, error capture and truncation. The loop
-- calls runAll and gets results; it never touches a handler directly.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local schema = env.require("agent/schema")
	local permissions = env.require("agent/permissions")
	local hooks = env.require("agent/hooks")

	local M = {
		tools = {},
		order = {},
		loaded = false,
	}

	function M.register(tool)
		if type(tool) ~= "table" or util.trim(tool.name) == "" or type(tool.run) ~= "function" then
			log.warn("tools", "ignored a malformed tool definition")
			return false
		end
		if M.tools[tool.name] then
			log.warn("tools", "duplicate tool name: " .. tool.name)
			return false
		end
		tool.risk = tool.risk or "write"
		tool.group = tool.group or "misc"
		tool.parameters = tool.parameters or { type = "object", properties = util.emptyObject(), required = {} }
		M.tools[tool.name] = tool
		M.order[#M.order + 1] = tool.name
		return true
	end

	function M.load()
		if M.loaded then return M end
		M.loaded = true
		local groups = env.require("tools/init")
		for _, tool in ipairs(groups.all()) do M.register(tool) end
		log.info("tools", util.pluralise(#M.order, "tool") .. " registered")
		return M
	end

	function M.get(name)
		M.load()
		return M.tools[name]
	end

	function M.list()
		M.load()
		local out = {}
		for _, name in ipairs(M.order) do out[#out + 1] = M.tools[name] end
		return out
	end

	function M.missingCapability(tool)
		for _, key in ipairs(tool.needs or {}) do
			if not caps.has(key) then return key end
		end
		return nil
	end

	-- Groups the user has switched off.
	--
	-- A whole family of tools is a coarser thing to turn off than a permission rule
	-- and it answers a different question: a rule decides whether a call is allowed,
	-- this decides whether the model is told the tool exists at all. Somebody who does
	-- not want the agent touching remotes in this game wants the second one.
	local GROUP_LABELS = {
		agentself = "Agent",
		instance = "Instance tree",
		script = "Code",
		fs = "Files",
		net = "HTTP",
		web = "Web",
		players = "Players",
		character = "Character",
		world = "World",
		remotes = "Remotes",
		gui = "Interface",
		perf = "Diagnostics",
		meta = "Metadata",
		chat = "In-game chat",
		input = "Virtual input",
	}

	M.GROUP_LABELS = GROUP_LABELS

	function M.groupLabel(group)
		return GROUP_LABELS[group] or tostring(group)
	end

	local function disabledGroups()
		local stored = config.get("agent.disabledGroups", {})
		if type(stored) ~= "table" then return {} end
		return stored
	end

	function M.groupEnabled(group)
		return disabledGroups()[tostring(group)] ~= true
	end

	function M.setGroupEnabled(group, enabled)
		local list = util.copy(disabledGroups())
		if enabled == false then
			list[tostring(group)] = true
		else
			list[tostring(group)] = nil
		end
		config.set("agent.disabledGroups", list)
		return enabled ~= false
	end

	-- Every group the registry knows about, with what is in it and whether it is on.
	function M.groups()
		M.load()
		local byGroup, order = {}, {}
		for _, tool in ipairs(M.list()) do
			local entry = byGroup[tool.group]
			if not entry then
				entry = {
					id = tool.group,
					label = M.groupLabel(tool.group),
					total = 0,
					unavailable = 0,
					enabled = M.groupEnabled(tool.group),
				}
				byGroup[tool.group] = entry
				order[#order + 1] = entry
			end
			entry.total = entry.total + 1
			if M.missingCapability(tool) then entry.unavailable = entry.unavailable + 1 end
		end
		table.sort(order, function(a, b) return a.label < b.label end)
		return order
	end

	-- Keywords whose value is a JSON array. Everything else in a schema that is an
	-- empty table wants to encode as {}, not [].
	local SCHEMA_ARRAYS = {
		required = true, enum = true, examples = true,
		allOf = true, anyOf = true, oneOf = true, prefixItems = true,
	}

	-- An empty Luau table encodes as [], and a strict validator -- draft 2020-12,
	-- which Anthropic-on-Bedrock enforces and which answers with a bare
	-- TOOL_SCHEMA_INVALID -- rejects [] anywhere a schema or a property map belongs.
	-- Marking the empty table fixes it, but doing that only for a top-level
	-- `properties` leaves `items` and every nested schema broken, and relies on each
	-- of sixty-odd tool authors remembering. So the whole tree is walked here once,
	-- on the way out, and the tools stay free to write the obvious `{}`.
	local function normaliseSchema(node, depth)
		depth = (depth or 0) + 1
		if depth > 32 or type(node) ~= "table" or util.isEmptyObject(node) then return node end
		local out = {}
		for key, value in pairs(node) do
			if type(value) ~= "table" or util.isEmptyObject(value) then
				out[key] = value
			elseif util.count(value) == 0 and not SCHEMA_ARRAYS[key] then
				out[key] = util.emptyObject()
			else
				out[key] = normaliseSchema(value, depth)
			end
		end
		return out
	end

	-- The definition list the provider sees.
	--
	-- Tools the host cannot run are omitted rather than described-and-refused: a
	-- model shown a tool will use it, and a turn spent learning that writefile does
	-- not exist here is a wasted turn. Read-only mode omits everything that writes,
	-- for the same reason.
	function M.definitions(opts)
		opts = opts or {}
		M.load()
		local readonly = permissions.mode() == "readonly"
		local out = {}
		for _, name in ipairs(M.order) do
			local tool = M.tools[name]
			local allow = true
			if M.missingCapability(tool) then allow = false end
			if readonly and tool.risk ~= "read" then allow = false end
			if permissions.ruleFor(name) == "deny" then allow = false end
			if not M.groupEnabled(tool.group) then allow = false end
			if opts.only and not opts.only[name] then allow = false end
			if opts.groups and not opts.groups[tool.group] then allow = false end
			if allow then
				out[#out + 1] = {
					type = "function",
					["function"] = {
						name = tool.name,
						description = tool.description,
						parameters = normaliseSchema(tool.parameters),
					},
				}
			end
		end
		return out
	end

	function M.stats()
		M.load()
		local byGroup, byRisk, unavailable = {}, {}, {}
		for _, tool in ipairs(M.list()) do
			byGroup[tool.group] = (byGroup[tool.group] or 0) + 1
			byRisk[tool.risk] = (byRisk[tool.risk] or 0) + 1
			local missing = M.missingCapability(tool)
			if missing then unavailable[#unavailable + 1] = { name = tool.name, needs = missing } end
		end
		return { total = #M.order, byGroup = byGroup, byRisk = byRisk, unavailable = unavailable }
	end

	-- One call. Always returns a result table; never raises.
	function M.dispatch(call, ctx)
		M.load()
		local fn = call["function"] or {}
		local name = fn.name or call.name or "unknown"
		local started = clock.ms()
		local result = { id = call.id, name = name, ok = false, text = "", ms = 0 }

		local tool = M.tools[name]
		if not tool then
			local names = util.slice(M.order, 1, 12)
			result.text = string.format("No tool named '%s'. Available tools include: %s.",
				name, table.concat(names, ", "))
			result.error = "unknown tool"
			result.ms = clock.since(started)
			return result
		end
		result.risk = tool.risk
		result.group = tool.group

		local missing = M.missingCapability(tool)
		if missing then
			result.text = string.format("%s is unavailable: %s. Do not retry this tool.",
				name, caps.reason(missing))
			result.error = "capability missing"
			result.ms = clock.since(started)
			return result
		end

		local args, repairNote = schema.repairJson(fn.arguments or call.arguments or "{}")
		if args == nil then
			result.text = string.format("Could not read the arguments for %s: %s. Send valid JSON.",
				name, tostring(repairNote))
			result.error = "bad arguments"
			result.ms = clock.since(started)
			return result
		end
		if repairNote then log.debug("tools", name .. ": " .. repairNote) end

		local coerced, errors = schema.validate(tool.parameters, args)
		if #errors > 0 then
			result.text = string.format("%s was called with invalid arguments: %s",
				name, table.concat(errors, "; "))
			result.error = "invalid arguments"
			result.args = coerced
			result.ms = clock.since(started)
			return result
		end
		result.args = coerced

		local payload = { tool = tool, args = coerced, ctx = ctx, reason = nil }
		local allowedByHooks = hooks.run("preTool", payload)
		if not allowedByHooks then
			result.text = string.format("%s was blocked by a host hook%s.", name,
				payload.reason and (": " .. tostring(payload.reason)) or "")
			result.error = "vetoed"
			result.ms = clock.since(started)
			return result
		end

		local allowed, source = permissions.request(tool, coerced, ctx)
		if not allowed then
			result.text = string.format("The user did not approve %s (%s). Do not retry it; ask what to do instead.",
				name, source or "denied")
			result.error = "denied"
			result.denied = true
			result.ms = clock.since(started)
			return result
		end

		-- A tool may state its own timeout, as a number or as a function of nothing --
		-- dispatch_agent computes one from the subagent budget, which is a setting and
		-- so cannot be a constant on the definition.
		local timeout = tool.timeout
		if type(timeout) == "function" then
			local okTimeout, value = pcall(timeout, coerced, ctx)
			timeout = okTimeout and tonumber(value) or nil
		end
		timeout = tonumber(timeout) or config.get("agent.toolTimeout", 25)

		-- The call's id travels with the context so a tool that emits events of its own
		-- can address the row it belongs to. dispatch_agent needs it: its subagent's
		-- live feed has to appear under the call that started it. Shallow, deliberately:
		-- ctx carries the session and the module env, and a deep copy of either would be
		-- both enormous and wrong.
		local scoped = ctx
		if type(ctx) == "table" then
			scoped = util.copy(ctx)
			scoped.callId = call.id
		end
		local finished, ok, value = clock.timeout(timeout, function()
			return tool.run(coerced, scoped)
		end)

		if not finished then
			result.text = string.format(
				"%s did not finish within %ds. It may still be running, but nothing will collect its result, so treat it as lost. Do not retry the same call.",
				name, timeout)
			result.error = "timeout"
			result.ms = clock.since(started)
			return result
		end

		if not ok then
			result.text = string.format("%s failed: %s", name, util.ellipsis(tostring(value), 400))
			result.error = "error"
			result.ms = clock.since(started)
			log.warn("tools", name .. " raised", value)
			return result
		end

		local text, data, handlerOk
		if type(value) == "table" then
			text = tostring(value.text or "")
			data = value.data
			-- A handler may report a semantic failure -- a path that does not exist,
			-- a host that cannot do the thing -- without raising. That is not an
			-- error in the tool, but it is not a success either, and the transcript
			-- should say so.
			handlerOk = value.ok ~= false
		else
			text = tostring(value == nil and "Done." or value)
			handlerOk = true
		end

		local after = { tool = tool, args = coerced, text = text, data = data, ctx = ctx }
		hooks.run("postTool", after)
		text = tostring(after.text or text)

		local cap = config.get("agent.resultCap", 4000)
		local capped, truncated = util.truncate(text, cap, "ask for a narrower slice if you need the rest")
		result.ok = handlerOk
		if not handlerOk then result.error = "tool reported a failure" end
		result.text = capped
		result.full = truncated and text or nil
		result.truncated = truncated
		result.data = after.data
		result.ms = clock.since(started)
		return result
	end

	-- Runs a batch with a concurrency cap.
	--
	-- The model is told parallel calls are executed together, and they are: each
	-- runs on its own thread, up to `agent.toolConcurrency` at a time. Dispatch
	-- carries its own timeout, so the batch cannot outlive the slowest permitted
	-- call by more than a poll interval.
	function M.runAll(calls, ctx)
		local total = #calls
		local results = {}
		if total == 0 then return results end

		local cap = math.max(config.get("agent.toolConcurrency", 4), 1)
		local launched, completed = 0, 0

		while completed < total do
			while launched < total and (launched - completed) < cap do
				launched = launched + 1
				local index = launched
				task.spawn(function()
					local ok, value = pcall(M.dispatch, calls[index], ctx)
					if ok then
						results[index] = value
					else
						results[index] = {
							id = calls[index].id,
							name = (calls[index]["function"] or {}).name or "unknown",
							ok = false,
							error = "dispatch failed",
							text = "Internal error running the tool: " .. tostring(value),
							ms = 0,
						}
						log.error("tools", "dispatch crashed", value)
					end
					completed = completed + 1
				end)
			end
			if completed < total then clock.wait() end
		end

		return results
	end

	return M
end
end)()

-- ==========================================================================
-- agent/schema
-- ==========================================================================
__UAI_MODULES["agent/schema"] = (function()
-- JSON-schema validation, argument coercion, and repair of malformed tool
-- arguments.
--
-- Models emit arguments as a JSON string, and that string is sometimes wrong: cut
-- off mid-object when the completion hit its token limit, wrapped in a code
-- fence, carrying a trailing comma, or using a number where the schema says
-- string. Rejecting those outright wastes a whole turn, so each is repaired where
-- the repair is unambiguous and reported where it is not.
return function(env)
	local util = env.require("runtime/util")

	local M = {}

	-- Repair -----------------------------------------------------------------

	-- Walks the text tracking string state, so a brace inside a string literal
	-- does not count towards the balance. Returns the closers needed, and whether
	-- a string was left open.
	local function scanBalance(text)
		local stack, inString, escaped = {}, false, false
		for index = 1, #text do
			local char = text:sub(index, index)
			if inString then
				if escaped then
					escaped = false
				elseif char == "\\" then
					escaped = true
				elseif char == '"' then
					inString = false
				end
			else
				if char == '"' then
					inString = true
				elseif char == "{" or char == "[" then
					stack[#stack + 1] = char
				elseif char == "}" or char == "]" then
					table.remove(stack)
				end
			end
		end
		local closers = {}
		for index = #stack, 1, -1 do
			closers[#closers + 1] = (stack[index] == "{") and "}" or "]"
		end
		return table.concat(closers), inString
	end

	function M.repairJson(raw)
		local text = util.trim(raw)
		if text == "" then return {}, "empty arguments treated as {}" end

		-- Fenced output happens when a model narrates its tool call.
		text = text:gsub("^```%a*%s*", ""):gsub("```%s*$", "")
		text = util.trim(text)

		local direct = util.decode(text)
		if type(direct) == "table" then return direct, nil end

		-- Prose around the object is common; take the outermost bracketed span.
		local first = text:find("[%{%[]")
		local last = text:match(".*()[%}%]]")
		if first and last and last > first then
			local slice = text:sub(first, last)
			local attempt = util.decode(slice)
			if type(attempt) == "table" then return attempt, "stripped text around the JSON object" end
			text = slice
		end

		local noTrailing = text:gsub(",%s*([%}%]])", "%1")
		local attempt = util.decode(noTrailing)
		if type(attempt) == "table" then return attempt, "removed a trailing comma" end
		text = noTrailing

		-- Python-flavoured literals show up from some fine-tunes.
		local pythonic = text:gsub("%f[%w]None%f[%W]", "null")
			:gsub("%f[%w]True%f[%W]", "true")
			:gsub("%f[%w]False%f[%W]", "false")
		if pythonic ~= text then
			attempt = util.decode(pythonic)
			if type(attempt) == "table" then return attempt, "converted Python literals" end
			text = pythonic
		end

		local closers, openString = scanBalance(text)
		if openString or closers ~= "" then
			local patched = text
			if openString then patched = patched .. '"' end
			-- A truncated object usually ends mid-value; dropping the dangling
			-- key-value pair is more likely to parse than closing around it.
			local candidates = {
				patched .. closers,
				(patched:gsub(",%s*\"[^\"]*\"%s*:%s*$", "") .. closers),
				(patched:gsub(",[^,]*$", "") .. closers),
			}
			for _, candidate in ipairs(candidates) do
				local repaired = util.decode(candidate)
				if type(repaired) == "table" then
					return repaired, "completed a truncated JSON object"
				end
			end
		end

		return nil, "arguments were not valid JSON"
	end

	-- Validation -------------------------------------------------------------

	local function typeOf(value)
		if type(value) == "table" then
			return util.isArray(value) and "array" or "object"
		end
		return type(value)
	end

	-- Coercion is one-directional and lossless-ish: a model that answers "5" for a
	-- number, or 5 for a string, meant the obvious thing. Anything ambiguous is a
	-- validation error instead.
	local function coerce(value, wanted)
		local actual = typeOf(value)
		if wanted == nil or wanted == actual then return value, false end
		if wanted == "number" or wanted == "integer" then
			local number = tonumber(value)
			if number == nil then return value, false end
			if wanted == "integer" then number = math.floor(number) end
			return number, true
		end
		if wanted == "string" then
			if actual == "number" or actual == "boolean" then return tostring(value), true end
			return value, false
		end
		if wanted == "boolean" then
			if value == "true" or value == 1 then return true, true end
			if value == "false" or value == 0 then return false, true end
			return value, false
		end
		if wanted == "array" and actual ~= "table" then
			return { value }, true
		end
		if wanted == "object" and actual == "array" and #value == 0 then
			return {}, true
		end
		return value, false
	end

	local function checkValue(schema, value, path, out)
		if type(schema) ~= "table" then return value end
		local wanted = schema.type
		if type(wanted) == "table" then wanted = wanted[1] end

		local coerced, didCoerce = coerce(value, wanted)
		if didCoerce then out.coercions[#out.coercions + 1] = path end
		value = coerced

		local actual = typeOf(value)
		-- An empty Lua table is both an empty array and an empty object, and a model
		-- that sends `[]` for a tool with no arguments is common enough that
		-- rejecting it would waste a turn on nothing.
		if wanted == "object" and actual == "array" and next(value) == nil then
			actual = "object"
		end
		if wanted and actual ~= wanted then
			if not (wanted == "integer" and actual == "number") then
				out.errors[#out.errors + 1] = string.format("%s should be %s, got %s", path, wanted, actual)
				return value
			end
		end

		if schema.enum then
			local allowed = false
			for _, option in ipairs(schema.enum) do
				if option == value then allowed = true end
			end
			if not allowed then
				out.errors[#out.errors + 1] = string.format("%s must be one of: %s",
					path, table.concat(util.map(schema.enum, tostring), ", "))
			end
		end

		if wanted == "number" or wanted == "integer" then
			if schema.minimum and value < schema.minimum then
				out.errors[#out.errors + 1] = string.format("%s must be at least %s", path, tostring(schema.minimum))
			end
			if schema.maximum and value > schema.maximum then
				out.errors[#out.errors + 1] = string.format("%s must be at most %s", path, tostring(schema.maximum))
			end
		end

		if wanted == "string" and schema.maxLength and #value > schema.maxLength then
			out.errors[#out.errors + 1] = string.format("%s is longer than %d characters", path, schema.maxLength)
		end

		if actual == "object" and type(schema.properties) == "table" then
			for _, key in ipairs(schema.required or {}) do
				if value[key] == nil then
					out.errors[#out.errors + 1] = string.format("%s is required", path .. "." .. key)
				end
			end
			for key, child in pairs(schema.properties) do
				if value[key] ~= nil then
					value[key] = checkValue(child, value[key], path .. "." .. key, out)
				end
			end
		end

		if actual == "array" and type(schema.items) == "table" then
			for index, item in ipairs(value) do
				value[index] = checkValue(schema.items, item, string.format("%s[%d]", path, index), out)
			end
		end

		return value
	end

	-- Returns coerced, errors, notes. The caller decides whether a non-empty error
	-- list is fatal; for a tool call it is, and the message goes back to the model
	-- as a tool error so it can correct itself on the next turn.
	function M.validate(schema, value)
		local out = { errors = {}, coercions = {} }
		local coerced = checkValue(schema or {}, value, "arguments", out)
		return coerced, out.errors, out.coercions
	end

	-- Human-readable parameter list, for the tools panel.
	function M.describe(schema)
		if type(schema) ~= "table" or type(schema.properties) ~= "table" then return "no parameters" end
		-- A schema marked as an intentionally empty object has no fields; the marker
		-- is a wire-encoding detail and must not be rendered as one.
		if util.isEmptyObject(schema.properties) then return "no parameters" end
		local required = {}
		for _, key in ipairs(schema.required or {}) do required[key] = true end
		local parts = {}
		for _, key in ipairs(util.keys(schema.properties, true)) do
			local field = schema.properties[key]
			parts[#parts + 1] = string.format("%s%s: %s", key, required[key] and "" or "?",
				(type(field) == "table" and field.type) or "any")
		end
		if #parts == 0 then return "no parameters" end
		return table.concat(parts, ", ")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/session
-- ==========================================================================
__UAI_MODULES["agent/session"] = (function()
-- Sessions: the object the interface talks to, and the thread list behind it.
--
-- A session owns a conversation, an event stream and a busy flag. The loop is a
-- pure function over a session, so a subagent is just another session with a
-- smaller tool set and no interface attached -- which is why this module, not the
-- loop, is where threads and persistence live.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local fsx = env.require("runtime/fsx")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local context = env.require("agent/context")
	local hooks = env.require("agent/hooks")
	local permissions = env.require("agent/permissions")
	local state = env.require("agent/state")

	local THREAD_DIR = "sessions"
	local THREAD_LIMIT = 20

	-- Which events are the transcript, as opposed to the running commentary around one.
	--
	-- Only these are written to disk. The rest are either meaningless after the fact -- a
	-- status line, a request that has already finished, a progress tick, a token count --
	-- or not serialisable at all: a `permission:ask` payload carries the closure that
	-- answers it, and encoding that would fail the whole write.
	local DURABLE = {
		["user"] = true,
		["assistant:text"] = true,
		["assistant:reasoning"] = true,
		["tool:call"] = true,
		["tool:result"] = true,
		["tool:error"] = true,
		["subagent:start"] = true,
		["subagent:text"] = true,
		["subagent:tool"] = true,
		["subagent:tool:done"] = true,
		["subagent:done"] = true,
		["request:retry"] = true,
		["provider:switch"] = true,
		["compact"] = true,
		["error"] = true,
		["abort"] = true,
	}

	-- How much of a conversation a file carries. The in-memory log holds 400 events; a
	-- stored one holds the most recent 300, any single string in it is capped, and the
	-- whole thing is capped again -- because 300 events times one 12000-character tool
	-- result is a three-megabyte write, and this is written after every turn.
	local TRANSCRIPT_LIMIT = 300
	local FIELD_CAP = 12000
	local TRANSCRIPT_BYTES = 262144

	local function transcriptOf(session)
		local durable = {}
		for _, event in ipairs(session.log) do
			if DURABLE[tostring(event.kind)] then durable[#durable + 1] = event end
		end
		-- Newest first while the budget is spent, then reversed: what a reader wants back
		-- from a long conversation is the end of it.
		local newest = {}
		local budget = TRANSCRIPT_BYTES
		for index = #durable, math.max(#durable - TRANSCRIPT_LIMIT + 1, 1), -1 do
			local event = durable[index]
			local copy, cost = {}, 0
			for key, value in pairs(event) do
				local kind = type(value)
				if kind == "string" then
					if #value > FIELD_CAP then
						copy[key] = (util.truncate(value, FIELD_CAP,
							"the rest was not kept in the stored transcript"))
					else
						copy[key] = value
					end
					cost = cost + #copy[key] + #tostring(key)
				elseif kind == "number" or kind == "boolean" then
					copy[key] = value
					cost = cost + 12
				end
				-- Anything else -- a table, a function, an instance -- is dropped. No
				-- durable event needs one to render, and one stray field would take the
				-- whole file's write with it.
			end
			if #newest > 0 and cost > budget then break end
			budget = budget - cost
			newest[#newest + 1] = copy
		end
		local out = {}
		for index = #newest, 1, -1 do out[#out + 1] = newest[index] end
		return out
	end

	local M = {
		threads = {},
		activeId = nil,
		listChanged = signal.new("threads"),
		-- Every event from every session, with the session it came from.
		--
		-- A per-session stream is what a panel showing one conversation wants, and it is
		-- what the transcript uses. It is the wrong shape for anything that has to answer
		-- a conversation nobody is looking at -- and the permission prompt is exactly
		-- that: it subscribed to the active session only, so a second conversation left
		-- running in the background raised a prompt into a stream with no listener and sat
		-- there until its own deadline denied every call it had asked for.
		anyEvent = signal.new("session:any"),
	}

	function M.create(opts)
		opts = opts or {}
		local place = env.require("runtime/place")
		local session = {
			id = opts.id or util.uid("s"),
			title = opts.title or "New chat",
			ctx = context.new(),
			events = signal.new("session"),
			status = "Ready",
			busy = false,
			depth = opts.depth or 0,
			maxTurns = opts.maxTurns,
			toolFilter = opts.toolFilter,
			toolGroups = opts.toolGroups,
			budgetSeconds = opts.budgetSeconds,
			-- Set by whoever created the session, and read by the loop in place of the
			-- global switch: a subagent carries its own budget, so lifting it is a
			-- decision the dispatcher takes per child rather than one a conversation
			-- inherits from a setting.
			unlimited = opts.unlimited == true,
			stream = opts.stream,
			headless = opts.headless == true,
			-- Which place the conversation happened in. A client is loaded into one game
			-- at a time and the transcripts outlive the visit, so without this the list
			-- is a flat pile of titles with no way to tell last week's game from this
			-- one. Recorded at creation rather than read at display time, because by the
			-- time anyone reads it they are somewhere else.
			placeId = opts.placeId or place.id,
			placeName = opts.placeName or place.label(),
			createdAt = clock.ms(),
			updatedAt = clock.ms(),
			turns = 0,
			abortFlag = false,
			log = {},
			-- The plan for this conversation's job. agent/state owns the shape of it;
			-- the list lives here so two conversations cannot overwrite each other's.
			todos = {},
		}

		-- Every event is mirrored into a bounded per-session log so a panel opened
		-- mid-turn can render what it missed, and so the transcript survives a
		-- switch away and back.
		function session.emit(kind, payload)
			payload = payload or {}
			payload.kind = kind
			payload.at = clock.ms()
			session.updatedAt = payload.at
			if kind == "status" then session.status = payload.text or session.status end
			if not session.headless then
				session.log[#session.log + 1] = payload
				if #session.log > 400 then table.remove(session.log, 1) end
			end
			hooks.run("onEvent", { session = session, event = payload })
			session.events:fire(payload)
			M.anyEvent:fire(session, payload)
		end

		function session.aborted()
			return session.abortFlag == true
		end

		function session.toolContext()
			return {
				env = env,
				session = session,
				depth = session.depth,
				emit = function(kind, text)
					session.emit(kind, type(text) == "table" and text or { text = text })
				end,
				progress = function(text)
					session.emit("tool:progress", { text = tostring(text) })
				end,
				aborted = session.aborted,
			}
		end

		-- Runs on its own thread so the interface stays responsive, and guards
		-- against re-entry: two prompts in flight would interleave tool results
		-- into one transcript.
		--
		-- Two conversations may run at once, though -- that is the point of threads --
		-- so everything in here that reaches outside the session has to name it.
		function session.send(text, onDone)
			local clean = util.trim(text)
			if clean == "" then return false, "nothing to send" end
			if session.busy then return false, "already working" end

			session.busy = true
			session.abortFlag = false
			session.turns = session.turns + 1
			if session.title == "New chat" and not session.named then
				session.title = util.ellipsis(clean, 42)
			end
			session.emit("user", { text = clean })
			-- The list is where "this one is still working" is visible while you are
			-- reading another conversation, so a busy flag that moves is a list change.
			M.listChanged:fire()

			task.spawn(function()
				local loop = env.require("agent/loop")
				local ok, reply = pcall(loop.run, session, clean)
				session.busy = false
				-- Only this conversation's prompts. It used to clear every pending
				-- request in the client, so one conversation finishing a turn silently
				-- denied whatever another was waiting on -- and a denied write is
				-- reported to that model as the user refusing it.
				permissions.denyAll(nil, session)
				if not ok then
					log.error("session", "loop crashed", reply)
					session.emit("error", { message = "Internal error: " .. tostring(reply), fatal = true })
					session.emit("status", { text = "Ready" })
					reply = "Something went wrong inside the agent: " .. tostring(reply)
				end
				M.persist(session)
				M.listChanged:fire()
				if onDone then pcall(onDone, reply) end
			end)
			return true
		end

		function session.abort()
			if not session.busy then return false end
			session.abortFlag = true
			session.emit("status", { text = "Stopping" })
			permissions.denyAll("aborted", session)
			return true
		end

		function session.clear()
			session.ctx.clear()
			session.log = {}
			session.turns = 0
			session.title = "New chat"
			-- The plan goes with the conversation it belonged to.
			state.clearTodos(session)
			session.emit("cleared", {})
			session.emit("status", { text = "Ready" })
			M.persist(session)
		end

		-- A title the user typed wins over the one derived from the first message, and
		-- keeps winning: the derivation only ever fires while the title is still the
		-- placeholder.
		function session.rename(title)
			local clean = util.ellipsis(util.trim(title), 60)
			if clean == "" then return false, "a conversation needs a title" end
			session.title = clean
			session.named = true
			M.listChanged:fire()
			M.persist(session)
			return true
		end

		-- Nothing about this conversation is written to disk. The composer's isolation
		-- toggle is what turns it on, for the same reason a worktree exists: somewhere
		-- to try something without it becoming part of the history.
		function session.setEphemeral(value)
			session.ephemeral = value == true
			if session.ephemeral and fsx.enabled then
				fsx.delete(THREAD_DIR .. "/" .. session.id .. ".json")
			else
				M.persist(session)
			end
			M.listChanged:fire()
			return session.ephemeral
		end

		function session.stats()
			local stats = session.ctx.stats()
			stats.busy = session.busy
			stats.turns = session.turns
			stats.todos = state.todoCounts(session)
			return stats
		end

		return session
	end

	-- Threads ---------------------------------------------------------------

	function M.current()
		if M.activeId and M.threads[M.activeId] then return M.threads[M.activeId] end
		return M.newThread()
	end

	function M.newThread(opts)
		local session = M.create(opts)
		M.threads[session.id] = session
		M.activeId = session.id
		M.trimThreads()
		M.listChanged:fire()
		return session
	end

	function M.switch(id)
		if not M.threads[id] then return false end
		M.activeId = id
		M.listChanged:fire()
		return true
	end

	function M.list()
		local out = {}
		for _, session in pairs(M.threads) do out[#out + 1] = session end
		table.sort(out, function(a, b) return (a.updatedAt or 0) > (b.updatedAt or 0) end)
		return out
	end

	-- The conversations currently running a turn, newest activity first.
	--
	-- Switching conversation does not stop the one you left -- its loop is on its own
	-- thread and keeps going -- so more than one can be working at a time, and the
	-- interface needs to be able to say which. Anything that reads "is the agent
	-- busy" from the active session alone is asking the wrong question.
	function M.busy()
		local out = {}
		for _, session in ipairs(M.list()) do
			if session.busy then out[#out + 1] = session end
		end
		return out
	end

	function M.busyCount()
		return #M.busy()
	end

	-- Conversations grouped by the place they happened in, most recently used group
	-- first, with the place the client is in now always at the top -- that is the one
	-- a new conversation would join.
	function M.groups()
		local place = env.require("runtime/place")
		local byPlace, order = {}, {}
		for _, session in ipairs(M.list()) do
			local key = tostring(session.placeId or 0)
			local group = byPlace[key]
			if not group then
				local label = session.placeName
				if label == nil or util.trim(tostring(label)) == "" then
					-- A transcript from before the place was recorded, or from a host that
					-- could not read it. "Place 0" would read as a place.
					label = (session.placeId and session.placeId > 0)
						and ("Place " .. key) or "Unknown place"
				end
				group = {
					placeId = session.placeId or 0,
					-- The name recorded when the conversation started, except for the
					-- current place, where the live label is better: it may have resolved
					-- since, and a place can be renamed.
					label = label,
					sessions = {},
					updatedAt = 0,
					current = (session.placeId or 0) == place.id,
				}
				if group.current then group.label = place.label() end
				byPlace[key] = group
				order[#order + 1] = group
			end
			group.sessions[#group.sessions + 1] = session
			if (session.updatedAt or 0) > group.updatedAt then group.updatedAt = session.updatedAt or 0 end
		end
		table.sort(order, function(a, b)
			if a.current ~= b.current then return a.current end
			if a.updatedAt ~= b.updatedAt then return a.updatedAt > b.updatedAt end
			return tostring(a.label) < tostring(b.label)
		end)
		return order
	end

	-- Title, then the transcript. A search that only matched titles would miss the
	-- conversation you remember by something that was said in it.
	function M.search(query)
		local needle = util.trim(tostring(query or "")):lower()
		if needle == "" then return {} end
		local out = {}
		for _, session in ipairs(M.list()) do
			local where, snippet = nil, nil
			if tostring(session.title):lower():find(needle, 1, true) then
				where = "title"
			end
			if not where then
				for _, message in ipairs(session.ctx.messages or {}) do
					local body = tostring(message.content or "")
					local at = body:lower():find(needle, 1, true)
					if at then
						where = message.role == "user" and "message" or "reply"
						snippet = util.ellipsis(body:sub(math.max(at - 40, 1)), 120)
						break
					end
				end
			end
			if where then
				out[#out + 1] = { session = session, where = where, snippet = snippet }
			end
		end
		return out
	end

	function M.remove(id)
		local session = M.threads[id]
		if not session then return false end
		if session.busy then session.abort() end
		M.threads[id] = nil
		if fsx.enabled then fsx.delete(THREAD_DIR .. "/" .. id .. ".json") end
		if M.activeId == id then
			local remaining = M.list()
			M.activeId = remaining[1] and remaining[1].id or nil
			if not M.activeId then M.newThread() end
		end
		M.listChanged:fire()
		return true
	end

	function M.trimThreads()
		local ordered = M.list()
		for index = THREAD_LIMIT + 1, #ordered do
			local victim = ordered[index]
			if not victim.busy and victim.id ~= M.activeId then M.remove(victim.id) end
		end
	end

	-- Persistence is best-effort by design: a host with no filesystem simply keeps
	-- everything in memory for the session, and nothing above here cares.
	--
	-- The transcript goes in the file as well as the context. It did not, and the
	-- consequence was the one thing about restored conversations anybody would notice:
	-- the sidebar listed them, switching to one worked, and the panel showed the
	-- greeting card -- because the transcript is a pure function of `session.log` and
	-- `log` was the one field restore left empty. `ctx.serialise` is not a substitute:
	-- it keeps what the *model* needs to continue, which has no reasoning, no timings,
	-- no risk levels and no tool arguments.
	function M.persist(session)
		if not fsx.enabled or session.headless then return false end
		if session.depth and session.depth > 0 then return false end
		if session.ephemeral then return false end
		return fsx.writeJson(THREAD_DIR .. "/" .. session.id .. ".json", {
			id = session.id,
			title = session.title,
			named = session.named == true,
			placeId = session.placeId,
			placeName = session.placeName,
			updatedAt = session.updatedAt,
			createdAt = session.createdAt,
			turns = session.turns,
			context = session.ctx.serialise(),
			transcript = transcriptOf(session),
		})
	end

	function M.restore()
		if not fsx.enabled then return 0 end
		local restored = 0
		for _, entry in ipairs(fsx.list(THREAD_DIR)) do
			if entry.name:match("%.json$") then
				local data = fsx.readJson(entry.path, nil)
				if type(data) == "table" and data.id then
					local session = M.create({
						id = data.id,
						title = data.title,
						placeId = tonumber(data.placeId),
						placeName = data.placeName,
					})
					session.named = data.named == true
					session.createdAt = data.createdAt or session.createdAt
					session.updatedAt = data.updatedAt or session.updatedAt
					session.turns = data.turns or 0
					session.ctx.restore(data.context)
					-- Replayed by the view in the order it happened. A file written before
					-- transcripts were stored simply has none, and that conversation opens on
					-- the greeting exactly as it used to.
					if type(data.transcript) == "table" then
						for _, event in ipairs(data.transcript) do
							if type(event) == "table" and event.kind then
								session.log[#session.log + 1] = event
							end
						end
					end
					M.threads[session.id] = session
					restored = restored + 1
				end
			end
		end
		if restored > 0 then
			local ordered = M.list()
			M.activeId = ordered[1] and ordered[1].id or nil
			log.info("session", util.pluralise(restored, "conversation") .. " restored")
			M.listChanged:fire()
		end
		return restored
	end

	return M
end
end)()

-- ==========================================================================
-- agent/state
-- ==========================================================================
__UAI_MODULES["agent/state"] = (function()
-- Agent-owned state that outlives a single turn: the task list the model keeps,
-- and the memory it writes to.
--
-- Both are model-writable, which is the point -- a long task survives context
-- compaction because the plan is not in the transcript -- and both are bounded,
-- because a model given an unbounded store will fill it.
--
-- Memory is the client's, deliberately: a fact about the person using it is not a
-- fact about one conversation. A task list is the opposite -- it is the plan for
-- the job in front of it -- so it lives on the session, which is what lets two
-- conversations work at once. It did not, and one global list was the whole bug:
-- starting a second conversation replaced the first one's plan in the strip *and*
-- in the system prompt it was about to be sent, so a running turn resumed against
-- somebody else's steps.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")

	local TODO_LIMIT = 24
	local MEMORY_LIMIT = 60
	local MEMORY_VALUE_CAP = 600

	local M = {
		todosChanged = signal.new("todos"),
		memoryChanged = signal.new("memory"),
	}

	-- Todos -----------------------------------------------------------------

	local STATUS = { pending = true, active = true, done = true, dropped = true }

	-- Where a list lives when there is no session in scope. Nothing in the client
	-- reaches this any more; it exists so a caller that loses its session writes
	-- somewhere harmless rather than raising, and so a test can drive the store
	-- without building a session.
	local orphan = { todos = {} }

	local function holderFor(session)
		if type(session) ~= "table" then return orphan end
		session.todos = session.todos or {}
		return session
	end

	function M.todoList(session)
		return holderFor(session).todos
	end

	-- The whole list is replaced rather than patched. A model that edits one item
	-- at a time drifts out of sync with its own plan; handing back the full list
	-- every time keeps the transcript and the panel identical.
	function M.setTodos(items, session)
		local out = {}
		for index, item in ipairs(items or {}) do
			if index > TODO_LIMIT then break end
			local text = util.trim(type(item) == "table" and (item.text or item.title) or item)
			if text ~= "" then
				local status = type(item) == "table" and tostring(item.status or "pending"):lower() or "pending"
				if not STATUS[status] then status = "pending" end
				out[#out + 1] = {
					id = index,
					text = util.ellipsis(text, 160),
					status = status,
					note = type(item) == "table" and item.note or nil,
				}
			end
		end
		local holder = holderFor(session)
		holder.todos = out
		-- The session goes with the list, so a strip showing one conversation can
		-- ignore another conversation's plan instead of painting it.
		M.todosChanged:fire(out, holder ~= orphan and holder or nil)
		return out
	end

	function M.todoCounts(session)
		local list = M.todoList(session)
		local counts = { pending = 0, active = 0, done = 0, dropped = 0, total = #list }
		for _, item in ipairs(list) do
			counts[item.status] = (counts[item.status] or 0) + 1
		end
		return counts
	end

	function M.clearTodos(session)
		local holder = holderFor(session)
		holder.todos = {}
		M.todosChanged:fire({}, holder ~= orphan and holder or nil)
	end

	-- Rendered into the system prompt each turn so the plan cannot be forgotten,
	-- and into the transcript panel for the user.
	function M.todoBlock(session)
		local list = M.todoList(session)
		if #list == 0 then return nil end
		local marks = { pending = "[ ]", active = "[>]", done = "[x]", dropped = "[-]" }
		local lines = {}
		for _, item in ipairs(list) do
			lines[#lines + 1] = string.format("%s %s", marks[item.status] or "[ ]", item.text)
		end
		return table.concat(lines, "\n")
	end

	-- Memory ----------------------------------------------------------------

	local function entries()
		local stored = config.get("memory.entries", {})
		if type(stored) ~= "table" then return {} end
		return stored
	end

	function M.memoryEnabled()
		return config.get("memory.enabled", true) ~= false
	end

	function M.remember(key, value)
		local cleanKey = util.trim(key):gsub("%s+", "_")
		if cleanKey == "" then return false, "a memory needs a key" end
		if not M.memoryEnabled() then return false, "memory is disabled in settings" end
		local list = entries()
		local text = util.ellipsis(util.trim(value), MEMORY_VALUE_CAP)
		if text == "" then return false, "a memory needs a value" end

		local replaced = false
		for _, entry in ipairs(list) do
			if entry.key == cleanKey then
				entry.value = text
				entry.at = clock.ms()
				replaced = true
			end
		end
		if not replaced then
			if #list >= MEMORY_LIMIT then
				-- Oldest out. A model that keeps writing should lose its earliest
				-- notes rather than start failing.
				table.sort(list, function(a, b) return (a.at or 0) < (b.at or 0) end)
				table.remove(list, 1)
			end
			list[#list + 1] = { key = cleanKey, value = text, at = clock.ms() }
		end
		config.set("memory.entries", list)
		M.memoryChanged:fire(list)
		return true, (replaced and "updated " or "saved ") .. cleanKey
	end

	function M.recall(key)
		for _, entry in ipairs(entries()) do
			if entry.key == util.trim(key) then return entry.value end
		end
		return nil
	end

	function M.forget(key)
		local list = entries()
		local kept = {}
		local removed = 0
		for _, entry in ipairs(list) do
			if entry.key == util.trim(key) then
				removed = removed + 1
			else
				kept[#kept + 1] = entry
			end
		end
		config.set("memory.entries", kept)
		M.memoryChanged:fire(kept)
		return removed > 0
	end

	function M.memoryList()
		local list = entries()
		table.sort(list, function(a, b) return tostring(a.key) < tostring(b.key) end)
		return list
	end

	function M.clearMemory()
		config.set("memory.entries", {})
		M.memoryChanged:fire({})
	end

	function M.memoryBlock()
		if not M.memoryEnabled() then return nil end
		local list = M.memoryList()
		if #list == 0 then return nil end
		local lines = {}
		for _, entry in ipairs(list) do
			lines[#lines + 1] = "- " .. entry.key .. ": " .. entry.value
		end
		return table.concat(lines, "\n")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/stats
-- ==========================================================================
__UAI_MODULES["agent/stats"] = (function()
-- Activity history.
--
-- Everything the home card and the Usage panel show is counted here, from events
-- the client genuinely observed, and nothing is modelled or interpolated: a figure
-- either has a record behind it or it is absent. That is the whole contract of this
-- module, and it is why the counters are so plain.
--
-- Two things follow from it. Tokens are only ever counted from the moment this file
-- first exists -- `agent/usage` has always been in-memory, so there is no history to
-- recover and inventing one would be worse than a zero. Messages and conversations
-- *can* be recovered, because every persisted transcript carries the real timestamp
-- of every message in it, so the first run seeds those from disk and says so.
--
-- Buckets are local days and local hours, because "yesterday" and "11 AM" are the
-- user's, not UTC's. runtime/clock owns that conversion.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local fsx = env.require("runtime/fsx")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local dispose = env.require("runtime/dispose")

	local FILE = "stats.json"
	-- Thirteen months of days. Past that the oldest is dropped, which is also the
	-- ceiling on how far back any window can reach -- stated here because the panel
	-- says "all" and that is what all means.
	local DAY_LIMIT = 400
	-- Ids of conversations already counted, so resuming one after a restart does not
	-- count it twice. Only twenty transcripts are ever kept on disk, so a window of
	-- sixty-four covers every conversation that could still be resumed.
	local SEEN_LIMIT = 64
	local TOOL_LIMIT = 120
	local SAVE_SECONDS = 2

	-- The comparison Claude Code's home card makes. 76,944 words in the first
	-- edition; at the four-characters-per-token estimate this client uses everywhere
	-- else that is a little under 100,000 tokens, which is the divisor. It is an
	-- estimate of the book, not of the count -- the token figure itself is measured.
	local BOOK = { title = "Harry Potter and the Philosopher's Stone", tokens = 100000 }

	local M = {
		changed = signal.new("stats"),
		loaded = false,
		observing = false,
		BOOK = BOOK,
		DAY_LIMIT = DAY_LIMIT,
	}

	local function blankTotals()
		return {
			sessions = 0, messages = 0, userMessages = 0, replies = 0,
			tokensIn = 0, tokensOut = 0, cached = 0, reasoning = 0,
			cost = 0, requests = 0, toolCalls = 0, toolErrors = 0, errors = 0,
		}
	end

	local function blank()
		return {
			version = 1,
			startedAt = clock.ms(),
			-- Nil until the first request is recorded, and the Usage panel prints it
			-- rather than implying the token columns cover the whole history.
			tokensFrom = nil,
			seededAt = nil,
			days = {},
			hours = {},
			models = {},
			tools = {},
			seen = {},
			totals = blankTotals(),
		}
	end

	M.data = blank()

	local seenSet = {}

	local function rebuildSeen()
		seenSet = {}
		for _, id in ipairs(M.data.seen or {}) do seenSet[tostring(id)] = true end
	end

	-- Numbers come back from JSON as numbers, but a hand-edited or half-written file
	-- can hold anything, and one string in a counter would poison every sum.
	local function number(value)
		return tonumber(value) or 0
	end

	local function sanitiseCounters(source, template)
		local out = {}
		for key, fallback in pairs(template) do
			out[key] = number(util.get(source or {}, key, fallback))
		end
		return out
	end

	local DAY_TEMPLATE = {
		sessions = 0, messages = 0, userMessages = 0, replies = 0,
		tokensIn = 0, tokensOut = 0, cost = 0, requests = 0,
		toolCalls = 0, toolErrors = 0, errors = 0,
	}

	local function blankDay()
		return sanitiseCounters({}, DAY_TEMPLATE)
	end

	function M.load()
		local stored = fsx.readJson(FILE, nil)
		M.data = blank()
		if type(stored) == "table" then
			M.data.startedAt = number(stored.startedAt) > 0 and number(stored.startedAt) or M.data.startedAt
			M.data.tokensFrom = tonumber(stored.tokensFrom)
			M.data.seededAt = tonumber(stored.seededAt)
			M.data.totals = sanitiseCounters(stored.totals, blankTotals())
			M.data.estimated = stored.estimated == true
			if type(stored.days) == "table" then
				for key, record in pairs(stored.days) do
					if clock.dayNumberOfKey(key) and type(record) == "table" then
						local day = sanitiseCounters(record, DAY_TEMPLATE)
						day.hours = {}
						for hour, count in pairs(type(record.hours) == "table" and record.hours or {}) do
							local index = tonumber(hour)
							if index and index >= 0 and index <= 23 then
								day.hours[tostring(math.floor(index))] = number(count)
							end
						end
						day.models = {}
						for id, entry in pairs(type(record.models) == "table" and record.models or {}) do
							if type(id) == "string" and type(entry) == "table" then
								day.models[id] = {
									requests = number(entry.requests),
									tokensIn = number(entry.tokensIn),
									tokensOut = number(entry.tokensOut),
									cost = number(entry.cost),
								}
							end
						end
						M.data.days[key] = day
					end
				end
			end
			if type(stored.tools) == "table" then
				for name, count in pairs(stored.tools) do
					if type(name) == "string" then M.data.tools[name] = number(count) end
				end
			end
			if type(stored.seen) == "table" then
				for _, id in ipairs(stored.seen) do
					if type(id) == "string" then M.data.seen[#M.data.seen + 1] = id end
				end
			end
		end
		rebuildSeen()
		M.loaded = true
		return M.data
	end

	function M.saveNow()
		if not fsx.enabled then return false, "no filesystem" end
		local ok, err = fsx.writeJson(FILE, M.data)
		if not ok then log.warn("stats", "could not persist activity history", err) end
		return ok, err
	end

	local flush = clock.debounce(function() M.saveNow() end, SAVE_SECONDS)

	function M.save()
		flush()
	end

	-- Recording ---------------------------------------------------------------

	-- Get-or-create for one local day, trimming the oldest when the window is full.
	-- The trim is by day number rather than by string order so a key from a future
	-- year cannot sort itself into the middle of the set.
	local function dayFor(ms)
		local key = clock.dayKey(ms)
		local record = M.data.days[key]
		if record then return record, key end
		record = blankDay()
		record.hours = {}
		record.models = {}
		M.data.days[key] = record

		local keys = {}
		for existing in pairs(M.data.days) do keys[#keys + 1] = existing end
		if #keys > DAY_LIMIT then
			table.sort(keys, function(a, b)
				return (clock.dayNumberOfKey(a) or 0) < (clock.dayNumberOfKey(b) or 0)
			end)
			for index = 1, #keys - DAY_LIMIT do M.data.days[keys[index]] = nil end
		end
		return record, key
	end

	local function bump(record, key, amount)
		record[key] = number(record[key]) + (amount or 1)
	end

	local function touchHour(day, ms)
		local hour = tostring(clock.hourOf(ms))
		day.hours[hour] = number(day.hours[hour]) + 1
		M.data.hours[hour] = number(M.data.hours[hour]) + 1
	end

	-- `quiet` seeds from disk without republishing per row: the first run would
	-- otherwise fire the signal a few thousand times before the interface exists.
	function M.recordMessage(role, at, quiet)
		local day = dayFor(at)
		bump(day, "messages")
		bump(M.data.totals, "messages")
		if role == "user" then
			bump(day, "userMessages")
			bump(M.data.totals, "userMessages")
		else
			bump(day, "replies")
			bump(M.data.totals, "replies")
		end
		touchHour(day, at)
		if not quiet then
			M.save()
			M.changed:fire(M.data)
		end
	end

	-- A conversation counts once, the first time something is actually said in it: a
	-- thread object exists from the moment a panel opens and counting those would
	-- report a session for every time the window was looked at.
	function M.recordSession(id, at, quiet)
		local key = tostring(id or "")
		if key ~= "" then
			if seenSet[key] then return false end
			seenSet[key] = true
			M.data.seen[#M.data.seen + 1] = key
			while #M.data.seen > SEEN_LIMIT do table.remove(M.data.seen, 1) end
		end
		local day = dayFor(at)
		bump(day, "sessions")
		bump(M.data.totals, "sessions")
		if not quiet then
			M.save()
			M.changed:fire(M.data)
		end
		return true
	end

	function M.counted(id)
		return seenSet[tostring(id or "")] == true
	end

	-- One inference request, after the fact, with whatever the provider reported.
	-- `delta` is what agent/usage measured for this request alone.
	function M.recordRequest(delta)
		delta = delta or {}
		local at = delta.at or clock.ms()
		local day = dayFor(at)
		local tokensIn = number(delta.prompt)
		local tokensOut = number(delta.completion)
		local cost = number(delta.cost)

		bump(day, "requests")
		bump(day, "tokensIn", tokensIn)
		bump(day, "tokensOut", tokensOut)
		bump(day, "cost", cost)
		bump(M.data.totals, "requests")
		bump(M.data.totals, "tokensIn", tokensIn)
		bump(M.data.totals, "tokensOut", tokensOut)
		bump(M.data.totals, "cached", number(delta.cached))
		bump(M.data.totals, "reasoning", number(delta.reasoning))
		bump(M.data.totals, "cost", cost)
		if delta.estimated then M.data.estimated = true end
		if not M.data.tokensFrom then M.data.tokensFrom = at end

		local model = util.trim(tostring(delta.model or ""))
		if model ~= "" then
			local perDay = day.models[model]
			if not perDay then
				perDay = { requests = 0, tokensIn = 0, tokensOut = 0, cost = 0 }
				day.models[model] = perDay
			end
			bump(perDay, "requests")
			bump(perDay, "tokensIn", tokensIn)
			bump(perDay, "tokensOut", tokensOut)
			bump(perDay, "cost", cost)

			local lifetime = M.data.models[model]
			if not lifetime then
				lifetime = { requests = 0, tokensIn = 0, tokensOut = 0, cost = 0, firstAt = at }
				M.data.models[model] = lifetime
			end
			bump(lifetime, "requests")
			bump(lifetime, "tokensIn", tokensIn)
			bump(lifetime, "tokensOut", tokensOut)
			bump(lifetime, "cost", cost)
			lifetime.lastAt = at
		end

		M.save()
		M.changed:fire(M.data)
	end

	function M.recordTool(name, ok, at)
		local day = dayFor(at)
		bump(day, "toolCalls")
		bump(M.data.totals, "toolCalls")
		if not ok then
			bump(day, "toolErrors")
			bump(M.data.totals, "toolErrors")
		end
		local key = util.trim(tostring(name or ""))
		if key ~= "" then
			if M.data.tools[key] == nil and util.count(M.data.tools) >= TOOL_LIMIT then
				-- A tool list is bounded by the registry, so this only trips if a host
				-- registers its own; dropping the new name is better than growing
				-- without limit.
				key = nil
			end
			if key then M.data.tools[key] = number(M.data.tools[key]) + 1 end
		end
		M.save()
	end

	function M.recordError(at)
		local day = dayFor(at)
		bump(day, "errors")
		bump(M.data.totals, "errors")
		M.save()
	end

	-- Recovering what is already on disk ---------------------------------------

	-- A persisted transcript carries the real timestamp of every message in it, so
	-- the conversations and messages of a client that has been in use since before
	-- this file existed are real history rather than a guess, and are counted once.
	--
	-- Tokens are deliberately not seeded. Nothing on disk records them, and an
	-- estimate would be a number with no measurement behind it.
	function M.seedFromSessions(list)
		if M.data.seededAt then return 0 end
		local messages, conversations = 0, 0
		for _, session in ipairs(list or {}) do
			local first = nil
			for _, message in ipairs((session.ctx and session.ctx.messages) or {}) do
				local role = tostring(message.role or "")
				local body = util.trim(tostring(message.content or ""))
				-- An assistant turn with no prose is a tool-call round, not a reply.
				if role == "user" or (role == "assistant" and body ~= "") then
					local at = tonumber(message.at) or tonumber(session.createdAt) or clock.ms()
					M.recordMessage(role, at, true)
					messages = messages + 1
					if not first then first = at end
				end
			end
			if first and M.recordSession(session.id, first, true) then
				conversations = conversations + 1
			end
		end
		M.data.seededAt = clock.ms()
		if messages > 0 then
			log.info("stats", string.format("%s recovered from %s already on disk",
				util.pluralise(messages, "message"), util.pluralise(conversations, "conversation")))
		end
		M.saveNow()
		M.changed:fire(M.data)
		return messages
	end

	-- Observation --------------------------------------------------------------

	function M.observe()
		if M.observing then return function() end end
		M.observing = true
		local hooks = env.require("agent/hooks")
		local usage = env.require("agent/usage")

		-- Every session event passes through the hook bus, which is how this stays out
		-- of the loop and the session object entirely.
		local unhook = hooks.register("onEvent", function(payload)
			local event = payload and payload.event
			local session = payload and payload.session
			if type(event) ~= "table" then return end
			-- A subagent's requests and tokens are work the conversation asked for and
			-- are counted with it, but its messages are not messages anyone typed or
			-- read: counting those would inflate the card by however many helpers a
			-- turn happened to dispatch.
			local nested = session ~= nil
				and (session.headless == true or (tonumber(session.depth) or 0) > 0)
			local kind = event.kind
			local at = tonumber(event.at) or clock.ms()

			if kind == "user" then
				if nested then return end
				if session then M.recordSession(session.id, at) end
				M.recordMessage("user", at)
			elseif kind == "assistant:text" then
				if nested then return end
				if util.trim(tostring(event.text or "")) ~= "" then
					M.recordMessage("assistant", at)
				end
			elseif kind == "tool:result" then
				M.recordTool(event.name, event.ok ~= false, at)
			elseif kind == "tool:error" then
				M.recordTool(event.name, false, at)
			elseif kind == "error" then
				M.recordError(at)
			end
		end, { name = "stats", order = -1000 })

		local untoken = usage.recorded:connect(function(delta) M.recordRequest(delta) end)

		dispose.add(unhook, "stats.events")
		dispose.add(untoken, "stats.usage")
		-- The last few seconds of a session are the ones the debounce has not written
		-- yet, and an unload is exactly when they would be lost.
		dispose.add(function() M.saveNow() end, "stats.flush")
		return unhook
	end

	function M.init()
		if M.loaded then return M end
		M.load()
		M.observe()
		local ok, err = pcall(function()
			M.seedFromSessions(env.require("agent/session").list())
		end)
		if not ok then log.warn("stats", "could not read history from disk", err) end
		return M
	end

	-- Reading ------------------------------------------------------------------

	local RANGES = { all = 0, ["30d"] = 30, ["7d"] = 7 }
	M.RANGES = { { value = "all", label = "All" }, { value = "30d", label = "30d" }, { value = "7d", label = "7d" } }

	local function dayIsActive(day)
		return number(day.messages) > 0 or number(day.requests) > 0 or number(day.sessions) > 0
	end

	-- A streak is consecutive active days ending today, or ending yesterday when
	-- today has not started yet -- otherwise every streak would read as broken until
	-- the first message of the morning.
	local function streaksOf(active, today, from)
		local current, cursor = 0, today
		if not active[cursor] then cursor = cursor - 1 end
		while active[cursor] and (from == nil or cursor >= from) do
			current = current + 1
			cursor = cursor - 1
		end

		local ordered = {}
		for value in pairs(active) do ordered[#ordered + 1] = value end
		table.sort(ordered)
		local longest, run = 0, 0
		for index, value in ipairs(ordered) do
			if index > 1 and value == ordered[index - 1] + 1 then
				run = run + 1
			else
				run = 1
			end
			if run > longest then longest = run end
		end
		return current, longest
	end

	-- Everything the home card shows for one range, aggregated from the day records
	-- so that "all" and "7d" are the same computation over a different span rather
	-- than two sources that can disagree.
	function M.window(range)
		if not RANGES[range] then range = "all" end
		local span = RANGES[range]
		local today = clock.dayNumber()
		local from = nil
		if span > 0 then from = today - (span - 1) end

		local out = {
			range = range,
			today = clock.keyFromDayNumber(today),
			fromKey = from and clock.keyFromDayNumber(from) or nil,
			activeDays = 0,
			sessions = 0, messages = 0, userMessages = 0, replies = 0,
			tokensIn = 0, tokensOut = 0, tokens = 0, cost = 0,
			requests = 0, toolCalls = 0, toolErrors = 0, errors = 0,
			estimated = M.data.estimated == true,
			hours = {},
			models = {},
			tokensFrom = M.data.tokensFrom,
			startedAt = M.data.startedAt,
		}
		local active, perModel = {}, {}

		for key, day in pairs(M.data.days) do
			local index = clock.dayNumberOfKey(key)
			if index and index <= today and (from == nil or index >= from) then
				out.sessions = out.sessions + number(day.sessions)
				out.messages = out.messages + number(day.messages)
				out.userMessages = out.userMessages + number(day.userMessages)
				out.replies = out.replies + number(day.replies)
				out.tokensIn = out.tokensIn + number(day.tokensIn)
				out.tokensOut = out.tokensOut + number(day.tokensOut)
				out.cost = out.cost + number(day.cost)
				out.requests = out.requests + number(day.requests)
				out.toolCalls = out.toolCalls + number(day.toolCalls)
				out.toolErrors = out.toolErrors + number(day.toolErrors)
				out.errors = out.errors + number(day.errors)
				for hour, count in pairs(day.hours or {}) do
					out.hours[hour] = number(out.hours[hour]) + number(count)
				end
				for id, entry in pairs(day.models or {}) do
					local row = perModel[id]
					if not row then
						row = { id = id, requests = 0, tokensIn = 0, tokensOut = 0, cost = 0 }
						perModel[id] = row
					end
					row.requests = row.requests + number(entry.requests)
					row.tokensIn = row.tokensIn + number(entry.tokensIn)
					row.tokensOut = row.tokensOut + number(entry.tokensOut)
					row.cost = row.cost + number(entry.cost)
				end
				if dayIsActive(day) then
					active[index] = true
					out.activeDays = out.activeDays + 1
				end
			end
		end

		out.tokens = out.tokensIn + out.tokensOut
		out.currentStreak, out.longestStreak = streaksOf(active, today, from)

		local peakHour, peakCount = nil, 0
		for hour = 0, 23 do
			local count = number(out.hours[tostring(hour)])
			if count > peakCount then peakHour, peakCount = hour, count end
		end
		out.peakHour = peakHour
		out.peakHourCount = peakCount

		for _, row in pairs(perModel) do
			row.tokens = row.tokensIn + row.tokensOut
			local lifetime = M.data.models[row.id]
			row.firstAt = lifetime and lifetime.firstAt or nil
			row.lastAt = lifetime and lifetime.lastAt or nil
			out.models[#out.models + 1] = row
		end
		-- Tokens first, then requests: two models with one request each are ordered by
		-- which actually did the work.
		table.sort(out.models, function(a, b)
			if a.tokens ~= b.tokens then return a.tokens > b.tokens end
			if a.requests ~= b.requests then return a.requests > b.requests end
			return a.id < b.id
		end)
		for _, row in pairs(out.models) do
			row.share = out.tokens > 0 and (row.tokens / out.tokens)
				or (out.requests > 0 and (row.requests / out.requests) or 0)
		end
		out.topModel = out.models[1]
		return out
	end

	-- One column per week, seven rows per column, ending on the week that contains
	-- today. Every cell names the day it stands for, so a cell with no record is
	-- reported as a real day with nothing on it rather than as a gap.
	function M.heatmap(weeks)
		weeks = math.max(math.floor(tonumber(weeks) or 26), 1)
		local today = clock.dayNumber()
		-- Monday-based columns, so the last column is the current week.
		local weekday = clock.weekdayOfDayNumber(today)
		local lastMonday = today - (weekday - 1)
		local firstMonday = lastMonday - (weeks - 1) * 7

		local peak = 0
		local columns = {}
		for column = 1, weeks do
			local cells = {}
			for row = 1, 7 do
				local index = firstMonday + (column - 1) * 7 + (row - 1)
				local key = clock.keyFromDayNumber(index)
				local day = M.data.days[key]
				local value = day and (number(day.tokensIn) + number(day.tokensOut)) or 0
				local messages = day and number(day.messages) or 0
				if value > peak then peak = value end
				cells[row] = {
					key = key,
					day = index,
					future = index > today,
					tokens = value,
					messages = messages,
					sessions = day and number(day.sessions) or 0,
					requests = day and number(day.requests) or 0,
					active = day ~= nil and dayIsActive(day),
				}
			end
			columns[column] = cells
		end

		-- Four levels, so a quiet day still reads as activity next to a heavy one.
		for _, cells in ipairs(columns) do
			for _, cell in ipairs(cells) do
				cell.level = 0
				if cell.active then
					cell.level = 1
					if peak > 0 and cell.tokens > 0 then
						local share = cell.tokens / peak
						if share > 0.66 then
							cell.level = 4
						elseif share > 0.33 then
							cell.level = 3
						else
							cell.level = 2
						end
					end
				end
			end
		end
		return { columns = columns, weeks = weeks, peak = peak, fromKey = clock.keyFromDayNumber(firstMonday) }
	end

	-- The comparison the home card ends on. Absent below one whole book, because
	-- "0.4x a book" is a sentence nobody wants and a rounding away from claiming a
	-- book that was not written.
	function M.comparison(tokens)
		local value = number(tokens)
		if value < BOOK.tokens then return nil end
		local times = value / BOOK.tokens
		local rendered = string.format("%d", math.floor(times + 0.5))
		if times < 10 then rendered = string.format("%.1f", times) end
		return string.format("You've used ~%s\195\151 more tokens than %s.", rendered, BOOK.title)
	end

	function M.topTools(limit)
		local out = {}
		for name, count in pairs(M.data.tools) do
			out[#out + 1] = { name = name, count = number(count) }
		end
		table.sort(out, function(a, b)
			if a.count ~= b.count then return a.count > b.count end
			return a.name < b.name
		end)
		if limit and #out > limit then out = util.slice(out, 1, limit) end
		return out
	end

	function M.reset()
		M.data = blank()
		M.data.seededAt = clock.ms()
		rebuildSeen()
		M.saveNow()
		M.changed:fire(M.data)
	end

	return M
end
end)()

-- ==========================================================================
-- agent/subagent
-- ==========================================================================
__UAI_MODULES["agent/subagent"] = (function()
-- Subagent dispatch.
--
-- A subagent is a full session with a smaller tool set, its own context and no
-- interface. It exists to keep long or repetitive work out of the main
-- conversation: the parent pays for one paragraph of report instead of forty tool
-- results, and a search that goes nowhere costs the main context nothing.
--
-- Depth is capped because a subagent that can spawn subagents indefinitely is a
-- fork bomb with a token bill.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local prompt = env.require("agent/prompt")
	local session = env.require("agent/session")

	local M = {}

	-- Groups a subagent may be given. Anything that changes the world is absent
	-- from the read-only preset, which is the default: the point of a subagent is
	-- usually to go and find out, and a delegated write is hard for the user to
	-- attribute afterwards.
	M.PRESETS = {
		read = { instance = true, world = true, players = true, perf = true, meta = true, web = true, net = true, fs = true },
		web = { web = true, net = true },
		game = { instance = true, world = true, players = true, gui = true, remotes = true, meta = true },
		full = nil,
	}

	-- The register.
	--
	-- `live` was a bare counter, which is enough to enforce a ceiling and nothing else:
	-- there was no way to ask what is running, what it was asked to do, or to stop one
	-- of them without stopping the whole turn. A dispatch is the longest-lived and least
	-- visible thing this client does -- minutes of work, its own context, its own tool
	-- calls, and a transcript card that scrolls away -- so each one gets a record here
	-- that outlives its card, and the interface reads this rather than the log.
	--
	-- Bounded, because a long session dispatches a lot: running records are never
	-- dropped, finished ones are kept newest-first up to the history limit.
	--
	-- Of those, only the newest few keep the session they ran on. A child's context is
	-- the expensive half of it -- every tool result it collected -- and holding two dozen
	-- of them for the life of the client would make delegation the largest thing in
	-- memory. So a record outlives its session: the newest are resumable, the rest keep
	-- their report and lose the context behind it.
	local HISTORY = 24
	local RESUMABLE = 6

	M.records = {}
	M.changed = signal.new("subagents")

	local function announceChange()
		M.changed:fire(M.records)
	end

	local function isLive(record)
		return record.status == "running" or record.status == "queued"
	end

	-- Newest first, which is the order the register is held in, so the count runs from
	-- the most recent finished dispatch outward. It used to run from the oldest, which
	-- inverted both rules: the twenty-four kept were the oldest twenty-four, and the
	-- dispatch that had just reported back was the first one dropped.
	local function trimHistory()
		local finished = 0
		local kept = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then
				kept[#kept + 1] = record
			else
				finished = finished + 1
				if finished <= HISTORY then
					if finished > RESUMABLE then
						-- Nothing can address this one any more, so neither reference earns its
						-- keep: the child's context, and the conversation that was waiting on
						-- it. `parentTitle` is a string and stays, because the card still says
						-- where the dispatch came from.
						record.session = nil
						record.parent = nil
					end
					kept[#kept + 1] = record
				end
			end
		end
		M.records = kept
	end

	local function track(record)
		record.startedAt = clock.ms()
		record.status = "queued"
		record.calls = 0
		record.finishedCalls = 0
		record.tools = {}
		table.insert(M.records, 1, record)
		trimHistory()
		announceChange()
		return record
	end

	-- Newest first, running before finished: what a panel wants to draw in order.
	function M.list()
		local running, done = {}, {}
		for _, record in ipairs(M.records) do
			if isLive(record) then
				running[#running + 1] = record
			else
				done[#done + 1] = record
			end
		end
		local out = {}
		for _, record in ipairs(running) do out[#out + 1] = record end
		for _, record in ipairs(done) do out[#out + 1] = record end
		return out
	end

	function M.running()
		local out = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then out[#out + 1] = record end
		end
		return out
	end

	-- The finished dispatches that still have their context, newest first: the ones a
	-- follow-up can be sent to.
	function M.resumable()
		local out = {}
		for _, record in ipairs(M.records) do
			if record.session and not isLive(record) then out[#out + 1] = record end
		end
		return out
	end

	function M.get(id)
		for _, record in ipairs(M.records) do
			if record.id == id then return record end
		end
		return nil
	end

	-- Finds the dispatch the model named.
	--
	-- The id is what the report hands back, so that is the exact match. A label prefix
	-- is accepted too: a model that has lost the id reaches for the task's first line
	-- instead, and refusing that spends a step teaching it nothing.
	function M.find(reference)
		local needle = util.trim(tostring(reference or ""))
		if needle == "" then return nil end
		local exact = M.get(needle)
		if exact then return exact end
		local lowered = needle:lower()
		for _, record in ipairs(M.records) do
			if tostring(record.label):lower():find(lowered, 1, true) then return record end
		end
		return nil
	end

	-- Stops one dispatch without stopping the turn that asked for it.
	--
	-- The child notices between steps, so this returns before it has actually stopped;
	-- the record says so until its loop unwinds. There is no way to kill a Luau thread,
	-- which is why the flag is the mechanism everywhere in this client.
	function M.stop(id)
		local record = M.get(id)
		if not record or not record.session then return false end
		if not isLive(record) then return false end
		record.session.abortFlag = true
		record.stopping = true
		announceChange()
		log.info("subagent", "stop requested for " .. tostring(record.label))
		return true
	end

	function M.stopAll()
		local stopped = 0
		for _, record in ipairs(M.running()) do
			if M.stop(record.id) then stopped = stopped + 1 end
		end
		return stopped
	end

	-- Clears the finished ones. Running dispatches are left alone.
	function M.clearHistory()
		local kept = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then kept[#kept + 1] = record end
		end
		M.records = kept
		announceChange()
		return true
	end

	function M.available(depth)
		local limit = config.get("agent.subagentDepth", 2)
		return (depth or 0) < limit
	end

	-- How long a subagent may run, and how long the tool that started it waits.
	--
	-- Both come from one number on purpose. They used to be independent: the child was
	-- given four minutes and the call that started it was bounded by the generic
	-- `agent.toolTimeout` of twenty-five seconds, so nearly every dispatch was reported
	-- to the model as "did not finish within 25s and was left running in the
	-- background" -- and it was, against a caller that had stopped listening. The
	-- report arrived a minute later with nowhere to go, and the model, asked what its
	-- subagents found, could only say it never heard back.
	--
	-- The slack covers one request. A child notices its own deadline between steps, so
	-- it returns a moment after the budget expires rather than exactly on it, and the
	-- tool has to still be there to take the answer.
	local SLACK_SECONDS = 60

	-- Whether a child runs with its clocks off. Read per run rather than captured, so
	-- flipping the switch applies to the next dispatch and to the next follow-up on a
	-- child that has already reported.
	function M.unlimited()
		return config.get("agent.subagentUnlimited", false) == true
	end

	function M.budgetSeconds()
		return math.max(tonumber(config.get("agent.subagentBudget", 240)) or 240, 15)
	end

	-- A day, and it is not a deadline in disguise: with the ceiling lifted there is no
	-- budget to derive a timeout from, and the honest bound on the call above is "as
	-- long as the child takes". A caller that gives up first is the failure this number
	-- exists to avoid -- the child cannot be killed, so it finishes into a void and the
	-- user pays for a report nobody collects.
	local FOREVER_SECONDS = 86400

	function M.toolTimeout()
		if M.unlimited() then return FOREVER_SECONDS end
		return M.budgetSeconds() + SLACK_SECONDS
	end

	-- Width, not just depth.
	--
	-- Several dispatch_agent calls in one step run at the same time, which is the
	-- point: three searches in parallel cost one step instead of three. What that
	-- leaves unbounded is the tree. `agent.toolConcurrency` caps one batch, so it caps
	-- a parallel dispatch from the main conversation -- but a subagent given the
	-- `full` preset dispatches its own batch under its own cap, and two levels of
	-- that multiply rather than add. This is the ceiling on live children anywhere,
	-- and the depth cap above is no substitute for it.
	M.live = 0

	function M.concurrencyLimit()
		return math.max(tonumber(config.get("agent.subagentConcurrency", 8)) or 8, 1)
	end

	-- A dispatch over the ceiling waits for a slot instead of failing: the model has
	-- already paid for the step that asked, and a refusal would spend another one
	-- learning that it asked for too much at once.
	--
	-- The wait is bounded and comes out of the child's own budget, which is what keeps
	-- `toolTimeout` a valid bound on the call above it. Without that subtraction a
	-- queued child could finish after the tool that started it had given up, and a
	-- report nobody is left to collect is exactly the failure the budget and the
	-- timeout were tied together to prevent.
	--
	-- Returns the budget to run on, `nil` when there is no budget to run against, or
	-- `false` when the turn was stopped while queued. An unlimited child has nothing to
	-- subtract from, so its wait is capped by the ceiling alone.
	local QUEUE_CEILING = 45

	local function waitForSlot(budget, aborted)
		local ceiling = budget and math.min(QUEUE_CEILING, budget / 4) or QUEUE_CEILING
		local waited = 0
		while M.live >= M.concurrencyLimit() and waited < ceiling do
			if aborted and aborted() then return false end
			waited = waited + (clock.wait(0.2) or 0.2)
		end
		if waited <= 0 then return budget end
		log.info("subagent", string.format("queued %.1fs for a slot (%d live)", waited, M.live))
		if not budget then return nil end
		return math.max(budget - waited, 15)
	end

	-- The card in the transcript is titled with the task, so the first line of it is
	-- what the user reads to tell three concurrent subagents apart.
	local function labelFor(task)
		local first = tostring(task):match("^%s*([^\n]*)") or ""
		first = util.trim(first)
		if first == "" then first = "task" end
		return util.ellipsis(first, 64)
	end

	-- Live view.
	--
	-- The transcript renders the parent's event stream and nothing else, so a subagent
	-- that wants to be watched has to speak through it. Every event carries the child's
	-- id, which keys the card, and the id of the tool call that started it, which tells
	-- the view what to nest the card under.
	--
	-- One subscription per child, made with it and kept for the rest of its life: a
	-- follow-up runs the same session again, and a second subscription would draw every
	-- row twice. Which conversation to narrate into is read off the record rather than
	-- captured here, for the same reason -- the turn asking a follow-up is a different
	-- tool call, sometimes in a different conversation, and the card has to appear under
	-- the row the user is looking at now.
	--
	-- Tool RESULTS are summarised to one line rather than forwarded: absorbing that
	-- volume is the entire point of a subagent, and the parent's log is bounded. What
	-- does go across is names, outcomes and timings, because that is the difference
	-- between watching work happen and watching a spinner.
	local function wire(record, child)
		local function announce(kind, payload)
			local parent = record.parent
			if not parent then return end
			payload = payload or {}
			payload.id = record.id
			payload.call = record.callId
			payload.label = record.label
			parent.emit(kind, payload)
		end
		record.announce = announce

		-- Stop has to reach the child, from whichever conversation is waiting on it.
		-- Without this, aborting the turn left every dispatched subagent running out its
		-- full budget against a conversation that had already moved on -- billed,
		-- invisible and unstoppable.
		child.aborted = function()
			if child.abortFlag == true then return true end
			local parent = record.parent
			return parent ~= nil and parent.aborted() == true
		end

		child.events:connect(function(event)
			if event.kind == "tool:call" then
				record.calls = (record.calls or 0) + 1
				record.currentTool = tostring(event.name)
				-- Names only, and the last twelve of them: the register is read by a
				-- panel that lists every dispatch in the session, so it cannot hold
				-- their arguments as well.
				record.tools[#record.tools + 1] = tostring(event.name)
				if #record.tools > 12 then table.remove(record.tools, 1) end
				announceChange()
				announce("subagent:tool", {
					callId = event.id,
					name = event.name,
					risk = event.risk,
					-- Forwarded whole, and summarised by the view instead.
					--
					-- A child session is headless and therefore keeps no log of its own, so
					-- this event is the only record that the call ever happened. At 160
					-- characters, whitespace-collapsed, the Luau a subagent executed was
					-- unrecoverable -- and a subagent is exactly where the long-running code
					-- in this client gets run. The parent's log is bounded at 400 events,
					-- which is what caps the cost of keeping it.
					arguments = tostring(event.arguments or ""),
					index = record.calls,
				})
			elseif event.kind == "tool:result" or event.kind == "tool:error" then
				record.finishedCalls = (record.finishedCalls or 0) + 1
				announceChange()
				announce("subagent:tool:done", {
					callId = event.id,
					name = event.name,
					ok = event.kind == "tool:result",
					ms = event.ms,
					summary = util.ellipsis(tostring(event.text or ""):gsub("%s+", " "), 140),
					-- The full result as well, for the row that can open. `summary` is what
					-- the collapsed line shows and stays short.
					text = tostring(event.text or ""),
				})
			elseif event.kind == "assistant:text" then
				if util.trim(tostring(event.text or "")) ~= "" then
					announce("subagent:text", { text = util.ellipsis(util.trim(event.text), 400) })
				end
			elseif event.kind == "status" then
				-- "Ready" is the child's own idle text and means nothing on a card that
				-- reports its finish separately. Dropping it here rather than in the
				-- view keeps one entry per turn out of the parent's bounded log.
				if tostring(event.text) ~= "Ready" then
					record.statusText = tostring(event.text)
					announceChange()
					announce("subagent:status", { text = tostring(event.text) })
				end
			elseif event.kind == "error" then
				record.statusText = tostring(event.message)
				announceChange()
				announce("subagent:status", { text = tostring(event.message), bad = true })
			elseif event.kind == "permission:ask" then
				-- Nothing is subscribed to a headless session, so a prompt raised
				-- inside a subagent has to surface on the parent's stream or it
				-- would sit unanswered until its own deadline.
				local parent = record.parent
				if parent then parent.emit("permission:ask", event) end
			end
		end)
	end

	-- One run of a child: the slot, the announcement, the loop and the report. Shared
	-- by the first dispatch and by every follow-up, so a resumed subagent is watched,
	-- counted and bounded exactly like a fresh one.
	--
	-- Everything a run needs is read here rather than fixed when the child was created,
	-- because a second turn is a different turn: a different caller, and possibly a
	-- different answer from the unlimited switch.
	local function runChild(record, text, opts)
		opts = opts or {}
		local child = record.session
		local unlimited = M.unlimited()
		local announce = record.announce

		local budget = waitForSlot(unlimited and nil or (opts.budgetSeconds or M.budgetSeconds()),
			record.parent and record.parent.aborted or nil)
		if budget == false then
			record.status = "stopped"
			record.ms = clock.since(record.startedAt)
			record.report = "Stopped before it started."
			announceChange()
			return nil, "the turn was stopped before this subagent started"
		end

		child.abortFlag = false
		child.unlimited = unlimited
		child.budgetSeconds = budget
		if opts.turns then child.maxTurns = opts.turns end
		record.status = "running"
		record.stopping = nil
		record.startedAt = clock.ms()
		record.budget = budget
		record.unlimited = unlimited
		record.turns = child.maxTurns
		record.runs = (record.runs or 0) + 1
		announceChange()

		announce("subagent:start", {
			task = util.ellipsis(text, 400),
			preset = record.preset,
			turns = unlimited and 0 or child.maxTurns,
			budget = budget,
			unlimited = unlimited,
			depth = record.depth,
			followUp = record.runs > 1,
		})

		-- Counted around the pcall rather than around the whole setup, so a raise
		-- anywhere inside cannot leak a slot and permanently narrow the ceiling.
		local started = clock.ms()
		M.live = M.live + 1
		local ok, reply = pcall(env.require("agent/loop").run, child, text)
		M.live = math.max(M.live - 1, 0)

		local elapsed = clock.since(started)
		if not ok then
			log.warn("subagent", "failed", reply)
			local note = "the subagent failed: " .. util.ellipsis(tostring(reply), 200)
			record.status = "failed"
			record.ms = elapsed
			record.report = note
			record.currentTool = nil
			announceChange()
			announce("subagent:done", { ms = elapsed, ok = false, text = note })
			return nil, note
		end

		local stats = child.ctx.stats()
		local aborted = child.aborted() == true
		log.info("subagent", string.format("finished in %s over %d messages%s",
			util.formatDuration(elapsed), stats.messages, aborted and " (stopped)" or ""))

		record.status = aborted and "stopped" or "done"
		record.ms = elapsed
		record.messages = stats.messages
		record.turnsUsed = stats.turns
		record.report = tostring(reply)
		record.currentTool = nil
		record.stopping = nil
		-- Now that this one has finished, it is the newest resumable record -- which is
		-- what pushes the oldest past the line and releases the context behind it.
		trimHistory()
		announceChange()

		announce("subagent:done", {
			ms = elapsed,
			ok = not aborted,
			aborted = aborted,
			messages = stats.messages,
			turns = stats.turns,
			resumable = record.session ~= nil and not aborted,
			text = util.ellipsis(tostring(reply), 600),
		})

		return {
			id = record.id,
			text = tostring(reply),
			ms = elapsed,
			messages = stats.messages,
			turns = stats.turns,
			aborted = aborted,
			resumable = record.session ~= nil,
		}
	end

	-- Blocks until the subagent finishes. The caller is already on a tool thread, so
	-- yielding here is correct; the tool timeout above it comes from M.toolTimeout so it
	-- outlasts the child rather than the other way round.
	function M.dispatch(opts)
		local parent = opts.parent
		local depth = (parent and parent.depth or 0) + 1

		if not M.available(depth - 1) then
			return nil, "subagent depth limit reached (" .. tostring(config.get("agent.subagentDepth", 2)) .. ")"
		end

		local task_text = util.trim(opts.task)
		if task_text == "" then return nil, "a subagent needs a task" end

		local turns = opts.turns or config.get("agent.subagentTurns", 14)

		-- Registered before the queue wait, so a dispatch parked waiting for a slot is
		-- visible as one rather than looking like nothing happened.
		local record = track({
			id = util.uid("agent"),
			label = labelFor(task_text),
			task = task_text,
			preset = opts.preset or "read",
			depth = depth,
			-- The conversation currently waiting on this child, and the tool call inside
			-- it. Both move when a follow-up arrives from somewhere else, which is why
			-- they live on the record rather than in a closure.
			parent = parent,
			callId = opts.callId,
			parentId = parent and parent.id or nil,
			parentTitle = parent and parent.title or nil,
			turns = turns,
		})

		local child = session.create({
			title = "subagent",
			depth = depth,
			headless = true,
			maxTurns = turns,
			toolGroups = M.PRESETS[opts.preset or "read"],
			-- Streaming is left to the provider and the Ask-for-streams setting, the
			-- same as the main conversation. It used to be refused here, on the reading
			-- that a child with no interface has nothing to stream into -- but no Roblox
			-- transport delivers a body incrementally anyway, so that bought nothing and
			-- cost the two things the streamed shape carries: reasoning text, and the
			-- per-request usage block some gateways report token counts in at all. Every
			-- subagent request landing without one was enough to mark the whole session's
			-- cost readout estimated.
		})
		-- The record is what the Subagents panel reads, so it is kept whether or not
		-- there is a parent transcript to narrate into. The wiring below is therefore
		-- unconditional; only the forwarding inside it is not.
		record.session = child

		-- The brief replaces the main system prompt rather than appending to it, and it
		-- is a function so that every turn -- including a follow-up months of tool calls
		-- later -- is built against the environment and the switches in force then.
		-- Carrying it on the session, instead of swapping the prompt module's builder, is
		-- what makes two subagents dispatched in the same batch safe.
		child.systemPrompt = function()
			return prompt.subagent(task_text, {
				extra = opts.extra,
				unlimited = M.unlimited(),
			})
		end

		wire(record, child)
		return runChild(record, task_text, {
			turns = opts.turns,
			budgetSeconds = opts.budgetSeconds,
		})
	end

	-- A second turn on a subagent that has already reported back.
	--
	-- A dispatch used to be one shot: the child answered, its context went on the floor,
	-- and a parent that wanted one more fact had to describe the whole job again to a
	-- fresh subagent that would go and rediscover it. This continues the same
	-- conversation instead -- the child still has everything it found -- which is what
	-- makes a subagent that stopped at a limit worth talking to rather than worth
	-- replacing, and what lets the parent steer one instead of only reading it.
	function M.followUp(opts)
		local record = M.find(opts.id)
		if not record then
			local open = M.resumable()
			if #open == 0 then
				return nil, "no subagent is open for a follow-up. Dispatch one with dispatch_agent first."
			end
			local names = {}
			for _, candidate in ipairs(open) do
				names[#names + 1] = string.format("%s (%s)", candidate.id, candidate.label)
			end
			return nil, string.format("no subagent matches '%s'. Open for a follow-up: %s",
				tostring(opts.id), table.concat(names, "; "))
		end
		if isLive(record) then
			return nil, "that subagent is still working. Its report will arrive on the call that started it."
		end
		if not record.session then
			return nil, "that subagent's context has already been released, so there is nothing to continue. Dispatch a new one with what you know."
		end

		local text = util.trim(opts.task)
		if text == "" then return nil, "a follow-up needs a message" end

		record.parent = opts.parent or record.parent
		record.callId = opts.callId
		return runChild(record, text, { turns = opts.turns })
	end

	return M
end
end)()

-- ==========================================================================
-- agent/usage
-- ==========================================================================
__UAI_MODULES["agent/usage"] = (function()
-- Token and cost accounting.
--
-- Providers report usage inconsistently -- some only in a streamed final chunk,
-- some not at all -- so counts are taken from the response when present and
-- estimated when not, and an estimated figure is always labelled as one. Prices
-- are a convenience, not an invoice: they are per million tokens, they date from
-- when this was written, and the panel says so.
return function(env)
	local util = env.require("runtime/util")
	local signal = env.require("runtime/signal")

	local M = {
		session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false },
		turn = { prompt = 0, completion = 0, total = 0, cost = 0 },
		changed = signal.new("usage"),
		-- One request, as it was measured, rather than the running totals `changed`
		-- carries. This is the only place in the client where a model id and the tokens
		-- it actually spent are in scope together, so anything keeping a per-model
		-- history has to hear about it here.
		recorded = signal.new("usage:recorded"),
	}

	-- input, output per million tokens. Matched longest-prefix, so a dated model
	-- id still resolves.
	--
	-- The current Claude generations are listed individually because the family
	-- names no longer predict the price: an Opus has cost $5/$25 since 4.6, a third
	-- of what the 4.5-and-earlier line did, and reporting the old number made every
	-- turn in this client look three times more expensive than it was.
	local PRICES = {
		["gpt-4o-mini"] = { 0.15, 0.60 },
		["gpt-4o"] = { 2.50, 10.00 },
		["gpt-4.1-mini"] = { 0.40, 1.60 },
		["gpt-4.1"] = { 2.00, 8.00 },
		["o4-mini"] = { 1.10, 4.40 },
		["claude-haiku"] = { 1.00, 5.00 },
		["claude-sonnet"] = { 3.00, 15.00 },
		["claude-sonnet-5"] = { 2.00, 10.00 },
		["claude-opus"] = { 15.00, 75.00 },
		["claude-opus-4-6"] = { 5.00, 25.00 },
		["claude-opus-4-7"] = { 5.00, 25.00 },
		["claude-opus-4-8"] = { 5.00, 25.00 },
		["claude-opus-5"] = { 5.00, 25.00 },
		-- Covers the .1 revisions too: the id is a superstring of this prefix.
		["claude-fable-5"] = { 10.00, 50.00 },
		["claude-mythos-5"] = { 10.00, 50.00 },
		["deepseek-reasoner"] = { 0.55, 2.19 },
		["deepseek-chat"] = { 0.27, 1.10 },
		["llama-3.3-70b"] = { 0.59, 0.79 },
		["llama-3.1-8b"] = { 0.05, 0.08 },
		["mistral-large"] = { 2.00, 6.00 },
		["mistral-small"] = { 0.20, 0.60 },
		["grok-4"] = { 3.00, 15.00 },
		["grok-3-mini"] = { 0.30, 0.50 },
		["qwen"] = { 0.40, 0.80 },
		["gemini-2.5-flash"] = { 0.30, 2.50 },
	}

	function M.priceFor(model)
		local id = tostring(model or ""):lower()
		local best, bestLength = nil, 0
		for prefix, price in pairs(PRICES) do
			if id:find(prefix, 1, true) and #prefix > bestLength then
				best, bestLength = price, #prefix
			end
		end
		return best
	end

	-- Four characters per token is the usual English approximation; it is within
	-- about ten percent for prose and pessimistic for code, which is the right
	-- direction for a context budget.
	function M.estimateText(text)
		if type(text) ~= "string" then return 0 end
		return math.ceil(#text / 4)
	end

	function M.estimateMessages(messages)
		local total = 0
		for _, message in ipairs(messages or {}) do
			-- Per-message framing overhead, plus the role name.
			total = total + 4 + M.estimateText(message.content)
			-- Internal messages carry toolCalls; wire messages carry tool_calls, and
			-- the loop estimates over the wire form.
			for _, call in ipairs(message.toolCalls or message.tool_calls or {}) do
				local fn = call["function"] or {}
				total = total + 8 + M.estimateText(fn.name) + M.estimateText(fn.arguments)
			end
		end
		return total
	end

	function M.startTurn()
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
	end

	-- `usage` is the provider block when it exists. `fallback` supplies estimates
	-- so a provider that reports nothing still moves the counters.
	function M.record(usage, model, fallback)
		local prompt, completion, estimated
		if type(usage) == "table" and (usage.prompt_tokens or usage.completion_tokens) then
			prompt = tonumber(usage.prompt_tokens) or 0
			completion = tonumber(usage.completion_tokens) or 0
			estimated = false
		else
			prompt = (fallback and fallback.prompt) or 0
			completion = (fallback and fallback.completion) or 0
			estimated = true
		end

		local price = M.priceFor(model)
		local cost = 0
		if price then
			cost = (prompt / 1000000) * price[1] + (completion / 1000000) * price[2]
		end

		M.turn.prompt = M.turn.prompt + prompt
		M.turn.completion = M.turn.completion + completion
		M.turn.total = M.turn.prompt + M.turn.completion
		M.turn.cost = M.turn.cost + cost

		M.session.prompt = M.session.prompt + prompt
		M.session.completion = M.session.completion + completion
		M.session.total = M.session.prompt + M.session.completion
		M.session.cost = M.session.cost + cost
		M.session.requests = M.session.requests + 1
		if estimated then M.session.estimated = true end

		local cached = util.get(usage or {}, "prompt_tokens_details.cached_tokens", 0)
		local reasoning = util.get(usage or {}, "completion_tokens_details.reasoning_tokens", 0)
		M.session.cached = (M.session.cached or 0) + (tonumber(cached) or 0)
		M.session.reasoning = (M.session.reasoning or 0) + (tonumber(reasoning) or 0)

		local delta = {
			model = model,
			prompt = prompt,
			completion = completion,
			cost = cost,
			estimated = estimated,
			cached = tonumber(cached) or 0,
			reasoning = tonumber(reasoning) or 0,
		}
		M.recorded:fire(delta)
		M.changed:fire(M.session, M.turn)
		return { prompt = prompt, completion = completion, cost = cost, estimated = estimated }
	end

	function M.reset()
		M.session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false }
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
		M.changed:fire(M.session, M.turn)
	end

	function M.formatCost(value)
		if value <= 0 then return "" end
		if value < 0.01 then return string.format("$%.4f", value) end
		return string.format("$%.3f", value)
	end

	function M.line()
		local parts = {
			util.formatNumber(M.session.total) .. " tokens",
			util.formatNumber(M.session.prompt) .. " in",
			util.formatNumber(M.session.completion) .. " out",
		}
		local cost = M.formatCost(M.session.cost)
		if cost ~= "" then parts[#parts + 1] = cost .. (M.session.estimated and " est." or "") end
		return table.concat(parts, "  ")
	end

	return M
end
end)()

