-- ==========================================================================
-- provider/chat
-- ==========================================================================
__UAI_MODULES["provider/chat"] = (function()
-- Picks the wire protocol for a provider record.
--
-- Two adapters implement the same contract -- provider/openai for anything speaking
-- /chat/completions, provider/anthropic for the Messages API -- and this is the only
-- place that decides which one a record uses. Everything above it (the agent loop,
-- the transcript, the connection test) is written against one shape and does not
-- know there is a choice.
--
-- `record.api` is the switch. It is absent on every record saved before the second
-- adapter existed, and absent means OpenAI, so nothing needs migrating.
return function(env)
	local M = {}

	M.STYLES = {
		{ value = "openai", label = "Chat completions" },
		{ value = "anthropic", label = "Anthropic messages" },
	}

	function M.styleOf(record)
		return (tostring(record and record.api or "openai") == "anthropic")
			and "anthropic" or "openai"
	end

	function M.adapterFor(record)
		if M.styleOf(record) == "anthropic" then
			return env.require("provider/anthropic")
		end
		return env.require("provider/openai")
	end

	function M.complete(record, request)
		return M.adapterFor(record).complete(record, request)
	end

	function M.errorText(record, res, err)
		return M.adapterFor(record).errorText(res, err)
	end

	-- The headers a record's requests carry, including the ones its wire protocol
	-- requires. Model discovery hits the same host, so it asks for these too rather
	-- than assembling auth itself and getting the Anthropic case wrong.
	function M.headers(record)
		local adapter = M.adapterFor(record)
		if adapter.headers then return adapter.headers(record) end
		local headers = env.require("provider/registry").authHeaders(record)
		for key, value in pairs(record.headers or {}) do headers[key] = value end
		return headers
	end

	-- The path a record's completions go to, for the Providers panel to show.
	function M.endpointOf(record)
		local adapter = M.adapterFor(record)
		if adapter.endpoint then return adapter.endpoint(record) end
		return env.require("provider/registry").endpoint(record, "/chat/completions")
	end

	return M
end
end)()

-- ==========================================================================
-- provider/models
-- ==========================================================================
__UAI_MODULES["provider/models"] = (function()
-- Model discovery and the record's own model list.
--
-- The endpoint is the only authority on what it serves, so nothing here invents a
-- model id. Two sources, in this order:
--
--   1. what the user added by hand, which always wins because they typed it
--   2. what GET /v1/models reported, cached for the session
--
-- Nothing is filtered out of a provider's answer. A local server that also serves
-- embedding models will list them; hiding entries would mean guessing which ones
-- are chat models, which is the thing this module refuses to do.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local http = env.require("net/http")
	local registry = env.require("provider/registry")
	local signal = env.require("runtime/signal")

	local CACHE_MS = 10 * 60 * 1000

	local M = {
		cache = {},
		changed = signal.new("models"),
	}

	function M.cached(providerId)
		local entry = M.cache[providerId]
		if not entry then return nil end
		if clock.since(entry.at) > CACHE_MS then return nil end
		return entry.models
	end

	function M.discovered(record)
		return M.cached(record.id) or {}
	end

	-- Manual entry. The id is stored on the record, so it survives a restart and is
	-- offered first from then on.
	function M.add(record, id, opts)
		opts = opts or {}
		local clean = util.trim(id)
		if clean == "" then return false, "type a model id" end
		if #clean > 160 then return false, "that does not look like a model id" end
		record.models = record.models or {}
		for _, existing in ipairs(record.models) do
			if existing == clean then
				if opts.select then record.model = clean end
				return false, "already in the list"
			end
		end
		table.insert(record.models, 1, clean)
		if opts.select ~= false then record.model = clean end
		if opts.persist ~= false then registry.save(record, { force = true }) end
		M.changed:fire(record.id, record.models)
		return true, clean
	end

	function M.remove(record, id, opts)
		opts = opts or {}
		local kept = {}
		local removed = false
		for _, existing in ipairs(record.models or {}) do
			if existing == id then
				removed = true
			else
				kept[#kept + 1] = existing
			end
		end
		record.models = kept
		if record.model == id then record.model = kept[1] or "" end
		if removed then
			if opts.persist ~= false then registry.save(record, { force = true }) end
			M.changed:fire(record.id, kept)
		end
		return removed
	end

	-- The merged list, without touching the network.
	function M.list(record)
		local out, seen = {}, {}
		for _, id in ipairs(record.models or {}) do
			if util.trim(id) ~= "" and not seen[id] then
				seen[id] = true
				out[#out + 1] = id
			end
		end
		for _, id in ipairs(M.cached(record.id) or {}) do
			if not seen[id] then
				seen[id] = true
				out[#out + 1] = id
			end
		end
		return out
	end

	-- Yields. Returns the discovered ids and a note describing what happened, which
	-- the panel shows next to the fetch control. A provider with no /models route is
	-- a normal outcome, not an error: the user types the id instead.
	function M.discover(record, opts)
		opts = opts or {}
		if not opts.force then
			local hit = M.cached(record.id)
			if hit then return hit, "cached" end
		end

		local url = registry.endpoint(record, "/models")
		local headers = env.require("provider/chat").headers(record)

		local decoded, err, res = http.json({
			url = url,
			method = "GET",
			headers = headers,
			identity = (record.claudeUa ~= false) and "claude" or "none",
			attempts = 2,
			tag = "models:" .. record.id,
		})

		if not decoded then
			local note = "could not read " .. url
			if res and res.status == 404 then note = "this endpoint has no /models route -- add a model by hand" end
			if res and res.status == 401 then note = "the API key was rejected" end
			if res and res.status == 403 then note = "the key is not allowed to list models" end
			log.info("models", record.label .. ": " .. note, err)
			return {}, note
		end

		-- The documented shape is { data = { { id = ... } } }. Some servers answer
		-- with a bare array, and Ollama answers with { models = { { name = ... } } }.
		local rows = decoded.data or decoded.models or decoded
		local found, seen = {}, {}
		if type(rows) == "table" then
			for _, row in ipairs(rows) do
				local id
				if type(row) == "string" then
					id = row
				elseif type(row) == "table" then
					id = row.id or row.name or row.model
				end
				if type(id) == "string" and util.trim(id) ~= "" and not seen[id] then
					seen[id] = true
					found[#found + 1] = util.trim(id)
				end
			end
		end

		table.sort(found)
		M.cache[record.id] = { at = clock.ms(), models = found }
		M.changed:fire(record.id, found)

		if #found == 0 then
			return {}, "the endpoint returned an empty list -- add a model by hand"
		end
		return found, string.format("%d model%s from %s", #found, #found == 1 and "" or "s", url)
	end

	function M.invalidate(providerId)
		if providerId then
			M.cache[providerId] = nil
		else
			M.cache = {}
		end
	end

	return M
end
end)()

-- ==========================================================================
-- provider/openai
-- ==========================================================================
__UAI_MODULES["provider/openai"] = (function()
-- The OpenAI chat-completions adapter.
--
-- One request shape in, one normalised result out. Everything vendor-specific
-- lives here: auth style, the streaming decision, error extraction, and the
-- parameter repairs that make the same call work across a dozen gateways that all
-- claim to be OpenAI-compatible and none of which quite are.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local http = env.require("net/http")
	local sse = env.require("net/sse")
	local registry = env.require("provider/registry")
	local traits = env.require("provider/traits")

	local M = {}

	-- Messages are rewritten into the wire shape rather than passed through, so a
	-- field the context store finds useful (reasoning text, timing, ids) cannot
	-- leak into a payload and trip a gateway that rejects unknown fields.
	function M.wireMessages(messages)
		local out = {}
		for _, message in ipairs(messages or {}) do
			local entry = { role = message.role }
			if message.role == "tool" then
				entry.tool_call_id = message.tool_call_id
				entry.content = tostring(message.content or "")
			elseif message.toolCalls and #message.toolCalls > 0 then
				-- An assistant turn that called tools must replay those calls
				-- verbatim, and content may legitimately be an empty string.
				entry.content = message.content or ""
				entry.tool_calls = {}
				for _, call in ipairs(message.toolCalls) do
					entry.tool_calls[#entry.tool_calls + 1] = {
						id = call.id,
						type = "function",
						["function"] = {
							name = call["function"] and call["function"].name or call.name,
							arguments = call["function"] and call["function"].arguments or call.arguments or "{}",
						},
					}
				end
			else
				entry.content = tostring(message.content or "")
			end
			out[#out + 1] = entry
		end
		return out
	end

	function M.buildBody(record, request)
		local body = {
			messages = M.wireMessages(request.messages),
		}

		-- Azure takes the model from the deployment in the URL and rejects the
		-- field; everyone else requires it.
		if record.preset ~= "azure" and util.trim(record.model) ~= "" then
			body.model = record.model
		end

		if request.tools and #request.tools > 0 then
			body.tools = request.tools
			body.tool_choice = request.toolChoice or "auto"
			if request.parallelToolCalls ~= false then
				body.parallel_tool_calls = true
			end
		end

		-- Sampling parameters are rejected outright by the current Claude generations
		-- rather than ignored, so a model documented to refuse one is never sent it.
		-- Every other model keeps the behaviour it has always had, because
		-- withholding a parameter a gateway would have honoured is its own bug.
		local temperature = request.temperature
		if temperature == nil then temperature = config.get("agent.temperature", 0.4) end
		if temperature and traits.allowsSampling(record.model) then
			body.temperature = temperature
		end

		local maxTokens = M.cappedMaxTokens(record, request.maxTokens or config.get("agent.maxTokens", 4096))
		if maxTokens and maxTokens > 0 then body.max_tokens = maxTokens end

		-- Reasoning depth, spelled the way the chat-completions wire spells it. Only
		-- sent to a model with a scale to place it on, and clamped to that scale, so
		-- asking for more than a model has is a smaller request rather than a refusal.
		local effort = M.effortFor(record, request)
		if effort then body.reasoning_effort = effort end

		if request.stream then
			body.stream = true
			body.stream_options = { include_usage = true }
		end

		for key, value in pairs(record.params or {}) do body[key] = value end
		for key, value in pairs(request.extra or {}) do body[key] = value end
		return body
	end

	-- Error text, in the order gateways actually use. A 401 with an empty body is
	-- common enough that the status alone has to produce something readable.
	local STATUS_TEXT = {
		[400] = "the provider rejected the request",
		[401] = "the API key was rejected",
		[402] = "the account is out of credit",
		[403] = "the provider refused the request -- the key may lack access to it",
		[404] = "endpoint or model not found -- check the base URL and model name",
		[413] = "the request was too large",
		[422] = "the provider could not process the request",
		[429] = "rate limited",
		[500] = "the provider had an internal error",
		[502] = "the provider gateway is unavailable",
		[503] = "the provider is overloaded",
		[529] = "the provider is overloaded",
	}

	-- An HTML body on a refusal is not the API talking.
	--
	-- A gateway answers in JSON. A whole HTML document -- especially one opening with
	-- Cloudflare's `<!--[if lt IE 7]>` conditional-comment block -- means the request was
	-- stopped in front of the API and never reached the account, the key or the model. So
	-- naming any of those as a possible cause, which the 403 text did, sends the reader
	-- off to check three things that are all fine. The response headers say which edge it
	-- was: `server`, `cf-ray` and `cf-mitigated` are already kept for the Requests view.
	local function edgeBlock(res)
		if not res then return nil end
		local body = util.trim(tostring(res.body or ""))
		if body == "" then return nil end
		local head = body:sub(1, 400):lower()
		local looksHtml = body:sub(1, 1) == "<"
			and (head:find("<!doctype", 1, true) or head:find("<html", 1, true)
				or head:find("<!--[if", 1, true))
		if not looksHtml then return nil end
		local bits = {}
		local server = util.trim(tostring(http.header(res, "server") or ""))
		local mitigated = util.trim(tostring(http.header(res, "cf-mitigated") or ""))
		local ray = util.trim(tostring(http.header(res, "cf-ray") or ""))
		if server ~= "" then bits[#bits + 1] = server end
		if mitigated ~= "" then bits[#bits + 1] = "cf-mitigated " .. mitigated end
		if ray ~= "" then bits[#bits + 1] = ray end
		return #bits > 0 and table.concat(bits, ", ") or "an edge in front of the API"
	end

	function M.errorText(res, err)
		if err and not res then return tostring(err) end
		local status = res and res.status or 0
		-- Checked before the status table, because the status is the least informative
		-- thing about this class of failure.
		local edge = edgeBlock(res)
		if edge then
			return string.format(
				"stopped before it reached the API (%d) by %s. It answered with an HTML page "
				.. "rather than JSON, so the key, the model and the account are not implicated -- "
				.. "the request itself was refused. Turning off the Claude Code identity for this "
				.. "provider is the one thing this client can change about how it looks.",
				status, edge)
		end
		local decoded = res and util.decode(res.body) or nil
		local message
		if type(decoded) == "table" then
			if type(decoded.error) == "table" then
				message = decoded.error.message or decoded.error.type or decoded.error.code
			elseif type(decoded.error) == "string" then
				message = decoded.error
			elseif type(decoded.message) == "string" then
				message = decoded.message
			elseif type(decoded.detail) == "string" then
				message = decoded.detail
			end
		end
		if not message or message == "" then
			local raw = res and util.trim(res.body) or ""
			if raw ~= "" and #raw < 400 and not raw:find("^<") then
				message = raw
			end
		end
		local prefix = STATUS_TEXT[status]
		-- A refusal that carries no body at all is worth naming as such. It usually
		-- means the call never reached the API, so nothing about the key or the model
		-- accounts for it, and the answer is in the response headers the Requests view
		-- now keeps rather than anywhere in this string.
		if (not message or message == "") and res and util.trim(res.body or "") == "" then
			return string.format("%s (%d), and the response had no body -- see the Requests view",
				prefix or "the request was refused", status)
		end
		if message and prefix then return string.format("%s (%d): %s", prefix, status, message) end
		if message then return string.format("%s (%d)", message, status) end
		if prefix then return string.format("%s (%d)", prefix, status) end
		return string.format("request failed with status %d", status)
	end

	-- The output ceiling a refusal names, or nil when it names nothing usable.
	--
	-- Every model has its own max_tokens limit and no endpoint publishes it: /models
	-- reports ids, not capabilities. The one place the number appears is the 400 that
	-- comes back when a request exceeds it, and the wording is different everywhere --
	-- "max_tokens: 200000 > 64000, which is the maximum allowed number of output
	-- tokens for claude-sonnet-4-5-20250929", "max_tokens is too large: 200000. This
	-- model supports at most 16384 completion tokens", "must be less than or equal to
	-- 8192". What they share is that the limit is the largest number in the sentence
	-- below what was sent, so that is what is taken.
	--
	-- The floor is a thousand and it is load-bearing: the status code is part of the
	-- text this is handed, and clamping a reply ceiling to 400 tokens because "(400)"
	-- appeared in the prefix would be worse than the original error. Nothing caps
	-- output below a thousand tokens.
	function M.ceilingFromMessage(message, current)
		current = tonumber(current) or 0
		if current <= 0 then return nil end
		local best
		for digits in tostring(message or ""):gmatch("%d+") do
			local number = tonumber(digits)
			if number and number >= 1000 and number < current and (not best or number > best) then
				best = number
			end
		end
		if best then return best end
		-- Nothing quotable. Halving converges in a couple of attempts and cannot loop,
		-- because each attempt is a fresh request against a smaller number.
		local halved = math.floor(current / 2)
		return (halved >= 1000) and halved or nil
	end

	-- The ceiling to actually send: what the user asked for, lowered to whatever this
	-- record has already been told its model allows.
	--
	-- Kept per model rather than per record, because the limit belongs to the model.
	-- Pointing a record at a wider Claude has to stop clamping it to the narrower
	-- one's limit, and there would be nothing on screen to explain it if it did not:
	-- the slider would read 64k while every request asked for 32k.
	function M.cappedMaxTokens(record, wanted)
		wanted = tonumber(wanted) or 0
		-- What the model documents comes first, so a slider set above a model's
		-- ceiling costs nothing to discover. What a refusal actually taught this
		-- record still applies after it, because the gateway is the final word on
		-- what it will accept.
		local documented = traits.maxOutput(record.model)
		if documented and wanted > documented then wanted = documented end
		local cap = record.maxTokensCap
		if type(cap) ~= "table" or cap.model ~= record.model then return wanted end
		local limit = tonumber(cap.tokens) or 0
		if limit > 0 and wanted > limit then return limit end
		return wanted
	end

	-- The effort level to send, or nil for none. Both adapters ask this and differ
	-- only in how the answer is spelled on the wire.
	--
	-- Clamped to the model's own scale rather than passed through, because the scales
	-- differ by generation -- "xhigh" arrived after 4.6 -- and a level a model has
	-- never heard of is a refusal rather than a rounding.
	function M.effortFor(record, request)
		local wanted = request and request.effort
		if wanted == nil then wanted = config.get("agent.effort", "high") end
		wanted = tostring(wanted or "")
		if wanted == "" or wanted == "off" then return nil end
		return traits.nearestEffort(record and record.model, wanted)
	end

	-- Stores what a refusal named, against the model it came from. Both adapters call
	-- this; the record persists, so the lesson outlives the session.
	function M.rememberMaxTokens(record, tokens)
		record.maxTokensCap = { model = record.model, tokens = tokens }
		registry.save(record, { force = true })
	end

	-- Gateways reject different subsets of the payload. Rather than maintaining a
	-- per-vendor allowlist that goes stale, a 400 whose text names a field is
	-- repaired once and retried -- and the repair is remembered on the record so
	-- the next turn does not pay for it again.
	local REPAIRS = {
		{
			match = "max_completion_tokens",
			apply = function(body)
				if body.max_tokens then
					body.max_completion_tokens = body.max_tokens
					body.max_tokens = nil
					return "renamed max_tokens to max_completion_tokens"
				end
			end,
		},
		{
			-- Ordered after the rename on purpose: a gateway that wants the other field
			-- name says so in a message this would otherwise read as a size complaint.
			match = "max_tokens",
			apply = function(body, message)
				-- Only ever driven by a live refusal. Replayed from record.repairs there
				-- is no message, and halving on every request would be a silent bug.
				if not message then return nil end
				local current = body.max_tokens or body.max_completion_tokens
				if not current then return nil end
				local allowed = M.ceilingFromMessage(message, current)
				if not allowed or allowed >= current then return nil end
				if body.max_tokens then body.max_tokens = allowed end
				if body.max_completion_tokens then body.max_completion_tokens = allowed end
				return string.format("lowered max_tokens from %d to %d", current, allowed)
			end,
		},
		{
			match = "temperature",
			apply = function(body)
				if body.temperature ~= nil then
					body.temperature = nil
					return "dropped temperature"
				end
			end,
		},
		{
			match = "parallel_tool_calls",
			apply = function(body)
				if body.parallel_tool_calls ~= nil then
					body.parallel_tool_calls = nil
					return "dropped parallel_tool_calls"
				end
			end,
		},
		{
			match = "stream_options",
			apply = function(body)
				if body.stream_options ~= nil then
					body.stream_options = nil
					return "dropped stream_options"
				end
			end,
		},
		{
			-- Not every gateway that relays to a reasoning model forwards the field
			-- that asks for a depth. Dropping it costs the setting, not the turn.
			match = "reasoning_effort",
			apply = function(body)
				if body.reasoning_effort ~= nil then
					body.reasoning_effort = nil
					return "dropped reasoning_effort"
				end
			end,
		},
		{
			match = "tool_choice",
			apply = function(body)
				if body.tool_choice ~= nil then
					body.tool_choice = nil
					return "dropped tool_choice"
				end
			end,
		},
	}

	local function repair(body, message)
		local lowered = tostring(message or ""):lower()
		for _, entry in ipairs(REPAIRS) do
			if lowered:find(entry.match, 1, true) then
				local note = entry.apply(body, message)
				if note then return note, entry.match end
			end
		end
		return nil
	end

	local function applyRemembered(record, body)
		for _, key in ipairs(record.repairs or {}) do
			for _, entry in ipairs(REPAIRS) do
				if entry.match == key then entry.apply(body) end
			end
		end
	end

	local function remember(record, key)
		record.repairs = record.repairs or {}
		for _, existing in ipairs(record.repairs) do
			if existing == key then return end
		end
		record.repairs[#record.repairs + 1] = key
		registry.save(record, { force = true })
	end

	-- Performs one completion against one provider. Returns result, nil on success
	-- or nil, message on failure. Retries inside net/http cover transport and
	-- 5xx/429; the provider chain above this handles a dead endpoint.
	function M.complete(record, request)
		local wantStream = request.stream
		if wantStream == nil then wantStream = record.stream ~= false and config.get("agent.stream", true) end

		local body = M.buildBody(record, util.merge(request, { stream = wantStream }))
		applyRemembered(record, body)

		local url = registry.endpoint(record, "/chat/completions")
		local headers = registry.authHeaders(record)
		for key, value in pairs(record.headers or {}) do headers[key] = value end
		headers["Accept"] = wantStream and "text/event-stream" or "application/json"

		local started = clock.ms()
		local attemptsAllowed = request.attempts or config.get("agent.retries", 3)

		local function fire(payload)
			-- A socket is only used when the record names one and the host has
			-- WebSocket support; otherwise the SSE body arrives whole over HTTP.
			if wantStream and util.trim(record.wsUrl) ~= "" and caps.ws then
				local ws = env.require("net/ws")
				local streamBody, wsErr = ws.stream({
					url = record.wsUrl,
					path = "/chat/completions",
					headers = headers,
					body = payload,
					aborted = request.aborted,
					onFrame = request.onFrame,
					timeout = request.timeout or 120,
				})
				if streamBody then
					return { ok = true, status = 200, body = streamBody, via = "websocket", ms = clock.since(started) }
				end
				log.warn("provider", "websocket stream failed, falling back to http", wsErr)
			end
			return http.send({
				url = url,
				method = "POST",
				headers = headers,
				body = util.encode(payload),
				identity = (record.claudeUa ~= false) and "claude" or "none",
				attempts = attemptsAllowed,
				aborted = request.aborted,
				onRetry = request.onRetry,
				tag = "chat:" .. record.id,
				timeout = request.timeout,
			})
		end

		local res, err = fire(body)

		-- One parameter repair, then one more attempt. Repeating this would turn a
		-- misconfigured provider into a request storm.
		if res and res.status == 400 then
			local message = M.errorText(res, nil)
			local note, key = repair(body, message)
			if note then
				log.info("provider", record.label .. ": " .. note .. ", retrying")
				if key == "max_tokens" then
					-- A value, not a switch, so it cannot ride in record.repairs -- that
					-- list replays a key with no error text to read a number out of.
					M.rememberMaxTokens(record, body.max_tokens or body.max_completion_tokens)
				else
					remember(record, key)
				end
				if request.onRetry then
					request.onRetry({ attempt = 1, attempts = 2, wait = 0, reason = note, status = 400 })
				end
				res, err = fire(body)
			end
		end

		if not res or not res.ok then
			local message = M.errorText(res, err)
			registry.markFail(record, message)
			return nil, message, res
		end

		local parsed
		if sse.looksStreamed(res.body) then
			parsed = sse.parse(res.body)
		else
			local decoded, decodeErr = util.decode(res.body)
			if type(decoded) ~= "table" then
				local message = "provider returned a body that is not JSON: " .. tostring(decodeErr)
				registry.markFail(record, message)
				return nil, message, res
			end
			if decoded.error then
				local message = M.errorText(res, nil)
				registry.markFail(record, message)
				return nil, message, res
			end
			parsed = sse.fromResponse(decoded)
		end

		if parsed.streamError then
			registry.markFail(record, parsed.streamError)
			return nil, "stream error: " .. parsed.streamError, res
		end

		local hasText = util.trim(parsed.content) ~= ""
		local hasCalls = #(parsed.toolCalls or {}) > 0
		if not hasText and not hasCalls and util.trim(parsed.reasoning) == "" then
			-- An empty completion is not an error the model can act on, so it is
			-- reported as a failure and the chain may try elsewhere.
			local message = "the provider returned an empty completion"
			registry.markFail(record, message)
			return nil, message, res
		end

		parsed.ms = clock.since(started)
		parsed.provider = record.id
		parsed.providerLabel = record.label
		parsed.via = res.via
		parsed.streamed = parsed.frames and parsed.frames > 0 or false
		registry.markOk(record, parsed.ms)
		return parsed, nil, res
	end

	return M
end
end)()

-- ==========================================================================
-- provider/registry
-- ==========================================================================
__UAI_MODULES["provider/registry"] = (function()
-- Provider records: creation, validation, persistence, health and fallback order.
--
-- A record is the whole description of one endpoint, so switching provider is a
-- data change rather than a code path. Nothing above this module knows which
-- vendor is in use.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local catalog = env.require("provider/catalog")

	local COOLDOWN_AFTER = 3
	local COOLDOWN_SECONDS = 45

	local M = {
		changed = signal.new("providers"),
	}

	-- Base URL normalisation, done once on save so no request path has to guess.
	--
	--   api.openai.com            -> https://api.openai.com/v1
	--   https://x.dev/            -> https://x.dev/v1
	--   https://x.dev/openai/v1   -> unchanged (it already names a path)
	--   https://x.dev/v1/chat/completions -> unchanged, used verbatim
	function M.normaliseBaseUrl(raw)
		local text = util.trim(raw)
		if text == "" then return "" end
		if not text:find("^https?://") then text = "https://" .. text end
		text = text:gsub("/+$", "")
		local scheme, rest = text:match("^(https?://)(.*)$")
		if not scheme then return text end
		local hostAndPath = rest
		local path = hostAndPath:match("^[^/]+(/.*)$")
		if not path or path == "" then
			return text .. "/v1"
		end
		return text
	end

	function M.isFullEndpoint(url)
		return tostring(url):find("/chat/completions$") ~= nil
	end

	function M.endpoint(record, suffix)
		local base = record.baseUrl or ""
		local url
		if M.isFullEndpoint(base) then
			url = (suffix == "/chat/completions") and base or (base:gsub("/chat/completions$", "") .. suffix)
		else
			url = base .. suffix
		end
		local query = {}
		for key, value in pairs(record.query or {}) do
			query[#query + 1] = util.urlEncode(key) .. "=" .. util.urlEncode(value)
		end
		if #query > 0 then
			url = url .. (url:find("%?") and "&" or "?") .. table.concat(query, "&")
		end
		return url
	end

	function M.authHeaders(record)
		local key = util.trim(record.apiKey)
		local style = record.authStyle or "bearer"
		if key == "" or style == "none" then return {} end
		if style == "x-api-key" then return { ["x-api-key"] = key } end
		if style == "api-key" then return { ["api-key"] = key } end
		if style == "both" then
			return { ["Authorization"] = "Bearer " .. key, ["x-api-key"] = key }
		end
		return { ["Authorization"] = "Bearer " .. key }
	end

	-- A record always has every field, so no consumer needs a nil check.
	function M.blank(presetId)
		local preset = catalog.get(presetId or "custom") or catalog.get("custom")
		return {
			id = "",
			preset = preset.id,
			label = preset.label,
			baseUrl = preset.baseUrl,
			apiKey = "",
			authStyle = preset.authStyle or "bearer",
			-- Which wire protocol the record speaks. Absent means chat completions,
			-- which is what every record saved before the second adapter existed has.
			api = preset.api or "openai",
			models = util.deepCopy(preset.models or {}),
			model = (preset.models or {})[1] or "",
			headers = util.deepCopy(preset.headers or {}),
			params = util.deepCopy(preset.params or {}),
			query = util.deepCopy(preset.query or {}),
			stream = true,
			claudeUa = preset.claudeUa ~= nil and preset.claudeUa or true,
			enabled = true,
			order = 0,
			wsUrl = "",
			note = preset.note,
			requires = preset.requires,
			health = { ok = 0, fail = 0, streak = 0, lastError = "", cooldownUntil = 0, lastMs = 0 },
		}
	end

	local function ensureId(wanted)
		local base = util.trim(wanted):lower():gsub("[^%w%-_]", "-"):gsub("%-+", "-"):gsub("^%-", "")
		if base == "" then base = "provider" end
		local taken = {}
		for _, record in ipairs(M.list()) do taken[record.id] = true end
		if not taken[base] then return base end
		for index = 2, 99 do
			local candidate = base .. "-" .. tostring(index)
			if not taken[candidate] then return candidate end
		end
		return base .. "-" .. tostring(clock.ms())
	end

	function M.list()
		local stored = config.get("providers.list", {})
		if type(stored) ~= "table" then return {} end
		local out = {}
		for _, record in ipairs(stored) do
			if type(record) == "table" then out[#out + 1] = record end
		end
		table.sort(out, function(a, b)
			if (a.order or 0) ~= (b.order or 0) then return (a.order or 0) < (b.order or 0) end
			return tostring(a.id) < tostring(b.id)
		end)
		return out
	end

	function M.get(id)
		for _, record in ipairs(M.list()) do
			if record.id == id then return record end
		end
		return nil
	end

	function M.count()
		return #M.list()
	end

	-- Validation is deliberately about reachability, not taste: a record with a
	-- plausible URL and, where needed, a key is allowed even if the vendor turns
	-- out to reject it. The health counters are what report that.
	function M.validate(record)
		local problems = {}
		if util.trim(record.label) == "" then problems[#problems + 1] = "give the provider a name" end
		local base = M.normaliseBaseUrl(record.baseUrl)
		if base == "" then
			problems[#problems + 1] = "base URL is required"
		elseif not base:find("^https?://[^/]+") then
			problems[#problems + 1] = "base URL does not look like a URL"
		end
		if (record.authStyle or "bearer") ~= "none" and util.trim(record.apiKey) == "" then
			problems[#problems + 1] = "an API key is required for this auth style"
		end
		-- Azure takes the model from the deployment in the URL; everyone else needs
		-- one named, and nothing here will guess it.
		if record.preset ~= "azure" and util.trim(record.model) == "" then
			problems[#problems + 1] = "fetch the model list or add a model id"
		end
		if record.requires == "executor" and caps.http ~= "executor" then
			problems[#problems + 1] = "this endpoint needs an executor HTTP function; this host has none"
		end
		return #problems == 0, problems
	end

	function M.save(record, opts)
		opts = opts or {}
		record.baseUrl = M.normaliseBaseUrl(record.baseUrl)
		local ok, problems = M.validate(record)
		if not ok and not opts.force then return false, problems end

		local list = config.get("providers.list", {})
		if type(list) ~= "table" then list = {} end
		if util.trim(record.id) == "" then
			record.id = ensureId(record.label ~= "" and record.label or record.preset)
			record.order = #list + 1
			list[#list + 1] = record
		else
			local replaced = false
			for index, existing in ipairs(list) do
				if existing.id == record.id then
					list[index] = record
					replaced = true
				end
			end
			if not replaced then
				record.order = #list + 1
				list[#list + 1] = record
			end
		end
		config.set("providers.list", list)
		if util.trim(config.get("providers.active", "")) == "" then
			config.set("providers.active", record.id)
		end
		M.changed:fire("save", record)
		return true, record
	end

	function M.remove(id)
		local list = config.get("providers.list", {})
		local kept = {}
		for _, record in ipairs(list) do
			if record.id ~= id then kept[#kept + 1] = record end
		end
		config.set("providers.list", kept)
		if config.get("providers.active", "") == id then
			config.set("providers.active", kept[1] and kept[1].id or "")
		end
		M.changed:fire("remove", id)
		return true
	end

	function M.setActive(id)
		if not M.get(id) then return false, "unknown provider" end
		config.set("providers.active", id)
		M.changed:fire("active", id)
		return true
	end

	function M.active()
		local wanted = config.get("providers.active", "")
		local record = M.get(wanted)
		if record then return record end
		for _, candidate in ipairs(M.list()) do
			if candidate.enabled ~= false then return candidate end
		end
		return nil
	end

	function M.setModel(id, model)
		local record = M.get(id)
		if not record then return false end
		record.model = model
		if not util.find(record.models or {}, function(item) return item == model end) then
			record.models = record.models or {}
			table.insert(record.models, 1, model)
		end
		M.save(record, { force = true })
		M.changed:fire("model", record)
		return true
	end

	function M.reorder(id, direction)
		local list = M.list()
		for index, record in ipairs(list) do
			if record.id == id then
				local swapWith = list[index + direction]
				if not swapWith then return false end
				local mine, theirs = record.order or index, swapWith.order or (index + direction)
				record.order, swapWith.order = theirs, mine
				config.set("providers.list", list)
				M.changed:fire("order", id)
				return true
			end
		end
		return false
	end

	-- Health -----------------------------------------------------------------

	local function health(record)
		record.health = record.health or { ok = 0, fail = 0, streak = 0, lastError = "", cooldownUntil = 0 }
		return record.health
	end

	function M.markOk(record, ms)
		local state = health(record)
		state.ok = state.ok + 1
		state.streak = 0
		state.lastError = ""
		state.cooldownUntil = 0
		state.lastMs = ms or state.lastMs
		M.changed:fire("health", record)
	end

	-- Consecutive failures put a provider on the bench rather than the first one:
	-- a single 500 from an otherwise healthy endpoint is noise, and demoting on it
	-- would flap the active provider on every hiccup.
	function M.markFail(record, message)
		local state = health(record)
		state.fail = state.fail + 1
		state.streak = state.streak + 1
		state.lastError = util.ellipsis(message or "request failed", 200)
		if state.streak >= COOLDOWN_AFTER then
			state.cooldownUntil = clock.ms() + COOLDOWN_SECONDS * 1000
			log.warn("provider", record.label .. " benched for " .. tostring(COOLDOWN_SECONDS) .. "s", state.lastError)
		end
		M.changed:fire("health", record)
	end

	function M.cooling(record)
		local state = health(record)
		return (state.cooldownUntil or 0) > clock.ms()
	end

	-- Ordered attempt list: the active provider, then every other enabled one that
	-- is not cooling down, then -- if that leaves nothing -- the cooling ones
	-- anyway, because refusing to try at all is worse than trying a bad endpoint.
	function M.chain()
		local out = {}
		local seen = {}
		local activeRecord = M.active()
		if activeRecord and activeRecord.enabled ~= false then
			out[#out + 1] = activeRecord
			seen[activeRecord.id] = true
		end
		if config.get("agent.fallback", true) then
			for _, record in ipairs(M.list()) do
				if not seen[record.id] and record.enabled ~= false and not M.cooling(record) then
					out[#out + 1] = record
					seen[record.id] = true
				end
			end
			if #out == 0 then
				for _, record in ipairs(M.list()) do
					if record.enabled ~= false then out[#out + 1] = record end
				end
			end
		end
		return out
	end

	function M.summary(record)
		if not record then return "no provider configured" end
		local state = health(record)
		local bits = { record.label }
		if record.model ~= "" then bits[#bits + 1] = record.model end
		if M.cooling(record) then bits[#bits + 1] = "cooling down" end
		if state.lastMs and state.lastMs > 0 then bits[#bits + 1] = util.formatDuration(state.lastMs) end
		return table.concat(bits, " | ")
	end

	return M
end
end)()

-- ==========================================================================
-- provider/traits
-- ==========================================================================
__UAI_MODULES["provider/traits"] = (function()
-- What a model accepts, and how much it can hold.
--
-- Every gateway claims to be OpenAI-compatible and none of them publishes
-- capabilities: /models returns ids, not limits. So the facts that change how a
-- request must be built live here, in one table, rather than being rediscovered
-- from a 400 at each call site.
--
-- Matched by longest substring, the same way `usage.priceFor` resolves a price,
-- because gateways prefix and suffix ids freely -- "anthropic/claude-opus-5",
-- "claude-opus-5-1m", a dated snapshot -- and an exact-match table would miss
-- every one of them. Only families this client has a documented fact about appear;
-- an unknown id resolves to an empty trait set, which means "behave as before".
return function(env)
	local M = {}

	-- context  the input window, in tokens.
	-- output   the ceiling on a single reply, in tokens.
	-- sampling false only where temperature/top_p/top_k are *rejected* rather than
	--          ignored. Absent means "send them", which is what every other model
	--          in this client has always had.
	-- effort   the levels `output_config.effort` accepts, cheapest first, or absent
	--          where the model has no effort control.
	-- thinking "adaptive" for models that reason without a token budget and take
	--          `{ type = "adaptive" }`; "budget" for the older shape that requires
	--          `budget_tokens`. Absent means the model does not expose reasoning.
	-- default  the effort level the API itself uses when none is sent, so the
	--          interface can mark it rather than implying the client picked it.
	local FIVE = { "low", "medium", "high", "xhigh", "max" }
	local FOUR = { "low", "medium", "high", "max" }

	local TRAITS = {
		["claude-fable-5-1"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high", alwaysThinks = true },
		["claude-mythos-5-1"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high", alwaysThinks = true },
		["claude-fable-5"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high", alwaysThinks = true },
		-- Opus 5 thinks by default, unlike 4.8 and 4.7, and refuses a disabled
		-- thinking block above effort "high".
		["claude-opus-5"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		["claude-opus-4-8"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		["claude-opus-4-7"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		-- 4.6 is the last generation that still takes sampling parameters, and its
		-- effort scale has no "xhigh".
		["claude-opus-4-6"] = { context = 1000000, output = 128000,
			effort = FOUR, thinking = "adaptive", default = "high" },
		["claude-sonnet-5"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		["claude-sonnet-4-6"] = { context = 1000000, output = 128000,
			effort = FOUR, thinking = "adaptive", default = "high" },
		["claude-haiku-4-5"] = { context = 200000 },
	}

	local EMPTY = {}

	function M.of(model)
		local id = tostring(model or ""):lower()
		if id == "" then return EMPTY end
		local best, bestLength = EMPTY, 0
		for prefix, traits in pairs(TRAITS) do
			if id:find(prefix, 1, true) and #prefix > bestLength then
				best, bestLength = traits, #prefix
			end
		end
		return best
	end

	function M.contextWindow(model)
		return M.of(model).context
	end

	function M.maxOutput(model)
		return M.of(model).output
	end

	-- True unless the model is documented to reject them. Withholding a parameter a
	-- model would have accepted changes behaviour for every gateway this client
	-- talks to, so silence is not the safe default here -- only a known refusal is.
	function M.allowsSampling(model)
		return M.of(model).sampling ~= false
	end

	function M.effortLevels(model)
		return M.of(model).effort
	end

	function M.defaultEffort(model)
		return M.of(model).default
	end

	-- The nearest level this model actually has, never rounding up: asking for
	-- "xhigh" on a scale that stops at "high" must land on "high" rather than
	-- spending "max", because the setting is a ceiling the user chose.
	local RANK = { low = 1, medium = 2, high = 3, xhigh = 4, max = 5 }

	function M.nearestEffort(model, wanted)
		local levels = M.effortLevels(model)
		if not levels then return nil end
		local target = RANK[tostring(wanted or ""):lower()]
		if not target then return nil end
		local best
		for _, level in ipairs(levels) do
			local rank = RANK[level]
			if rank == target then return level end
			if rank and rank < target and (not best or RANK[best] < rank) then best = level end
		end
		-- Every level this model has sits above what was asked for, so the cheapest
		-- of them is the closest thing to it.
		return best or levels[1]
	end

	function M.thinkingStyle(model)
		return M.of(model).thinking
	end

	function M.alwaysThinks(model)
		return M.of(model).alwaysThinks == true
	end

	-- A short badge for the model pickers: "1M", "200K". Nil when unknown, so a
	-- row for an id this table has never heard of simply has no badge.
	function M.badge(model)
		local context = M.contextWindow(model)
		if not context then return nil end
		if context >= 1000000 then
			local millions = context / 1000000
			return (millions % 1 == 0) and string.format("%dM", millions)
				or string.format("%.1fM", millions)
		end
		if context >= 1000 then return string.format("%dK", math.floor(context / 1000)) end
		return tostring(context)
	end

	M.TRAITS = TRAITS

	return M
end
end)()

-- ==========================================================================
-- runtime/caps
-- ==========================================================================
__UAI_MODULES["runtime/caps"] = (function()
-- What this host can actually do.
--
-- Every optional capability is probed exactly once, here, and the rest of the
-- project asks this module rather than testing for a global inline. That matters
-- for more than tidiness: the same script has to run under an executor with a
-- full filesystem, under one with only HTTP, and inside a plain client with
-- neither, and each of those has to degrade in a way the interface can explain
-- to the user instead of erroring.
return function(env)
	local M = {}

	local function callable(value)
		return type(value) == "function" and value or nil
	end

	-- Executors disagree on where the HTTP function lives. Order matters only in
	-- that the bare global is the modern spelling.
	local function findRequest()
		local candidates = {
			{ name = "request", fn = callable(request) },
			{ name = "http_request", fn = callable(http_request) },
			{ name = "syn.request", fn = type(syn) == "table" and callable(syn.request) or nil },
			{ name = "http.request", fn = type(http) == "table" and callable(http.request) or nil },
			{ name = "fluxus.request", fn = type(fluxus) == "table" and callable(fluxus.request) or nil },
		}
		for _, candidate in ipairs(candidates) do
			if candidate.fn then return candidate.fn, candidate.name end
		end
		return nil, nil
	end

	local function findClipboard()
		return callable(setclipboard)
			or callable(toclipboard)
			or (type(syn) == "table" and callable(syn.write_clipboard))
			or nil
	end

	local requestFn, requestName = findRequest()

	M.fn = {
		request = requestFn,
		readfile = callable(readfile),
		writefile = callable(writefile),
		appendfile = callable(appendfile),
		isfile = callable(isfile),
		isfolder = callable(isfolder),
		makefolder = callable(makefolder),
		listfiles = callable(listfiles),
		delfile = callable(delfile),
		delfolder = callable(delfolder),
		loadstring = callable(loadstring) or (callable(getgenv) and callable(getgenv().loadstring)) or nil,
		getgenv = callable(getgenv),
		gethui = callable(gethui),
		clipboard = findClipboard(),
		identify = callable(identifyexecutor) or callable(getexecutorname),
		websocket = (type(WebSocket) == "table" and callable(WebSocket.connect)) or nil,
		getconnections = callable(getconnections),
		firesignal = callable(firesignal),
		fireclickdetector = callable(fireclickdetector),
		firetouchinterest = callable(firetouchinterest),
		getnilinstances = callable(getnilinstances),
		getinstances = callable(getinstances),
		getscripts = callable(getscripts),
		decompile = callable(decompile),
		cloneref = callable(cloneref),
		queueTeleport = callable(queue_on_teleport),
		setfflag = callable(setfflag),
		customasset = callable(getcustomasset),
	}

	M.requestName = requestName

	-- HTTP -------------------------------------------------------------------
	-- The executor path is preferred for one specific reason: RequestAsync
	-- refuses to send a User-Agent (along with Cookie, Host and Content-Length),
	-- so it physically cannot carry the Claude Code identity. When that is the
	-- only transport available the client says so rather than silently sending
	-- Roblox's own agent string.
	if M.fn.request then
		M.http = "executor"
		M.uaSupported = true
	else
		local ok = pcall(function()
			return env.services.HttpService ~= nil
		end)
		M.http = ok and "roblox" or "none"
		M.uaSupported = false
	end

	M.fs = (M.fn.writefile ~= nil and M.fn.readfile ~= nil)
	M.exec = M.fn.loadstring ~= nil
	M.ws = M.fn.websocket ~= nil
	M.clipboard = M.fn.clipboard ~= nil
	M.hui = M.fn.gethui ~= nil
	M.hooks = M.fn.getconnections ~= nil
	M.sourceRead = M.fn.decompile ~= nil or M.fn.getscripts ~= nil

	M.executor = "unknown"
	if M.fn.identify then
		local ok, name = pcall(M.fn.identify)
		if ok and type(name) == "string" and name ~= "" then M.executor = name end
	end

	do
		local ok, isStudio = pcall(function() return env.services.RunService:IsStudio() end)
		M.studio = ok and isStudio or false
	end

	do
		local ok, tenFoot = pcall(function() return env.services.GuiService:IsTenFootInterface() end)
		M.console = ok and tenFoot or false
	end

	M.available = {
		http = M.http ~= "none",
		fs = M.fs,
		exec = M.exec,
		ws = M.ws,
		clipboard = M.clipboard,
		hooks = M.hooks,
		["ua"] = M.uaSupported,
	}

	-- Tools declare `needs = { "fs" }`; the registry checks the answer here
	-- before dispatch so an unavailable tool reports a clear reason to the model
	-- instead of erroring somewhere inside a nil call.
	function M.has(key)
		return M.available[key] == true
	end

	M.MISSING = {
		http = "no HTTP transport is available in this host",
		fs = "this host has no filesystem functions (writefile/readfile)",
		exec = "this host cannot compile code (loadstring is unavailable)",
		ws = "this host has no WebSocket support",
		clipboard = "this host has no clipboard function",
		hooks = "this host does not expose signal introspection (getconnections)",
		ua = "this host cannot set a custom User-Agent",
	}

	function M.reason(key)
		return M.MISSING[key] or ("capability '" .. tostring(key) .. "' is unavailable")
	end

	function M.summary()
		local parts = {
			"transport " .. M.http .. (M.requestName and (" (" .. M.requestName .. ")") or ""),
			"ua " .. (M.uaSupported and "yes" or "no"),
			"fs " .. (M.fs and "yes" or "no"),
			"exec " .. (M.exec and "yes" or "no"),
		}
		if M.executor ~= "unknown" then table.insert(parts, 1, M.executor) end
		return table.concat(parts, " | ")
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/clock
-- ==========================================================================
__UAI_MODULES["runtime/clock"] = (function()
-- Time, scheduling and the retry curve.
--
-- os.clock reports processor time, which stops advancing while a thread is
-- yielded, so anything measuring a request or a backoff has to use a wall clock.
-- DateTime is the modern one; os.time is the fallback for hosts that lack it and
-- costs us sub-second resolution, which only ever affects display.
return function(env)
	local util = env.require("runtime/util")

	local M = {}

	local epochBase = 0
	do
		local ok, value = pcall(function()
			return DateTime.now().UnixTimestampMillis
		end)
		M.precise = ok and type(value) == "number"
		if not M.precise then epochBase = (os.time() or 0) * 1000 end
	end

	function M.ms()
		if M.precise then
			local ok, value = pcall(function() return DateTime.now().UnixTimestampMillis end)
			if ok then return value end
			M.precise = false
		end
		return (os.time() or 0) * 1000
	end

	function M.since(startMs)
		return M.ms() - (startMs or 0)
	end

	function M.stamp()
		local seconds = math.floor(M.ms() / 1000)
		local ok, text = pcall(function()
			return DateTime.fromUnixTimestamp(seconds):FormatLocalTime("HH:mm:ss", "en-us")
		end)
		if ok and type(text) == "string" then return text end
		return string.format("%02d:%02d:%02d",
			math.floor(seconds / 3600) % 24, math.floor(seconds / 60) % 60, seconds % 60)
	end

	-- Calendar ---------------------------------------------------------------
	--
	-- Activity is counted per day and per hour of the day, so both have to mean the
	-- same thing on every host: the day the person in front of the screen would
	-- name. Roblox's only calendar API is DateTime's pattern formatter, and its
	-- pattern support differs between client versions -- so the conversion is done
	-- here in arithmetic, from the epoch millisecond count plus this host's offset
	-- from UTC, and the formatter is asked for exactly one thing: that offset.
	local MINUTE_MS = 60000
	local DAY_MINUTES = 1440
	-- The widest real offsets are -12:00 (Baker Island) and +14:00 (Kiritimati).
	local OFFSET_LIMIT = 840
	local offsetMinutes = nil

	function M.offsetMinutes()
		if offsetMinutes then return offsetMinutes end
		offsetMinutes = 0
		local seconds = math.floor(M.ms() / 1000)
		local ok, text = pcall(function()
			return DateTime.fromUnixTimestamp(seconds):FormatLocalTime("HH:mm", "en-us")
		end)
		if ok and type(text) == "string" then
			local hour, minute = text:match("^(%d%d?):(%d%d)$")
			if hour then
				local delta = (tonumber(hour) * 60 + tonumber(minute))
					- math.floor((seconds % 86400) / 60)
				if delta > OFFSET_LIMIT then delta = delta - DAY_MINUTES end
				if delta < -OFFSET_LIMIT then delta = delta + DAY_MINUTES end
				-- Quarter-hour zones exist (Nepal is +05:45); minutes of drift between
				-- the two reads do not.
				offsetMinutes = math.floor(delta / 15 + 0.5) * 15
			end
		end
		return offsetMinutes
	end

	-- Howard Hinnant's civil-from-days, which is exact for every date a client can
	-- hold and needs no leap-year table. `days` is days since 1970-01-01.
	function M.civilFromDays(days)
		local shifted = math.floor(days) + 719468
		local era = math.floor(shifted / 146097)
		local dayOfEra = shifted - era * 146097
		local yearOfEra = math.floor((dayOfEra - math.floor(dayOfEra / 1460)
			+ math.floor(dayOfEra / 36524) - math.floor(dayOfEra / 146096)) / 365)
		local year = yearOfEra + era * 400
		local dayOfYear = dayOfEra - (365 * yearOfEra + math.floor(yearOfEra / 4)
			- math.floor(yearOfEra / 100))
		local monthPrime = math.floor((5 * dayOfYear + 2) / 153)
		local day = dayOfYear - math.floor((153 * monthPrime + 2) / 5) + 1
		local month = monthPrime + 3
		if monthPrime >= 10 then month = monthPrime - 9 end
		if month <= 2 then year = year + 1 end
		return year, month, day
	end

	function M.daysFromCivil(year, month, day)
		local y = year
		if month <= 2 then y = y - 1 end
		local era = math.floor(y / 400)
		local yearOfEra = y - era * 400
		local shift = 9
		if month > 2 then shift = -3 end
		local dayOfYear = math.floor((153 * (month + shift) + 2) / 5) + day - 1
		local dayOfEra = yearOfEra * 365 + math.floor(yearOfEra / 4)
			- math.floor(yearOfEra / 100) + dayOfYear
		return era * 146097 + dayOfEra - 719468
	end

	-- Local days since the epoch. The unit every per-day bucket is keyed by.
	function M.dayNumber(ms)
		local shifted = (ms or M.ms()) + M.offsetMinutes() * MINUTE_MS
		return math.floor(shifted / 86400000)
	end

	function M.keyFromDayNumber(days)
		local year, month, day = M.civilFromDays(days)
		return string.format("%04d-%02d-%02d", year, month, day)
	end

	function M.dayKey(ms)
		return M.keyFromDayNumber(M.dayNumber(ms))
	end

	-- Nil rather than a guess for anything that is not a key: these come out of a
	-- stored file, and a corrupt one must not be silently read as 1970.
	function M.dayNumberOfKey(key)
		local year, month, day = tostring(key or ""):match("^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
		if not year then return nil end
		return M.daysFromCivil(tonumber(year), tonumber(month), tonumber(day))
	end

	function M.hourOf(ms)
		local shifted = (ms or M.ms()) + M.offsetMinutes() * MINUTE_MS
		return math.floor((shifted % 86400000) / 3600000)
	end

	-- Monday = 1. The epoch itself was a Thursday, which is where the 3 comes from.
	function M.weekdayOfDayNumber(days)
		return ((days + 3) % 7) + 1
	end

	local MONTHS = { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
		"Jul", "Aug", "Sep", "Oct", "Nov", "Dec" }
	local WEEKDAYS = { "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun" }

	function M.monthName(month)
		return MONTHS[month] or "?"
	end

	function M.weekdayName(index)
		return WEEKDAYS[index] or "?"
	end

	-- "Sat 5 Jul 2026", or without the year when it is the current one -- the form a
	-- date is read in rather than the form it is stored in.
	function M.describeDay(key, todayKey)
		local days = M.dayNumberOfKey(key)
		if not days then return tostring(key) end
		local year, month, day = M.civilFromDays(days)
		local thisYear = M.civilFromDays(M.dayNumberOfKey(todayKey or M.dayKey()) or days)
		local head = string.format("%s %d %s", WEEKDAYS[M.weekdayOfDayNumber(days)], day, MONTHS[month])
		if year == thisYear then return head end
		return head .. " " .. tostring(year)
	end

	-- 12-hour clock with a meridiem, which is how a "peak hour" reads.
	function M.describeHour(hour)
		hour = math.floor(tonumber(hour) or 0) % 24
		local suffix = "AM"
		if hour >= 12 then suffix = "PM" end
		local display = hour % 12
		if display == 0 then display = 12 end
		return string.format("%d %s", display, suffix)
	end

	function M.wait(seconds)
		return task.wait(seconds)
	end

	function M.spawn(fn, ...)
		return task.spawn(fn, ...)
	end

	function M.delay(seconds, fn, ...)
		return task.delay(seconds, fn, ...)
	end

	-- Injectable so a test can pin the jitter. Nothing else should reach for
	-- math.random directly, or backoff stops being reproducible.
	function M.random()
		return math.random()
	end

	-- Trailing-edge debounce: the last call within the window wins. Returns the
	-- wrapped function plus a cancel handle, because a debounced relayout has to
	-- be cancellable when the surface it targets is destroyed.
	function M.debounce(fn, seconds)
		local generation = 0
		local function wrapped(...)
			generation = generation + 1
			local mine = generation
			local args = { ... }
			task.delay(seconds, function()
				if mine == generation then fn(unpack(args)) end
			end)
		end
		return wrapped, function() generation = generation + 1 end
	end

	-- Leading-edge throttle: fires immediately, then swallows calls for the rest
	-- of the window. Right for a resize signal that can arrive every frame.
	function M.throttle(fn, seconds)
		local lastRun = -math.huge
		return function(...)
			local now = M.ms()
			if now - lastRun < seconds * 1000 then return end
			lastRun = now
			return fn(...)
		end
	end

	function M.interval(seconds, fn)
		local alive = true
		task.spawn(function()
			while alive do
				task.wait(seconds)
				if not alive then return end
				local ok, err = pcall(fn)
				if not ok then env.require("runtime/log").warn("clock", "interval handler failed", err) end
			end
		end)
		-- Registered centrally as well as returned. A caller that forgets the
		-- canceller -- or one whose owning instance is destroyed without its
		-- Destroying handler running -- would otherwise leave a thread ticking for the
		-- lifetime of the process, and an unload could not stop it. The registry's
		-- closure both cancels and unregisters, so it is the one to hand back.
		return env.require("runtime/dispose").add(function() alive = false end, "interval")
	end

	-- Exponential backoff with full jitter, capped. Full jitter rather than a
	-- fixed multiple because several retrying clients behind one gateway
	-- otherwise re-collide on exactly the same schedule.
	function M.backoff(attempt, opts)
		opts = opts or {}
		local base = opts.base or 0.6
		local cap = opts.cap or 20
		local ceiling = math.min(cap, base * (2 ^ math.max(attempt - 1, 0)))
		local floor = opts.floor or (ceiling * 0.35)
		return util.clamp(floor + M.random() * (ceiling - floor), 0, cap)
	end

	-- Runs fn on its own thread and stops waiting after `seconds`.
	--
	-- The timeout cannot kill the thread -- Luau has no way to -- so a runaway
	-- body keeps running in the background and the caller is told so. Elapsed time
	-- comes from task.wait's own delta rather than a clock read per frame, and the
	-- first check happens before any yield: task.spawn runs inline until the first
	-- yield, so code that never yields is already finished and must not be billed
	-- a scheduler tick.
	function M.timeout(seconds, fn)
		local done, ok, result = false, false, nil
		task.spawn(function()
			ok, result = pcall(fn)
			done = true
		end)
		if not done then
			local elapsed = 0
			repeat
				elapsed = elapsed + (task.wait() or 0)
			until done or elapsed >= seconds
		end
		if not done then return false, false, nil end
		return true, ok, result
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/config
-- ==========================================================================
__UAI_MODULES["runtime/config"] = (function()
-- Persisted settings.
--
-- One file, one shape, defaults merged under whatever was saved -- so adding a
-- setting in a later version does not invalidate an existing install, and a
-- half-written file falls back to defaults rather than bricking the client.
-- Writes are debounced because the interface calls set() from slider drags.
return function(env)
	local util = env.require("runtime/util")
	local fsx = env.require("runtime/fsx")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local log = env.require("runtime/log")

	local FILE = "config.json"

	local DEFAULTS = {
		version = 1,
		ui = {
			density = "comfortable",
			accent = "claude",
			reduceMotion = "auto",
			layout = "auto",
			panel = "chat",
			fontScale = 1,
			showReasoning = true,
			showToolDetail = false,
			-- Whether the code a tool was handed is drawn under its row, outside the
			-- fold. On by default: the listing is the single most useful thing in a
			-- transcript of an agent that writes and executes code, and it used to be
			-- reachable only by opening a pane that defaulted shut.
			showToolCode = true,
			-- The key that opens quick chat, stored as an Enum.KeyCode name because
			-- that is what the capture in Settings produces and what survives a
			-- keyboard layout the character would not.
			quickKey = "Semicolon",
			showUsage = true,
			-- Appearance choices that name a family or a palette rather than a number.
			-- All four are read by ui/theme, so each one changes what is on screen.
			interfaceFont = "builder",
			codeFont = "code",
			codeTheme = "dark",
			transcriptWidth = "wide",
			-- The sidebar, the home card and the range the card opens on. Remembered
			-- because each is a place the user put something.
			sidebarCollapsed = false,
			sidebarExpanded = false,
			showActivity = true,
			activityRange = "all",
			window = { width = 0, height = 0, x = 0, y = 0, maximised = false, placed = false },
			mobilePanel = { width = 0, height = 0, x = 0, y = 0, placed = false },
			launcher = { x = 0, y = 0, placed = false },
		},
		agent = {
			maxTurns = 24,
			-- Lifts the step limit and the turn deadline for the top-level
			-- conversation, so a long job runs until the model answers in prose
			-- instead of stopping mid-way with "I reached this session's step limit".
			-- What still bounds a runaway: the repeat breaker, each tool's own
			-- timeout, the provider retry cap, and Stop. Subagents keep their own
			-- turn and time budgets either way -- an unbounded child is the one
			-- thing here nobody is watching.
			unlimitedTurns = false,
			toolConcurrency = 4,
			toolTimeout = 25,
			contextTokens = 24000,
			keepTurns = 14,
			compaction = true,
			stream = true,
			temperature = 0.4,
			-- Reasoning depth: sent as `reasoning_effort` on chat completions and as
			-- `output_config.effort` on the Messages API. "high" is what the API itself
			-- uses when the field is absent, so this default changes nothing until it is
			-- moved, and "off" sends no field at all. Clamped per model, because the
			-- scales differ by generation -- "xhigh" did not exist before Opus 4.7.
			effort = "high",
			maxTokens = 4096,
			-- Characters, not tokens, and it is the last word on how much of a tool
			-- result reaches the model. Eight thousand rather than four so that the
			-- tools' own defaults -- a six thousand character file read, a five thousand
			-- character response body -- arrive whole instead of being cut in half by a
			-- limit set somewhere the caller cannot see.
			resultCap = 8000,
			repeatLimit = 3,
			subagentDepth = 2,
			subagentTurns = 14,
			-- Live subagents anywhere in the tree. `toolConcurrency` bounds one batch,
			-- so it is what caps a parallel dispatch from the main conversation; this
			-- caps the whole tree, which nothing else did. Depth alone does not: a
			-- subagent's own batch is bounded separately, and two levels of that
			-- multiply rather than add.
			subagentConcurrency = 8,
			-- Seconds one subagent may run for. The tool that dispatches it derives its
			-- own timeout from this, so the two cannot drift apart -- when they did, the
			-- generic 25s tool timeout fired first and every finished report was thrown
			-- away by a caller that had already given up.
