			replyLanguage = "",
		},
		permissions = {
			mode = "ask",
			remember = true,
			rules = {},
		},
		providers = {
			active = "",
			list = {},
		},
		identity = {
			claudeUa = true,
			version = "2.0.14",
			extraHeaders = {},
		},
		memory = {
			enabled = true,
			entries = {},
