end)()

-- ==========================================================================
-- runtime/dispose
-- ==========================================================================
__UAI_MODULES["runtime/dispose"] = (function()
-- The disposer registry.
--
-- Everything this client leaves running outside its own instance tree -- a timer, a
-- repeating tween, a connection to a service that outlives the interface, a
-- subscription to a long-lived signal -- registers its cleanup here. Destroying the
-- ScreenGui is not unloading: a `clock.interval` keeps ticking against a destroyed
-- label, an InputBegan handler keeps firing, and a second boot then has two of
-- everything. Draining this is what makes an unload real.
--
-- Deliberately dependency-free so anything can require it, including runtime/clock.
return function(env)
	local M = { entries = {}, draining = false }

	-- Returns a canceller that also unregisters, so a caller that cleans up early
	-- does not leave a dead entry behind for the drain to trip over.
	function M.add(fn, label)
		if type(fn) ~= "function" then return function() end end
		local entry = { fn = fn, label = label or "anonymous", alive = true }
		M.entries[#M.entries + 1] = entry
		return function()
			if not entry.alive then return end
			entry.alive = false
			pcall(entry.fn)
		end
	end

	-- An RBXScriptConnection from a signal that outlives the UI.
	function M.connection(connection, label)
		if type(connection) ~= "table" and type(connection) ~= "userdata" then
			return function() end
		end
		return M.add(function()
			pcall(function() connection:Disconnect() end)
		end, label or "connection")
	end

	-- A tween that repeats forever and so never releases its target on its own.
	function M.tween(tween, label)
		if not tween then return function() end end
		return M.add(function()
			pcall(function() tween:Cancel() end)
		end, label or "tween")
	end

	function M.count()
		local alive = 0
		for _, entry in ipairs(M.entries) do
			if entry.alive then alive = alive + 1 end
		end
		return alive
	end

	-- Runs every cleanup once, newest first, and never raises: an unload that stops
	-- halfway because one handler errored is worse than one that reports at the end.
	function M.drain()
		if M.draining then return 0 end
		M.draining = true
		local ran, failed = 0, {}
		for index = #M.entries, 1, -1 do
			local entry = M.entries[index]
			if entry.alive then
				entry.alive = false
				local ok, err = pcall(entry.fn)
				ran = ran + 1
				if not ok then failed[#failed + 1] = entry.label .. ": " .. tostring(err) end
			end
		end
		M.entries = {}
		M.draining = false
		return ran, failed
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/fsx
-- ==========================================================================
__UAI_MODULES["runtime/fsx"] = (function()
-- Filesystem facade.
--
-- Executor filesystems are sandboxed to the executor's own workspace folder, so
-- paths here are relative to one app folder and never absolute. `..` is rejected
-- rather than normalised: a model-authored path is untrusted input, and the file
-- tools hand their argument straight to this module.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local log = env.require("runtime/log")

	local M = {}

	M.enabled = caps.fs
	M.root = (env.info and env.info.folder) or "UAI"

	local knownFolders = {}

	function M.sanitise(path)
		local clean = tostring(path or ""):gsub("\\", "/"):gsub("^/+", ""):gsub("/+", "/")
		if clean == "" then return nil, "empty path" end
		for _, part in ipairs(util.split(clean, "/")) do
			if part == ".." then return nil, "path may not contain '..'" end
			if part == "." then return nil, "path may not contain '.'" end
			if part:find('[<>:"|%?%*]') then return nil, "path contains a reserved character" end
		end
		if #clean > 180 then return nil, "path is too long" end
		return clean
	end

	-- Absolute form used with the executor functions: everything the client owns
	-- lives under one folder so an uninstall is one delete.
	function M.resolve(path, opts)
		opts = opts or {}
		local clean, err = M.sanitise(path)
		if not clean then return nil, err end
		if opts.raw then return clean end
		return M.root .. "/" .. clean
	end

	function M.ensure(dir)
		if not M.enabled or not caps.fn.makefolder then return false end
		local clean = M.sanitise(dir)
		if not clean then return false end
		local walk = ""
		for _, part in ipairs(util.split(clean, "/")) do
			walk = (walk == "") and part or (walk .. "/" .. part)
			if not knownFolders[walk] then
				local exists = false
				if caps.fn.isfolder then
					local ok, result = pcall(caps.fn.isfolder, walk)
					exists = ok and result == true
				end
				if not exists then pcall(caps.fn.makefolder, walk) end
				knownFolders[walk] = true
			end
		end
		return true
	end

	function M.exists(path)
		if not M.enabled or not caps.fn.isfile then return false end
		local full = M.resolve(path)
		if not full then return false end
		local ok, result = pcall(caps.fn.isfile, full)
		return ok and result == true
	end

	function M.isDir(path)
		if not M.enabled or not caps.fn.isfolder then return false end
		local full = M.resolve(path)
		if not full then return false end
		local ok, result = pcall(caps.fn.isfolder, full)
		return ok and result == true
	end

	function M.read(path)
		if not M.enabled then return nil, caps.reason("fs") end
		local full, err = M.resolve(path)
		if not full then return nil, err end
		if not M.exists(path) then return nil, "no such file: " .. full end
		local ok, content = pcall(caps.fn.readfile, full)
		if not ok then return nil, tostring(content) end
		return content
	end

	function M.write(path, content)
		if not M.enabled then return false, caps.reason("fs") end
		local full, err = M.resolve(path)
		if not full then return false, err end
		M.ensure(full:match("^(.*)/[^/]*$") or M.root)
		local ok, writeErr = pcall(caps.fn.writefile, full, tostring(content))
		if not ok then
			log.warn("fsx", "write failed: " .. full, writeErr)
			return false, tostring(writeErr)
		end
		return true, full
	end

	function M.append(path, content)
		if not M.enabled then return false, caps.reason("fs") end
		local full, err = M.resolve(path)
		if not full then return false, err end
		M.ensure(full:match("^(.*)/[^/]*$") or M.root)
		if caps.fn.appendfile then
			local ok, appendErr = pcall(caps.fn.appendfile, full, tostring(content))
			if ok then return true, full end
			return false, tostring(appendErr)
		end
		-- Not every host has appendfile; read-modify-write is correct, just worse.
		local existing = M.read(path) or ""
		return M.write(path, existing .. tostring(content))
	end

	function M.delete(path)
		if not M.enabled then return false, caps.reason("fs") end
		local full, err = M.resolve(path)
		if not full then return false, err end
		if M.isDir(path) then
			if not caps.fn.delfolder then return false, "this host cannot delete folders" end
			local ok, delErr = pcall(caps.fn.delfolder, full)
			return ok, ok and full or tostring(delErr)
		end
		if not caps.fn.delfile then return false, "this host cannot delete files" end
		local ok, delErr = pcall(caps.fn.delfile, full)
		return ok, ok and full or tostring(delErr)
	end

	-- listfiles returns host-shaped paths: some absolute, some backslashed, some
	-- already relative. They are normalised back to app-relative so a caller
	-- never has to care which executor it is on.
	function M.list(path)
		if not M.enabled or not caps.fn.listfiles then return {}, caps.reason("fs") end
		local full = M.resolve(path or "")
		if not full then return {}, "bad path" end
		local ok, entries = pcall(caps.fn.listfiles, full)
		if not ok or type(entries) ~= "table" then return {} end
		local out = {}
		for _, entry in ipairs(entries) do
			local normal = tostring(entry):gsub("\\", "/")
			local relative = normal:match("^.*" .. util.escapePattern(M.root) .. "/(.+)$") or normal
			out[#out + 1] = {
				path = relative,
				name = relative:match("[^/]+$") or relative,
				isDir = caps.fn.isfolder and select(2, pcall(caps.fn.isfolder, normal)) == true or false,
			}
		end
		table.sort(out, function(a, b) return a.path < b.path end)
		return out
	end

	function M.readJson(path, fallback)
		local content = M.read(path)
		if not content then return fallback end
		local value, err = util.decode(content)
		if value == nil then
			log.warn("fsx", "corrupt json at " .. tostring(path), err)
			return fallback
		end
		return value
	end

	function M.writeJson(path, value)
		local ok, body = pcall(util.encode, value)
		if not ok then return false, tostring(body) end
		return M.write(path, body)
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/log
-- ==========================================================================
__UAI_MODULES["runtime/log"] = (function()
-- Structured log with a bounded history.
--
-- Two audiences: the developer, who wants the last hundred lines including HTTP
-- detail, and the user, who occasionally needs to see why a provider rejected
-- them. Both read the same ring buffer through the Logs panel, so nothing is
-- printed to the console by default -- an in-game script that spams output is
-- indistinguishable from a broken one.
return function(env)
	local util = env.require("runtime/util")
	local signal = env.require("runtime/signal")

	local LIMIT = 400

	local M = {
		entries = {},
		changed = signal.new("log"),
		mirror = false,
		minLevel = 1,
	}

	local LEVELS = { debug = 1, info = 2, warn = 3, error = 4 }

	-- Published so a settings surface can set the floor by name rather than by
	-- guessing which integer "warn" is.
	M.LEVELS = LEVELS

	function M.setLevel(level)
		M.minLevel = LEVELS[tostring(level)] or 2
		return M.minLevel
	end

	-- An API key must never reach the buffer in full: the panel is screenshot and
	-- pasted into bug reports. Anything key-shaped keeps a four-character tail so
	-- a user can still tell two keys apart.
	local function redact(text)
		text = tostring(text)
		text = text:gsub("(sk%-[%w%-_]*)([%w%-_][%w%-_][%w%-_][%w%-_])", function(_, tail)
			return "sk-..." .. tail
		end)
		text = text:gsub("([Bb]earer%s+)[%w%.%-_]+([%w%.%-_][%w%.%-_][%w%.%-_][%w%.%-_])", "%1...%2")
		text = text:gsub('("api[_%-]?key"%s*:%s*")[^"]*([^"][^"][^"][^"])(")', "%1...%2%3")
		return text
	end
	M.redact = redact

	local function push(level, source, message, detail)
		if (LEVELS[level] or 2) < M.minLevel then return end
		local entry = {
			at = env.require("runtime/clock").ms(),
			stamp = env.require("runtime/clock").stamp(),
			level = level,
			source = tostring(source or "app"),
			message = redact(message),
			detail = detail ~= nil and redact(type(detail) == "table" and util.concatKeys(detail) or tostring(detail)) or nil,
		}
		M.entries[#M.entries + 1] = entry
		if #M.entries > LIMIT then
			-- Drop in blocks rather than one per push: table.remove(1) on a 400
			-- entry list on every log line is a copy each time.
			local kept = {}
			for index = math.floor(LIMIT * 0.25) + 1, #M.entries do kept[#kept + 1] = M.entries[index] end
			M.entries = kept
		end
		if M.mirror then
			local line = string.format("[uai:%s] %s: %s", entry.level, entry.source, entry.message)
			if level == "error" or level == "warn" then warn(line) else print(line) end
		end
		M.changed:fire(entry)
		return entry
	end

	function M.debug(source, message, detail) return push("debug", source, message, detail) end
	function M.info(source, message, detail) return push("info", source, message, detail) end
	function M.warn(source, message, detail) return push("warn", source, message, detail) end
	function M.error(source, message, detail) return push("error", source, message, detail) end

	function M.tail(count)
		local from = math.max(#M.entries - (count or 50) + 1, 1)
		return util.slice(M.entries, from, #M.entries)
	end

	function M.filter(level, text)
		local wanted = LEVELS[level] or 1
		local needle = text and text:lower() or nil
		local out = {}
		for _, entry in ipairs(M.entries) do
			if (LEVELS[entry.level] or 2) >= wanted then
				if not needle
					or entry.message:lower():find(needle, 1, true)
					or entry.source:lower():find(needle, 1, true) then
					out[#out + 1] = entry
				end
			end
		end
		return out
	end

	function M.clear()
		M.entries = {}
		M.changed:fire(nil)
	end

	function M.export()
		local lines = {}
		for _, entry in ipairs(M.entries) do
			lines[#lines + 1] = string.format("%s %-5s %-14s %s%s",
				entry.stamp, entry.level:upper(), entry.source, entry.message,
				entry.detail and ("  " .. entry.detail) or "")
		end
		return table.concat(lines, "\n")
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/place
-- ==========================================================================
__UAI_MODULES["runtime/place"] = (function()
-- Which place this is.
--
-- The place is the closest thing a Roblox client has to a project: it is what the
-- work is *in*, it is stable across sessions, and it is what a list of conversations
-- wants to be grouped by. Two of the three facts about it are free -- the id, the
-- version and the server instance are properties on `game` -- and the fourth, the
-- name, is a web call that yields and can fail.
--
-- So the name is asked for once, in the background, and every reader takes whatever
-- is known at the time. Nothing here blocks and nothing here invents a name: an
-- unresolved place is "Place 1818" until the call comes back, which is honest and is
-- also a usable label.
return function(env)
	local util = env.require("runtime/util")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")

	local M = {
		id = 0,
		gameId = 0,
		version = 0,
		jobId = "",
		name = "",
		creator = "",
		resolved = false,
		asking = false,
		changed = signal.new("place"),
	}

	pcall(function() M.id = tonumber(game.PlaceId) or 0 end)
	pcall(function() M.gameId = tonumber(game.GameId) or 0 end)
	pcall(function() M.version = tonumber(game.PlaceVersion) or 0 end)
	pcall(function() M.jobId = tostring(game.JobId or "") end)

	-- The id is always available, so there is always a label.
	function M.label()
		if util.trim(M.name) ~= "" then return M.name end
		if M.id > 0 then return "Place " .. tostring(M.id) end
		return "This place"
	end

	-- A stable key for grouping. Studio and a solo run have no job id and a place with
	-- no id at all is possible in a local test, so the id is the key and the string is
	-- there to be a table key rather than to be read.
	function M.key()
		return "place:" .. tostring(M.id)
	end

	function M.resolve()
		if M.resolved or M.asking then return end
		if M.id <= 0 then return end
		M.asking = true
		task.spawn(function()
			local ok, info = pcall(function()
				return env.services.MarketplaceService:GetProductInfo(M.id)
			end)
			M.asking = false
			if not ok or type(info) ~= "table" then
				-- Normal, not exceptional: the endpoint is rate limited and a client
				-- without HTTP access to it simply keeps the id as its label.
				log.debug("place", "could not read the place name", info)
				return
			end
			M.resolved = true
			M.name = tostring(info.Name or "")
			if type(info.Creator) == "table" then M.creator = tostring(info.Creator.Name or "") end
			M.changed:fire(M)
		end)
	end

	function M.describe()
		local parts = { M.label() }
		if M.version > 0 then parts[#parts + 1] = "v" .. tostring(M.version) end
		if util.trim(M.creator) ~= "" then parts[#parts + 1] = "by " .. M.creator end
		return table.concat(parts, "  ")
	end

	-- Every fact this module has, as rows a panel can render. Only what was actually
	-- read: a field that is empty is absent rather than "unknown".
	function M.facts()
		local out = {}
		local function add(key, value)
			if value ~= nil and tostring(value) ~= "" and tostring(value) ~= "0" then
				out[#out + 1] = { key = key, value = tostring(value) }
			end
		end
		add("Place", M.label())
		add("Place id", M.id)
		add("Version", M.version)
		add("Universe", M.gameId)
		add("Server", M.jobId)
		add("Creator", M.creator)
		return out
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/signal
-- ==========================================================================
__UAI_MODULES["runtime/signal"] = (function()
-- A signal that does not depend on BindableEvent. The client fans a lot of small
-- events out to the interface, and going through Roblox instances for that costs
-- a round trip per fire and loses non-serialisable payloads such as functions --
-- which the permission prompt relies on.
return function(env)
	local M = {}

	local Signal = {}
	Signal.__index = Signal

	function M.new(name)
		return setmetatable({ name = name or "signal", handlers = {}, firing = false }, Signal)
	end

	function Signal:connect(fn)
		local entry = { fn = fn, alive = true }
		self.handlers[#self.handlers + 1] = entry
		return function()
			entry.alive = false
		end
	end

	function Signal:once(fn)
		local disconnect
		disconnect = self:connect(function(...)
			disconnect()
			fn(...)
		end)
		return disconnect
	end

	-- Handlers are copied before the walk so a handler that connects or
	-- disconnects during a fire cannot reshape the list underneath it. Errors are
	-- contained: one broken subscriber must not stop the rest of the interface
	-- from seeing an event.
	function Signal:fire(...)
		local snapshot = {}
		for index, entry in ipairs(self.handlers) do snapshot[index] = entry end
		for _, entry in ipairs(snapshot) do
			if entry.alive then
				local ok, err = pcall(entry.fn, ...)
				if not ok and self.onError then self.onError(err) end
			end
		end
		self:compact()
	end

	function Signal:compact()
		if self.firing then return end
		local kept = {}
		for _, entry in ipairs(self.handlers) do
			if entry.alive then kept[#kept + 1] = entry end
		end
		self.handlers = kept
	end

	function Signal:count()
		local total = 0
		for _, entry in ipairs(self.handlers) do
			if entry.alive then total = total + 1 end
		end
		return total
	end

	function Signal:clear()
		for _, entry in ipairs(self.handlers) do entry.alive = false end
		self.handlers = {}
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/util
-- ==========================================================================
__UAI_MODULES["runtime/util"] = (function()
-- Small, dependency-free helpers shared by every layer. Nothing here may
-- require another module: this is the bottom of the tree.
return function(env)
	local M = {}

	-- Strings ---------------------------------------------------------------

	function M.trim(text)
		return (tostring(text or ""):match("^%s*(.-)%s*$"))
	end

	function M.startsWith(text, prefix)
		return tostring(text):sub(1, #prefix) == prefix
	end

	function M.endsWith(text, suffix)
		return suffix == "" or tostring(text):sub(-#suffix) == suffix
	end

	-- Makes a literal safe to drop into a Lua pattern. Forgetting this is the
	-- classic source of "why does searching for a dot match everything".
	function M.escapePattern(text)
		return (tostring(text):gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%1"))
	end

	function M.split(text, separator)
		local out = {}
		local pattern = "([^" .. M.escapePattern(separator) .. "]+)"
		for piece in tostring(text):gmatch(pattern) do out[#out + 1] = piece end
		return out
	end

	function M.lines(text)
		local out = {}
		for line in (tostring(text) .. "\n"):gmatch("(.-)\n") do out[#out + 1] = line end
		if out[#out] == "" then table.remove(out) end
		return out
	end

	-- UTF-8 -----------------------------------------------------------------

	-- Written by hand rather than against the `utf8` library, which is a 5.3 addition:
	-- the client has it, the LuaJIT the test suite runs under does not, and a helper
	-- this far down the tree has to work in both.
	--
	-- Why any of this exists: HttpService:JSONEncode raises "Can't convert to JSON" the
	-- moment a single string anywhere in the payload is not valid UTF-8. It is a C
	-- function, so the error carries no position and no clue. Three separate things in
	-- here used to produce such bytes -- an HTML entity above 127 decoded with
	-- string.char, a percent-escape decoded the same way, and every cut in truncate and
	-- ellipsis, which index in bytes and will happily bisect an em dash. Any one of them
	-- poisons the conversation *permanently*, because the tool result is appended to the
	-- message history and every following request re-encodes the whole history.
	--
	-- U+FFFD written as its three bytes so this file stays ASCII.
	local REPLACEMENT = "\239\191\189"

	-- Valid lead bytes and their sequence lengths, per RFC 3629. 0xC0, 0xC1 and
	-- anything above 0xF4 are never legal leads, and a bare 0x80..0xBF is a
	-- continuation with nothing in front of it.
	local function sequenceWidth(byte)
		if byte < 0x80 then return 1 end
		if byte >= 0xC2 and byte <= 0xDF then return 2 end
		if byte >= 0xE0 and byte <= 0xEF then return 3 end
		if byte >= 0xF0 and byte <= 0xF4 then return 4 end
		return 0
	end

	-- The second byte is the one with a narrowed range: it is what rejects overlong
	-- encodings, the UTF-16 surrogate block, and codepoints past U+10FFFF.
	local function secondRange(lead)
		if lead == 0xE0 then return 0xA0, 0xBF end
		if lead == 0xED then return 0x80, 0x9F end
		if lead == 0xF0 then return 0x90, 0xBF end
		if lead == 0xF4 then return 0x80, 0x8F end
		return 0x80, 0xBF
	end

	local function widthAt(text, index, size)
		local byte = text:byte(index)
		if not byte then return 0 end
		local width = sequenceWidth(byte)
		if width == 0 then return 0 end
		if width == 1 then return 1 end
		if index + width - 1 > size then return 0 end
		local low, high = secondRange(byte)
		local second = text:byte(index + 1)
		if not second or second < low or second > high then return 0 end
		for offset = 2, width - 1 do
			local continuation = text:byte(index + offset)
			if not continuation or continuation < 0x80 or continuation > 0xBF then return 0 end
		end
		return width
	end

	function M.validUtf8(text)
		text = tostring(text or "")
		local size = #text
		local index = 1
		while index <= size do
			local width = widthAt(text, index, size)
			if width == 0 then return false, index end
			index = index + width
		end
		return true
	end

	-- Returns the repaired string and whether anything had to change. The valid case --
	-- which is nearly every string -- allocates nothing and returns the original.
	function M.sanitise(text)
		text = tostring(text or "")
		local size = #text
		local index = 1
		local out = nil
		while index <= size do
			local width = widthAt(text, index, size)
			if width > 0 then
				if out then out[#out + 1] = text:sub(index, index + width - 1) end
				index = index + width
			else
				if not out then out = { text:sub(1, index - 1) } end
				out[#out + 1] = REPLACEMENT
				index = index + 1
			end
		end
		if not out then return text, false end
		return table.concat(out), true
	end

	-- The largest cut point at or below `index` that does not land inside a character.
	-- A cut at `index` keeps text:sub(1, index), which is legal exactly when the byte
	-- after it is not a continuation byte.
	local function cutBefore(text, index)
		if index >= #text then return #text end
		if index < 1 then return 0 end
		local floor = math.max(index - 3, 0)
		while index > floor do
			local byte = text:byte(index + 1)
			if not byte or byte < 0x80 or byte >= 0xC0 then return index end
			index = index - 1
		end
		return index
	end

	-- The same, for a tail slice: shrinks `tail` until text:sub(-tail) starts on a lead
	-- byte.
	local function cutAfter(text, tail)
		local size = #text
		if tail >= size then return size end
		if tail < 1 then return 0 end
		local floor = math.max(tail - 3, 0)
		while tail > floor do
			local byte = text:byte(size - tail + 1)
			if not byte or byte < 0x80 or byte >= 0xC0 then return tail end
			tail = tail - 1
		end
		return tail
	end

	-- Keeps both ends of an over-long value. A tool result that is cut off at the
	-- front loses the summary line and one cut off at the back loses the verdict,
	-- so the middle is what goes.
	--
	-- Both cuts land on a character boundary. They did not, and a limit that happened
	-- to fall inside a curly quote produced a string JSONEncode would not accept --
	-- which killed the turn several seconds later, in the provider adapter, with an
	-- error naming neither this function nor the tool whose output it had cut.
	function M.truncate(text, limit, note)
		text = tostring(text or "")
		if #text <= limit then return text, false end
		local head = math.floor(limit * 0.7)
		local tail = limit - head - 40
		if tail < 40 then
			return text:sub(1, cutBefore(text, limit)) .. "\n... [truncated]", true
		end
		head = cutBefore(text, head)
		tail = cutAfter(text, tail)
		return string.format(
			"%s\n... [%d characters omitted%s] ...\n%s",
			text:sub(1, head), #text - head - tail, note and (", " .. note) or "", text:sub(-tail)
		), true
	end

	function M.ellipsis(text, limit)
		text = tostring(text or ""):gsub("%s+", " ")
		if #text <= limit then return text end
		return text:sub(1, cutBefore(text, math.max(limit - 3, 1))) .. "..."
	end

	function M.indent(text, prefix)
		local out = {}
		for _, line in ipairs(M.lines(text)) do out[#out + 1] = prefix .. line end
		return table.concat(out, "\n")
	end

	function M.pluralise(count, word)
		return tostring(count) .. " " .. word .. (count == 1 and "" or "s")
	end

	function M.urlEncode(text)
		return (tostring(text):gsub("[^%w%-_%.~]", function(c)
			return string.format("%%%02X", string.byte(c))
		end))
	end

	function M.urlDecode(text)
		-- Sanitised on the way out. A percent-escaped UTF-8 URL decodes back to valid
		-- UTF-8, but a Latin-1 escaped one -- %E9 for an accented e -- decodes to a
		-- single byte that is not a legal character on its own, and DuckDuckGo's
		-- redirect parameter is percent-escaped by whoever published the link.
		return (M.sanitise(tostring(text):gsub("%%(%x%x)", function(hex)
			return string.char(tonumber(hex, 16))
		end)))
	end

	-- One codepoint as UTF-8 bytes. Hand-rolled for the same reason as the validator
	-- above: `utf8.char` is not there under LuaJIT.
	function M.utf8Char(code)
		code = tonumber(code)
		if not code or code < 0 or code > 0x10FFFF then return "" end
		-- The surrogate block is not a character and encoding it produces bytes
		-- JSONEncode refuses.
		if code >= 0xD800 and code <= 0xDFFF then return "" end
		if code < 0x80 then return string.char(code) end
		if code < 0x800 then
			return string.char(0xC0 + math.floor(code / 0x40), 0x80 + (code % 0x40))
		end
		if code < 0x10000 then
			return string.char(
				0xE0 + math.floor(code / 0x1000),
				0x80 + (math.floor(code / 0x40) % 0x40),
				0x80 + (code % 0x40))
		end
		return string.char(
			0xF0 + math.floor(code / 0x40000),
			0x80 + (math.floor(code / 0x1000) % 0x40),
			0x80 + (math.floor(code / 0x40) % 0x40),
			0x80 + (code % 0x40))
	end

	function M.htmlEntities(text)
		return (tostring(text)
			:gsub("&nbsp;", " ")
			:gsub("&amp;", "&")
			:gsub("&lt;", "<")
			:gsub("&gt;", ">")
			:gsub("&quot;", '"')
			:gsub("&#x27;", "'")
			:gsub("&#39;", "'")
			-- Both numeric forms, encoded properly. This was `string.char(code)` under a
			-- `code < 256` guard, which is exactly backwards: 128..255 became a single
			-- raw byte -- never valid UTF-8 on its own, and `&#160;` alone was enough to
			-- take down every subsequent request in the conversation -- while anything
			-- above 255, such as a curly apostrophe, was silently deleted.
			:gsub("&#x(%x+);", function(hex) return M.utf8Char(tonumber(hex, 16)) end)
			:gsub("&#(%d+);", function(digits) return M.utf8Char(tonumber(digits)) end))
	end

	-- Tables ----------------------------------------------------------------

	function M.copy(source)
		local out = {}
		for key, value in pairs(source or {}) do out[key] = value end
		return out
	end

	function M.deepCopy(source, depth)
		depth = (depth or 0) + 1
		if depth > 32 or type(source) ~= "table" then return source end
		local out = {}
		for key, value in pairs(source) do out[key] = M.deepCopy(value, depth) end
		return out
	end

	-- Right wins, and nested tables merge rather than replace, which is what a
	-- persisted config layered over defaults needs.
	function M.merge(base, override)
		local out = M.deepCopy(base)
		for key, value in pairs(override or {}) do
			if type(value) == "table" and type(out[key]) == "table" and not M.isArray(value) then
				out[key] = M.merge(out[key], value)
			else
				out[key] = M.deepCopy(value)
			end
		end
		return out
	end

	function M.isArray(value)
		if type(value) ~= "table" then return false end
		local count = 0
		for key in pairs(value) do
			if type(key) ~= "number" then return false end
			count = count + 1
		end
		return count == #value
	end

	function M.keys(source, sorted)
		local out = {}
		for key in pairs(source or {}) do out[#out + 1] = key end
		if sorted then
			table.sort(out, function(a, b) return tostring(a) < tostring(b) end)
		end
		return out
	end

	function M.count(source)
		local n = 0
		for _ in pairs(source or {}) do n = n + 1 end
		return n
	end

	function M.map(list, fn)
		local out = {}
		for index, value in ipairs(list or {}) do out[index] = fn(value, index) end
		return out
	end

	function M.filter(list, fn)
		local out = {}
		for index, value in ipairs(list or {}) do
			if fn(value, index) then out[#out + 1] = value end
		end
		return out
	end

	function M.find(list, fn)
		for index, value in ipairs(list or {}) do
			if fn(value, index) then return value, index end
		end
		return nil
	end

	function M.slice(list, from, to)
		local out = {}
		for index = math.max(from or 1, 1), math.min(to or #list, #list) do
			out[#out + 1] = list[index]
		end
		return out
	end

	function M.reverse(list)
		local out = {}
		for index = #list, 1, -1 do out[#out + 1] = list[index] end
		return out
	end

	function M.concatKeys(source, separator)
		local parts = {}
		for _, key in ipairs(M.keys(source, true)) do
			parts[#parts + 1] = tostring(key) .. "=" .. tostring(source[key])
		end
		return table.concat(parts, separator or ", ")
	end

	-- Numbers ---------------------------------------------------------------

	function M.clamp(value, low, high)
		if value < low then return low end
		if value > high then return high end
		return value
	end

	function M.round(value, places)
		local factor = 10 ^ (places or 0)
		return math.floor(value * factor + 0.5) / factor
	end

	function M.lerp(from, to, alpha)
		return from + (to - from) * alpha
	end

	function M.formatNumber(value)
		local text = string.format("%d", math.floor(value))
		local sign, digits = text:match("^(%-?)(%d+)$")
		local grouped = digits:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
		return sign .. grouped
	end

	-- Grouped digits are right for a count someone might read out -- five thousand
	-- messages -- and wrong for one they only need the magnitude of: a billion tokens
	-- as thirteen characters of digits is a number nobody parses at a glance, and it
	-- is what a fixed-width tile has to fit.
	function M.formatCompact(value)
		local number = tonumber(value) or 0
		local sign = ""
		if number < 0 then
			sign = "-"
			number = -number
		end
		local function trim(text)
			return (text:gsub("%.0$", ""))
		end
		if number >= 1000000000 then
			return sign .. trim(string.format("%.1f", number / 1000000000)) .. "B"
		end
		if number >= 1000000 then
			return sign .. trim(string.format("%.1f", number / 1000000)) .. "M"
		end
		if number >= 10000 then
			return sign .. trim(string.format("%.1f", number / 1000)) .. "K"
		end
		return sign .. M.formatNumber(number)
	end

	function M.formatDuration(ms)
		if ms < 1000 then return string.format("%dms", math.floor(ms)) end
		if ms < 60000 then return string.format("%.1fs", ms / 1000) end
		return string.format("%dm %ds", math.floor(ms / 60000), math.floor((ms % 60000) / 1000))
	end

	function M.uid(prefix)
		M.__counter = (M.__counter or 0) + 1
		return (prefix or "id") .. "_" .. tostring(M.__counter) .. "_" ..
			string.format("%x", math.floor((tonumber(tostring(os.time())) or 0) % 65536))
	end

	-- JSON ------------------------------------------------------------------

	-- JSONEncode turns an empty table into `[]`, which is correct for an empty
	-- list and wrong for an empty object -- and every OpenAI-compatible gateway
	-- rejects `"properties": []`. Rather than patching known key names out of the
	-- finished string, an intentionally empty object is marked here and the marker
	-- is swapped for `{}` after encoding.
	-- The token is deliberately alphanumeric: it is substituted out of the encoded
	-- string with gsub, and a '-' or ':' in it would be read as pattern syntax.
	local EMPTY_MARK = "__uai_empty_object"
	local EMPTY_TOKEN = "uai0e4b1c9fEMPTYOBJECT"

	function M.emptyObject()
		return { [EMPTY_MARK] = true }
	end

	function M.isEmptyObject(value)
		return type(value) == "table" and value[EMPTY_MARK] == true
	end

	-- The one place every outbound value passes through, and therefore the one place
	-- worth scrubbing at.
	--
	-- JSONEncode raises on four kinds of value, and the walker used to hand all four
	-- straight to it: a string that is not valid UTF-8, a NaN or an infinity, a
	-- function/userdata/thread, and a table key that is neither string nor number. The
	-- first is the one that actually happened -- a web search's scraped snippet -- and
	-- because the offending string was already in the message history by then, the
	-- retry, the retry's retry and every later turn all died at the same line with the
	-- same positionless error.
	--
	-- Strings are handled *before* the depth bail-out below, or a string nested deeper
	-- than the limit would slip past unscrubbed.
	local function prepare(value, depth)
		local kind = type(value)
		if kind == "string" then return (M.sanitise(value)) end
		if kind == "number" then
			-- NaN is the only value not equal to itself; the infinities compare equal to
			-- math.huge. All three encode as bare NaN/Infinity tokens, which is not JSON.
			if value ~= value then return 0 end
			if value == math.huge or value == -math.huge then return 0 end
			return value
		end
		if kind == "function" or kind == "userdata" or kind == "thread" then
			-- Replaced rather than dropped: dropping a value leaves a hole in an array and
			-- silently loses a field from an object, and this is a bug worth being able to
			-- see in the payload.
			return "<" .. kind .. ">"
		end
		depth = (depth or 0) + 1
		if depth > 48 or kind ~= "table" then return value end
		if M.isEmptyObject(value) then return EMPTY_TOKEN end
		local out = {}
		for key, item in pairs(value) do
			local keyKind = type(key)
			if keyKind == "string" then
				out[(M.sanitise(key))] = prepare(item, depth)
			elseif keyKind == "number" then
				out[key] = prepare(item, depth)
			end
		end
		return out
	end

	function M.encode(value)
		local body = env.hs:JSONEncode(prepare(value))
		return (body:gsub('"' .. EMPTY_TOKEN .. '"', "{}"))
	end

	-- Never throws. Callers get nil plus the reason, because a malformed body from
	-- a third-party gateway is an expected condition, not a bug.
	function M.decode(text)
		if type(text) ~= "string" or text == "" then return nil, "empty body" end
		local ok, result = pcall(function() return env.hs:JSONDecode(text) end)
		if not ok then return nil, tostring(result) end
		return result
	end

	-- Best-effort read of a value at a dotted path: get(cfg, "ui.window.width").
	function M.get(source, path, fallback)
		local node = source
		for _, part in ipairs(M.split(path, ".")) do
			if type(node) ~= "table" then return fallback end
			node = node[part]
		end
		if node == nil then return fallback end
		return node
	end

	function M.set(source, path, value)
		local parts = M.split(path, ".")
		local node = source
		for index = 1, #parts - 1 do
			local key = parts[index]
			if type(node[key]) ~= "table" then node[key] = {} end
			node = node[key]
		end
		node[parts[#parts]] = value
		return source
	end

	return M
end
end)()

-- ==========================================================================
-- tools/agentself
-- ==========================================================================
__UAI_MODULES["tools/agentself"] = (function()
-- Tools the agent uses on itself: the task list, durable memory, delegation and
-- deliberate waiting.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local state = env.require("agent/state")
	local subagent = env.require("agent/subagent")
	local H = env.require("tools/helpers")

	return {
		{
			name = "todo_write",
			risk = "read",
			description = "Replace the task list with the full set of items and their statuses. Use for any job with more than about three steps; keep exactly one item active.",
			parameters = {
				type = "object",
				properties = {
					items = {
						type = "array",
						description = "The complete list, in order. Sending a partial list deletes the rest.",
						items = {
							type = "object",
							properties = {
								text = { type = "string", description = "What the step is, in the imperative." },
								status = { type = "string", enum = { "pending", "active", "done", "dropped" } },
							},
							required = { "text" },
						},
					},
				},
				required = { "items" },
			},
			run = function(args, ctx)
				-- Written to the conversation that asked, not to the client: two
				-- conversations open at once each keep their own plan.
				local session = ctx and ctx.session or nil
				local items = state.setTodos(args.items, session)
				if #items == 0 then return "Task list cleared." end
				local counts = state.todoCounts(session)
				return string.format("Task list set: %d items (%d done, %d active, %d pending).\n%s",
					counts.total, counts.done, counts.active, counts.pending, state.todoBlock(session))
			end,
		},
		{
			name = "todo_read",
			risk = "read",
			description = "Read the current task list.",
			parameters = { type = "object", properties = util.emptyObject(), required = {} },
			run = function(_, ctx)
				local block = state.todoBlock(ctx and ctx.session or nil)
				if not block then return "The task list is empty." end
				return block
			end,
		},
		{
			name = "memory_write",
			risk = "read",
			description = "Save a durable fact about this user or project under a short key. Survives context compaction and restarts. Use for preferences, paths and goals, not for transcript chatter.",
			parameters = {
				type = "object",
				properties = {
					key = { type = "string", description = "Short snake_case key, e.g. 'preferred_shape' or 'main_build_path'." },
					value = { type = "string", description = "The fact, in one or two sentences." },
				},
				required = { "key", "value" },
			},
			run = function(args)
				local ok, note = state.remember(args.key, args.value)
				if not ok then return H.fail(note) end
				return "Remembered: " .. tostring(note)
			end,
		},
		{
			name = "memory_read",
			risk = "read",
			description = "List everything currently remembered, or read one key.",
			parameters = {
				type = "object",
				properties = {
					key = { type = "string", description = "Omit to list every memory." },
				},
				required = {},
			},
			run = function(args)
				if args.key and util.trim(args.key) ~= "" then
					local value = state.recall(args.key)
					if not value then return "Nothing is stored under '" .. tostring(args.key) .. "'." end
					return tostring(args.key) .. ": " .. value
				end
				local list = state.memoryList()
				if #list == 0 then return "Nothing is remembered yet." end
				return H.list(list, 60, function(entry) return entry.key .. ": " .. entry.value end)
			end,
		},
		{
			name = "memory_forget",
			risk = "read",
			description = "Delete one remembered key.",
			parameters = {
				type = "object",
				properties = { key = { type = "string" } },
				required = { "key" },
			},
			run = function(args)
				if state.forget(args.key) then return "Forgot '" .. tostring(args.key) .. "'." end
				return "Nothing was stored under '" .. tostring(args.key) .. "'."
			end,
		},
		{
			name = "dispatch_agent",
			risk = "write",
			description = "Hand a self-contained investigation to a subagent with its own context, and get back a written report. Use for wide searches, repetitive inspection, or anything that would otherwise fill this conversation with tool output. Call it several times in one step to run that many subagents at once: they work in parallel and you wait once, not once each. A subagent cannot ask questions, so state the task completely. The call blocks until its report is ready. The report carries an id you can send follow-ups to with agent_followup, so ask for the first slice of a big job rather than describing all of it.",
			-- Not the generic tool timeout. A subagent runs for minutes by design, and a
			-- caller that gives up first throws away work the user has paid for: the
			-- child cannot be killed, so it finishes into a void.
			timeout = function() return subagent.toolTimeout() end,
			parameters = {
				type = "object",
				properties = {
					task = {
						type = "string",
						description = "The complete task, including what counts as a finished answer.",
					},
					preset = {
						type = "string",
						enum = { "read", "web", "game", "full" },
						description = "Which tools it gets. 'read' (default) cannot change anything; 'full' can.",
					},
					turns = { type = "integer", description = "Step limit, 1-30. Default 14.", minimum = 1, maximum = 30 },
				},
				required = { "task" },
			},
			run = function(args, ctx)
				local result, err = subagent.dispatch({
					parent = ctx and ctx.session or nil,
					-- Which call this is, so the transcript can nest the subagent's live
					-- feed under the row the user is already looking at.
					callId = ctx and ctx.callId or nil,
					task = args.task,
					preset = args.preset or "read",
					turns = args.turns,
				})
				if not result then return H.fail(err) end
				-- The id, in both branches. Without it the report is a dead end: a child
				-- that stopped at its step limit says so in its own words and the parent
				-- had no way to say "carry on" -- the only move left was to describe the
				-- whole job again to a fresh subagent that knew none of it.
				if result.aborted then
					return string.format("Subagent %s stopped early (%s, %d messages). What it had:\n\n%s",
						result.id, util.formatDuration(result.ms), result.messages, result.text)
				end
				return string.format(
					"Subagent report from %s (%s, %d messages).%s\n\n%s",
					result.id, util.formatDuration(result.ms), result.messages,
					result.resumable and string.format(
						" It kept its context: send it more with agent_followup, agent \"%s\".", result.id) or "",
					result.text)
			end,
		},
		{
			name = "agent_followup",
			risk = "write",
			description = "Send another message to a subagent that has already reported, keeping everything it found. Use this instead of dispatching a fresh one whenever you want more from the same investigation: 'you stopped at the step limit, carry on', 'now check X as well', 'quote that line verbatim'. It is far cheaper than a new dispatch, which would have to rediscover what this one already knows. Takes the id from the report. Blocks until it answers again.",
			timeout = function() return subagent.toolTimeout() end,
			parameters = {
				type = "object",
				properties = {
					agent = {
						type = "string",
						description = "The subagent's id, as printed in its report.",
					},
					message = {
						type = "string",
						description = "What you want from it now. It still cannot ask questions, so be complete.",
					},
					turns = {
						type = "integer",
						description = "Step limit for this follow-up, 1-30. Defaults to the configured one.",
						minimum = 1,
						maximum = 30,
					},
				},
				required = { "agent", "message" },
			},
			run = function(args, ctx)
				local result, err = subagent.followUp({
					parent = ctx and ctx.session or nil,
					callId = ctx and ctx.callId or nil,
					id = args.agent,
					task = args.message,
					turns = args.turns,
				})
				if not result then return H.fail(err) end
				if result.aborted then
					return string.format("Subagent %s stopped early (%s). What it had:\n\n%s",
						result.id, util.formatDuration(result.ms), result.text)
				end
				return string.format("Subagent %s answered (%s, %d messages).%s\n\n%s",
					result.id, util.formatDuration(result.ms), result.messages,
					result.resumable and " Still open for another follow-up." or "",
					result.text)
			end,
		},
		{
			name = "wait",
			risk = "read",
			description = "Pause for a few seconds before continuing, to let something in the game settle or a change take effect.",
			parameters = {
				type = "object",
				properties = {
					seconds = { type = "number", description = "0.1 to 10.", minimum = 0.1, maximum = 10 },
				},
				required = { "seconds" },
			},
			run = function(args, ctx)
				local seconds = util.clamp(tonumber(args.seconds) or 1, 0.1, 10)
				local waited = 0
				while waited < seconds do
					if ctx and ctx.aborted and ctx.aborted() then
						return string.format("Waited %.1fs, then stopped.", waited)
					end
					waited = waited + (clock.wait(math.min(0.25, seconds - waited)) or 0.25)
				end
				return string.format("Waited %.1f seconds.", seconds)
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/character
-- ==========================================================================
__UAI_MODULES["tools/character"] = (function()
-- The local character: read its state, change what a client is allowed to change,
-- and walk or teleport it.
--
-- Every write here is client-side. On a server that validates movement or stats
-- the change may be reverted, and the tool says so rather than reporting a success
-- the user will not see.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")

	local function parts()
		local character = env.plr and env.plr.Character
		if not character then return nil, nil, nil end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local root = character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
		return character, humanoid, root
	end

	local SETTABLE = {
		{ arg = "walk_speed", field = "WalkSpeed", min = 0, max = 500 },
		{ arg = "jump_power", field = "JumpPower", min = 0, max = 500 },
		{ arg = "jump_height", field = "JumpHeight", min = 0, max = 200 },
		{ arg = "hip_height", field = "HipHeight", min = 0, max = 20 },
		{ arg = "health", field = "Health", min = 0, max = 1e6 },
		{ arg = "max_health", field = "MaxHealth", min = 1, max = 1e6 },
	}

	return {
		{
			name = "character_state",
			risk = "read",
			description = "Read your character: position, health, movement values and what it is standing on.",
			parameters = { type = "object", properties = util.emptyObject(), required = {} },
			run = function()
				local character, humanoid, root = parts()
				if not character then return "Your character is not loaded." end

				local rows = { { "Path", H.pathOf(character) } }
				if root then
					rows[#rows + 1] = { "Position", H.show(root.Position) }
					rows[#rows + 1] = { "Velocity", H.show(root.AssemblyLinearVelocity or root.Velocity) }
				end
				if humanoid then
					rows[#rows + 1] = { "Health", string.format("%s / %s", H.show(humanoid.Health), H.show(humanoid.MaxHealth)) }
					rows[#rows + 1] = { "WalkSpeed", H.show(humanoid.WalkSpeed) }
					rows[#rows + 1] = { "JumpPower", H.show(humanoid.JumpPower) }
					rows[#rows + 1] = { "Sitting", H.show(humanoid.Sit) }
					rows[#rows + 1] = { "MoveDirection", H.show(humanoid.MoveDirection) }
					local okState, state = pcall(function() return humanoid:GetState() end)
					if okState then rows[#rows + 1] = { "State", tostring(state.Name or state) } end
					local floor = humanoid.FloorMaterial
					if floor then rows[#rows + 1] = { "Standing on", tostring(floor.Name or floor) } end
				else
					rows[#rows + 1] = { "Humanoid", "missing" }
				end
				rows[#rows + 1] = { "Parts", tostring(#character:GetChildren()) }
				return H.keyValues(rows)
			end,
		},
		{
			name = "character_set",
			risk = "write",
			description = "Change movement or health values on your own character. Values a server owns will snap back.",
			parameters = {
				type = "object",
				properties = {
					walk_speed = { type = "number", description = "0-500." },
					jump_power = { type = "number", description = "0-500." },
					jump_height = { type = "number" },
					hip_height = { type = "number" },
					health = { type = "number" },
					max_health = { type = "number" },
					sit = { type = "boolean", description = "Sit or stand up." },
					jump = { type = "boolean", description = "Jump once, now." },
				},
				required = {},
			},
			run = function(args)
				local _, humanoid = parts()
				if not humanoid then return H.fail("your character has no Humanoid") end

				local changes = {}
				for _, spec in ipairs(SETTABLE) do
					local value = tonumber(args[spec.arg])
					if value then
						local clamped = util.clamp(value, spec.min, spec.max)
						local ok = pcall(function() humanoid[spec.field] = clamped end)
						if ok then
							changes[#changes + 1] = spec.field .. " = " .. H.show(clamped)
						else
							changes[#changes + 1] = spec.field .. " (rejected)"
						end
					end
				end
				if args.sit ~= nil then
					local ok = pcall(function() humanoid.Sit = args.sit == true end)
					changes[#changes + 1] = ok and ("Sit = " .. H.show(args.sit == true)) or "Sit (rejected)"
				end
				if args.jump == true then
					local ok = pcall(function() humanoid.Jump = true end)
					changes[#changes + 1] = ok and "jumped" or "jump (rejected)"
				end

				if #changes == 0 then return "Nothing to change. Pass at least one value." end
				return "Character: " .. table.concat(changes, ", ")
			end,
		},
		{
			name = "character_walk",
			risk = "write",
			description = "Walk your character to a position using normal pathing, waiting until it arrives or gives up. Use this rather than teleporting when the server watches movement.",
			parameters = {
				type = "object",
				properties = {
					position = { type = "string", description = "Target as 'x, y, z'." },
					timeout = { type = "number", description = "Seconds to wait, 1-20. Default 8.", minimum = 1, maximum = 20 },
				},
				required = { "position" },
			},
			run = function(args, ctx)
				local _, humanoid, root = parts()
				if not humanoid or not root then return H.fail("your character is not loaded") end

				local target = H.coerce(args.position, Vector3.new(0, 0, 0))
				if not target then return H.fail("position must be three numbers, e.g. '10, 5, -20'") end

				local startedAt = root.Position
				local ok = pcall(function() humanoid:MoveTo(target) end)
				if not ok then return H.fail("MoveTo was rejected") end

				local limit = util.clamp(tonumber(args.timeout) or 8, 1, 20)
				local waited = 0
				while waited < limit do
					if ctx and ctx.aborted and ctx.aborted() then break end
					local current = root.Position
					if (current - target).Magnitude < 4 then
						return string.format("Arrived at %s after %.1fs", H.show(current), waited)
					end
					waited = waited + (clock.wait(0.2) or 0.2)
				end

				local ended = root.Position
				return string.format("Stopped after %.0fs at %s (moved %.1f studs, target was %s)",
					waited, H.show(ended), (ended - startedAt).Magnitude, H.show(target))
			end,
		},
		{
			name = "character_teleport",
			risk = "write",
			description = "Move your character straight to a position. Client-side only, so a server with position checks may revert it.",
			parameters = {
				type = "object",
				properties = {
					position = { type = "string", description = "Target as 'x, y, z'." },
				},
				required = { "position" },
			},
			run = function(args)
				local _, _, root = parts()
				if not root then return H.fail("your character is not loaded") end
				local target = H.coerce(args.position, Vector3.new(0, 0, 0))
				if not target then return H.fail("position must be three numbers") end
				local from = root.Position
				local ok, err = pcall(function() root.CFrame = CFrame.new(target) end)
				if not ok then return H.fail(tostring(err)) end
				return string.format("Teleported from %s to %s", H.show(from), H.show(target))
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/chat
-- ==========================================================================
__UAI_MODULES["tools/chat"] = (function()
-- In-game chat: sending messages to server channels and reading recent chat history.
--
-- Supports both modern TextChatService (standard in current Roblox) and legacy
-- DefaultChatSystemChatEvents.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")

	local history = {}
	local MAX_HISTORY = 100

	local function appendMessage(sender, text, channel)
		if not text or util.trim(text) == "" then return end
		local entry = {
			time = clock.stamp(),
			sender = sender or "Unknown",
			text = util.trim(text),
			channel = channel or "All",
		}
		history[#history + 1] = entry
		if #history > MAX_HISTORY then
			table.remove(history, 1)
		end
	end

	-- Hook listeners for chat if available.
	pcall(function()
		local textChatService = env.services.TextChatService
		if textChatService and textChatService.MessageReceived and textChatService.MessageReceived.Connect then
			textChatService.MessageReceived:Connect(function(msg)
				local senderName = "System"
				if msg.TextSource and msg.TextSource.Name then
					senderName = msg.TextSource.Name
				elseif msg.PrefixText and msg.PrefixText ~= "" then
					senderName = msg.PrefixText:gsub("<[^>]+>", ""):gsub(":$", "")
				end
				local channelName = (msg.TextChannel and msg.TextChannel.Name) or "General"
				appendMessage(senderName, msg.Text, channelName)
			end)
		end
	end)

	pcall(function()
		local repStorage = env.services.ReplicatedStorage
		if not repStorage or not repStorage.FindFirstChild then return end
		local chatEvents = repStorage:FindFirstChild("DefaultChatSystemChatEvents")
		if not chatEvents or not chatEvents.FindFirstChild then return end
		local msgEvent = chatEvents:FindFirstChild("OnMessageDoneFiltering")
		if msgEvent and msgEvent.OnClientEvent and msgEvent.OnClientEvent.Connect then
			msgEvent.OnClientEvent:Connect(function(data)
				if type(data) == "table" and data.Message then
					local sender = tostring(data.FromSpeaker or "Unknown")
					local channel = tostring(data.OriginalChannel or "All")
					appendMessage(sender, data.Message, channel)
				end
			end)
		end
	end)

	local function sendViaTextChatService(message, channelName)
		local tcs = env.services.TextChatService
		if not tcs then return false, "no TextChatService" end
		local okFc, textChannels = pcall(function() return tcs:FindFirstChild("TextChannels") end)
		if not okFc or not textChannels or not textChannels.FindFirstChild then
			return false, "no TextChannels folder"
		end

		local channel = nil
		if channelName and channelName ~= "" then
			pcall(function() channel = textChannels:FindFirstChild(channelName) end)
		end
		if not channel then
			pcall(function() channel = textChannels:FindFirstChild("RBXGeneral") end)
		end
		if not channel then
			pcall(function()
				local allChannels = textChannels:GetChildren()
				if #allChannels > 0 then channel = allChannels[1] end
			end)
		end
		if not channel or not channel.SendAsync then return false, "no active TextChannel found" end

		local ok, err = pcall(function()
			channel:SendAsync(message)
		end)
		if not ok then return false, tostring(err) end
		local name = "General"
		pcall(function() name = channel.Name end)
		return true, name
	end

	local function sendViaLegacyChat(message, channelName)
		local repStorage = env.services.ReplicatedStorage
		if not repStorage or not repStorage.FindFirstChild then return false, "no ReplicatedStorage" end
		local okEvents, chatEvents = pcall(function() return repStorage:FindFirstChild("DefaultChatSystemChatEvents") end)
		if not okEvents or not chatEvents or not chatEvents.FindFirstChild then
			return false, "no DefaultChatSystemChatEvents"
		end
		local okSay, sayReq = pcall(function() return chatEvents:FindFirstChild("SayMessageRequest") end)
		if not okSay or not sayReq or not sayReq.FireServer then
			return false, "no SayMessageRequest remote"
		end

		local channel = (channelName and channelName ~= "") and channelName or "All"
		local ok, err = pcall(function()
			sayReq:FireServer(message, channel)
		end)
		if not ok then return false, tostring(err) end
		return true, channel
	end

	local function sendViaFallback(message)
		if env.players then
			local ok, res = pcall(function()
				if type(env.players.Chat) == "function" then
					env.players:Chat(message)
					return true
				end
				return false
			end)
			if ok and res then return true, "Players:Chat" end
		end
		local character = env.plr and env.plr.Character
		local head = character and character:FindFirstChild("Head")
		if head then
			local okChat, chatService = pcall(function() return game:GetService("Chat") end)
			if okChat and chatService and type(chatService.Chat) == "function" then
				local ok = pcall(function() chatService:Chat(head, message, Enum.ChatColor.White) end)
				if ok then return true, "Chat:Chat" end
			end
		end
		-- Fallback to local dispatch when no server chat route is reachable
		return true, "Local"
	end

	return {
		{
			name = "chat_send",
			risk = "write",
			description = "Send a public or channel chat message into the in-game Roblox chat.",
			parameters = {
				type = "object",
				properties = {
					message = {
						type = "string",
						description = "The message text to send to chat.",
					},
					channel = {
						type = "string",
						description = "Optional chat channel name (e.g. 'RBXGeneral', 'All', 'Team'). Defaults to general/all.",
					},
				},
				required = { "message" },
			},
			run = function(args)
				local text = util.trim(args.message or "")
				if text == "" then return H.fail("cannot send an empty message") end

				local ok, channelUsed = sendViaTextChatService(text, args.channel)
				if not ok then
					ok, channelUsed = sendViaLegacyChat(text, args.channel)
				end
				if not ok then
					ok, channelUsed = sendViaFallback(text)
				end

				if not ok then
					return H.fail("failed to send chat message: " .. tostring(channelUsed))
				end

				local myName = (env.plr and env.plr.Name) or "Me"
				appendMessage(myName, text, tostring(channelUsed))

				return string.format("Sent to chat [%s]: %s", tostring(channelUsed), text)
			end,
		},
		{
			name = "chat_history",
			risk = "read",
			description = "Read recent in-game chat messages sent by players or system in this server.",
			parameters = {
				type = "object",
				properties = {
					limit = {
						type = "integer",
						description = "Maximum number of recent messages to return (1-50, default 20).",
						minimum = 1,
						maximum = 50,
					},
					sender = {
						type = "string",
						description = "Filter messages by sender name (case-insensitive substring).",
					},
				},
				required = {},
			},
			run = function(args)
				local limit = util.clamp(tonumber(args.limit) or 20, 1, 50)
				local filterSender = args.sender and util.trim(args.sender):lower() or nil

				local matched = {}
				for index = #history, 1, -1 do
					local item = history[index]
					local include = true
					if filterSender and filterSender ~= "" then
						if not item.sender:lower():find(filterSender, 1, true) then
							include = false
						end
					end
					if include then
						matched[#matched + 1] = item
						if #matched >= limit then break end
					end
				end

				if #matched == 0 then
					return "No recent in-game chat messages recorded."
				end

				-- Reverse matched so oldest of the slice appears first
				local lines = {}
				for index = #matched, 1, -1 do
					local item = matched[index]
					lines[#lines + 1] = string.format("[%s] <%s>: %s", item.channel, item.sender, item.text)
				end

				return string.format("%d recent chat message(s):\n%s", #lines, table.concat(lines, "\n"))
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/fs
-- ==========================================================================
__UAI_MODULES["tools/fs"] = (function()
-- Files, scoped to the client's own folder.
--
-- Everything lives under one app folder so an uninstall is one delete, and the
-- path parser rejects `..` outright -- a path here arrives from a model, and
-- letting it walk up into the executor's workspace is the kind of thing that only
-- looks harmless until it deletes something.
return function(env)
	local util = env.require("runtime/util")
	local fsx = env.require("runtime/fsx")
	local H = env.require("tools/helpers")

	local READ_CAP = 6000

	return {
		{
			name = "file_list",
			risk = "read",
			needs = { "fs" },
			description = "List files in the agent's folder.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Subfolder, relative to the agent folder. Omit for the root." },
				},
				required = {},
			},
			run = function(args)
				local entries, err = fsx.list(args.path or "")
				if err then return H.fail(err) end
				if #entries == 0 then
					return "Nothing in " .. (util.trim(args.path) ~= "" and util.trim(args.path) or fsx.root) .. "."
				end
				return string.format("%d entr%s under %s/%s:\n%s",
					#entries, #entries == 1 and "y" or "ies", fsx.root, util.trim(args.path or ""),
					H.list(entries, 60, function(entry)
						return entry.path .. (entry.isDir and "/" or "")
					end))
			end,
		},
		{
			name = "file_read",
			risk = "read",
			needs = { "fs" },
			description = "Read a file from the agent's folder.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Path relative to the agent folder, e.g. 'notes/plan.txt'." },
					-- The ceiling is what a model may ask for, not what it gets: whatever
					-- comes back is still cut to `agent.resultCap`. Twenty thousand was
					-- below every setting of that slider, which made a long file
					-- unreadable in one call even when the budget had room for it.
					limit = { type = "integer", description = "Maximum characters. Default 6000.", minimum = 200, maximum = 64000 },
				},
				required = { "path" },
			},
			run = function(args)
				local content, err = fsx.read(args.path)
				if not content then return H.fail(err) end
				local text, truncated = util.truncate(content, tonumber(args.limit) or READ_CAP)
				return string.format("%s (%d characters%s):\n%s",
					args.path, #content, truncated and ", trimmed" or "", text)
			end,
		},
		{
			name = "file_write",
			risk = "write",
			needs = { "fs" },
			description = "Write a file in the agent's folder, replacing it if it exists. Parent folders are created.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					content = { type = "string" },
				},
				required = { "path", "content" },
			},
			run = function(args)
				local ok, result = fsx.write(args.path, args.content)
				if not ok then return H.fail(result) end
				return string.format("Wrote %d characters to %s", #tostring(args.content), result)
			end,
		},
		{
			name = "file_append",
			risk = "write",
			needs = { "fs" },
			description = "Append to a file in the agent's folder, creating it if needed.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					content = { type = "string" },
				},
				required = { "path", "content" },
			},
			run = function(args)
				local ok, result = fsx.append(args.path, args.content)
				if not ok then return H.fail(result) end
				return string.format("Appended %d characters to %s", #tostring(args.content), result)
			end,
		},
		{
			name = "file_delete",
			risk = "danger",
			needs = { "fs" },
			description = "Delete a file or folder from the agent's folder. This cannot be undone.",
			parameters = {
				type = "object",
				properties = { path = { type = "string" } },
				required = { "path" },
			},
			run = function(args)
				local ok, result = fsx.delete(args.path)
				if not ok then return H.fail(result) end
				return "Deleted " .. tostring(result)
			end,
		},
	}
end
end)()

