-- tools/players
-- ==========================================================================
__UAI_MODULES["tools/players"] = (function()
-- Other players: who is here, what state they are in, and getting to them.
return function(env)
	local util = env.require("runtime/util")
	local H = env.require("tools/helpers")

	-- Name matching is a case-insensitive substring over both the username and the
	-- display name, because a model working from chat has usually seen the display
	-- name and the two are frequently different.
	local function findPlayer(query)
		local needle = util.trim(query):lower()
		if needle == "" then return nil, "give a player name" end
		local matches = {}
		for _, player in ipairs(env.players:GetPlayers()) do
			local name = tostring(player.Name):lower()
			local display = tostring(player.DisplayName or ""):lower()
			if name == needle or display == needle then
				return player
			end
			if name:find(needle, 1, true) or display:find(needle, 1, true) then
				matches[#matches + 1] = player
			end
		end
		if #matches == 1 then return matches[1] end
		if #matches > 1 then
			local names = util.map(matches, function(player) return player.Name end)
			return nil, "several players match '" .. util.trim(query) .. "': " .. table.concat(names, ", ")
		end
		return nil, "no player here matches '" .. util.trim(query) .. "'"
	end

	local function rootOf(player)
		local character = player and player.Character
		if not character then return nil end
		return character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
	end

	local function distanceTo(player)
		local mine = rootOf(env.plr)
		local theirs = rootOf(player)
		if not mine or not theirs then return nil end
		return (theirs.Position - mine.Position).Magnitude
	end

	return {
		{
			name = "players_list",
			risk = "read",
			description = "List everyone in the server with their distance from you.",
			parameters = {
				type = "object",
				properties = {
					limit = { type = "integer", minimum = 1, maximum = 100 },
				},
				required = {},
			},
			run = function(args)
				local players = env.players:GetPlayers()
				if #players == 0 then return "No players are in the server." end
				table.sort(players, function(a, b)
					return (distanceTo(a) or math.huge) < (distanceTo(b) or math.huge)
				end)
				return string.format("%d player(s):\n%s", #players,
					H.list(players, H.limit(args.limit, 40, 100), function(player)
						local bits = { player.Name }
						if player.DisplayName and player.DisplayName ~= player.Name then
							bits[#bits + 1] = "(" .. player.DisplayName .. ")"
						end
						if player == env.plr then bits[#bits + 1] = "[you]" end
						local distance = distanceTo(player)
						if distance then bits[#bits + 1] = string.format("%.0f studs", distance) end
						if not player.Character then bits[#bits + 1] = "no character" end
						return table.concat(bits, " ")
					end))
			end,
		},
		{
			name = "player_info",
			risk = "read",
			description = "Details for one player: ids, team, character state, position and distance.",
			parameters = {
				type = "object",
				properties = { player = { type = "string", description = "Username or display name; a substring is enough." } },
				required = { "player" },
			},
			run = function(args)
				local player, err = findPlayer(args.player)
				if not player then return H.fail(err) end

				local rows = {
					{ "Name", player.Name },
					{ "DisplayName", tostring(player.DisplayName) },
					{ "UserId", tostring(player.UserId) },
					{ "AccountAge", tostring(player.AccountAge) .. " days" },
					{ "Team", player.Team and tostring(player.Team.Name) or "none" },
					{ "Is you", player == env.plr and "yes" or "no" },
				}

				local character = player.Character
				if not character then
					rows[#rows + 1] = { "Character", "not loaded" }
				else
					local humanoid = character:FindFirstChildOfClass("Humanoid")
					if humanoid then
						rows[#rows + 1] = { "Health", string.format("%s / %s",
							H.show(humanoid.Health), H.show(humanoid.MaxHealth)) }
						rows[#rows + 1] = { "WalkSpeed", H.show(humanoid.WalkSpeed) }
						local okState, state = pcall(function() return humanoid:GetState() end)
						if okState then rows[#rows + 1] = { "State", tostring(state.Name or state) } end
					end
					local root = rootOf(player)
					if root then
						rows[#rows + 1] = { "Position", H.show(root.Position) }
						local distance = distanceTo(player)
						if distance then rows[#rows + 1] = { "Distance", string.format("%.1f studs", distance) } end
					end
					rows[#rows + 1] = { "Character path", H.pathOf(character) }
				end

				return H.keyValues(rows)
			end,
		},
		{
			name = "teleport_to_player",
			risk = "write",
			description = "Move your character next to another player. Client-side only: on a server with position checks this may be reverted or punished.",
			parameters = {
				type = "object",
				properties = {
					player = { type = "string" },
					offset = { type = "number", description = "Studs to stand away from them. Default 4.", minimum = 0, maximum = 60 },
				},
				required = { "player" },
			},
			run = function(args)
				local player, err = findPlayer(args.player)
				if not player then return H.fail(err) end
				if player == env.plr then return "That is you." end

				local target = rootOf(player)
				if not target then return H.fail(player.Name .. " has no character loaded") end
				local mine = rootOf(env.plr)
				if not mine then return H.fail("your character is not loaded") end

				local offset = util.clamp(tonumber(args.offset) or 4, 0, 60)
				local destination = target.Position + Vector3.new(offset, 0, 0)
				local ok, setErr = pcall(function()
					mine.CFrame = CFrame.new(destination)
				end)
				if not ok then return H.fail(tostring(setErr)) end
				return string.format("Moved to %s at %s", player.Name, H.show(destination))
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/remotes
-- ==========================================================================
__UAI_MODULES["tools/remotes"] = (function()
-- Remotes: find them, call them, watch what the server sends.
--
-- Firing a remote is the single most consequential thing in this toolset -- it is
-- the one that talks to the server, so it is the one that can get an account
-- actioned. Both call tools are marked dangerous and neither guesses at argument
-- types: the model states them.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")

	local REMOTE_CLASSES = { "RemoteEvent", "RemoteFunction", "UnreliableRemoteEvent" }

	-- Typed argument forms, so a model can pass a Vector3 or an Instance through
	-- JSON without the tool having to guess from a string's shape.
	local PREFIXES = {
		vec3 = function(text) return H.coerce(text, Vector3.new(0, 0, 0)) end,
		vector3 = function(text) return H.coerce(text, Vector3.new(0, 0, 0)) end,
		vec2 = function(text) return H.coerce(text, Vector2.new(0, 0)) end,
		color3 = function(text) return H.coerce(text, Color3.new(0, 0, 0)) end,
		cframe = function(text) return H.coerce(text, CFrame.new(0, 0, 0)) end,
		instance = function(text) return H.resolve(text) end,
		number = function(text) return tonumber(text) end,
		string = function(text) return tostring(text) end,
	}

	local function convertArgs(list)
		local out = {}
		local notes = {}
		for index, item in ipairs(list or {}) do
			if type(item) == "string" then
				local prefix, rest = item:match("^(%a+):(.*)$")
				if prefix and PREFIXES[prefix:lower()] then
					local value, err = PREFIXES[prefix:lower()](rest)
					if value == nil then
						return nil, string.format("argument %d (%s) could not be converted: %s",
							index, prefix, tostring(err or "bad value"))
					end
					out[index] = value
					notes[#notes + 1] = string.format("%d=%s", index, H.show(value))
				else
					out[index] = item
					notes[#notes + 1] = string.format("%d=%q", index, util.ellipsis(item, 40))
				end
			else
				out[index] = item
				notes[#notes + 1] = string.format("%d=%s", index, H.show(item))
			end
		end
		return out, table.concat(notes, ", "), #list
	end

	local function findRemote(path, wanted)
		local instance, err = H.resolve(path)
		if not instance then return nil, err end
		local matches = false
		for _, class in ipairs(wanted or REMOTE_CLASSES) do
			local ok, isA = pcall(function() return instance:IsA(class) end)
			if ok and isA then matches = true end
		end
		if not matches then
			return nil, string.format("%s is a %s, not a %s", H.pathOf(instance), instance.ClassName,
				table.concat(wanted or REMOTE_CLASSES, " or "))
		end
		return instance
	end

	return {
		{
			name = "remotes_list",
			risk = "read",
			description = "Find remotes in the place, with how many client-side listeners each has when the host can tell.",
			parameters = {
				type = "object",
				properties = {
					root = { type = "string", description = "Where to search. Defaults to game." },
					name = { type = "string", description = "Substring filter on the remote name." },
					limit = { type = "integer", minimum = 1, maximum = 100 },
				},
				required = {},
			},
			run = function(args)
				local root, err = H.resolve(args.root or "game")
				if not root then return H.fail(err) end
				local needle = util.trim(args.name):lower()

				local ok, descendants = pcall(function() return root:GetDescendants() end)
				if not ok then return H.fail("could not read that subtree") end

				local hits = {}
				for _, node in ipairs(descendants) do
					local isRemote = false
					for _, class in ipairs(REMOTE_CLASSES) do
						local okA, isA = pcall(function() return node:IsA(class) end)
						if okA and isA then isRemote = true end
					end
					if isRemote and (needle == "" or tostring(node.Name):lower():find(needle, 1, true)) then
						hits[#hits + 1] = node
					end
				end

				if #hits == 0 then return "No remotes found under " .. H.pathOf(root) .. "." end
				return string.format("%d remote(s):\n%s", #hits,
					H.list(hits, H.limit(args.limit, 30, 100), function(node)
						local suffix = ""
						if caps.fn.getconnections then
							local signalName = node:IsA("RemoteFunction") and nil or "OnClientEvent"
							if signalName then
								local okConn, connections = pcall(caps.fn.getconnections, node[signalName])
								if okConn and type(connections) == "table" then
									suffix = string.format(" (%d listener%s)", #connections, #connections == 1 and "" or "s")
								end
							end
						end
						return H.pathOf(node) .. " [" .. node.ClassName .. "]" .. suffix
					end))
			end,
		},
		{
			name = "remote_fire",
			risk = "danger",
			description = "Fire a RemoteEvent to the server. This is a real server call: it can change the game and can be logged or punished by anticheat. Prefix an argument with a type when it is not a plain string or number, e.g. 'vec3:0, 10, 0' or 'instance:Workspace.Door'.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Dotted path to the RemoteEvent." },
					args = {
						type = "array",
						description = "Arguments in order. Strings, numbers, booleans, or a typed form such as 'vec3:1, 2, 3'.",
						-- `items` is a schema, so it has to encode as {} and not as [].
						-- An empty one means "any value", which is the intent here.
						items = util.emptyObject(),
					},
				},
				required = { "path" },
			},
			run = function(args)
				local remote, err = findRemote(args.path, { "RemoteEvent", "UnreliableRemoteEvent" })
				if not remote then return H.fail(err) end
				local values, notes = convertArgs(args.args)
				if not values then return H.fail(notes) end
				local ok, fireErr = pcall(function() remote:FireServer(unpack(values, 1, #(args.args or {}))) end)
				if not ok then return H.fail(tostring(fireErr)) end
				return string.format("Fired %s with %d argument(s)%s",
					H.pathOf(remote), #(args.args or {}), notes ~= "" and (": " .. notes) or "")
			end,
		},
		{
			name = "remote_invoke",
			risk = "danger",
			description = "Invoke a RemoteFunction and return what the server answers. Blocks until it replies, and can hang if the server never does.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					args = { type = "array", items = util.emptyObject() },
				},
				required = { "path" },
			},
			run = function(args)
				local remote, err = findRemote(args.path, { "RemoteFunction" })
				if not remote then return H.fail(err) end
				local values, notes = convertArgs(args.args)
				if not values then return H.fail(notes) end

				local finished, ok, result = clock.timeout(8, function()
					return remote:InvokeServer(unpack(values, 1, #(args.args or {})))
				end)
				if not finished then
					return "The server did not answer within 8 seconds. The call is still outstanding."
				end
				if not ok then return H.fail(tostring(result)) end
				return string.format("%s returned: %s%s",
					H.pathOf(remote), H.show(result), notes ~= "" and ("\nSent: " .. notes) or "")
			end,
		},
		{
			name = "remote_watch",
			risk = "read",
			description = "Listen to a RemoteEvent and report the next few things the server sends through it. Useful for learning a remote's argument shape before firing it.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					count = { type = "integer", description = "Calls to capture, 1-10. Default 3.", minimum = 1, maximum = 10 },
					timeout = { type = "number", description = "Seconds to wait, 1-20. Default 8.", minimum = 1, maximum = 20 },
				},
				required = { "path" },
			},
			run = function(args, ctx)
				local remote, err = findRemote(args.path, { "RemoteEvent", "UnreliableRemoteEvent" })
				if not remote then return H.fail(err) end

				local wanted = H.limit(args.count, 3, 10)
				local limit = util.clamp(tonumber(args.timeout) or 8, 1, 20)
				local captured = {}

				local connection = remote.OnClientEvent:Connect(function(...)
					if #captured >= wanted then return end
					local parts = {}
					for index = 1, select("#", ...) do
						parts[#parts + 1] = string.format("%d: %s", index, H.show((select(index, ...))))
					end
					captured[#captured + 1] = #parts > 0 and table.concat(parts, ", ") or "(no arguments)"
				end)

				local waited = 0
				while #captured < wanted and waited < limit do
					if ctx and ctx.aborted and ctx.aborted() then break end
					waited = waited + (clock.wait(0.1) or 0.1)
				end
				pcall(function() connection:Disconnect() end)

				if #captured == 0 then
					return string.format("%s sent nothing in %.0f seconds.", H.pathOf(remote), waited)
				end
				return string.format("%s fired %d time(s) in %.1fs:\n%s",
					H.pathOf(remote), #captured, waited, H.list(captured, wanted))
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/script
-- ==========================================================================
__UAI_MODULES["tools/script"] = (function()
-- Running and reading Luau.
--
-- Execution is the most dangerous thing in the toolset and the least reviewable,
-- so it is marked accordingly and it is deliberately awkward: output is captured
-- rather than printed, the thread is abandoned on timeout rather than pretended
-- to be stopped, and the two loop forms that cannot yield are rewritten so the
-- client stays interruptible.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")

	local EXEC_TIMEOUT = 10
	local LOG_CAP = 120

	return {
		{
			name = "run_luau",
			risk = "danger",
			needs = { "exec" },
			description = "Compile and run Luau on the local client. Returns anything printed plus the return value. Every loop must call task.wait() or the client freezes. Prefer a specific tool when one exists.",
			parameters = {
				type = "object",
				properties = {
					code = { type = "string", description = "The source to run. Use print() for output; return a value to report it." },
				},
				required = { "code" },
			},
			run = function(args, ctx)
				local code = tostring(args.code or "")
				if util.trim(code) == "" then return "Nothing to run." end

				-- A loop with no body cannot yield, so no timeout, thread or stop
				-- button can reach it -- the scheduler itself is blocked. These two
				-- forms have no legitimate use, so they get a yield. Loops with a real
				-- body are left alone: injecting a wait into one that already yields
				-- would silently halve its speed.
				local patched = code
					:gsub("while%s+true%s+do%s*end", "while true do task.wait() end")
					:gsub("repeat%s*until%s+false", "repeat task.wait() until false")

				local compile = caps.fn.loadstring
				local fn, compileErr = compile(patched)
				if not fn then return "Compile error: " .. tostring(compileErr) end

				local logs = {}
				local truncatedLogs = false
				local globals = (caps.fn.getgenv and caps.fn.getgenv()) or _G
				local sandbox = setmetatable({
					print = function(...)
						if #logs >= LOG_CAP then
							truncatedLogs = true
							return
						end
						local parts = {}
						for index = 1, select("#", ...) do
							parts[#parts + 1] = H.show((select(index, ...)))
						end
						logs[#logs + 1] = table.concat(parts, "\t")
					end,
					warn = function(...)
						if #logs >= LOG_CAP then
							truncatedLogs = true
							return
						end
						local parts = {}
						for index = 1, select("#", ...) do
							parts[#parts + 1] = H.show((select(index, ...)))
						end
						logs[#logs + 1] = "[warn] " .. table.concat(parts, "\t")
					end,
				}, { __index = globals, __newindex = globals })
				if setfenv then pcall(setfenv, fn, sandbox) end

				local started = clock.ms()
				local finished, ok, result = clock.timeout(EXEC_TIMEOUT, fn)

				local output = {}
				if not finished then
					output[#output + 1] = string.format(
						"Timed out after %ds and was left running in the background. It was not stopped -- Luau cannot kill a thread. Do not retry the same code; make it finish or yield.",
						EXEC_TIMEOUT)
				elseif not ok then
					output[#output + 1] = "Runtime error: " .. tostring(result)
				else
					output[#output + 1] = string.format("Ran in %s.", util.formatDuration(clock.since(started)))
					if result ~= nil then output[#output + 1] = "Returned: " .. H.show(result) end
				end

				if #logs > 0 then
					output[#output + 1] = "Output:\n" .. table.concat(logs, "\n")
					if truncatedLogs then
						output[#output + 1] = string.format("(output stopped after %d lines)", LOG_CAP)
					end
				end
				return table.concat(output, "\n")
			end,
		},
		{
			name = "script_list",
			risk = "read",
			description = "List script instances in the place, with their paths. Useful for finding where behaviour lives before reading it.",
			parameters = {
				type = "object",
				properties = {
					root = { type = "string", description = "Where to search. Defaults to game." },
					kind = { type = "string", enum = { "any", "Script", "LocalScript", "ModuleScript" } },
					limit = { type = "integer", minimum = 1, maximum = 100 },
				},
				required = {},
			},
			run = function(args)
				local root, err = H.resolve(args.root or "game")
				if not root then return H.fail(err) end
				local wanted = args.kind
				if not wanted or wanted == "any" then wanted = "LuaSourceContainer" end

				local ok, descendants = pcall(function() return root:GetDescendants() end)
				if not ok then return H.fail("could not read that subtree") end

				local hits = {}
				for _, node in ipairs(descendants) do
					local okA, isA = pcall(function() return node:IsA(wanted) end)
					if okA and isA then hits[#hits + 1] = node end
				end
				if #hits == 0 then return "No scripts found under " .. H.pathOf(root) .. "." end
				return string.format("%d script(s):\n%s", #hits,
					H.list(hits, H.limit(args.limit, 30, 100), function(node)
						return H.pathOf(node) .. " [" .. node.ClassName .. "]"
					end))
			end,
		},
		{
			name = "script_source",
			risk = "read",
			description = "Read a script's source. Works when the host can read or decompile it; many live scripts cannot be read at all.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string", description = "Dotted path to the script instance." },
					limit = { type = "integer", description = "Maximum characters to return. Default 3000.", minimum = 200, maximum = 64000 },
				},
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end

				local okA, isScript = pcall(function() return instance:IsA("LuaSourceContainer") end)
				if not okA or not isScript then
					return H.fail(instance.ClassName .. " is not a script")
				end

				local source
				local okSource, value = pcall(function() return instance.Source end)
				if okSource and type(value) == "string" and value ~= "" then
					source = value
				elseif caps.fn.decompile then
					local okDecomp, decompiled = pcall(caps.fn.decompile, instance)
					if okDecomp and type(decompiled) == "string" then source = decompiled end
				end

				if not source or util.trim(source) == "" then
					return "The source is not readable from here. Roblox hides Source from client scripts, and this host has no decompiler."
				end

				local limit = tonumber(args.limit) or 3000
				local text, truncated = util.truncate(source, limit)
				return string.format("%s (%d characters%s):\n%s",
					H.pathOf(instance), #source, truncated and ", trimmed" or "", text)
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/web
-- ==========================================================================
__UAI_MODULES["tools/web"] = (function()
-- The public web: search, and turn a page into readable text.
--
-- These are the one place a browser User-Agent is sent instead of the client's
-- own. It is not a preference: DuckDuckGo's HTML endpoint and most CDNs answer 403
-- to an unfamiliar agent, so a search tool that presented the CLI identity would
-- simply never work.
return function(env)
	local util = env.require("runtime/util")
	local http = env.require("net/http")
	local H = env.require("tools/helpers")

	local PAGE_CAP = 4000

	-- Sanitised at the end, not only at encode time.
	--
	-- A third-party page can be served as Latin-1, CP1252 or nothing at all, and
	-- Roblox's HTTP client hands back the bytes as they arrived. Scrubbing here as well
	-- as in util.encode is not belt-and-braces: this text is also what the transcript
	-- paints, what the Logs panel keeps and what the bridge uploads, and a raw 0xA0 in
	-- a TextLabel is a visible replacement glyph rather than an error anyone can trace.
	local function toText(html)
		local text = tostring(html)
			:gsub("<!%-%-.-%-%->", " ")
			:gsub("<script.-</script>", " ")
			:gsub("<style.-</style>", " ")
			:gsub("<noscript.-</noscript>", " ")
			:gsub("<svg.-</svg>", " ")
			:gsub("<br%s*/?>", "\n")
			:gsub("</p>", "\n\n")
			:gsub("</h%d>", "\n\n")
			:gsub("</li>", "\n")
			:gsub("<[^>]+>", " ")
		text = util.htmlEntities(text)
		text = text:gsub("[ \t]+", " "):gsub(" ?\n ?", "\n"):gsub("\n\n\n+", "\n\n")
		return (util.sanitise(util.trim(text)))
	end

	return {
		{
			name = "web_search",
			risk = "read",
			needs = { "http" },
			description = "Search the web and return titles, URLs and snippets. Use when the answer depends on something current or outside the game.",
			parameters = {
				type = "object",
				properties = {
					query = { type = "string" },
					limit = { type = "integer", description = "Results to return, 1-10. Default 5.", minimum = 1, maximum = 10 },
				},
				required = { "query" },
			},
			run = function(args)
				local query = util.trim(args.query)
				if query == "" then return "Give a query." end

				local res, err = http.send({
					url = "https://html.duckduckgo.com/html/",
					method = "POST",
					identity = "browser",
					headers = { ["Content-Type"] = "application/x-www-form-urlencoded" },
					body = "q=" .. util.urlEncode(query) .. "&b=&kl=us-en",
					attempts = 2,
					tag = "tool:web_search",
				})
				if not res then return H.fail(err) end
				if not res.ok then return H.fail("search returned status " .. tostring(res.status)) end

				local limit = H.limit(args.limit, 5, 10)
				local records = {}
				for href, title in res.body:gmatch('<a[^>]+class="result__a"[^>]*href="([^"]*)"[^>]*>(.-)</a>') do
					if #records >= limit then break end
					-- Results are wrapped in a redirect; the real URL is the uddg param.
					local link = href:match("[?&]uddg=([^&]+)")
					link = link and util.urlDecode(link) or href
					if not link:find("^https://duckduckgo%.com") then
						records[#records + 1] = { title = toText(title), url = link }
					end
				end

				local index = 1
				for snippet in res.body:gmatch('<a[^>]+class="result__snippet"[^>]*>(.-)</a>') do
					if records[index] then
						records[index].snippet = util.ellipsis(toText(snippet), 260)
						index = index + 1
					end
				end

				if #records == 0 then
					return "No results. The search endpoint may be blocking this host; try web_read on a known URL instead."
				end
				local blocks = {}
				for position, record in ipairs(records) do
					blocks[#blocks + 1] = string.format("%d. %s\n   %s\n   %s",
						position, record.title, record.url, record.snippet or "(no snippet)")
				end
				return table.concat(blocks, "\n\n")
			end,
		},
		{
			name = "web_read",
			risk = "read",
			needs = { "http" },
			description = "Fetch a web page and return its readable text, with markup and scripts stripped.",
			parameters = {
				type = "object",
				properties = {
					url = { type = "string" },
					limit = { type = "integer", description = "Maximum characters. Default 4000.", minimum = 200, maximum = 64000 },
				},
				required = { "url" },
			},
			run = function(args)
				local url = util.trim(args.url)
				if not url:find("^https?://") then url = "https://" .. url end

				local res, err = http.send({
					url = url,
					method = "GET",
					identity = "browser",
					attempts = 2,
					tag = "tool:web_read",
				})
				if not res then return H.fail(err) end
				if not res.ok then return H.fail("the page returned status " .. tostring(res.status)) end

				local body = tostring(res.body)
				-- A JSON endpoint reached through this tool should not be run through
				-- an HTML stripper. Still sanitised: a JSON body is only UTF-8 by
				-- convention, and this one came from a stranger.
				local looksJson = util.trim(body):sub(1, 1) == "{" or util.trim(body):sub(1, 1) == "["
				local text = looksJson and (util.sanitise(util.trim(body))) or toText(body)
				if text == "" then return "The page returned no readable text." end

				local title = body:match("<title[^>]*>(.-)</title>")
				local trimmed, truncated = util.truncate(text, tonumber(args.limit) or PAGE_CAP)
				return string.format("%s%s\n\n%s",
					title and (toText(title) .. "\n" .. url) or url,
					truncated and string.format("\n(%d characters, trimmed)", #text) or "",
					trimmed)
			end,
		},
	}
end
end)()

