__UAI_MODULES["ui/assets"] = (function()
-- Embedded custom icon assets packed from assets/icons/*.png.
--
-- Generated by tools/pack_icons.lua. Do not edit directly.
return function(env)
	local M = {}

	local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local T = {}
	for i = 1, #B do T[B:byte(i)] = i - 1 end

	function M.decode(data)
		data = data:gsub("[^%w%+%/%=]", "")
		local out = {}
		local len = #data
		for i = 1, len, 4 do
			local c1 = T[data:byte(i)] or 0
			local c2 = T[data:byte(i + 1)] or 0
			local b3 = data:byte(i + 2)
			local b4 = data:byte(i + 3)
			local c3 = (b3 and b3 ~= 61) and T[b3] or 0
			local c4 = (b4 and b4 ~= 61) and T[b4] or 0
			local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
			out[#out + 1] = string.char(math.floor(n / 65536) % 256)
			if b3 and b3 ~= 61 then
				out[#out + 1] = string.char(math.floor(n / 256) % 256)
			end
			if b4 and b4 ~= 61 then
				out[#out + 1] = string.char(n % 256)
			end
		end
		return table.concat(out)
	end

	M.icons = {
		["arrow-left"] = "",
