		["book-open"] = "",
		["check"] = "iVBORw0KGgoAAAANSUhEUgAAABgAAAAYCAYAAADgdz34AAAAmElEQVR4nO3SSw5FQBCFYbGSXgorwU5YCTthZ0ckJaFUP6ofRj04Mbr/F1e1AJqSayvwNzAC6ACYEsAOYKVnlxt4RXP/RTy+0bIAUnzK9QbeuAR8riAlzgHzuILBgQTHOfD80WxBVHEObBS2Ieq49A0WCxIVt12RhETFXWfKkai4C5AQddwH3EhPU8dDgGsHTR0PBZJWAe9OID7fyxEPESgAAAAASUVORK5CYII=",
