		["circle"] = "",
		["code"] = "",
		["copy"] = "",
		["dot"] = "iVBORw0KGgoAAAANSUhEUgAAABgAAAAYCAYAAADgdz34AAAAbUlEQVR4nO3RsQ2AMAxEUZQdUmeKrMMSMAYswTqZIjVDfBTpipRBMgIkF1fYxT3JDsD0ZIIDDjhwC4jAokRroBUWYFPKKDIKzEDq5qTdf35wALWbq3ZmwAlkYFWydqYnaoW7MlT+qR844MCLwAUtksfLrwTSVgAAAABJRU5ErkJggg==",
		["file-text"] = "",
		["folder"] = "",
		["git-branch"] = "",
		["git-fork"] = "",
		["globe"] = "",
		["log-out"] = "",
		["maximize-2"] = "",
		["menu"] = "iVBORw0KGgoAAAANSUhEUgAAABgAAAAYCAYAAADgdz34AAAAUklEQVR4nGP6//8/Ay0x07CzIPv////1FOJsXBaAJKYA2Q0U4inIltA1iKb+//8/hwo+yIGahdUHIIlGCvFUXD4YTaajyXQ0mY4m09FkOnKTKQCHtSva+DmbtgAAAABJRU5ErkJggg==",
