-- ==========================================================================
-- ui/boot
-- ==========================================================================
__UAI_MODULES["ui/boot"] = (function()
-- The boot indicator, and the one piece of the interface that exists before the
-- interface does.
--
-- Running the loader used to be silent. `loadstring(game:HttpGet(...))()` fetches a
-- megabyte, parses it, then loads sixty modules and mounts a window -- on a slow
-- client that is a few seconds of nothing at all, which is indistinguishable from a
-- script that failed. What was actually missing is the only thing this can honestly
-- report: modules finishing. The loader in the bootstrap counts them and this draws
-- the count.
--
-- The denominator is every module in the artifact, which a boot deliberately does not
-- reach: a panel's module loads the first time that panel is opened, so a finished
-- boot sits at about four fifths and the closing line says so rather than rounding
-- itself up to a full bar.
--
-- Its dependencies are the two cheapest surfaces in the project on purpose. This has
-- to be on screen before the work it is measuring, so it cannot pull the icon set (an
-- asset table and a filesystem probe) or the control set behind it -- which is also
-- why the progress here is a bar and a number rather than a spinner.
return function(env)
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")

	local M = {}

	-- Where a client GUI can live. gethui is the sturdiest under an executor (nothing
	-- in the game can see it); CoreGui is next; PlayerGui always works but is wiped on
	-- respawn, so it is the last resort.
	--
	-- It lives here rather than in ui/app because this is the first surface mounted and
	-- app is the second, and two copies of the fallback chain would be two things to
	-- keep in step.
	function M.container()
		local caps = env.require("runtime/caps")
		if caps.fn.gethui then
			local ok, container = pcall(caps.fn.gethui)
			if ok and container then return container end
		end
		local okCore, coreGui = pcall(function() return env.services.CoreGui end)
		if okCore and coreGui then return coreGui end
		if env.plr then
			local playerGui = env.plr:FindFirstChild("PlayerGui") or env.plr:WaitForChild("PlayerGui")
			if playerGui then return playerGui end
		end
		return nil
	end

	-- Above the interface's own DisplayOrder, so a slow mount cannot draw over the
	-- thing reporting it.
	local DISPLAY_ORDER = 2147481000

	function M.show()
		if M.screen then return M end
		local container = M.container()
		if not container then return M end

		local screen = Instance.new("ScreenGui")
		screen.Name = "UAI_Boot"
		screen.ResetOnSpawn = false
		screen.DisplayOrder = DISPLAY_ORDER
		screen.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		pcall(function() screen.ScreenInsets = Enum.ScreenInsets.DeviceSafeInsets end)
		screen.Parent = container
		M.screen = screen

		-- Bottom centre, which is where this client's own toasts land: it is a transient
		-- notice about the client rather than a dialog to be answered, and the middle of
		-- someone's screen belongs to the game they are in.
		local card = P.column(screen, {
			name = "BootPill",
			size = UDim2.fromOffset(theme.size.menuWide, 0),
			auto = "Y",
			anchor = Vector2.new(0.5, 1),
			position = UDim2.new(0.5, 0, 1, -theme.space.huge),
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.lg,
			gap = theme.space.xs,
			padding = { x = theme.space.md, y = theme.space.sm },
		})
		P.stroke(card, theme.color.border)
		M.card = card

		local top = P.row(card, {
			name = "BootHead",
			size = UDim2.new(1, 0, 0, theme.text.label.height),
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.text(top, {
			name = "BootTitle",
			text = "UAI",
			role = "label",
			color = theme.color.text,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		M.count = P.text(top, {
			name = "BootCount",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})
		M.count.Size = UDim2.fromOffset(0, theme.text.caption.height)

		-- The bar. A real fraction of a real total, so it moves in steps of one module
		-- and stops where the boot stopped.
		local track = P.frame(card, {
			name = "BootTrack",
			size = UDim2.new(1, 0, 0, theme.size.track),
			bg = theme.color.surfaceActive,
			radius = theme.radius.pill,
			layoutOrder = 2,
			clip = true,
		})
		M.fill = P.frame(track, {
			name = "BootFill",
			size = UDim2.new(0, 0, 1, 0),
			bg = theme.color.accent,
			radius = theme.radius.pill,
		})

		M.status = P.text(card, {
			name = "BootStatus",
			text = "starting",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			size = UDim2.new(1, 0, 0, 0),
			layoutOrder = 3,
		})

		return M
	end

	-- One module finished. Called from the bootstrap's loader, so it must never raise
	-- and never do enough work to be worth measuring itself: two property writes.
	function M.step(id, count, total)
		if not M.screen then return end
		if M.count then
			M.count.Text = string.format("%d / %d", count or 0, total or 0)
		end
		if M.fill and total and total > 0 then
			M.fill.Size = UDim2.new(math.min((count or 0) / total, 1), 0, 1, 0)
		end
		if M.status and id then M.status.Text = tostring(id) end
	end

	-- The interface is up. The closing line is the honest version of a full bar: it
	-- says how many of the artifact's modules this boot needed and what the rest are
	-- waiting for.
	function M.done(text)
		if not M.screen then return end
		if M.status then
			M.status.Text = text or "ready"
		end
		local screen = M.screen
		local card = M.card
		M.screen, M.card, M.fill, M.count, M.status = nil, nil, nil, nil, nil
		-- Held for a beat rather than cut: the last thing it says is the count, and a
		-- notice that vanishes on the same frame it finishes has not said it.
		local function drop()
			pcall(function() screen:Destroy() end)
		end
		local responsive = env.require("ui/responsive")
		if responsive.reduceMotion or not card then
			env.require("runtime/clock").delay(0.4, drop)
			return
		end
		env.require("runtime/clock").delay(0.5, function()
			local fade = env.tween:Create(card, theme.tween("exit"), {
				BackgroundTransparency = 1,
				Position = UDim2.new(0.5, 0, 1, -theme.space.lg),
			})
			fade.Completed:Connect(drop)
			fade:Play()
			-- The card's children are separate instances, so the fill and every label
			-- would otherwise hang in the air for the length of the fade.
			for _, child in ipairs(card:GetDescendants()) do
				if child:IsA("TextLabel") then
					env.tween:Create(child, theme.tween("exit"), { TextTransparency = 1 }):Play()
				elseif child:IsA("GuiObject") then
					env.tween:Create(child, theme.tween("exit"), { BackgroundTransparency = 1 }):Play()
				end
			end
			-- A cancelled or dropped tween must not leave the notice on screen for the
			-- rest of the session, which is the failure mode the window's own fade had.
			env.require("runtime/clock").delay(0.6, drop)
		end)
	end

	-- A boot that failed leaves nothing behind either, and says what happened while it
	-- is still the only thing on screen.
	function M.fail(why)
		if not M.screen then return end
		if M.status then
			M.status.Text = tostring(why or "failed to start")
			M.status.TextColor3 = theme.color.danger
		end
		if M.fill then M.fill.BackgroundColor3 = theme.color.danger end
		local screen = M.screen
		M.screen, M.card, M.fill, M.count, M.status = nil, nil, nil, nil, nil
		env.require("runtime/clock").delay(6, function()
			pcall(function() screen:Destroy() end)
		end)
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/composer
-- ==========================================================================
__UAI_MODULES["ui/chat/composer"] = (function()
-- The composer: the scope chips, the prompt field, send/stop, and the meta row.
--
-- Send behaviour differs by platform on purpose. With a keyboard, Enter sends --
-- that is what everyone expects and reaching for a button breaks the typing rhythm.
-- On touch there is no Enter worth the name, so the button is the primary action and
-- the field grows instead. The expand toggle switches to a multi-line field where
-- Enter inserts a newline and only the button sends.
--
-- Everything on the two rows around the field states something the client knows and
-- changes something when pressed. That is worth saying because it was not true: the
-- chips were a list of invented project and branch names, the permission chip
-- announced "Full Auto" while the agent was actually prompting for every write, and
-- the model name was a literal that no provider had ever reported.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local fsx = env.require("runtime/fsx")
	local place = env.require("runtime/place")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local sessions = env.require("agent/session")
	local permissions = env.require("agent/permissions")
	local providers = env.require("provider/registry")
	local traits = env.require("provider/traits")

	local M = {}

	-- How much of an attached file travels with the message. The agent can read the
	-- rest with its own tools; this is context, not a transfer.
	local ATTACH_CAP = 4000

	function M.new(parent, props)
		props = props or {}

		-- One bordered box holding the field and the send control, sitting on the
		-- canvas rather than in a bar of its own. There is no rule above it: the box's
		-- own outline is what separates it from the transcript, and a rule as well
		-- draws two lines where the eye needs one. That is also why the field goes in
		-- `bare` -- a bordered input inside a bordered bar was two nested rectangles
		-- for one input.
		local shell = P.column(parent, {
			name = "Composer",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			-- One step of air between the three rows rather than six pixels. The meta row
			-- sat close enough to the input box to read as part of it, so "Allow
			-- everything" and the token count looked like status inside the field.
			gap = theme.space.sm,
			-- Matches the transcript's own horizontal inset, so the composer's box and the
			-- reading column above it share a left edge instead of missing it by four.
			padding = { x = theme.space.xl, top = theme.space.sm, bottom = theme.space.md },
			zIndex = theme.z.raised,
		})

		local composer = { expanded = false, busy = false, attachments = {} }

		-- Scope chips ---------------------------------------------------------

		local scopeRow = P.row(shell, {
			name = "ScopeRow",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			wrap = true,
			layoutOrder = 1,
		})

		local function chip(name, iconName, labelText, order, onClick)
			local handle = P.rowButton(scopeRow, {
				name = "Chip_" .. name,
				auto = "X",
				height = theme.size.chip,
				size = UDim2.fromOffset(0, theme.size.chip),
				bg = theme.color.surface,
				stroke = true,
				strokeColor = theme.color.borderSubtle,
				radius = theme.radius.sm,
				gap = theme.space.xxs,
				padding = { x = theme.space.xs },
				layoutOrder = order,
				onClick = onClick,
			})
			handle.iconSlot = handle.icon(iconName, 1, theme.color.textTertiary, theme.size.icon - theme.space.hair)
			if labelText ~= nil then
				handle.text = P.text(handle.row, {
					name = "ChipLabel",
					text = labelText,
					role = "caption",
					color = theme.color.textSecondary,
					auto = "X",
					layoutOrder = 2,
				})
			end
			return handle
		end

		-- 1. What this client is running on. Not a choice -- it is the host -- so the
		-- menu is the capability report, which is the thing anyone clicking it wants.
		local runtimeLabel = caps.executor
		if runtimeLabel == "unknown" then
			runtimeLabel = caps.studio and "Studio" or "Client"
		end
		chip("runtime", "terminal", runtimeLabel, 1, function(handle)
			local options = {}
			local function fact(label, value, tone)
				options[#options + 1] = { label = label, value = tostring(value), detail = tostring(value), tone = tone }
			end
			fact("Transport", caps.http .. (caps.requestName and (" (" .. caps.requestName .. ")") or ""))
			fact("Claude Code identity", caps.uaSupported and "can be sent" or "cannot be sent here",
				caps.uaSupported and "good" or "warn")
			fact("Filesystem", caps.fs and "available" or "unavailable", caps.fs and "good" or "warn")
			fact("Code execution", caps.exec and "available" or "unavailable", caps.exec and "good" or "warn")
			fact("WebSocket", caps.ws and "available" or "unavailable")
			fact("Clipboard", caps.clipboard and "available" or "unavailable")
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if caps.clipboard then
						pcall(caps.fn.clipboard, tostring(value))
						overlay.toast("Copied", "good", 1.5)
					else
						overlay.toast(tostring(value), "info", 3)
					end
				end,
			})
		end)

		-- 2. The place, which is this client's project: it is what the work is in and
		-- what the conversation list groups by.
		local placeChip = chip("place", "folder", place.label(), 2, function(handle)
			local options = {}
			for _, group in ipairs(sessions.groups()) do
				options[#options + 1] = {
					label = group.label,
					value = "place:" .. tostring(group.placeId),
					detail = util.pluralise(#group.sessions, "conversation"),
					selected = group.current,
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = { label = "Place details", value = "details", icon = "document", tone = "info" }
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if value == "details" then
						local facts = place.facts()
						overlay.menu({
							target = handle.instance,
							width = theme.size.menuWide,
							options = (function()
								local out = {}
								for _, entry in ipairs(facts) do
									out[#out + 1] = { label = entry.key, value = entry.value, detail = entry.value }
								end
								return out
							end)(),
							onSelect = function(fact)
								if caps.clipboard then
									pcall(caps.fn.clipboard, tostring(fact))
									overlay.toast("Copied", "good", 1.5)
								else
									overlay.toast(tostring(fact), "info", 3)
								end
							end,
						})
					elseif util.startsWith(tostring(value), "place:") then
						local wanted = tostring(value):sub(7)
						for _, group in ipairs(sessions.groups()) do
							if tostring(group.placeId) == wanted and group.sessions[1] then
								env.require("ui/app").openSession(group.sessions[1].id)
							end
						end
					end
				end,
			})
		end)

		-- 3. The place version, which is the closest thing a running client has to a
		-- revision: it is what changes when the game is republished under you.
		if place.version > 0 then
			chip("version", "branch", "v" .. tostring(place.version), 3, function(handle)
				overlay.toast(place.describe(), "info", 3)
			end)
		end

		-- 4. Isolation. A conversation marked this way is never written to disk, which
		-- is the same reason a worktree exists: somewhere to try something without it
		-- becoming part of the history.
		local isolateChip
		local function paintIsolate()
			local session = sessions.current()
			local on = session.ephemeral == true
			isolateChip.instance.BackgroundColor3 = on and theme.color.accentSurface or theme.color.surface
			if isolateChip.text then
				isolateChip.text.Text = on and "isolated" or "worktree"
				isolateChip.text.TextColor3 = on and theme.color.accentHot or theme.color.textSecondary
			end
		end
		isolateChip = chip("isolate", "worktree", "worktree", 4, function()
			local session = sessions.current()
			local now = session.setEphemeral(not session.ephemeral)
			paintIsolate()
			overlay.toast(now
				and "This conversation will not be saved to disk."
				or "This conversation is saved again.", "info", 2.5)
		end)
		paintIsolate()

		-- 5. Attach. Real files from the client's own folder, and the memory it keeps.
		local attachRow
		local function renderAttachments()
			for _, child in ipairs(attachRow:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			attachRow.Visible = #composer.attachments > 0
			for index, entry in ipairs(composer.attachments) do
				local handle = P.rowButton(attachRow, {
					name = "Attachment_" .. tostring(index),
					auto = "X",
					height = theme.size.chip,
					size = UDim2.fromOffset(0, theme.size.chip),
					bg = theme.color.surfaceRaised,
					radius = theme.radius.sm,
					gap = theme.space.xxs,
					padding = { x = theme.space.xs },
					layoutOrder = index,
					onClick = function()
						table.remove(composer.attachments, index)
						renderAttachments()
					end,
				})
				handle.icon("document", 1, theme.color.accent, theme.size.icon - theme.space.hair)
				P.text(handle.row, {
					text = entry.label,
					role = "caption",
					color = theme.color.textSecondary,
					auto = "X",
					layoutOrder = 2,
				})
				handle.icon("close", 3, theme.color.textTertiary, theme.size.icon - theme.space.xxs)
			end
		end

		local function attachMenu(target)
			local options = {}
			local files = fsx.enabled and fsx.list("") or {}
			for _, entry in ipairs(files) do
				if not entry.isDir then
					options[#options + 1] = {
						label = entry.name,
						value = "file:" .. entry.path,
						detail = entry.path,
						icon = "document",
					}
				end
			end
			local state = env.require("agent/state")
			for _, entry in ipairs(state.memoryList()) do
				options[#options + 1] = {
					label = entry.key,
					value = "memory:" .. entry.key,
					detail = util.ellipsis(entry.value, 60),
					icon = "book",
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = { label = "A path in " .. fsx.root, value = "path", icon = "folder", tone = "info" }

			overlay.menu({
				target = target,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					local function attachFile(path)
						local body, err = fsx.read(path)
						if not body then
							overlay.toast(tostring(err), "warn", 3)
							return
						end
						composer.attachments[#composer.attachments + 1] = {
							label = path,
							path = path,
							text = util.truncate(body, ATTACH_CAP, "attach a narrower slice if you need the rest"),
						}
						renderAttachments()
					end
					if util.startsWith(tostring(value), "file:") then
						attachFile(tostring(value):sub(6))
					elseif util.startsWith(tostring(value), "memory:") then
						local key = tostring(value):sub(8)
						composer.attachments[#composer.attachments + 1] = {
							label = "memory/" .. key,
							text = tostring(state.recall(key) or ""),
						}
						renderAttachments()
					elseif value == "path" then
						overlay.prompt({
							title = "Attach a file",
							description = "A path inside " .. fsx.root .. ". Its contents travel with the message.",
							placeholder = "notes/plan.txt",
							confirmText = "Attach",
							onConfirm = function(path)
								if util.trim(path) ~= "" then attachFile(util.trim(path)) end
							end,
						})
					end
				end,
			})
		end

		chip("attach", "document", nil, 5, function(handle)
			attachMenu(handle.instance)
		end)

		attachRow = P.row(shell, {
			name = "Attachments",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			wrap = true,
			layoutOrder = 2,
		})
		attachRow.Visible = false

		-- The field ------------------------------------------------------------

		-- A wrapper with no layout of its own, so the mascot can perch on the input
		-- box's top edge without becoming a layout item -- a positioned child inside a
		-- list layout takes a slot of its own and pushes everything after it out.
		local inputHolder = P.frame(shell, {
			name = "InputHolder",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = 3,
		})

		local inputRow = P.row(inputHolder, {
			name = "InputRow",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surfaceRaised,
			radius = theme.radius.lg,
			gap = theme.space.xs,
			padding = { x = theme.space.sm, y = theme.space.xxs },
			alignY = "Center",
		})
		local boxStroke = P.stroke(inputRow, theme.color.borderSubtle)

		-- Decoration, and the only thing in this interface that is. It has no handler,
		-- because a mascot that announced "Ready to code!" in a toast was pretending to
		-- be a control. It does march, though, and what it does is tied to the turn: see
		-- ui/icons for why that is the one honest thing a mascot can do here.
		--
		-- A step larger than iconLarge, which is what the animation needs to read: at
		-- twenty pixels the hop is three of them and the arms move by five, and nobody
		-- notices either from a foot away.
		local mascotSize = theme.size.iconLarge + theme.space.sm
		local mascotSlot = P.frame(inputHolder, {
			name = "Mascot",
			size = UDim2.fromOffset(mascotSize + theme.space.xs, mascotSize),
			anchor = Vector2.new(0.5, 1),
			position = UDim2.new(1, -(theme.size.control + theme.space.xl), 0, theme.space.hair),
			zIndex = theme.z.raised + 1,
		})
		local _, mascot = icons.mascot(mascotSlot, mascotSize, theme.color.accent)
		composer.mascot = mascot

		local fieldHolder = P.frame(inputRow, {
			name = "FieldHolder",
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			layoutOrder = 1,
		})

		-- An attachment is context, so it travels ahead of the question in a block the
		-- model can tell from prose. It is dropped after the send: leaving it attached
		-- would silently re-send the same file with every following message.
		local function compose(text)
			if #composer.attachments == 0 then return text end
			local parts = {}
			for _, entry in ipairs(composer.attachments) do
				parts[#parts + 1] = string.format("<attached name=\"%s\">\n%s\n</attached>",
					tostring(entry.label), tostring(entry.text))
			end
			parts[#parts + 1] = text
			return table.concat(parts, "\n\n")
		end

		local function submit()
			local text = util.trim(composer.field.get())
			if text == "" then return end
			local payload = compose(text)
			composer.field.clear()
			composer.attachments = {}
			renderAttachments()
			if props.onSend then props.onSend(payload) end
		end

		-- Focus is the box lifting a step and taking the accent on its outline, not just
		-- the outline. On a dark ramp a hairline changing hue is easy to miss, and this is
		-- the one control in the app whose focus state has to be unmistakable -- the
		-- keyboard shortcut that opens quick chat is a printable character, so "is this
		-- focused" decides where the next keystroke goes.
		local function paintFocus(focused)
			env.tween:Create(boxStroke, theme.tween("hover"), {
				Color = focused and theme.color.accentBorder or theme.color.borderSubtle,
			}):Play()
			env.tween:Create(inputRow, theme.tween("hover"), {
				BackgroundColor3 = focused and theme.color.surfaceOverlay or theme.color.surfaceRaised,
			}):Play()
		end

		-- One line at rest, which is what a single-line field is.
		--
		-- It was briefly two, on the theory that the primary surface of the app deserves
		-- the room. It does not: `multiline` is false at rest, so the second line was
		-- empty space under one line of text with the caret at the top of it -- a tall
		-- grey box, which is exactly what it looked like. The expand toggle is what asks
		-- for room, and that is the mode where the extra lines can actually be typed
		-- into.
		local function buildField(carried)
			return P.field(fieldHolder, {
				name = "Prompt",
				bare = true,
				placeholder = props.placeholder or "Describe a task or ask a question",
				multiline = composer.expanded,
				height = composer.expanded and (theme.text.body.height * 5 + theme.space.md) or nil,
				text = carried,
				onFocus = function() paintFocus(true) end,
				onBlur = function() paintFocus(false) end,
				onSubmit = function()
					if not composer.expanded then submit() end
				end,
			})
		end

		composer.field = buildField(nil)

		local sendButton = P.iconButton(inputRow, {
			name = "Send",
			icon = "send",
			variant = "ghost",
			diameter = theme.size.control,
			layoutOrder = 2,
			onClick = function()
				if composer.busy then
					if props.onStop then props.onStop() end
				else
					submit()
				end
			end,
		})
		sendButton.instance.LayoutOrder = 2

		-- The meta row ---------------------------------------------------------

		-- Wraps rather than overflows. Six controls -- a permission label that can read
		-- "Auto (ask for dangerous)", a model id, a context dot and two text buttons --
		-- do not fit on one line in a 340px window, and a row that cannot wrap puts the
		-- last of them past the edge where the CanvasGroup clips them away.
		local metaRow = P.row(shell, {
			name = "Meta",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.xs,
			padding = { x = theme.space.xxs },
			layoutOrder = 4,
		})

		-- Permission mode, which is what the reference client's "Bypass permissions"
		-- control is. It reads the real mode and writes the real mode: the label used to
		-- say "Bypass permissions" on a client that was set to ask for every write,
		-- which is the one place in this interface where a lie was also a safety
		-- problem.
		local permissionChip = P.rowButton(metaRow, {
			name = "PermissionMode",
			auto = "X",
			height = theme.size.chip,
			size = UDim2.fromOffset(0, theme.size.chip),
			radius = theme.radius.sm,
			gap = theme.space.xxs,
			padding = { x = theme.space.xs },
			layoutOrder = 1,
			onClick = function(handle)
				local options = {}
				for _, mode in ipairs(permissions.MODES) do
					options[#options + 1] = {
						label = permissions.MODE_LABELS[mode] or mode,
						value = mode,
						detail = permissions.MODE_HINTS[mode],
						selected = permissions.mode() == mode,
						tone = mode == "full" and "warn" or nil,
					}
				end
				overlay.menu({
					target = handle.instance,
					width = theme.size.menuWide,
					options = options,
					onSelect = function(mode)
						permissions.setMode(mode)
						composer.syncContext()
					end,
				})
			end,
		})
		local permissionLabel = P.text(permissionChip.row, {
			name = "PermissionLabel",
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			auto = "X",
			layoutOrder = 1,
		})

		local plusButton = P.iconButton(metaRow, {
			name = "AddContext",
			icon = "plus",
			variant = "ghost",
			diameter = theme.size.chip,
			layoutOrder = 2,
			onClick = function(handle)
				attachMenu(handle.instance)
			end,
		})
		plusButton.instance.LayoutOrder = 2

		local statusLabel = P.text(metaRow, {
			name = "Status",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			-- An explicit height, not a scale one: the row wraps, so it sizes itself to
			-- its contents and a (0, 0, 1, 0) child inside it resolves to nothing.
			size = UDim2.new(0, 0, 0, math.max(theme.size.chip, responsive.minTarget())),
			flex = "Fill",
			layoutOrder = 3,
		})

		-- The model, the effort it is being asked for, and how full the context is. All
		-- three come from the provider record and the session; the menu behind them is
		-- the real provider and model picker.
		local modelChip = P.rowButton(metaRow, {
			name = "ModelChip",
			auto = "X",
			height = theme.size.chip,
			size = UDim2.fromOffset(0, theme.size.chip),
			radius = theme.radius.sm,
			gap = theme.space.xxs,
			padding = { x = theme.space.xs },
			layoutOrder = 4,
			onClick = function(handle)
				M.providerMenu(handle.instance, composer)
			end,
		})
		local modelLabel = P.text(modelChip.row, {
			name = "ModelLabel",
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			auto = "X",
			layoutOrder = 1,
		})
		local effortLabel = P.text(modelChip.row, {
			name = "EffortLabel",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			auto = "X",
			layoutOrder = 2,
		})
		local contextDot = P.statusDot(modelChip.row, {
			diameter = theme.size.dot,
			color = theme.color.textTertiary,
			layoutOrder = 3,
		})

		local expandButton = P.button(metaRow, {
			name = "Expand",
			text = "multiline",
			variant = "ghost",
			size = "sm",
			tight = true,
			layoutOrder = 5,
			onClick = function()
				composer.setExpanded(not composer.expanded)
			end,
		})
		expandButton.instance.LayoutOrder = 5

		local clearButton = P.button(metaRow, {
			name = "Clear",
			text = "clear",
			variant = "ghost",
			size = "sm",
			tight = true,
			layoutOrder = 6,
			onClick = function()
				if props.onClear then props.onClear() end
			end,
		})
		clearButton.instance.LayoutOrder = 6

		-- Everything on the meta row, from the real records ---------------------

		function composer.syncContext()
			permissionLabel.Text = permissions.MODE_LABELS[permissions.mode()] or permissions.mode()
			permissionLabel.TextColor3 = permissions.mode() == "full"
				and theme.color.warn or theme.color.textSecondary

			local record = providers.active()
			if not record then
				modelLabel.Text = "no provider"
				modelLabel.TextColor3 = theme.color.warn
				effortLabel.Text = ""
			else
				local model = util.trim(tostring(record.model or ""))
				if model == "" then
					modelLabel.Text = record.label .. "  no model"
					modelLabel.TextColor3 = theme.color.warn
				else
					local badge = traits.badge(model)
					modelLabel.Text = model .. (badge and ("  " .. badge) or "")
					modelLabel.TextColor3 = theme.color.textSecondary
				end
				-- The effort actually sent, which is the setting clamped to what this
				-- model offers -- "Max" on a model whose scale stops at high is high, and
				-- saying Max would be reporting the setting rather than the request.
				local wanted = tostring(config.get("agent.effort", "high"))
				local levels = traits.effortLevels(model)
				local sending = wanted
				if levels then sending = traits.nearestEffort(model, wanted) or wanted end
				if levels == nil and model ~= "" then
					effortLabel.Text = ""
				else
					effortLabel.Text = (sending:gsub("^%l", string.upper))
				end
			end

			-- Context pressure, from the conversation the composer is attached to.
			local session = sessions.current()
			local stats = session.ctx.stats()
			local budget = math.max(tonumber(config.get("agent.contextTokens", 24000)) or 24000, 1)
			local share = util.clamp(stats.tokens / budget, 0, 1)
			composer.contextShare = share
			local tone = theme.color.success
			if share > 0.85 then
				tone = theme.color.danger
			elseif share > 0.6 then
				tone = theme.color.warn
			end
			contextDot.BackgroundColor3 = tone
		end

		-- Rebuilding the field is the honest way to switch MultiLine: changing the
		-- property on a live TextBox leaves its alignment and height wrong.
		function composer.setExpanded(value)
			composer.expanded = value == true
			local carried = composer.field.get()
			pcall(function() composer.field.shell:Destroy() end)
			composer.field = buildField(carried)
			expandButton.setText(composer.expanded and "single line" or "multiline")
		end

		function composer.setBusy(value)
			composer.busy = value == true
			-- The mascot works while the agent does. It is peripheral motion next to the
			-- field, which is where the eyes are just after sending.
			if composer.mascot then pcall(composer.mascot.setBusy, composer.busy) end
			-- ClearAllChildren would take the UICorner that P.button attached along
			-- with the icon, and since this runs once at build time that is why the
			-- send button has been square from the moment it existed. Only the drawn
			-- content is replaced.
			for _, child in ipairs(sendButton.instance:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			-- The primary action becomes Stop while a turn is running, in place
			-- rather than as a second control, so there is only ever one thing to
			-- press.
			local content = P.row(sendButton.instance, {
				size = UDim2.fromScale(1, 1),
				alignX = "Center",
			})
			local holder = P.frame(content, {
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			})
			if composer.pulse then
				pcall(function() composer.pulse:Cancel() end)
				composer.pulse = nil
			end
			if composer.busy then
				-- Danger is outline-and-text rather than a fill, so the glyph is the
				-- danger colour: drawing it in the on-accent tone left a near-black
				-- square on a transparent button.
				icons.stop(holder, theme.size.icon, theme.color.danger)
				-- setVariant tweens the background over 0.12s, so assigning
				-- BackgroundColor3 here as well only started a race the tween won.
				sendButton.setVariant("danger")
				-- A breathing outline. It is the one piece of motion visible with the
				-- transcript scrolled away, which is where a long turn is usually spent.
				if not responsive.reduceMotion then
					composer.busyStroke = composer.busyStroke
						or P.stroke(sendButton.instance, theme.color.danger, theme.stroke.focus)
					composer.busyStroke.Color = theme.color.danger
					composer.busyStroke.Transparency = theme.opacity.dim
					composer.pulse = env.tween:Create(composer.busyStroke, theme.motion.pulse,
						{ Transparency = 0 })
					composer.pulse:Play()
				end
			else
				icons.send(holder, theme.size.icon, theme.color.textSecondary)
				sendButton.setVariant("ghost")
				if composer.busyStroke then composer.busyStroke.Transparency = 1 end
			end
		end

		function composer.setStatus(text)
			statusLabel.Text = tostring(text or "")
		end

		-- The running token line, which is a setting rather than progress: it is the one
		-- thing on this row that is about cost, and not everyone wants it in front of
		-- them. Kept separate from setStatus so turning it off cannot also hide "Working
		-- (step 3)".
		function composer.setUsage(text)
			if config.get("ui.showUsage", true) ~= true then
				statusLabel.Text = ""
				return
			end
			statusLabel.Text = tostring(text or "")
		end

		function composer.focus()
			composer.field.focus()
		end

		-- The keyboard covering the field is the classic mobile bug. The window moves
		-- itself; this only has to stop showing the meta row when there is no height
		-- left for it.
		local unsubscribeResponsive = responsive.changed:connect(function()
			if not metaRow.Parent then return end
			metaRow.Visible = not responsive.isCompactHeight()
		end)
		metaRow.Visible = not responsive.isCompactHeight()

		-- The chips are a view of state that other surfaces change: the permission mode
		-- from a menu, the model from the Providers panel, the place name when it
		-- resolves.
		local unsubscribeProviders = providers.changed:connect(function()
			if not metaRow.Parent then return end
			composer.syncContext()
		end)
		local unsubscribePermissions = permissions.changed:connect(function()
			if not metaRow.Parent then return end
			composer.syncContext()
		end)
		local unsubscribePlace = place.changed:connect(function()
			if not scopeRow.Parent then return end
			if placeChip.text then placeChip.text.Text = place.label() end
		end)
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not scopeRow.Parent then return end
			paintIsolate()
		end)
		shell.Destroying:Connect(function()
			pcall(unsubscribeResponsive)
			pcall(unsubscribeProviders)
			pcall(unsubscribePermissions)
			pcall(unsubscribePlace)
			pcall(unsubscribeSessions)
		end)

		composer.shell = shell
		composer.setBusy(false)
		composer.syncContext()
		return composer
	end

	-- Picks the endpoint, the model on it, and the effort it is asked for. All three
	-- live behind the same chip because they are one decision from the user's point of
	-- view -- and behind ui/panels/modelpicker rather than an anchored menu, because a
	-- menu is the right shape for six rows and this list is as long as the endpoint's
	-- catalogue. `target` is unused now and kept in the signature: it is what an
	-- anchored menu needed, and the chip still passes it.
	function M.providerMenu(target, composer)
		return env.require("ui/panels/modelpicker").open(function()
			if composer then composer.syncContext() end
		end)
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/message
-- ==========================================================================
__UAI_MODULES["ui/chat/message"] = (function()
-- Transcript message renderers.
--
-- Each kind of thing that can appear in a conversation gets its own builder, and
-- each returns a handle so the view can update it later -- a tool call is created
-- when the model asks for it and completed when the result arrives, which means the
-- row has to be mutable rather than a one-shot render.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local markdown = env.require("ui/markdown")
	local icons = env.require("ui/icons")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local usage = env.require("agent/usage")

	-- How many lines of a block are shown before it folds. Generous, because the point
	-- of showing code at all is that it can be read; the fold is for a thousand-line
	-- file, not for a function.
	--
	-- A tool call's listing gets a much tighter one. Sixty lines of Luau between two
	-- paragraphs is the single largest thing in a transcript, and the model writes one
	-- of those per call: a turn that ran four scripts pushed the answer it was working
	-- towards several screens down. Twelve lines is enough to recognise what the call
	-- is doing, and "Show all N lines" is on the block.
	local CODE_LINES = 60
	local TOOL_CODE_LINES = 12
	local ARG_PREVIEW = 90

	-- Average glyph advance for the mono families, as a fraction of the font size.
	-- Used only to size the line-number gutter, which has to be wide enough for the
	-- largest number in the block and is the one width here that cannot come from a
	-- token: it depends on how many lines the block has.
	local MONO_RATIO = 0.62

	local M = {}

	-- Every row spans the reading column.
	--
	-- It used to leave a gutter -- 0.76 of the width for the user, 0.94 for the agent,
	-- the user's turn anchored to the right edge -- which is the chat-app convention of
	-- two speakers facing each other. This is not that: a turn here is a document with
	-- the questions marked in it, so both sides take the full measure and the
	-- difference between them is a fill, not a side. The column itself is what bounds
	-- the line length, and the panel caps that.
	local function wrapper(parent, props)
		return P.frame(parent, {
			name = props.name or "Message",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = props.layoutOrder or 0,
		})
	end

	-- A left rule beside a column of wrapped text.
	--
	-- The obvious construction is a row holding a 2px frame sized (0, 2, 1, 0) and a
	-- filling label beside it. That is circular and it does not work: the row is
	-- AutomaticSize.Y, so its height comes from its children, and one of those children
	-- asks for one hundred percent of that height. Roblox excludes scale-sized children
	-- from the measurement, but the UIListLayout's flex pass has already run against an
	-- unsettled height -- which inflates the row and can leave the filling label with no
	-- width at all, so a long message renders as a tall empty box with a coral line down
	-- the side of it.
	--
	-- The holder here has no UIListLayout. The rule is positioned rather than laid out,
	-- nothing measures it, and the text sits in an ordinary column with an explicit
	-- width. Callers get the column.
	local function ruled(parent, props)
		local holder = P.frame(parent, {
			name = props.name or "Ruled",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = props.layoutOrder,
			bg = props.bg,
			radius = props.radius,
			clip = props.clip,
		})
		if props.strokeColor then P.stroke(holder, props.strokeColor) end
		local width = props.width or theme.stroke.hair
		local body = P.column(holder, {
			name = "Body",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = props.gap or theme.space.xs,
			padding = {
				left = width + (props.inset or theme.space.md),
				right = props.padRight or 0,
				top = props.padY or 0,
				bottom = props.padY or 0,
			},
		})
		P.frame(holder, {
			name = "Rule",
			size = UDim2.new(0, width, 1, 0),
			position = UDim2.new(0, props.ruleAt or 0, 0, 0),
			bg = props.color or theme.color.borderSubtle,
			radius = props.ruleRadius,
			zIndex = 2,
		})
		return body, holder
	end

	-- Code: monospace below the surface of the page, with the language, a line-number
	-- gutter, a copy control and horizontal scrolling.
	--
	-- Three things changed here and each was a real loss of information. Lines wrapped,
	-- so a Luau line past the reading column folded and the indentation of everything
	-- after it read as wrong; there were no line numbers, so an error naming line 40 had
	-- nothing to point at; and anything past the fold was replaced by a dead sentence
	-- saying how much had been hidden, with no way to see it. Code is now what the model
	-- actually wrote, scrolled rather than reflowed, and the fold opens.
	function M.codeBlock(parent, props)
		local caps = env.require("runtime/caps")
		local lines = util.lines(props.text)
		if #lines == 0 then lines = { "" } end
		local numbered = props.numbers ~= false
		local role = theme.textRole("mono")
		-- Looser than the rest of the mono text, and the one number in here that both
		-- labels and the row height have to agree on: the gutter is a separate label
		-- from the code, so a line height that is not shared puts number 11 beside line
		-- 9. Everything below reads `codeLine`; nothing recomputes it from the role.
		local codeLine = theme.line.code
		local lineHeight = math.ceil(role.size * codeLine)
		-- Air inside the block, on all four sides, and one number per axis.
		--
		-- It used to be neither. The vertical inset was a token here and the horizontal
		-- one was an accident of two other measurements: the left came out of the gutter's
		-- own width, which baked twelve pixels of margin into a column sized for digits,
		-- and the right came from padding on the scroll viewport. So the two edges never
		-- agreed with each other, the language bar above them agreed with neither, and a
		-- block with no gutter -- a result, a raw JSON envelope -- had its first character
		-- sitting on the border. Both axes are one padding on the body row now, the bar
		-- shares the horizontal one, and the gutter is only as wide as its digits plus the
		-- gap to the code.
		local padY = theme.space.md
		local padX = theme.space.lg

		local card = P.column(parent, {
			name = "Code",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			gap = 0,
			layoutOrder = props.layoutOrder,
			clip = true,
		})
		P.stroke(card, theme.color.codeBorder)

		local bar = P.row(card, {
			name = "Bar",
			-- As tall as the copy button inside it. P.iconButton floors its diameter at
			-- the platform hit target, which is 44 on touch, so a bar fixed at the 26px
			-- token had eighteen pixels of button hanging over the code below it -- on
			-- exactly the platform the floor exists for.
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget())),
			bg = theme.color.codeBar,
			gap = theme.space.xs,
			-- The same left inset the gutter gets, so the language names the column of code
			-- underneath it rather than floating four pixels to the left of it. The right is
			-- tighter because what sits there is a round ghost button with its own padding,
			-- and padX again would push it off the block's corner.
			padding = { left = padX, right = theme.space.xs },
			layoutOrder = 1,
		})
		P.text(bar, {
			name = "Language",
			text = (props.lang and props.lang:lower() or "code") .. (props.unterminated and " (incomplete)" or ""),
			role = "caption",
			color = theme.color.codeGutter,
			-- Fills rather than reserving controlSmall: the copy button is sized to
			-- max(controlSmall, minTarget()), which is 44 on touch, so the reserve was
			-- twelve pixels short on exactly the platform the minimum exists for.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 1,
		})
		-- What is in the block, on the right of its own bar. A line count is the one
		-- fact about a block of code that is worth reading before the code itself.
		P.text(bar, {
			name = "Meta",
			text = props.meta or util.pluralise(#lines, "line"),
			role = "caption",
			color = theme.color.codeGutter,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})

		if caps.clipboard then
			local copy = P.iconButton(bar, {
				name = "Copy",
				icon = "copy",
				diameter = theme.size.controlSmall,
				variant = "ghost",
				iconColor = theme.color.codeGutter,
				layoutOrder = 3,
				onClick = function()
					pcall(caps.fn.clipboard, props.text)
					env.require("ui/overlay").toast("Copied to clipboard", "good", 2)
				end,
			})
			copy.instance.LayoutOrder = 3
		end

		-- Body. The gutter is outside the scroll so it stays put while the code moves,
		-- which is the whole reason a sticky gutter is worth the extra frame.
		local bodyRow = P.row(card, {
			name = "Body",
			size = UDim2.new(1, 0, 0, 0),
			gap = 0,
			alignY = "Top",
			padding = { left = padX, right = padX, top = padY, bottom = padY },
			layoutOrder = 2,
		})

		local gutter, gutterLabel
		local gutterWidth = 0
		if numbered then
			-- Wide enough for the largest number in this block, plus the gap to the code
			-- beside it. It is the one width in here that cannot come from a token, because
			-- it depends on how many lines there are; the ratio is what keeps it in step
			-- with the text scale, and the gap is a token because it is a gap.
			gutterWidth = math.ceil(#tostring(#lines) * role.size * MONO_RATIO) + theme.space.md
			gutter = P.frame(bodyRow, {
				name = "Gutter",
				size = UDim2.fromOffset(gutterWidth, 0),
				layoutOrder = 1,
			})
			gutterLabel = P.text(gutter, {
				name = "Numbers",
				text = "",
				role = "mono",
				line = codeLine,
				color = theme.color.codeGutter,
				align = "Right",
				alignY = "Top",
				size = UDim2.new(1, -theme.space.md, 1, 0),
			})
		end

		local viewport = P.scroll(bodyRow, {
			name = "Viewport",
			horizontal = true,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			gap = 0,
			bar = theme.size.scrollbar,
		})
		-- Not wrapped, and sized from the text: that is what makes the gutter line up
		-- with the code beside it. A wrapped body puts two visual lines against one
		-- number, and every number below it is then wrong.
		local body = P.text(viewport.instance, {
			name = "Source",
			text = "",
			role = "mono",
			line = codeLine,
			color = theme.color.codeText,
			alignY = "Top",
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
		})

		local expanded = false
		local foldRow
		-- Where this block folds. A reply's code gets the generous default; a tool
		-- call's listing passes its own, because there are several of them per turn.
		local foldAt = math.max(tonumber(props.maxLines) or CODE_LINES, 1)

		local function paint()
			local shown = lines
			if not expanded and #lines > foldAt then
				shown = util.slice(lines, 1, foldAt)
			end
			body.Text = table.concat(shown, "\n")
			if gutterLabel then
				local numbers = {}
				for index = 1, #shown do numbers[index] = tostring(index) end
				gutterLabel.Text = table.concat(numbers, "\n")
			end
			local height = #shown * lineHeight
			bodyRow.Size = UDim2.new(1, 0, 0, height + padY * 2 + theme.size.scrollbar)
			if gutter then gutter.Size = UDim2.fromOffset(gutterWidth, height) end
			if foldRow then
				foldRow.setText(expanded
					and "Show less"
					or string.format("Show all %s", util.pluralise(#lines, "line")))
			end
		end

		if #lines > foldAt then
			foldRow = P.button(card, {
				name = "Fold",
				-- Given its text up front, because P.button only builds a label when it
				-- has one to put in it -- an empty string leaves setText with nothing to
				-- write to.
				text = string.format("Show all %s", util.pluralise(#lines, "line")),
				variant = "ghost",
				size = "sm",
				fill = true,
				align = "Left",
				-- Starts where the code above it starts. On the button's own default inset
				-- the control read as belonging to the card's edge rather than to the
				-- listing it opens.
				padX = padX,
				radius = theme.radius.none,
				layoutOrder = 3,
				onClick = function()
					expanded = not expanded
					paint()
				end,
			})
			foldRow.instance.LayoutOrder = 3
		end

		paint()
		return card
	end

	-- Renders markdown blocks into an existing column. Returned so a streaming or
	-- edited message can clear and re-render.
	function M.renderBlocks(column, text)
		for _, child in ipairs(column:GetChildren()) do
			if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
		end

		local blocks = markdown.blocks(text)
		if #blocks == 0 then
			P.text(column, { text = "", role = "body", wrap = true, auto = "Y" })
			return
		end

		for index, block in ipairs(blocks) do
			if block.kind == "code" then
				-- A fenced block is an object in the prose rather than another paragraph of
				-- it, so it gets more air than the uniform paragraph gap -- above and below
				-- both. At the bare gap the sentence introducing the code sat exactly as
				-- close to it as the next paragraph did, which is what makes a reply read as
				-- one column with a slab dropped into it.
				local slot = P.column(column, {
					name = "CodeSlot",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = 0,
					padding = { y = theme.space.xs },
					layoutOrder = index,
				})
				M.codeBlock(slot, {
					text = block.text,
					lang = block.lang,
					unterminated = block.unterminated,
					layoutOrder = 1,
				})
			elseif block.kind == "heading" then
				-- A heading belongs to what is under it, so it needs more air above than
				-- the uniform paragraph gap gives it. Without this a section title sits
				-- exactly as far from the paragraph it introduces as from the one it ends,
				-- and a long reply reads as an undifferentiated run of text.
				local head = P.column(column, {
					name = "Heading",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = 0,
					padding = index > 1 and { top = theme.space.sm } or nil,
					layoutOrder = index,
				})
				local label = P.text(head, {
					text = markdown.inline(block.text),
					role = block.level == 1 and "title" or "heading",
					rich = true,
					wrap = true,
					auto = "Y",
				})
				label.Size = UDim2.new(1, 0, 0, 0)
			elseif block.kind == "rule" then
				P.divider(column, { layoutOrder = index })
			elseif block.kind == "quote" then
				-- An aside gets a rule down its left edge and nothing else. A tinted card
				-- would make a quoted line louder than the prose quoting it.
				local body = ruled(column, {
					name = "Quote",
					layoutOrder = index,
					color = theme.color.border,
					width = theme.stroke.focus,
				})
				local quoted = P.text(body, {
					text = markdown.inline(block.text),
					role = "body",
					color = theme.color.textSecondary,
					rich = true,
					wrap = true,
					auto = "Y",
				})
				quoted.Size = UDim2.new(1, 0, 0, 0)
			elseif block.kind == "bullets" then
				local list = P.column(column, {
					name = "List",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xxs,
					layoutOrder = index,
				})
				-- One marker column for the whole list, wide enough for its longest
				-- marker, so "9." and "10." put their text at the same x.
				local markerWidth = theme.space.md
				for _, item in ipairs(block.items) do
					if item.marker then
						markerWidth = math.max(markerWidth,
							math.ceil(#item.marker * theme.text.body.size * MONO_RATIO))
					end
				end
				-- The marker is text, in the same role and on the same line height as the
				-- item beside it, and both are top-aligned inside boxes of that same
				-- height. That is what makes them line up: two labels with one role, one
				-- line height and one top edge put their first line on one baseline by
				-- construction. It used to be a 4px frame centred in a 23px slot next to a
				-- label centred in its own measured bounds -- two heights computed
				-- separately, agreeing only by luck, and they did not: every bullet in a
				-- reply sat low, near the descender of the line it belonged to.
				local bulletRole = theme.textRole("body")
				for position, item in ipairs(block.items) do
					local row = P.row(list, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						-- Closer to its own text than to the item above it. At sm the gap
						-- was wider than the mark, which reads as a stray dot rather than
						-- as the start of a line.
						gap = theme.space.xs,
						alignY = "Top",
						layoutOrder = position,
					})
					if (item.depth or 0) > 0 then
						P.frame(row, {
							name = "Indent",
							size = UDim2.fromOffset(item.depth * theme.space.lg, bulletRole.height),
							layoutOrder = 1,
						})
					end
					P.text(row, {
						name = "Marker",
						-- The middle dot rather than a bullet: it is Latin-1, so every family
						-- the engine offers has it, and at body size a round bullet next to
						-- 14px text is the loudest thing in the paragraph.
						text = item.marker or "\194\183",
						role = "body",
						line = bulletRole.line,
						color = theme.color.textTertiary,
						align = "Right",
						alignY = "Top",
						size = UDim2.new(0, markerWidth, 0, bulletRole.height),
						layoutOrder = 2,
					})
					P.text(row, {
						text = markdown.inline(item.text),
						role = "body",
						line = bulletRole.line,
						rich = true,
						wrap = true,
						alignY = "Top",
						auto = "Y",
						size = UDim2.new(0, 0, 0, 0),
						flex = "Fill",
						layoutOrder = 3,
					})
				end
			else
				local label = P.text(column, {
					text = markdown.inline(block.text),
					role = "body",
					rich = true,
					wrap = true,
					auto = "Y",
					layoutOrder = index,
				})
				label.Size = UDim2.new(1, 0, 0, 0)
			end
		end
	end

	-- Who said it, above what they said.
	--
	-- One quiet line. It is the piece the transcript was missing: a turn was a tinted box
	-- followed by unmarked prose followed by another tinted box, so scrolling back
	-- through a long conversation meant inferring the speaker from the fill, and the
	-- reply's attribution existed nowhere at all -- a client that can switch model
	-- mid-conversation was rendering four different models' answers identically.
	--
	-- On the reply the model id is the whole byline. There is no "Claude" beside it: the
	-- surface is a client for one agent, so naming it on every turn is a constant, and a
	-- constant next to the one thing that actually varies is what makes the varying thing
	-- hard to find. The mark plus the id says the same thing in one field.
	--
	-- Not a bubble and not an avatar. The transcript is a document with the questions
	-- marked in it, so the mark is a byline.
	local function byline(parent, props)
		local row = P.row(parent, {
			name = "Byline",
			size = UDim2.new(1, 0, 0, theme.text.label.height),
			gap = theme.space.xs,
			layoutOrder = props.layoutOrder or 1,
		})
		if props.icon then
			local slot = P.frame(row, {
				name = "BylineIcon",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 1,
			})
			icons.draw(props.icon, slot, theme.size.icon, props.iconColor or theme.color.textTertiary)
		end
		-- Fills rather than sizing to its text, so the byline is one full-width row and a
		-- long model id truncates instead of pushing the line past the reading column.
		P.text(row, {
			name = "Speaker",
			text = tostring(props.name or ""),
			role = props.mono and "monoSmall" or "label",
			color = props.color or theme.color.textSecondary,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			truncate = true,
			layoutOrder = 2,
		})
		return row
	end

	-- Who the person at this client is, for the byline. The display name, because that
	-- is what they see everywhere else in the game.
	local function localName()
		local okName, display = pcall(function() return env.plr and env.plr.DisplayName end)
		if okName and type(display) == "string" and util.trim(display) ~= "" then
			return display
		end
		if env.plr and type(env.plr.Name) == "string" and env.plr.Name ~= "" then
			return env.plr.Name
		end
		return "You"
	end

	-- The user's own turn. A fill, a hairline, and an accent rule down the left edge.
	--
	-- The rule is what makes it unmistakably a sent message. Without it the turn was a
	-- rounded surfaceRaised box with a border and a line of text in it, which is the
	-- exact description of the composer's input field twenty pixels below -- so a
	-- transcript read as a column of empty prompts rather than as a conversation.
	function M.user(parent, text, order)
		local holder = P.column(parent, {
			name = "User",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = order or 0,
		})
		byline(holder, { name = localName(), layoutOrder = 1 })
		local body = ruled(holder, {
			name = "Bubble",
			bg = theme.color.bubbleUser,
			strokeColor = theme.color.bubbleUserBorder,
			radius = theme.radius.md,
			color = theme.color.accent,
			width = theme.stroke.focus,
			ruleAt = theme.space.hair,
			ruleRadius = theme.radius.pill,
			inset = theme.space.md,
			padRight = theme.space.md,
			padY = theme.space.sm,
			clip = true,
			layoutOrder = 2,
		})
		local label = P.text(body, {
			text = tostring(text),
			role = "body",
			wrap = true,
			auto = "Y",
		})
		label.Size = UDim2.new(1, 0, 0, 0)
		return { root = holder, label = label }
	end

	function M.agent(parent, text, order)
		local holder = P.column(parent, {
			name = "Agent",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = order or 0,
		})
		-- The model that is answering, from the record the request will actually be built
		-- from, and it is the whole byline rather than a detail beside a name. Read here
		-- rather than passed in because the transcript renders from an event log that does
		-- not carry it. A record with no model named falls back to the provider's label,
		-- which is the most this client honestly knows in that state.
		local record = env.require("provider/registry").active()
		local model = record and util.trim(tostring(record.model or "")) or ""
		if model == "" then model = record and record.label or "no model" end
		byline(holder, {
			name = model,
			mono = true,
			icon = "spark",
			iconColor = theme.color.accent,
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		local column = P.column(holder, {
			name = "Body",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			-- Paragraphs need more than eight pixels between them or a long reply
			-- arrives as one grey slab with no shape to it.
			gap = theme.space.md,
			layoutOrder = 2,
		})
		local handle = { root = holder, column = column }
		function handle.setText(value)
			M.renderBlocks(column, value)
		end
		handle.setText(text or "")
		return handle
	end

	-- Reasoning is a quieter register of the same page, not an object on it: a header
	-- row and muted body text, no card and no outline. It used to be a bordered panel,
	-- which gave a paragraph of thinking the same visual weight as a settings group.
	--
	-- The body now sits behind a rule and an indent. Flush left in the same measure as
	-- the reply, at 13px against the reply's 14 and one step down in colour, thinking
	-- and answer were two paragraphs that looked alike -- so a turn read as the model
	-- saying the same thing twice, which is exactly what it looks like when a model
	-- restates its conclusion in prose.
	function M.reasoning(parent, text, order)
		local holder = wrapper(parent, { name = "Reasoning", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
		})

		local header = Instance.new("TextButton", card)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		-- A disclosure control, so it answers to the platform's hit-target floor like
		-- every other one. At max(label.height, icon) it was sixteen pixels tall, which
		-- is under the pointer minimum and well under the 44 a touch device needs.
		header.Size = UDim2.new(1, 0, 0, math.max(theme.text.label.height + theme.space.xs,
			responsive.minTarget() - theme.space.sm))
		header.LayoutOrder = 1
		header.Selectable = true

		local row = P.row(header, { size = UDim2.fromScale(1, 1), gap = theme.space.xs })
		local caret = P.frame(row, {
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")
		local title = P.text(row, {
			text = "Thinking",
			role = "label",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		-- How much of it there is, in the unit it is billed in. A card that says only
		-- "reasoning" gives no grounds for opening it or for leaving it shut, and this
		-- is the one part of a turn whose size is otherwise invisible: reasoning is
		-- charged as output and never appears in the reply.
		P.text(row, {
			text = "~" .. util.formatNumber(usage.estimateText(text)) .. " tokens",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			auto = "X",
			layoutOrder = 3,
		})

		local asideBody, bodyRow = ruled(card, {
			name = "Aside",
			layoutOrder = 2,
			color = theme.color.borderSubtle,
			width = theme.stroke.hair,
			-- Positioned under the caret's centre line, so the rule continues the
			-- disclosure triangle above it rather than starting at the row's edge.
			ruleAt = math.floor(theme.size.icon / 2),
			inset = theme.space.md,
		})
		local body = P.text(asideBody, {
			text = markdown.plain(text),
			role = "small",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		body.Size = UDim2.new(1, 0, 0, 0)

		-- Open on arrival. The thinking is what explains the answer, and a card that
		-- hides it by default reads as though there were nothing inside; the header
		-- still folds a long one away once it has been read.
		local open = true
		caret.Rotation = 90
		local function toggle()
			open = not open
			bodyRow.Visible = open
			caret.Rotation = open and 90 or 0
		end
		header.Activated:Connect(toggle)
		-- The wrapper, not the card: hiding the card alone left its frame in the list
		-- layout, so a hidden reasoning row still pushed the reply down by its padding.
		if config.get("ui.showReasoning", true) == false then holder.Visible = false end

		return { root = holder, body = body }
	end

	-- Which argument on a call is a listing rather than a value, and what language it
	-- is in.
	--
	-- Ordered, because a call can carry more than one: file_write takes a `path` and a
	-- `content`, run_luau takes only `code`. Anything matched here is drawn as code and
	-- kept out of the key/value list, so the same string is never shown twice.
	local CODE_KEYS = {
		{ key = "code", lang = "lua" },
		{ key = "source", lang = "lua" },
		{ key = "script", lang = "lua" },
		{ key = "expression", lang = "lua" },
		{ key = "patch", lang = "diff" },
		{ key = "diff", lang = "diff" },
		-- Language from the path it is being written to, since a file_write is whatever
		-- the extension says it is.
		{ key = "content" },
		{ key = "body" },
		{ key = "text" },
	}

	local EXTENSION_LANGS = {
		lua = "lua", luau = "lua", json = "json", md = "markdown", markdown = "markdown",
		js = "javascript", ts = "typescript", py = "python", html = "html", css = "css",
		yml = "yaml", yaml = "yaml", toml = "toml", sh = "bash", xml = "xml", csv = "csv",
		rbxmx = "xml", rbxlx = "xml",
	}

	-- The fields worth putting on the header line, most identifying first. Raw JSON
	-- used to go here, which at ninety characters shows the shape of the payload and
	-- none of its meaning: `{"path":"notes/plan.txt","content":"# Pl`.
	local SUMMARY_KEYS = {
		"path", "file", "query", "url", "class", "property", "name", "id",
		"command", "task", "key", "value",
	}

	local function langForPath(path)
		local extension = tostring(path or ""):match("%.([%w]+)$")
		if not extension then return nil end
		return EXTENSION_LANGS[extension:lower()]
	end

	-- Splits decoded arguments into the listings and the scalar facts.
	local function splitArguments(args)
		local code, facts = {}, {}
		if type(args) ~= "table" then return code, facts end
		local taken = {}
		local pathHint = args.path or args.file or args.name
		for _, spec in ipairs(CODE_KEYS) do
			local value = args[spec.key]
			if type(value) == "string" and value ~= "" and not taken[spec.key] then
				-- Only a listing if there is something to look at. A one-line `text` is a
				-- value, and a code card around three words is more chrome than content.
				local multiline = value:find("\n") ~= nil
				if spec.lang or multiline then
					code[#code + 1] = {
						key = spec.key,
						text = value,
						lang = spec.lang or langForPath(pathHint),
					}
					taken[spec.key] = true
				end
			end
		end
		for _, key in ipairs(util.keys(args, true)) do
			if not taken[key] then
				local value = args[key]
				local kind = type(value)
				if kind == "string" or kind == "number" or kind == "boolean" then
					facts[#facts + 1] = { key = tostring(key), value = tostring(value) }
				elseif kind == "table" then
					-- A nested structure is still shown verbatim: it is what an
					-- instance_create property map and a remote_fire argument list are, and
					-- both were previously invisible.
					local ok, encoded = pcall(util.encode, value)
					facts[#facts + 1] = { key = tostring(key), value = ok and encoded or "(not encodable)" }
				end
			end
		end
		return code, facts
	end

	local function summarise(args, raw)
		if type(args) ~= "table" then
			return util.ellipsis(tostring(raw or ""):gsub("[\n\r]+", " "), ARG_PREVIEW)
		end
		local parts = {}
		for _, key in ipairs(SUMMARY_KEYS) do
			local value = args[key]
			if type(value) == "string" or type(value) == "number" then
				parts[#parts + 1] = tostring(value)
			end
		end
		if #parts == 0 then
			for _, key in ipairs(util.keys(args, true)) do
				local value = args[key]
				local kind = type(value)
				if kind == "string" or kind == "number" or kind == "boolean" then
					parts[#parts + 1] = key .. " " .. tostring(value)
				end
				if #parts >= 3 then break end
			end
		end
		return util.ellipsis(table.concat(parts, "  \194\183  "), ARG_PREVIEW)
	end

	-- A run of tool calls, as one block.
	--
	-- Every call used to be a top-level row in the transcript, and the transcript puts
	-- xxl between top-level rows because that gap is what separates a question from the
	-- reply to it. Eight calls therefore arrived as eight paragraph-spaced lines with
	-- eight listings hanging off them, which is what makes a turn look like machinery
	-- with an answer buried in it: the tools were louder than anything the agent said.
	--
	-- So consecutive calls go in here instead. Inside, rows are one step apart; the
	-- block keeps the transcript's own gap to whatever is above and below it. The header
	-- counts the run and folds it -- automatically once it has finished and there are
	-- more of them than anyone reads line by line, since a finished run is a receipt.
	local FOLD_RUN_AT = 4

	function M.toolRun(parent, order)
		local holder = wrapper(parent, { name = "ToolRun", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
		})

		local header = Instance.new("TextButton", card)
		header.Name = "RunHeader"
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.rowTight,
			responsive.minTarget() - theme.space.sm))
		header.LayoutOrder = 1
		header.Selectable = true
		header.Visible = false

		local headerRow = P.row(header, { size = UDim2.fromScale(1, 1), gap = theme.space.xs })
		local caret = P.frame(headerRow, {
			name = "Caret",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")
		local summary = P.text(headerRow, {
			name = "RunSummary",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		local timing = P.text(headerRow, {
			name = "RunTiming",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 3,
		})
		timing.Size = UDim2.fromOffset(theme.size.metaColumn, theme.text.caption.height)

		local rows = P.column(card, {
			name = "Calls",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			-- One step, not the transcript's paragraph gap: these are lines of one
			-- list, not separate events.
			gap = theme.space.xxs,
			layoutOrder = 2,
		})

		local handle = { root = holder, rows = rows, calls = 0, settled = 0 }
		local started = clock.ms()
		local open = true
		local folded = false
		local slot = 0

		-- The next layout order inside the block. Everything that goes in here -- a
		-- call, the thinking between two calls, a retry notice -- takes one, so the
		-- block reads in the order it happened.
		function handle.slot()
			slot = slot + 1
			return slot
		end

		local function paint()
			local waited = handle.ms or clock.since(started)
			timing.Text = waited >= 1000 and util.formatDuration(waited) or ""
			summary.Text = string.format("%s%s",
				util.pluralise(handle.calls, "tool"),
				handle.settled < handle.calls
					and string.format("  \194\183  %d done", handle.settled) or "")
			-- The header earns its line once there is a run to fold. One call is a row,
			-- and a fold control above a single line is furniture.
			header.Visible = handle.calls > 1
		end

		local function setOpen(value)
			open = value == true
			rows.Visible = open
			caret.Rotation = open and 90 or 0
		end
		setOpen(true)
		header.Activated:Connect(function()
			-- Once a person has an opinion about this run, the automatic fold stops
			-- having one.
			folded = true
			setOpen(not open)
		end)

		-- Ticks only while something in the run is outstanding, and stops for good when
		-- the last result lands.
		local stop = clock.interval(0.5, function()
			if handle.settled < handle.calls then paint() end
		end)
		holder.Destroying:Connect(function() pcall(stop) end)

		-- Called by the view for each call it puts in here.
		function handle.opened()
			handle.calls = handle.calls + 1
			paint()
		end

		function handle.closed()
			handle.settled = handle.settled + 1
			paint()
			if handle.settled < handle.calls then return end
			handle.ms = clock.since(started)
			pcall(stop)
			paint()
			-- A finished run of more than a few calls folds itself away. The header
			-- keeps the count and the duration, which is what anyone rereading a turn
			-- wants from it; the rows are one click away.
			if not folded and handle.calls > FOLD_RUN_AT then
				folded = true
				setOpen(false)
			end
		end

		return handle
	end

	-- A tool call row: a disclosure caret, a risk dot, the tool's name, what it is
	-- doing, how long it took -- and underneath, verbatim, the code it was given.
	--
	-- Flat, not a card. A turn that calls six tools was six outlined boxes stacked
	-- between two paragraphs of prose, which made the machinery louder than the answer.
	--
	-- The code is outside the fold on purpose. Every listing the model produced -- the
	-- Luau it is about to execute, the body it is about to write to a file, the property
	-- map it is about to apply -- was reachable only by opening a pane that defaulted
	-- shut and gave no sign it existed, and what showed instead was ninety characters of
	-- the JSON envelope. Arguments that are values still live behind the fold; arguments
	-- that are code do not, though they fold at a dozen lines rather than sixty.
	function M.toolCall(parent, info, order)
		local holder = wrapper(parent, { name = "Tool", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
		})

		local raw = tostring(info.arguments or "")
		local decoded = util.decode(raw)
		local codeParts, facts = splitArguments(decoded)

		local header = Instance.new("TextButton", card)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		-- One line of a list rather than a row of its own. At `row` these stacked into
		-- eight paragraph-height bands per turn; the touch floor still applies, because
		-- the whole row is the disclosure control.
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.rowTight,
			responsive.minTarget() - theme.space.sm))
		header.LayoutOrder = 1
		header.Selectable = true

		local row = P.row(header, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
		})

		-- The affordance the row never had. Without it a tool call was a line of text
		-- that happened to answer a click, so the detail pane may as well not have been
		-- there.
		local caret = P.frame(row, {
			name = "Caret",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")

		local spinner = C.spinner(row, { diameter = theme.size.icon - theme.space.hair, layoutOrder = 2 })
		local dotSlot = P.frame(row, {
			name = "DotSlot",
			size = UDim2.fromOffset(theme.size.icon - theme.space.hair, theme.size.icon - theme.space.hair),
			layoutOrder = 2,
		})
		dotSlot.Visible = false
		local dot = P.statusDot(dotSlot, {
			color = theme.riskColor(info.risk),
			diameter = theme.size.dot,
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.5),
		})

		local name = P.text(row, {
			text = tostring(info.name or "tool"),
			role = "monoSmall",
			color = theme.color.textSecondary,
			layoutOrder = 3,
		})
		name.Size = UDim2.fromOffset(0, theme.text.monoSmall.height)
		name.AutomaticSize = Enum.AutomaticSize.X

		local preview = P.text(row, {
			text = summarise(decoded, raw),
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			-- Takes whatever is left rather than reserving a guess. The guess was
			-- icon + 90, but the row also has to fit an auto-width tool name, so it
			-- over-committed by the width of that name and pushed `timing` out past
			-- the card's clip -- which is why a tool call never showed how long it took.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 4,
		})

		local timing = P.text(row, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 5,
		})
		timing.Size = UDim2.fromOffset(theme.size.metaColumn, theme.text.caption.height)

		-- Always-on code, indented to the caret's centre line so it reads as belonging
		-- to the row above it.
		local codeColumn
		if #codeParts > 0 and config.get("ui.showToolCode", true) ~= false then
			codeColumn = P.column(card, {
				name = "Listing",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				padding = { left = theme.size.icon + theme.space.xs },
				layoutOrder = 2,
			})
			for index, part in ipairs(codeParts) do
				M.codeBlock(codeColumn, {
					text = part.text,
					lang = part.lang or part.key,
					maxLines = TOOL_CODE_LINES,
					layoutOrder = index,
				})
			end
		end

		local detail = P.column(card, {
			name = "Detail",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surface,
			radius = theme.radius.md,
			gap = theme.space.sm,
			padding = theme.space.sm,
			layoutOrder = 3,
			visible = config.get("ui.showToolDetail", false) == true,
		})

		-- Arguments that are values, as a key column rather than as a wall of JSON.
		if #facts > 0 then
			local factColumn = P.column(detail, {
				name = "Arguments",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xxs,
				layoutOrder = 1,
			})
			for index, fact in ipairs(facts) do
				C.keyValue(factColumn, {
					key = fact.key,
					value = fact.value,
					role = "monoSmall",
					color = theme.color.textSecondary,
					layoutOrder = index,
				})
			end
		elseif #codeParts == 0 and util.trim(raw) ~= "" and util.trim(raw) ~= "{}" then
			-- Nothing decoded and nothing recognised: show what actually arrived. A model
			-- that emits malformed arguments is a thing worth being able to see.
			M.codeBlock(detail, {
				text = raw,
				lang = "json",
				numbers = false,
				layoutOrder = 1,
			})
		end

		local resultHolder = P.column(detail, {
			name = "Result",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
			layoutOrder = 3,
			visible = false,
		})

		local open = detail.Visible
		local function setOpen(value)
			open = value == true
			detail.Visible = open
			caret.Rotation = open and 90 or 0
		end
		setOpen(open)
		header.Activated:Connect(function() setOpen(not open) end)

		local handle = { root = holder, card = card }
		local nested

		-- Where a tool that runs an agent of its own puts its live feed. Sits between the
		-- arguments and the result, which is the order it happens in, and forces the
		-- detail pane open: a row with something moving inside it should not be the one
		-- thing hiding it.
		function handle.nest()
			if not nested then
				nested = P.column(detail, {
					name = "Nested",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					layoutOrder = 2,
				})
			end
			setOpen(true)
			return nested
		end

		function handle.progress(text)
			preview.Text = util.ellipsis(tostring(text), ARG_PREVIEW)
		end

		-- A call whose result is not in this transcript.
		--
		-- Restored conversations can have one: the stored log keeps the most recent 300
		-- durable events, so a long transcript can begin part-way through a turn. It is
		-- not a failure and must not be drawn as one, but the row cannot be left spinning
		-- either -- a spinner that never stops reads as a hung agent.
		function handle.stale()
			pcall(function() spinner:Destroy() end)
			dotSlot.Visible = true
			dot.BackgroundColor3 = theme.color.textDisabled
			timing.Text = ""
			resultHolder.Visible = true
			local note = P.text(resultHolder, {
				name = "ResultLabel",
				text = "No result in the stored transcript.",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 1,
			})
			note.Size = UDim2.new(1, 0, 0, 0)
		end

		function handle.finish(result)
			pcall(function() spinner:Destroy() end)
			dotSlot.Visible = true
			if result.ok then
				dot.BackgroundColor3 = theme.riskColor(info.risk)
			else
				dot.BackgroundColor3 = result.denied and theme.color.warn or theme.color.danger
			end
			timing.Text = result.ms and util.formatDuration(result.ms) or ""
			local text = tostring(result.text or "")
			preview.Text = util.ellipsis(text:gsub("[\n\r]+", " "), ARG_PREVIEW)
			preview.TextColor3 = result.ok and theme.color.textTertiary or theme.color.danger

			resultHolder.Visible = true
			local label = P.text(resultHolder, {
				name = "ResultLabel",
				text = result.ok and "result" or "failed",
				role = "label",
				color = result.ok and theme.color.textTertiary or theme.color.danger,
				auto = "Y",
				layoutOrder = 1,
			})
			label.Size = UDim2.new(1, 0, 0, theme.text.label.height)
			-- Multi-line output is a listing -- a file's contents, a print capture, a
			-- stack trace -- and gets the same numbered surface the arguments do. One
			-- line is a sentence and gets read as one.
			if text:find("\n") then
				M.codeBlock(resultHolder, {
					text = text,
					lang = "output",
					layoutOrder = 2,
				})
			else
				local body = P.text(resultHolder, {
					text = text,
					role = "monoSmall",
					color = result.ok and theme.color.textSecondary or theme.color.danger,
					wrap = true,
					auto = "Y",
					layoutOrder = 2,
				})
				body.Size = UDim2.new(1, 0, 0, 0)
			end
			if result.truncated then
				local note = P.text(resultHolder, {
					text = "Trimmed before the model saw it.",
					role = "caption",
					color = theme.color.warn,
					wrap = true,
					auto = "Y",
					layoutOrder = 3,
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end
			-- A failure the user cannot see is a failure they cannot act on, so an error
			-- opens its own pane. A success does not: that is what the fold is for.
			if not result.ok then setOpen(true) end
		end

		return handle
	end

	-- A subagent's live feed.
	--
	-- The parent pays for one paragraph of report, but the user should still be able to
	-- watch the work. From outside, a delegated task is a spinner on a row that says
	-- nothing, which is indistinguishable from a hang -- and three of them at once are
	-- indistinguishable from each other. So each dispatch gets a card that fills in as
	-- its child works: every tool it calls, what it said between calls, the report at
	-- the end.
	--
	-- Driven by events forwarded onto the parent's stream rather than by reaching into
	-- the child session, so it replays from the log like every other row. Switching
	-- panel mid-dispatch and coming back shows the same feed, not an empty box.
	function M.subagent(parent, info, order, opts)
		opts = opts or {}
		local holder = wrapper(parent, { name = "Subagent", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
			clip = true,
		})

		local header = Instance.new("TextButton", card)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.row - theme.space.xxs,
			responsive.minTarget() - theme.space.sm))
		header.LayoutOrder = 1
		header.Selectable = true

		local row = P.row(header, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
		})

		local spinner = C.spinner(row, { diameter = theme.size.icon - theme.space.hair, layoutOrder = 1 })
		local dotSlot = P.frame(row, {
			name = "DotSlot",
			size = UDim2.fromOffset(theme.size.icon - theme.space.hair, theme.size.icon - theme.space.hair),
			layoutOrder = 1,
		})
		dotSlot.Visible = false
		local dot = P.statusDot(dotSlot, {
			color = theme.color.accent,
			diameter = theme.size.dot,
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.5),
		})

		local kindLabel = P.text(row, {
			-- A follow-up says so. It is the same subagent with the same context and the
			-- same id, so two cards under one conversation would otherwise read as two
			-- separate dispatches doing the same job twice.
			text = info.followUp and "follow-up" or "agent",
			role = "monoSmall",
			color = theme.color.accent,
			layoutOrder = 2,
		})
		kindLabel.Size = UDim2.fromOffset(0, theme.text.monoSmall.height)
		kindLabel.AutomaticSize = Enum.AutomaticSize.X
		local title = P.text(row, {
			text = tostring(info.label or "task"),
			role = "caption",
			color = theme.color.textSecondary,
			truncate = true,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 3,
		})

		local meta = P.text(row, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 4,
		})
		meta.Size = UDim2.fromOffset(theme.size.metaColumnWide, theme.text.caption.height)

		local feed = P.column(card, {
			name = "Feed",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			-- A nested card sits inside a tool row's detail pane, which is already on
			-- `surface`, so the feed has to step up again or the two are the same colour
			-- and the card loses its edge.
			bg = opts.nested and theme.color.surfaceRaised or theme.color.surface,
			radius = theme.radius.md,
			gap = theme.space.xxs,
			padding = theme.space.sm,
			layoutOrder = 2,
		})

		local status = P.text(feed, {
			text = "Starting",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 1,
		})
		status.Visible = false
		status.Size = UDim2.new(1, 0, 0, 0)

		-- The feed is open while the work happens, which is the whole point of it. The
		-- header still toggles, because a finished subagent's feed is history and a
		-- conversation with six of them in it should be collapsible.
		local open = true
		header.Activated:Connect(function()
			open = not open
			feed.Visible = open
		end)
		local rows = {}
		local slot = 1
		local function nextSlot()
			slot = slot + 1
			return slot
		end

		local function line(text, colour, role)
			local label = P.text(feed, {
				text = tostring(text),
				role = role or "caption",
				color = colour or theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = nextSlot(),
			})
			label.Size = UDim2.new(1, 0, 0, 0)
			return label
		end

		local started = clock.ms()
		local calls, finished, finalMs = 0, 0, nil

		local function paintMeta()
			local bits = {}
			if calls > 0 then bits[#bits + 1] = string.format("%d/%d", finished, calls) end
			local waited = finalMs or clock.since(started)
			if waited >= 1000 then bits[#bits + 1] = util.formatDuration(waited) end
			meta.Text = table.concat(bits, "  ")
		end

		-- One timer for the clock, stopped when the subagent reports back. Same reason
		-- the working row has one: a number that moves is what separates "this is taking
		-- a while" from "this is stuck", and a subagent takes minutes.
		local stop = clock.interval(0.5, function()
			if not finalMs then paintMeta() end
		end)
		holder.Destroying:Connect(function() pcall(stop) end)
		local handle = { root = holder, card = card }

		function handle.status(event)
			local text = util.trim(tostring(event.text or ""))
			if text == "" or text == "Ready" then return end
			status.Visible = true
			status.Text = text
			status.TextColor3 = event.bad and theme.color.danger or theme.color.textTertiary
		end

		function handle.say(event)
			local text = util.trim(tostring(event.text or ""))
			if text == "" then return end
			line(text, theme.color.textSecondary, "small")
		end

		-- One line per tool the child calls, keyed by the child's own call id so the
		-- result can land on the row that asked for it -- plus, underneath, whatever code
		-- that call was handed.
		--
		-- The line collapses to a summary and the listing is drawn in full, which is the
		-- same treatment a top-level call gets. Before, the child's arguments arrived
		-- already cut to 160 whitespace-collapsed characters and there was nowhere else to
		-- look: a headless session keeps no log, so a subagent's work was the one thing in
		-- this client that could not be read back.
		function handle.tool(event)
			calls = calls + 1
			local toolRow = P.row(feed, {
				size = UDim2.new(1, 0, 0, theme.text.monoSmall.height),
				gap = theme.space.xs,
				layoutOrder = nextSlot(),
			})
			P.statusDot(toolRow, {
				color = theme.riskColor(event.risk),
				diameter = theme.size.dotSmall,
				layoutOrder = 1,
			})
			local name = P.text(toolRow, {
				text = tostring(event.name or "tool"),
				role = "monoSmall",
				color = theme.color.textSecondary,
				layoutOrder = 2,
			})
			name.Size = UDim2.fromOffset(0, theme.text.monoSmall.height)
			name.AutomaticSize = Enum.AutomaticSize.X
			local raw = tostring(event.arguments or "")
			local decoded = util.decode(raw)
			local args = P.text(toolRow, {
				text = summarise(decoded, raw),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(0, 0, 1, 0),
				flex = "Fill",
				layoutOrder = 3,
			})
			local timing = P.text(toolRow, {
				text = "",
				role = "caption",
				color = theme.color.textTertiary,
				align = "Right",
				layoutOrder = 4,
			})
			timing.Size = UDim2.fromOffset(theme.size.metaColumn, theme.text.caption.height)
			if config.get("ui.showToolCode", true) ~= false then
				local codeParts = splitArguments(decoded)
				for _, part in ipairs(codeParts) do
					M.codeBlock(feed, {
						text = part.text,
						lang = part.lang or part.key,
						maxLines = TOOL_CODE_LINES,
						layoutOrder = nextSlot(),
					})
				end
			end
			rows[tostring(event.callId or calls)] = { args = args, timing = timing }
			paintMeta()
		end
		function handle.toolDone(event)
			finished = finished + 1
			local entry = rows[tostring(event.callId or "")]
			if entry then
				entry.timing.Text = event.ms and util.formatDuration(event.ms) or ""
				local summary = util.trim(tostring(event.summary or ""))
				if summary ~= "" then entry.args.Text = summary end
				if not event.ok then entry.args.TextColor3 = theme.color.danger end
			end
			paintMeta()
		end

		function handle.finish(event)
			finalMs = event.ms or clock.since(started)
			pcall(stop)
			pcall(function() spinner:Destroy() end)
			dotSlot.Visible = true
			if event.aborted then
				dot.BackgroundColor3 = theme.color.warn
			elseif event.ok == false then
				dot.BackgroundColor3 = theme.color.danger
			else
				dot.BackgroundColor3 = theme.color.accent
			end
			paintMeta()
			status.Visible = true
			if event.aborted then
				status.Text = "Stopped before it finished."
			elseif event.ok == false then
				status.Text = tostring(event.text or "Failed.")
			else
				status.Text = string.format("Reported back after %s over %s.",
					util.formatDuration(finalMs), util.pluralise(event.messages or 0, "message"))
			end
			if event.ok ~= false and util.trim(tostring(event.text or "")) ~= "" then
				line(tostring(event.text), theme.color.text, "small")
			end
		end

		-- The same sweep the tool rows get: a dispatch whose report is not in the stored
		-- transcript stops spinning and says so, rather than counting up forever.
		function handle.stale()
			pcall(stop)
			pcall(function() spinner:Destroy() end)
			dotSlot.Visible = true
			dot.BackgroundColor3 = theme.color.textDisabled
			finalMs = finalMs or clock.since(started)
			paintMeta()
			status.Visible = true
			status.Text = "No report in the stored transcript."
		end

		paintMeta()
		return handle
	end

	-- An inline note: a retry, a provider switch, a compaction, an error.
	--
	-- Only a bad one gets a fill. The rest are ordinary events in the life of a turn
	-- and were each arriving as a tinted panel, so a conversation that retried twice
	-- and compacted once read as three warnings rather than as three footnotes.
	function M.notice(parent, props, order)
		local tone = props.tone or "info"
		local holder = wrapper(parent, { name = "Notice", layoutOrder = order })
		local bad = tone == "bad"
		local row = P.row(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = bad and theme.color.dangerSurface or nil,
			radius = bad and theme.radius.md or nil,
			gap = theme.space.xs,
			-- Padded either way, so a bad notice does not indent its own text eight pixels
			-- further than the plain one above it. The fill is what marks it, not the inset.
			padding = { x = bad and theme.space.sm or 0, y = bad and theme.space.xs or 0 },
			alignY = "Top",
		})
		-- The same slot width the tool and reasoning rows put their caret in, so every
		-- top-level row in the transcript starts its text at one x. This was a bare 4px
		-- dot: a notice's text began twelve pixels left of the tool call above it.
		local dotSlot = P.frame(row, {
			name = "DotSlot",
			size = UDim2.fromOffset(theme.size.icon, theme.text.small.height),
			layoutOrder = 1,
		})
		P.statusDot(dotSlot, {
			color = theme.toneColor(tone),
			diameter = theme.size.dotSmall,
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.5),
		})
		local label = P.text(row, {
			text = tostring(props.text),
			role = "small",
			color = bad and theme.color.danger or theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			size = UDim2.new(0, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		return { root = holder, label = label }
	end

	-- The working indicator: one row that reports the current status text, replaced
	-- by the answer when the turn ends. It carries the two signals that separate
	-- "thinking" from "hung" -- a label that moves and a clock that counts up --
	-- because the HTTP call it covers can take a minute and says nothing while it
	-- does.
	function M.working(parent, order)
		local holder = wrapper(parent, { name = "Working", layoutOrder = order })
		local rowHeight = math.max(theme.size.row - theme.space.xs, theme.text.small.height)
		local row = P.row(holder, {
			size = UDim2.new(1, 0, 0, rowHeight),
			gap = theme.space.xs,
		})
		C.spinner(row, { diameter = theme.size.icon, layoutOrder = 1 })
		local label = P.text(row, {
			text = "Thinking",
			role = "small",
			color = theme.color.textSecondary,
			-- Fills, rather than subtracting the spinner and the clock by hand. That
			-- remainder was three numbers deep and one of them was a literal 52 that
			-- also appeared, separately, as the clock's own width.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		local elapsed = P.text(row, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 3,
		})
		elapsed.Size = UDim2.fromOffset(theme.size.metaColumn, rowHeight)

		local handle = { root = holder, label = label }
		local base = "Thinking"
		local started = clock.ms()
		local frame = 0
		-- One timer drives both, so the trailing dots and the clock stay in step.
		local stop = clock.interval(0.4, function()
			frame = frame + 1
			if not responsive.reduceMotion then
				label.Text = base .. string.rep(".", frame % 4)
			end
			local waited = clock.since(started)
			if waited >= 1000 then elapsed.Text = util.formatDuration(waited) end
		end)
		holder.Destroying:Connect(function() pcall(stop) end)

		-- The status text is the base the dots are appended to, not the whole label,
		-- or the next tick would overwrite whatever was just set.
		function handle.set(text)
			base = tostring(text)
			label.Text = base
		end
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/todo
-- ==========================================================================
__UAI_MODULES["ui/chat/todo"] = (function()
-- The task-list strip.
--
-- The model keeps a plan; this is where the user can see it. It collapses to a
-- single line when there is nothing active, because a permanent panel for a
-- three-item list wastes the height a phone does not have.
--
-- It shows one conversation's plan: the strip is attached to a session, and a change
-- announced for a different one is ignored. Before, the store held a single list for
-- the whole client, so opening a second conversation replaced what this was showing
-- with that conversation's steps.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local P = env.require("ui/primitives")
	local state = env.require("agent/state")

	local M = {}

	local MARKS = {
		pending = { colour = "textTertiary", glyph = nil },
		active = { colour = "accent", glyph = "dot" },
		done = { colour = "success", glyph = "check" },
		dropped = { colour = "textDisabled", glyph = "minus" },
	}

	function M.new(parent, props)
		props = props or {}

		local shell = P.column(parent, {
			name = "Todos",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surfaceRaised,
			gap = 0,
			layoutOrder = props.layoutOrder,
			visible = false,
			clip = true,
		})
		-- Last in the stack rather than anchored to the bottom edge: the shell is a
		-- column, and a UIListLayout moves every child it has to its own slot, so an
		-- anchored rule would silently become the first row instead of the last.
		P.frame(shell, {
			name = "Rule",
			size = UDim2.new(1, 0, 0, theme.stroke.hair),
			bg = theme.color.borderSubtle,
			layoutOrder = 3,
		})

		local header = Instance.new("TextButton", shell)
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundTransparency = 1
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget() - theme.space.sm))
		header.LayoutOrder = 1
		header.Selectable = true

		local headerRow = P.row(header, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			-- The transcript's own horizontal inset. At md the task strip's caret sat four
			-- pixels left of every row in the conversation under it, down the full height
			-- of the panel.
			padding = { x = theme.space.xl },
		})
		local caret = P.frame(headerRow, {
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")
		local summary = P.text(headerRow, {
			text = "",
			role = "label",
			color = theme.color.textSecondary,
			truncate = true,
			layoutOrder = 2,
		})
		summary.Size = UDim2.new(1, -(theme.size.icon + theme.space.xs), 1, 0)

		local list = P.column(shell, {
			name = "Items",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
			padding = { x = theme.space.xl, bottom = theme.space.sm },
			layoutOrder = 2,
			visible = false,
		})

		local open = false
		header.Activated:Connect(function()
			open = not open
			list.Visible = open
			caret.Rotation = open and 90 or 0
		end)

		local handle = { shell = shell, session = nil }

		local function rebuild(items)
			for _, child in ipairs(list:GetChildren()) do
				if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
			end

			if #items == 0 then
				shell.Visible = false
				return
			end
			shell.Visible = true

			local counts = state.todoCounts(handle.session)
			local activeText
			for _, item in ipairs(items) do
				if item.status == "active" then activeText = item.text end
			end
			summary.Text = string.format("%d of %d done%s",
				counts.done, counts.total,
				activeText and ("  -  " .. util.ellipsis(activeText, 60)) or "")

			for index, item in ipairs(items) do
				local mark = MARKS[item.status] or MARKS.pending
				local row = P.row(list, {
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					alignY = "Top",
					layoutOrder = index,
				})
				local glyphHolder = P.frame(row, {
					size = UDim2.fromOffset(theme.size.icon, theme.text.small.height),
					layoutOrder = 1,
				})
				if mark.glyph then
					icons.draw(mark.glyph, glyphHolder, theme.size.icon - 2, theme.color[mark.colour])
				else
					P.statusDot(glyphHolder, {
						diameter = theme.size.dotSmall,
						color = theme.color[mark.colour],
						anchor = Vector2.new(0.5, 0.5),
						position = UDim2.fromScale(0.5, 0.5),
					})
				end
				local label = P.text(row, {
					text = item.text,
					role = item.status == "active" and "bodyStrong" or "small",
					color = theme.color[mark.colour],
					wrap = true,
					auto = "Y",
					layoutOrder = 2,
				})
				label.Size = UDim2.new(1, -(theme.size.icon + theme.space.xs), 0, 0)
			end

			-- An active item is worth showing without a click; a finished list is not.
			if activeText and not open then
				open = true
				list.Visible = true
				caret.Rotation = 90
			end
		end

		-- A change announced for another conversation is somebody else's plan.
		local unsubscribe = state.todosChanged:connect(function(items, session)
			if session ~= nil and session ~= handle.session then return end
			rebuild(items)
		end)

		-- Points the strip at a conversation and paints its plan. Called on every
		-- switch, so folding state resets with the list it belonged to.
		function handle.attach(session)
			handle.session = session
			open = false
			list.Visible = false
			caret.Rotation = 0
			rebuild(state.todoList(session))
		end

		function handle.destroy()
			unsubscribe()
			pcall(function() shell:Destroy() end)
		end

		handle.attach(props.session)
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/view
-- ==========================================================================
__UAI_MODULES["ui/chat/view"] = (function()
-- The transcript.
--
-- It is a pure function of the session's event log: `attach` subscribes to a
-- session, replays whatever it missed, and renders each new event as it arrives.
-- That is what makes rebuilding on a layout-mode change safe -- switching a phone
-- from portrait to landscape rebuilds the whole view and loses nothing.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local message = env.require("ui/chat/message")

	local M = {}

	function M.new(parent, props)
		props = props or {}

		local scroll = P.scroll(parent, {
			name = "Transcript",
			size = props.size or UDim2.new(1, 0, 1, 0),
			-- More air between turns than inside one. A turn's own paragraphs are md
			-- apart, so the gap between turns has to be clearly larger or a reply and
			-- the question after it read as one block of text. At xl the difference was
			-- eight pixels, which is not a boundary anyone reads as one -- a turn, its
			-- thinking, its tool calls and its answer are all siblings in this list, so
			-- whatever separates them is the only thing giving the transcript structure.
			gap = theme.space.xxl,
			padding = { x = theme.space.xl, top = theme.space.lg, bottom = theme.space.xl },
			fade = false,
		})

		local view = {
			scroll = scroll,
			order = 0,
			tools = {},
			agents = {},
			working = nil,
			-- The open activity block, if the transcript is mid-run. Tool calls, the
			-- thinking between them and the notices they raise all go inside it; prose
			-- from either side closes it.
			run = nil,
			agentHandle = nil,
			session = nil,
			unsubscribe = nil,
			pinned = true,
		}

		-- Autoscroll only when the user is already at the bottom. Yanking someone
		-- back down while they are reading earlier output is the most irritating
		-- thing a chat view can do.
		local function follow(force)
			if force or view.pinned then
				scroll.toBottom()
			end
		end

		scroll.instance:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			view.pinned = scroll.atBottom(theme.space.huge)
		end)

		local function nextOrder()
			view.order = view.order + 1
			return view.order
		end

		-- The activity block.
		--
		-- A turn's machinery -- the calls, the thinking between them, a retry notice --
		-- used to be a stack of top-level rows, and the transcript deliberately puts a
		-- paragraph's worth of air between top-level rows. Eight calls therefore read as
		-- eight separate events with the reply lost at the bottom, which is the "too much
		-- tool call" this fixes: one block, one paragraph gap around it, tight lines
		-- inside, and a header that folds the whole run once it has finished.
		--
		-- Only prose closes it, because prose is what a run is between. Closing on
		-- reasoning instead would give a step-per-call turn one block per call and change
		-- nothing, and putting a later row above an earlier one is not an option: the
		-- block takes its layout order when it opens, so anything that has to sort after
		-- the rows already in it has to go in it.
		local function openRun()
			if not view.run then
				view.run = message.toolRun(scroll.instance, nextOrder())
			end
			return view.run
		end

		local function closeRun()
			view.run = nil
		end

		-- Where a row belongs: inside the open block, or in the transcript itself.
		local function target()
			if view.run then return view.run.rows, view.run.slot() end
			return scroll.instance, nextOrder()
		end

		local function clearWorking()
			if view.working then
				pcall(function() view.working.root:Destroy() end)
				view.working = nil
			end
		end

		-- The working row is transient and always belongs at the end of the
		-- transcript, so it takes an order no real row will reach rather than the next
		-- sequential one. Otherwise a tool row created while it is up sorts below it
		-- and the indicator ends up stranded in the middle of the conversation.
		local WORKING_ORDER = 1e6

		local function ensureWorking()
			if not view.working then
				view.working = message.working(scroll.instance, WORKING_ORDER)
			end
			return view.working
		end

		-- Progressive reveal.
		--
		-- No Roblox HTTP transport reads a body incrementally, so a reply arrives whole
		-- and there is nothing to stream. The motion is manufactured here instead: the
		-- bubble is built empty and filled over a fixed number of ticks, so a long
		-- answer takes the same time to land as a short one rather than crawling.
		-- Revealed in chunks, not per character, because setText re-renders the whole
		-- markdown tree on each call.
		local REVEAL_TICKS = 40
		local REVEAL_STEP = 0.04

		local function stopReveal(complete)
			local reveal = view.reveal
			if not reveal then return end
			view.reveal = nil
			pcall(reveal.stop)
			-- Whatever interrupts a reveal, the full text still has to land: a half
			-- written answer left in the transcript would be a far worse bug than the
			-- missing animation this replaces.
			if complete and reveal.handle then
				pcall(reveal.handle.setText, reveal.text)
			end
		end

		local function revealAgent(text)
			local handle = message.agent(scroll.instance, "", nextOrder())
			view.agentHandle = handle
			if responsive.reduceMotion then
				handle.setText(text)
				follow()
				return handle
			end
			-- Cuts land on a UTF-8 boundary. Replies are full of em dashes and curly
			-- quotes, and slicing one in half shows a replacement glyph for a frame --
			-- Lua's # and sub work in bytes, not characters.
			local function boundary(index)
				while index < #text do
					local byte = text:byte(index + 1)
					if not byte or byte < 128 or byte >= 192 then return index end
					index = index + 1
				end
				return #text
			end
			local shown = 0
			local step = math.max(1, math.ceil(#text / REVEAL_TICKS))
			local reveal = { handle = handle, text = text }
			reveal.stop = clock.interval(REVEAL_STEP, function()
				shown = boundary(math.min(#text, shown + step))
				handle.setText(text:sub(1, shown))
				follow()
				if shown >= #text then stopReveal(false) end
			end)
			view.reveal = reveal
			return handle
		end

		function view.empty()
			stopReveal(false)
			if view.welcomeCard then
				pcall(function() view.welcomeCard:Destroy() end)
				view.welcomeCard = nil
			end
			scroll.clear()
			view.order = 0
			view.tools = {}
			view.agents = {}
			view.working = nil
			view.run = nil
			view.agentHandle = nil
			view.pinned = true
		end


		-- What an empty conversation shows: the greeting, the activity card, and -- on a
		-- client with nothing configured yet -- the one thing to do about that. The card
		-- itself lives in ui/panels/home, which reads agent/stats.
		function view.greeting()
			local providers = env.require("provider/registry")
			if view.welcomeCard then
				pcall(function() view.welcomeCard:Destroy() end)
				view.welcomeCard = nil
			end
			view.welcomeCard = env.require("ui/panels/home").card(scroll.instance, nextOrder())
			if providers.count() == 0 then
				C.emptyState(scroll.instance, {
					title = "No provider configured",
					description = "Add an OpenAI-compatible endpoint to start. Anything that speaks /v1/chat/completions works: a hosted API, a relay, or a local server.",
					action = "Open providers",
					onAction = function()
						env.require("ui/app").show("providers")
					end,
					layoutOrder = nextOrder(),
				})
			end
		end

		-- One event in, one row out. Anything not listed is deliberately ignored:
		-- the log carries more than a transcript should show.
		function view.render(event)
			if event.kind == "user" then
				stopReveal(true)
				clearWorking()
				closeRun()
				if view.welcomeCard then
					pcall(function() view.welcomeCard:Destroy() end)
					view.welcomeCard = nil
				end
				view.agentHandle = nil
				message.user(scroll.instance, event.text, nextOrder())
				view.pinned = true
				follow(true)
			elseif event.kind == "status" then
				if event.text and event.text ~= "Ready" then
					ensureWorking().set(event.text)
					follow()
				elseif event.text == "Ready" then
					clearWorking()
				end
			elseif event.kind == "request:start" then
				-- The entire HTTP round trip sits between this and request:done with no
				-- events in between, and it can run for the better part of a minute.
				-- Without a row here that whole wait looks like nothing is happening,
				-- which is the single largest gap in the turn.
				ensureWorking().set("Contacting " .. tostring(event.provider))
				follow()
			elseif event.kind == "assistant:reasoning" then
				local into, order = target()
				message.reasoning(into, event.text, order)
				follow()
			elseif event.kind == "assistant:text" then
				if util.trim(event.text) ~= "" then
					stopReveal(true)
					clearWorking()
					closeRun()
					revealAgent(event.text)
					follow()
				end
			elseif event.kind == "tool:call" then
				-- The working row deliberately survives a tool call: it is the "this
				-- turn is still running" indicator and it sorts last, so it stays put
				-- below the tool rows instead of being destroyed and rebuilt -- which
				-- restarted the spinner's phase and left the following request with no
				-- indicator at all.
				local run = openRun()
				local handle = message.toolCall(run.rows, event, run.slot())
				handle.run = run
				run.opened()
				view.tools[event.id or util.uid("tool")] = handle
				follow()
			elseif event.kind == "tool:progress" then
				-- Progress has no id: it belongs to whichever call is still open.
				for _, handle in pairs(view.tools) do
					if handle.progress then handle.progress(event.text) end
				end
			elseif event.kind == "tool:result" or event.kind == "tool:error" then
				local handle = view.tools[event.id]
				if handle then
					handle.finish(event)
					if handle.run then handle.run.closed() end
					view.tools[event.id] = nil
				else
					local into, order = target()
					message.notice(into, {
						tone = event.kind == "tool:error" and "bad" or "info",
						text = string.format("%s: %s", tostring(event.name), util.ellipsis(event.text, 200)),
					}, order)
				end
				follow()
			elseif event.kind == "subagent:start" then
				-- Nested under the call that started it while that row is still tracked,
				-- so a delegated task reads as one block rather than as a card floating
				-- next to its own tool row. Standalone if the row is gone, which happens
				-- when the log has been trimmed past it.
				local host = event.call and view.tools[event.call] or nil
				if host and host.nest then
					view.agents[event.id] = message.subagent(host.nest(), event, 1, { nested = true })
				else
					local into, order = target()
					view.agents[event.id] = message.subagent(into, event, order, {})
				end
				follow()
			elseif event.kind == "subagent:status" then
				local handle = view.agents[event.id]
				if handle then handle.status(event) end
			elseif event.kind == "subagent:text" then
				local handle = view.agents[event.id]
				if handle then
					handle.say(event)
					follow()
				end
			elseif event.kind == "subagent:tool" then
				local handle = view.agents[event.id]
				if handle then
					handle.tool(event)
					follow()
				end
			elseif event.kind == "subagent:tool:done" then
				local handle = view.agents[event.id]
				if handle then handle.toolDone(event) end
			elseif event.kind == "subagent:done" then
				local handle = view.agents[event.id]
				if handle then
					handle.finish(event)
					view.agents[event.id] = nil
					follow()
				end
			elseif event.kind == "request:retry" then
				local into, order = target()
				message.notice(into, {
					tone = "warn",
					text = string.format("%s: %s, retrying in %.1fs (attempt %d of %d)",
						tostring(event.provider), tostring(event.reason), event.wait or 0,
						event.attempt or 1, event.attempts or 1),
				}, order)
				follow()
			elseif event.kind == "provider:switch" then
				local into, order = target()
				message.notice(into, {
					tone = "warn",
					text = string.format("%s failed, trying %s", tostring(event.from), tostring(event.to)),
				}, order)
				follow()
			elseif event.kind == "compact" then
				local into, order = target()
				message.notice(into, {
					tone = "info",
					text = "Older turns were summarised to stay inside the context budget.",
				}, order)
				follow()
			elseif event.kind == "error" then
				stopReveal(true)
				clearWorking()
				closeRun()
				message.notice(scroll.instance, {
					tone = "bad",
					text = tostring(event.message),
				}, nextOrder())
				follow()
			elseif event.kind == "abort" then
				stopReveal(true)
				clearWorking()
				closeRun()
				message.notice(scroll.instance, { tone = "warn", text = "Stopped." }, nextOrder())
				follow()
			elseif event.kind == "cleared" then
				view.empty()
				view.greeting()
			end
		end

		-- Replays the session's own log, so opening the panel mid-turn shows what
		-- has happened rather than an empty pane.
		function view.attach(session)
			if view.unsubscribe then
				view.unsubscribe()
				view.unsubscribe = nil
			end
			view.empty()
			view.session = session
			if not session then
				view.greeting()
				return
			end

			if #session.log == 0 then
				view.greeting()
			else
				for _, event in ipairs(session.log) do
					local ok, err = pcall(view.render, event)
					if not ok then env.require("runtime/log").warn("ui", "replay failed", err) end
				end
			end
			-- Anything still open after a replay is a call or a dispatch whose outcome is
			-- not in the log: trimmed away by the stored transcript's own ceiling, or lost
			-- because the turn died before it landed. On a live session those are genuinely
			-- in flight, so only a settled one is swept.
			if not session.busy then
				clearWorking()
				closeRun()
				for id, handle in pairs(view.tools) do
					if handle.stale then pcall(handle.stale) end
					-- The block the row sits in is counting outstanding calls, and a row
					-- swept as stale is one it will never see a result for.
					if handle.run then pcall(handle.run.closed) end
					view.tools[id] = nil
				end
				for id, handle in pairs(view.agents) do
					if handle.stale then pcall(handle.stale) end
					view.agents[id] = nil
				end
			end

			view.unsubscribe = session.events:connect(function(event)
				local ok, err = pcall(view.render, event)
				if not ok then env.require("runtime/log").warn("ui", "render failed", err) end
			end)
			follow(true)
		end

		function view.destroy()
			if view.unsubscribe then view.unsubscribe() end
			pcall(function() scroll.instance:Destroy() end)
		end

		return view
	end

	return M
end
end)()

-- ==========================================================================
-- ui/controls
-- ==========================================================================
__UAI_MODULES["ui/controls"] = (function()
-- Compound controls built from the primitives.
--
-- Each one owns its own state and exposes a handle, so a panel never reaches into
-- an instance to change what a control shows.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")

	local C = {}

	-- A rotating arc, approximated with three dots at descending opacity. Rotation
	-- is the one property Roblox will tween indefinitely, so this costs one tween
	-- rather than a per-frame connection.
	function C.spinner(parent, props)
		props = props or {}
		local size = props.diameter or theme.size.icon
		local holder = P.frame(parent, {
			name = "Spinner",
			size = UDim2.fromOffset(size, size),
			layoutOrder = props.layoutOrder,
			anchor = props.anchor,
			position = props.position,
		})
		local tint = props.color or theme.color.accent
		-- Three dots spread evenly around the circle rather than bunched into an arc.
		-- At icon size the arc version came out as three two-pixel dots inside eighty
		-- degrees, two of them part-transparent -- a smudge that was hard to tell from
		-- a static one, which rather defeated the point of animating it.
		local dotSize = math.max(math.floor(size / 3.2), 3)
		-- One opacity ramp, used both for the resting state and for the chase. It was
		-- two -- 0.3 at rest and 0.34 animated -- so the dots jumped a step the moment
		-- the first tick landed.
		local FADE_STEP = 0.34
		local dots = {}
		for index = 1, 3 do
			local dot = P.frame(holder, {
				name = "Dot" .. index,
				size = UDim2.fromOffset(dotSize, dotSize),
				bg = tint,
				radius = theme.radius.pill,
				anchor = Vector2.new(0.5, 0.5),
			})
			dots[index] = dot
			dot.BackgroundTransparency = (index - 1) * FADE_STEP
			local angle = (index - 1) * 120
			dot.Position = UDim2.fromScale(
				0.5 + math.cos(math.rad(angle)) * 0.34,
				0.5 + math.sin(math.rad(angle)) * 0.34)
		end
		if not responsive.reduceMotion then
			local spin = env.tween:Create(holder, theme.motion.spin, { Rotation = 360 })
			spin:Play()
			-- The dots chase each other in opacity as well as going round. A single
			-- Rotation tween on a sixteen-pixel box is easy to miss, and if a client
			-- ever declines to tween Rotation there is nothing left at all -- this does
			-- not depend on the tween having taken.
			local phase = 0
			local stop = clock.interval(theme.motion.fast, function()
				phase = (phase + 1) % 3
				for index = 1, 3 do
					dots[index].BackgroundTransparency = ((index + phase) % 3) * FADE_STEP
				end
			end)
			holder.Destroying:Connect(function()
				pcall(function() spin:Cancel() end)
				pcall(stop)
			end)
		end
		return holder
	end

	function C.switch(parent, props)
		props = props or {}
		local width = theme.size.switchWide
		local height = theme.size.switch
		local inset = math.max(math.floor(height / 8), 2)
		local knobSize = height - inset * 2
		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Size = UDim2.fromOffset(width, height)
		button.BackgroundColor3 = theme.color.surfaceActive
		button.BorderSizePixel = 0
		button.Selectable = true
		button.LayoutOrder = props.layoutOrder or 0
		P.corner(button, theme.radius.pill)
		local stroke = P.stroke(button, theme.color.border)

		local knob = P.frame(button, {
			name = "Knob",
			size = UDim2.fromOffset(knobSize, knobSize),
			position = UDim2.new(0, inset, 0.5, 0),
			anchor = Vector2.new(0, 0.5),
			bg = theme.color.textTertiary,
			radius = theme.radius.pill,
		})

		local handle = { value = props.value == true }

		-- On is the full accent with a cream knob, not a muted wash: a switch is the
		-- one control whose entire job is to be readable at a glance from across a
		-- settings list, and the muted version could not be told from off.
		local function paint(animate)
			local info = animate and theme.tween("hover") or theme.tween("instant")
			env.tween:Create(button, info, {
				BackgroundColor3 = handle.value and theme.color.accent or theme.color.surfaceActive,
			}):Play()
			env.tween:Create(stroke, info, {
				Color = handle.value and theme.color.accent or theme.color.border,
			}):Play()
			env.tween:Create(knob, info, {
				Position = handle.value and UDim2.new(1, -inset, 0.5, 0) or UDim2.new(0, inset, 0.5, 0),
				BackgroundColor3 = handle.value and theme.color.solid or theme.color.textTertiary,
			}):Play()
			knob.AnchorPoint = handle.value and Vector2.new(1, 0.5) or Vector2.new(0, 0.5)
		end

		function handle.set(value, silent)
			handle.value = value == true
			paint(true)
			if not silent and props.onChange then pcall(props.onChange, handle.value) end
		end

		button.Activated:Connect(function() handle.set(not handle.value) end)
		paint(false)
		handle.instance = button
		return handle
	end

	-- Track, fill and knob, dragged with either pointer or touch. The value is
	-- reported live while dragging and committed on release, so a setting that costs
	-- something to apply can wait for the commit.
	function C.slider(parent, props)
		props = props or {}
		-- `stops` names the allowed values instead of a range, and the knob then moves
		-- one stop per equal slice of the track. A token budget needs that: four
		-- thousand to a million as a linear range puts every value anyone actually
		-- picks inside the first three percent of the control, where one pixel is
		-- several thousand tokens and 24k cannot be told from 32k.
		local stops = props.stops
		if stops and #stops < 2 then stops = nil end
		local min = props.min or (stops and stops[1]) or 0
		local max = props.max or (stops and stops[#stops]) or 1
		local step = props.step
		local height = math.max(responsive.minTarget(), theme.size.controlSmall)

		local shell = P.frame(parent, {
			name = props.name or "Slider",
			size = UDim2.new(1, 0, 0, height),
			layoutOrder = props.layoutOrder,
		})
		local track = P.frame(shell, {
			name = "Track",
			size = UDim2.new(1, 0, 0, theme.size.track),
			position = UDim2.fromScale(0, 0.5),
			anchor = Vector2.new(0, 0.5),
			bg = theme.color.surfaceActive,
			radius = theme.radius.pill,
		})
		local fill = P.frame(track, {
			name = "Fill",
			size = UDim2.fromScale(0, 1),
			bg = theme.color.accent,
			radius = theme.radius.pill,
		})
		local knob = P.frame(shell, {
			name = "Knob",
			size = UDim2.fromOffset(theme.size.knob, theme.size.knob),
			anchor = Vector2.new(0.5, 0.5),
			bg = theme.color.solid,
			radius = theme.radius.pill,
			zIndex = 3,
		})

		local handle = { value = util.clamp(props.value or min, min, max), instance = shell }

		local function nearestStop(value)
			local bestIndex, bestGap = 1, math.huge
			for index, candidate in ipairs(stops) do
				local gap = math.abs(candidate - value)
				if gap < bestGap then bestIndex, bestGap = index, gap end
			end
			return bestIndex
		end

		local function quantise(value)
			if stops then return stops[nearestStop(value)] end
			if step and step > 0 then
				value = min + math.floor(((value - min) / step) + 0.5) * step
			end
			return util.clamp(value, min, max)
		end

		local function alphaFor(value)
			if stops then return (nearestStop(value) - 1) / (#stops - 1) end
			return (max > min) and ((value - min) / (max - min)) or 0
		end

		local function paint()
			local alpha = alphaFor(handle.value)
			fill.Size = UDim2.fromScale(alpha, 1)
			knob.Position = UDim2.new(alpha, 0, 0.5, 0)
		end

		function handle.set(value, silent)
			handle.value = quantise(tonumber(value) or min)
			paint()
			if not silent and props.onChange then pcall(props.onChange, handle.value) end
		end

		local dragging = false

		local function fromInput(input)
			local origin = track.AbsolutePosition.X
			local span = math.max(track.AbsoluteSize.X, 1)
			local alpha = util.clamp((input.Position.X - origin) / span, 0, 1)
			if stops then
				local index = math.floor(alpha * (#stops - 1) + 0.5) + 1
				handle.set(stops[math.max(1, math.min(#stops, index))])
			else
				handle.set(min + alpha * (max - min))
			end
		end

		local hit = Instance.new("TextButton", shell)
		hit.Text = ""
		hit.BackgroundTransparency = 1
		hit.Size = UDim2.new(1, 0, 1, 0)
		hit.ZIndex = 4
		hit.AutoButtonColor = false
		hit.Selectable = true

		hit.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			dragging = true
			fromInput(input)
			env.tween:Create(knob, theme.tween("press"), {
				Size = UDim2.fromOffset(theme.size.knob + theme.space.xxs, theme.size.knob + theme.space.xxs),
			}):Play()
		end)

		hit.InputEnded:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			if not dragging then return end
			dragging = false
			env.tween:Create(knob, theme.tween("press"), {
				Size = UDim2.fromOffset(theme.size.knob, theme.size.knob),
			}):Play()
			if props.onCommit then pcall(props.onCommit, handle.value) end
		end)

		dispose.connection(env.uis.InputChanged:Connect(function(input)
			if not dragging then return end
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then return end
			fromInput(input)
		end))

		paint()
		return handle
	end

	-- Segmented control. Used for permission mode, density, log level: anywhere a
	-- dropdown would hide the options that matter.
	--
	-- The width is capped rather than left to fill the parent. Filling is right on a
	-- phone and absurd on a desktop: at 1920 a two-option control stretched across
	-- the whole window and rendered as two words nine hundred pixels apart, which
	-- reads as a layout fault rather than as something to press. The cap comes from
	-- the labels, because a fixed budget per segment either wastes half the control
	-- on "Log" or truncates "Auto (ask for dangerous)".
	local SEGMENT_MIN = 64
	local SEGMENT_CAP = 860

	-- Average glyph advance as a fraction of the font size, for this family at label
	-- weight. Derived rather than hardcoded in pixels, so the measurement follows the
	-- text scale instead of silently mis-measuring every label at 1.4.
	local GLYPH_RATIO = 0.53

	local function segmentedWidth(options)
		local perCharacter = theme.text.label.size * GLYPH_RATIO
		local total = 0
		for _, option in ipairs(options or {}) do
			local text = tostring(option.label or option.value or option)
			total = total + math.max(SEGMENT_MIN, math.floor(#text * perCharacter) + theme.space.md * 2)
		end
		total = total + theme.space.xxs + math.max(#(options or {}) - 1, 0) * theme.space.hair
		return math.min(total, SEGMENT_CAP)
	end

	-- The width a segmented control wants, for a caller that has to state one because
	-- its own row is sizing itself to its contents. Exposed rather than left private
	-- so the header does not have to keep a remembered number in step with the labels.
	function C.segmentedWidth(options)
		return segmentedWidth(options)
	end

	function C.segmented(parent, props)
		props = props or {}
		local height = math.max(theme.size.tab, responsive.minTarget())
		local cap = segmentedWidth(props.options)
		-- An inset well: the container is a step *below* whatever it sits on and has
		-- no outline of its own, so the selected segment reads as raised out of it
		-- rather than as one bordered box inside another.
		local row = P.row(parent, {
			name = props.name or "Segmented",
			-- An explicit width is an offset, because a scale width contributes
			-- nothing to a parent that is sizing itself to its contents.
			size = props.width and UDim2.fromOffset(props.width, height)
				or UDim2.new(1, 0, 0, height),
			maxSize = (not props.width) and Vector2.new(cap, math.huge) or nil,
			bg = theme.color.surface,
			radius = theme.radius.md,
			gap = theme.space.hair,
			padding = theme.space.hair,
			layoutOrder = props.layoutOrder,
			stretch = true,
		})

		local handle = { value = props.value, buttons = {} }

		local function paint()
			for value, entry in pairs(handle.buttons) do
				local selected = value == handle.value
				env.tween:Create(entry.button, theme.tween("hover"), {
					BackgroundColor3 = selected and theme.color.surfaceActive or theme.color.surface,
					BackgroundTransparency = selected and 0 or 1,
				}):Play()
				env.tween:Create(entry.label, theme.tween("hover"), {
					TextColor3 = selected and theme.color.text or theme.color.textTertiary,
				}):Play()
			end
		end

		for index, option in ipairs(props.options or {}) do
			local value = option.value or option
			local button = Instance.new("TextButton", row)
			button.Name = "Segment_" .. tostring(value)
			button.Text = ""
			button.AutoButtonColor = false
			button.BackgroundColor3 = theme.color.surface
			button.BackgroundTransparency = 1
			button.BorderSizePixel = 0
			button.Size = UDim2.new(0, 0, 1, 0)
			button.LayoutOrder = index
			button.Selectable = true
			P.corner(button, theme.radius.sm)
			local flex = Instance.new("UIFlexItem", button)
			flex.FlexMode = Enum.UIFlexMode.Fill

			local label = P.text(button, {
				text = option.label or tostring(value),
				role = "label",
				color = theme.color.textTertiary,
				align = "Center",
				size = UDim2.new(1, 0, 1, 0),
			})

			handle.buttons[value] = { button = button, label = label }
			button.Activated:Connect(function()
				handle.value = value
				paint()
				if props.onChange then pcall(props.onChange, value) end
			end)
		end

		function handle.set(value)
			handle.value = value
			paint()
		end

		paint()
		handle.instance = row
		return handle
	end

	function C.progress(parent, props)
		props = props or {}
		local track = P.frame(parent, {
			name = "Progress",
			size = UDim2.new(1, 0, 0, theme.size.track),
			bg = theme.color.surfaceActive,
			radius = theme.radius.pill,
			layoutOrder = props.layoutOrder,
			clip = true,
		})
		local fill = P.frame(track, {
			name = "Fill",
			size = UDim2.fromScale(util.clamp(props.value or 0, 0, 1), 1),
			bg = props.color or theme.color.accent,
			radius = theme.radius.pill,
		})
		local handle = { instance = track }
		function handle.set(value)
			env.tween:Create(fill, theme.tween("hover"), {
				Size = UDim2.fromScale(util.clamp(value or 0, 0, 1), 1),
			}):Play()
		end
		return handle
	end

	function C.keyValue(parent, props)
		props = props or {}
		local keyWidth = props.keyWidth or theme.size.keyColumn
		local row = P.row(parent, {
			name = "KeyValue",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			alignY = "Top",
			layoutOrder = props.layoutOrder,
		})
		local key = P.text(row, {
			text = tostring(props.key or ""),
			role = "small",
			color = theme.color.textTertiary,
			size = nil,
			layoutOrder = 1,
			truncate = true,
		})
		key.Size = UDim2.new(0, keyWidth, 0, theme.text.small.height)
		local value = P.text(row, {
			text = tostring(props.value or ""),
			role = props.role or "small",
			color = props.color or theme.color.text,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		value.Size = UDim2.new(1, -(keyWidth + theme.space.sm), 0, 0)
		return row, value
	end

	function C.emptyState(parent, props)
		props = props or {}
		local column = P.column(parent, {
			name = "Empty",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			alignX = "Center",
			padding = { y = theme.space.xxl, x = theme.space.lg },
			layoutOrder = props.layoutOrder,
		})
		P.text(column, {
			text = tostring(props.title or ""),
			role = "bodyStrong",
			color = theme.color.textSecondary,
			align = "Center",
			auto = "Y",
			wrap = true,
		})
		if props.description then
			P.text(column, {
				text = props.description,
				role = "small",
				color = theme.color.textTertiary,
				align = "Center",
				wrap = true,
				auto = "Y",
			})
		end
		if props.action then
			local wrapper = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", alignX = "Center" })
			P.button(wrapper, {
				text = props.action,
				variant = "secondary",
				size = "sm",
				onClick = props.onAction,
			})
		end
		return column
	end

	return C
end
end)()

-- ==========================================================================
-- ui/icons
-- ==========================================================================
__UAI_MODULES["ui/icons"] = (function()
-- Icons drawn from primitives.
--
-- No image assets and no icon font: an asset id can fail to load or be moderated,
-- and Roblox's bundled fonts have patchy glyph coverage, so a client that leans on
-- either shows empty boxes on someone's machine. These are built from thin frames,
-- which cost nothing, scale with the type ramp and are always exactly the accent
-- colour they were asked for.
--
-- Navigation deliberately uses words rather than icons. A hand-drawn glyph set
-- reads as homemade at any size; a small-caps label does not.
return function(env)
	local theme = env.require("ui/theme")
	local caps = env.require("runtime/caps")
	local fsx = env.require("runtime/fsx")
	local assets = env.require("ui/assets")

	local M = {}

	local LUCIDE_MAP = {
		close = "x",
		minus = "minus",
		plus = "plus",
		check = "check",
		chevron = "chevron-down",
		dot = "dot",
		bars = "menu",
		stop = "square",
		send = "send",
		copy = "copy",
		trash = "trash",
		sidebarToggle = "panel-left",
		search = "search",
		arrowLeft = "arrow-left",
		arrowRight = "arrow-right",
		code = "code",
		windowMinimize = "minus",
		windowMaximize = "maximize-2",
		circleHollow = "circle",
		enter = "send",
		folder = "folder",
		branch = "git-branch",
		worktree = "git-fork",
		terminal = "square-terminal",
		document = "file-text",
		gear = "settings",
		sliders = "sliders-horizontal",
		globe = "globe",
		book = "book-open",
		signOut = "log-out",
		ellipsis = "move-horizontal",
	}

	local assetCache = {}

	local function getCustomIcon(name)
		local mapped = LUCIDE_MAP[name]
		if not mapped then return nil end
		if assetCache[name] then return assetCache[name] end

		if not (caps.fn.customasset and caps.fs) then
			return nil
		end

		local relPath = "icons/" .. mapped .. ".png"
		local fullPath = fsx.resolve(relPath)
		if not fullPath then return nil end

		if not fsx.exists(relPath) and assets and assets.icons and assets.icons[mapped] then
			local decoded = assets.decode(assets.icons[mapped])
			if decoded then
				fsx.write(relPath, decoded)
			end
		end

		local ok, asset = pcall(caps.fn.customasset, fullPath)
		if ok and asset and type(asset) == "string" and asset ~= "" then
			assetCache[name] = asset
			return asset
		end

		return nil
	end

	local function bar(parent, props)
		local piece = Instance.new("Frame", parent)
		piece.BorderSizePixel = 0
		piece.AnchorPoint = Vector2.new(0.5, 0.5)
		piece.Position = props.position or UDim2.fromScale(0.5, 0.5)
		piece.Size = props.size
		piece.Rotation = props.rotation or 0
		piece.BackgroundColor3 = props.color
		piece.ZIndex = props.zIndex or 2
		if props.radius ~= 0 then
			Instance.new("UICorner", piece).CornerRadius = UDim.new(1, 0)
		end
		return piece
	end

	-- Every icon is a square container the caller sizes; the shapes inside are
	-- expressed in scale so one implementation serves every size.
	local function holder(parent, size, name)
		local frame = Instance.new("Frame", parent)
		frame.Name = name or "Icon"
		frame.BackgroundTransparency = 1
		frame.Size = UDim2.fromOffset(size, size)
		frame.AnchorPoint = Vector2.new(0.5, 0.5)
		frame.Position = UDim2.fromScale(0.5, 0.5)
		Instance.new("UIAspectRatioConstraint", frame).AspectRatio = 1
		return frame
	end

	local function makeCustom(parent, size, name, asset, colour, rotation)
		local frame = holder(parent, size, name)
		if rotation and rotation ~= 0 then
			frame.Rotation = rotation
		end
		local img = Instance.new("ImageLabel", frame)
		img.Name = "Image"
		img.BackgroundTransparency = 1
		img.BorderSizePixel = 0
		img.AnchorPoint = Vector2.new(0.5, 0.5)
		img.Position = UDim2.fromScale(0.5, 0.5)
		img.Size = UDim2.fromScale(1, 1)
		img.Image = asset
		img.ImageColor3 = colour
		return frame
	end

	local function customOrHolder(parent, size, name, iconKey, colour, rotation)
		local asset = getCustomIcon(iconKey)
		if asset then
			return makeCustom(parent, size, name, asset, colour, rotation), true
		end
		local frame = holder(parent, size, name)
		if rotation and rotation ~= 0 then
			frame.Rotation = rotation
		end
		return frame, false
	end

	local WEIGHT = 0.115

	function M.close(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconClose", "close", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.78, WEIGHT), rotation = 45, color = tint })
		bar(frame, { size = UDim2.fromScale(0.78, WEIGHT), rotation = -45, color = tint })
		return frame
	end

	function M.minus(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconMinus", "minus", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.72, WEIGHT), color = tint })
		return frame
	end

	function M.plus(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconPlus", "plus", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.72, WEIGHT), color = tint })
		bar(frame, { size = UDim2.fromScale(WEIGHT, 0.72), color = tint })
		return frame
	end

	function M.check(parent, size, colour)
		local tint = colour or theme.color.success
		local frame, custom = customOrHolder(parent, size, "IconCheck", "check", tint)
		if custom then return frame end
		bar(frame, {
			size = UDim2.fromScale(0.34, WEIGHT), rotation = 45, color = tint,
			position = UDim2.fromScale(0.3, 0.62),
		})
		bar(frame, {
			size = UDim2.fromScale(0.62, WEIGHT), rotation = -45, color = tint,
			position = UDim2.fromScale(0.58, 0.45),
		})
		return frame
	end

	-- direction: "up" | "down" | "left" | "right"
	local CHEVRON_ROTATION = { up = 180, down = 0, left = 90, right = -90 }

	function M.chevron(parent, size, colour, direction)
		local rot = CHEVRON_ROTATION[direction or "down"] or 0
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconChevron", "chevron", tint, rot)
		if custom then return frame end
		frame.Rotation = rot
		bar(frame, {
			size = UDim2.fromScale(0.46, WEIGHT), rotation = 45, color = tint,
			position = UDim2.fromScale(0.34, 0.44),
		})
		bar(frame, {
			size = UDim2.fromScale(0.46, WEIGHT), rotation = -45, color = tint,
			position = UDim2.fromScale(0.66, 0.44),
		})
		return frame
	end

	function M.dot(parent, size, colour)
		local tint = colour or theme.color.accent
		local frame, custom = customOrHolder(parent, size, "IconDot", "dot", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.42, 0.42), color = tint })
		return frame
	end

	function M.bars(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconBars", "bars", tint)
		if custom then return frame end
		for index, offset in ipairs({ 0.26, 0.5, 0.74 }) do
			bar(frame, {
				size = UDim2.fromScale(0.74, WEIGHT * 0.9), color = tint,
				position = UDim2.fromScale(0.5, offset), zIndex = index + 1,
			})
		end
		return frame
	end

	function M.stop(parent, size, colour)
		local tint = colour or theme.color.text
		local frame, custom = customOrHolder(parent, size, "IconStop", "stop", tint)
		if custom then return frame end
		local square = bar(frame, { size = UDim2.fromScale(0.5, 0.5), color = tint, radius = 0 })
		Instance.new("UICorner", square).CornerRadius = UDim.new(0, theme.radius.sm)
		return frame
	end

	-- A send affordance: the return arrow ↵ matching Claude Code Desktop.
	function M.send(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconSend", "send", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(WEIGHT, 0.34), color = tint, position = UDim2.fromScale(0.68, 0.44) })
		bar(frame, { size = UDim2.fromScale(0.42, WEIGHT), color = tint, position = UDim2.fromScale(0.5, 0.6) })
		bar(frame, { size = UDim2.fromScale(0.22, WEIGHT), rotation = 45, color = tint, position = UDim2.fromScale(0.38, 0.52) })
		bar(frame, { size = UDim2.fromScale(0.22, WEIGHT), rotation = -45, color = tint, position = UDim2.fromScale(0.38, 0.68) })
		return frame
	end

	-- An eight-pointed asterisk: four bars through the centre at forty-five degree
	-- steps. It is the mark this interface is modelled on, and it is the one glyph
	-- here that carries brand rather than function -- so it gets the accent by
	-- default rather than the secondary text tone every other icon uses.
	function M.spark(parent, size, colour)
		local frame = holder(parent, size, "IconSpark")
		local tint = colour or theme.color.accent
		for _, rotation in ipairs({ 0, 45, 90, 135 }) do
			bar(frame, { size = UDim2.fromScale(0.82, WEIGHT), rotation = rotation, color = tint })
		end
		return frame
	end

	function M.copy(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconCopy", "copy", tint)
		if custom then return frame end
		for index, spec in ipairs({
			{ position = UDim2.fromScale(0.38, 0.38), size = UDim2.fromScale(0.5, 0.5) },
			{ position = UDim2.fromScale(0.6, 0.6), size = UDim2.fromScale(0.5, 0.5) },
		}) do
			local box = Instance.new("Frame", frame)
			box.BackgroundTransparency = 1
			box.BorderSizePixel = 0
			box.AnchorPoint = Vector2.new(0.5, 0.5)
			box.Position = spec.position
			box.Size = spec.size
			box.ZIndex = index + 1
			Instance.new("UICorner", box).CornerRadius = UDim.new(0, theme.radius.sm)
			local stroke = Instance.new("UIStroke", box)
			stroke.Color = tint
			stroke.Thickness = theme.stroke.hair
		end
		return frame
	end

	function M.trash(parent, size, colour)
		local tint = colour or theme.color.danger
		local frame, custom = customOrHolder(parent, size, "IconTrash", "trash", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.66, WEIGHT), color = tint, position = UDim2.fromScale(0.5, 0.26) })
		local body = Instance.new("Frame", frame)
		body.BackgroundTransparency = 1
		body.BorderSizePixel = 0
		body.AnchorPoint = Vector2.new(0.5, 0)
		body.Position = UDim2.fromScale(0.5, 0.34)
		body.Size = UDim2.fromScale(0.5, 0.5)
		Instance.new("UICorner", body).CornerRadius = UDim.new(0, theme.radius.sm)
		local stroke = Instance.new("UIStroke", body)
		stroke.Color = tint
		stroke.Thickness = theme.stroke.hair
		return frame
	end

	function M.sidebarToggle(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconSidebarToggle", "sidebarToggle", tint)
		if custom then return frame end
		local box = Instance.new("Frame", frame)
		box.BackgroundTransparency = 1
		box.BorderSizePixel = 0
		box.AnchorPoint = Vector2.new(0.5, 0.5)
		box.Position = UDim2.fromScale(0.5, 0.5)
		box.Size = UDim2.fromScale(0.76, 0.68)
		Instance.new("UICorner", box).CornerRadius = UDim.new(0, theme.radius.xs + 1)
		local stroke = Instance.new("UIStroke", box)
		stroke.Color = tint
		stroke.Thickness = theme.stroke.hair
		bar(box, {
			size = UDim2.new(0, 1, 1, 0),
			position = UDim2.fromScale(0.38, 0.5),
			color = tint,
			radius = 0,
		})
		return frame
	end

	function M.search(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconSearch", "search", tint)
		if custom then return frame end
		local glass = Instance.new("Frame", frame)
		glass.BackgroundTransparency = 1
		glass.BorderSizePixel = 0
		glass.AnchorPoint = Vector2.new(0.5, 0.5)
		glass.Position = UDim2.fromScale(0.42, 0.42)
		glass.Size = UDim2.fromScale(0.46, 0.46)
		Instance.new("UICorner", glass).CornerRadius = UDim.new(1, 0)
		local stroke = Instance.new("UIStroke", glass)
		stroke.Color = tint
		stroke.Thickness = theme.stroke.hair
		bar(frame, {
			size = UDim2.fromScale(0.32, WEIGHT * 0.9),
			rotation = 45,
			color = tint,
			position = UDim2.fromScale(0.68, 0.68),
		})
		return frame
	end

	function M.arrowLeft(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconArrowLeft", "arrowLeft", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.56, WEIGHT), color = tint, position = UDim2.fromScale(0.52, 0.5) })
		bar(frame, { size = UDim2.fromScale(0.32, WEIGHT), rotation = 45, color = tint, position = UDim2.fromScale(0.35, 0.38) })
		bar(frame, { size = UDim2.fromScale(0.32, WEIGHT), rotation = -45, color = tint, position = UDim2.fromScale(0.35, 0.62) })
		return frame
	end

	function M.arrowRight(parent, size, colour)
		local tint = colour or theme.color.textSecondary
		local frame, custom = customOrHolder(parent, size, "IconArrowRight", "arrowRight", tint)
		if custom then return frame end
		bar(frame, { size = UDim2.fromScale(0.56, WEIGHT), color = tint, position = UDim2.fromScale(0.48, 0.5) })
		bar(frame, { size = UDim2.fromScale(0.32, WEIGHT), rotation = -45, color = tint, position = UDim2.fromScale(0.65, 0.38) })
		bar(frame, { size = UDim2.fromScale(0.32, WEIGHT), rotation = 45, color = tint, position = UDim2.fromScale(0.65, 0.62) })
