	-- A dialog: a large fixed surface with two panes and its own scrim.
	--
	-- Not a modal. `M.modal` is a narrow auto-height card built around a title and a
	-- footer, which is right for a confirmation and wrong for a settings window -- the
	-- one the settings dialog used to build by hand had no scrim dismissal and was not
	-- registered here, so Escape did nothing and clicking beside it did nothing.
	function M.dialog(props)
		props = props or {}
		if not ensure() then return nil end

		local margin = theme.space.lg * 2
		local width = math.min(props.width or theme.size.dialog, responsive.viewport.X - margin)
		local height = math.min(props.height or theme.size.dialogTall,
			responsive.viewport.Y - margin - responsive.inset.Y)

		local scrim = P.frame(M.layer, {
			name = "Scrim",
			size = UDim2.fromScale(1, 1),
			bg = theme.color.scrim,
			bgTransparency = 1,
			zIndex = theme.z.modal,
		})
		scrim.Active = true

		local dismiss = Instance.new("TextButton", scrim)
		dismiss.Name = "Dismiss"
		dismiss.Text = ""
		dismiss.BackgroundTransparency = 1
		dismiss.Size = UDim2.fromScale(1, 1)
		dismiss.AutoButtonColor = false
		dismiss.ZIndex = theme.z.modal

		local card = P.frame(scrim, {
			name = props.name or "Dialog",
			size = UDim2.fromOffset(width, height),
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.5),
			bg = theme.color.surface,
			radius = theme.radius.xl,
			zIndex = theme.z.modal + 1,
			clip = true,
		})
		card.Active = true
		P.stroke(card, theme.color.border)
		local scale = Instance.new("UIScale", card)
		scale.Scale = theme.scale.enter

		local handle = { card = card, scrim = scrim, closed = false, width = width, height = height }

		function handle.close()
			if handle.closed then return end
			handle.closed = true
			for index, item in ipairs(M.open) do
				if item == handle then table.remove(M.open, index) end
			end
			env.tween:Create(scale, theme.tween("exit"), { Scale = theme.scale.enter }):Play()
			local out = env.tween:Create(scrim, theme.tween("exit"), { BackgroundTransparency = 1 })
			out.Completed:Connect(function() pcall(function() scrim:Destroy() end) end)
			out:Play()
			if props.onClose then pcall(props.onClose) end
		end

		dismiss.Activated:Connect(handle.close)

		local closeDiameter = math.max(theme.size.control, responsive.minTarget())
		local close = P.iconButton(card, {
			name = "DialogClose",
			icon = "close",
			diameter = theme.size.control,
			anchor = Vector2.new(1, 0),
			position = UDim2.new(1, -theme.space.sm, 0, theme.space.sm),
			zIndex = theme.z.modal + 4,
			onClick = handle.close,
		})
		close.instance.ZIndex = theme.z.modal + 4
		-- How much of the card's top-right corner the close button owns.
		--
		-- It is absolutely positioned over whatever the caller fills the card with, and
		-- the dialog has no title bar to keep it out of, so a caller that starts its
		-- content at the top edge draws under it -- which on a narrow layout put the
		-- button on top of the last category row and made it unreachable. Published
		-- rather than left for each caller to re-derive from two tokens.
		handle.closeInset = closeDiameter + theme.space.sm * 2

		M.open[#M.open + 1] = handle
		env.tween:Create(scrim, theme.tween("enter"), { BackgroundTransparency = theme.opacity.scrim }):Play()
		local grow = env.tween:Create(scale, theme.tween("enter"), { Scale = 1 })
		grow.Completed:Connect(function()
			if not handle.closed then scale.Scale = 1 end
		end)
		grow:Play()
		return handle
	end

	-- Anchored menu ----------------------------------------------------------

	-- Opens below the target, or above it when there is not enough room. Options are
	-- { label, value, detail, selected, tone }.
	function M.menu(props)
		props = props or {}
		if not ensure() then return nil end
		local target = props.target
		if not target then return nil end

		local scrim = P.frame(M.layer, {
			name = "MenuLayer",
			size = UDim2.fromScale(1, 1),
			zIndex = theme.z.dropdown,
		})
		local dismiss = Instance.new("TextButton", scrim)
		dismiss.Text = ""
		dismiss.BackgroundTransparency = 1
		dismiss.Size = UDim2.fromScale(1, 1)
		dismiss.AutoButtonColor = false

		local width = math.max(props.width or target.AbsoluteSize.X, theme.size.menuMin)

		-- The row height is derived from what the rows actually contain, not from a
		-- control token. An option with a detail line stacks a `small` label over a
		-- `caption` one, and the two together outgrow theme.size.row -- which is how
		-- every menu in the app ended up with its detail text overlapping the label of
		-- the row beneath it.
		local hasDetail = false
		for _, option in ipairs(props.options or {}) do
			if option.detail then hasDetail = true end
		end
		local content = theme.text.small.height + theme.space.xxs
		if hasDetail then content = content + theme.text.caption.height + theme.space.hair end
		local rowHeight = math.max(theme.size.row, responsive.minTarget(), content + theme.space.xs)

		-- Measured rather than counted: a divider is one pixel and a header is its own
		-- height, and treating both as a full row made the profile menu tall enough to
		-- scroll when everything in it already fitted.
		local headerHeight = theme.text.bodyStrong.height + theme.text.caption.height + theme.space.sm
		local bodyHeight = theme.space.xs * 2
		for _, option in ipairs(props.options or {}) do
			if option.divider then
				bodyHeight = bodyHeight + 1 + theme.space.hair
			elseif option.isHeader then
				bodyHeight = bodyHeight + headerHeight + theme.space.hair
			else
				bodyHeight = bodyHeight + rowHeight + theme.space.hair
			end
		end
		bodyHeight = math.min(bodyHeight, theme.size.menuMax)

		local layerOrigin = M.layer.AbsolutePosition
		local layerSize = M.layer.AbsoluteSize
		local targetX = target.AbsolutePosition.X - layerOrigin.X
		local targetY = target.AbsolutePosition.Y - layerOrigin.Y
		local below = targetY + target.AbsoluteSize.Y + theme.space.xxs

		local topLimit = theme.space.xs
		local bottomObstruction = responsive.bottomObstruction()
		local bottomLimit = math.max(topLimit + 60, layerSize.Y - bottomObstruction - theme.space.xs)

		local spaceBelow = math.max(0, bottomLimit - below)
		local spaceAbove = math.max(0, targetY - theme.space.xxs - topLimit)

		-- Only flip upward if it cannot fit below AND there is strictly more room above than below.
		local flip = (spaceBelow < bodyHeight) and (spaceAbove > spaceBelow)

		local anchorY
		if flip then
			local maxH = math.max(120, spaceAbove)
			bodyHeight = math.min(bodyHeight, maxH)
			anchorY = targetY - theme.space.xxs - bodyHeight
		else
			local maxH = math.max(120, spaceBelow)
			bodyHeight = math.min(bodyHeight, maxH)
			anchorY = below
		end

		anchorY = util.clamp(anchorY, topLimit, math.max(topLimit, bottomLimit - bodyHeight))
		local maxWidth = math.max(theme.size.menuMin, layerSize.X - theme.space.sm * 2)
		width = math.min(width, maxWidth)
		local anchorX = util.clamp(targetX, theme.space.sm, math.max(theme.space.sm, layerSize.X - width - theme.space.sm))

		local card = P.frame(scrim, {
			name = "Menu",
			size = UDim2.fromOffset(width, bodyHeight),
			position = UDim2.fromOffset(anchorX, anchorY),
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			zIndex = theme.z.dropdown + 1,
			clip = true,
		})
		P.stroke(card, theme.color.border)

		local handle = { closed = false }

		function handle.close()
			if handle.closed then return end
			handle.closed = true
			for index, item in ipairs(M.open) do
				if item == handle then table.remove(M.open, index) end
			end
			pcall(function() scrim:Destroy() end)
			if props.onClose then pcall(props.onClose) end
		end

		dismiss.Activated:Connect(handle.close)

		local list = P.scroll(card, {
			name = "Options",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.hair,
			padding = theme.space.xs,
			zIndex = theme.z.dropdown + 2,
		})

		for index, option in ipairs(props.options or {}) do
			if option.divider then
				local div = P.divider(list.instance, {
					color = theme.color.borderSubtle,
					layoutOrder = index,
				})
				div.Size = UDim2.new(1, 0, 0, 1)
			elseif option.isHeader then
				-- The height the menu already reserved for it, sixty lines up. This was a
				-- literal 36 against 46 pixels of content, so every menu with a header --
				-- the profile menu, the conversation menu -- drew its subtitle ten pixels
				-- into the first option below it, while the menu as a whole still reserved
				-- the correct 48 and left the difference floating at the bottom.
				local headRow = P.column(list.instance, {
					size = UDim2.new(1, 0, 0, headerHeight),
					padding = { x = theme.space.sm, top = theme.space.xs },
					gap = 0,
					layoutOrder = index,
				})
				local title = P.text(headRow, {
					text = tostring(option.title or ""),
					role = "bodyStrong",
					color = theme.color.text,
					auto = "X",
					layoutOrder = 1,
				})
				title.Size = UDim2.fromOffset(0, theme.text.bodyStrong.height)
				if option.subtitle then
					local sub = P.text(headRow, {
						text = tostring(option.subtitle or ""),
						role = "caption",
						color = theme.color.textTertiary,
						auto = "X",
						layoutOrder = 2,
					})
					sub.Size = UDim2.fromOffset(0, theme.text.caption.height)
				end
			else
				local button = Instance.new("TextButton", list.instance)
				-- Named after the value it carries. A menu is where most of this
				-- interface's actions actually live, so an unnamed row is an action
				-- nothing outside the click handler can reach -- including a test.
				button.Name = "Option_" .. tostring(option.value ~= nil and option.value or option.label)
				button.Text = ""
				button.AutoButtonColor = false
				button.BackgroundColor3 = option.selected and theme.color.surfaceActive or theme.color.surfaceOverlay
				button.BackgroundTransparency = option.selected and 0 or 1
				button.BorderSizePixel = 0
				button.Size = UDim2.new(1, 0, 0, rowHeight)
				button.LayoutOrder = index
				button.Selectable = true
				P.corner(button, theme.radius.sm)

				local row = P.row(button, {
					size = UDim2.fromScale(1, 1),
					gap = theme.space.xs,
					padding = { x = theme.space.sm },
				})

				if option.icon then
					local iconHolder = P.frame(row, {
						size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
						layoutOrder = 1,
					})
					icons.draw(option.icon, iconHolder, theme.size.icon, theme.color.textSecondary)
				end

				local labelColumn = P.column(row, {
					size = UDim2.new(0, 0, 1, 0),
					flex = "Fill",
					gap = 0,
					alignY = "Center",
					layoutOrder = 2,
				})
				P.text(labelColumn, {
					text = tostring(option.label or option.value or ""),
					role = "small",
					color = option.tone and theme.toneColor(option.tone) or theme.color.text,
					truncate = true,
				})
				if option.detail then
					P.text(labelColumn, {
						text = option.detail,
						role = "caption",
						color = theme.color.textTertiary,
						truncate = true,
					})
				end

				if option.shortcut then
					local scLabel = P.text(row, {
						text = tostring(option.shortcut),
						role = "caption",
						color = theme.color.textTertiary,
						auto = "X",
						layoutOrder = 3,
					})
					scLabel.Size = UDim2.fromOffset(0, theme.text.caption.height)
				elseif option.chevron then
					local chSlot = P.frame(row, {
						size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
						layoutOrder = 3,
					})
					icons.chevron(chSlot, theme.size.icon, theme.color.textTertiary, "right")
				elseif option.selected then
					local mark = P.frame(row, {
						size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
						layoutOrder = 3,
					})
					icons.check(mark, theme.size.icon, theme.color.accent)
				end

				button.MouseEnter:Connect(function()
					if not option.selected then
						env.tween:Create(button, theme.tween("hover"), {
							BackgroundTransparency = 0, BackgroundColor3 = theme.color.surfaceHover,
						}):Play()
					end
				end)
				button.MouseLeave:Connect(function()
					if not option.selected then
						env.tween:Create(button, theme.tween("hover"), { BackgroundTransparency = 1 }):Play()
					end
				end)
				button.Activated:Connect(function()
					handle.close()
					if props.onSelect then pcall(props.onSelect, option.value ~= nil and option.value or option.label, option) end
				end)
			end
		end

		M.open[#M.open + 1] = handle
		return handle
	end

	function M.closeAll()
		for index = #M.open, 1, -1 do
			local item = M.open[index]
			if item and item.close then item.close() end
		end
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/agents
-- ==========================================================================
__UAI_MODULES["ui/panels/agents"] = (function()
-- Subagents: what has been delegated, what is still running, and the ceilings.
--
-- A dispatch is the longest-lived and least visible thing this client does. It runs
-- for minutes on its own context, calls its own tools, and the only trace of it was a
-- card in one conversation's transcript -- which scrolls away, belongs to whichever
-- conversation started it, and offered no way to stop one child without stopping the
-- whole turn. Three subagents working at once were three spinners in three places.
--
-- So this panel is the register: every dispatch in this session, running ones first,
-- with what it was asked to do, where it came from, what it has called, and a stop for
-- each. Nothing here is computed for display -- it is `agent/subagent`'s own record.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local subagent = env.require("agent/subagent")
	local registry = env.require("agent/registry")

	local M = {}

	local STATUS = {
		queued = { label = "waiting for a slot", colour = "warn" },
		running = { label = "working", colour = "accent" },
		done = { label = "reported back", colour = "success" },
		stopped = { label = "stopped", colour = "warn" },
		failed = { label = "failed", colour = "danger" },
	}

	local function isLive(record)
		return record.status == "running" or record.status == "queued"
	end

	-- What a preset actually grants, in the group names the Tools panel uses. `full` is
	-- the absence of a filter rather than a list, which is worth saying in those words:
	-- it is the one preset that can change the game.
	local function describePreset(id)
		local groups = subagent.PRESETS[id]
		if groups == nil then return "every tool this client has" end
		local names = {}
		for group in pairs(groups) do names[#names + 1] = registry.groupLabel(group) end
		table.sort(names)
		return table.concat(names, ", ")
	end

	function M.new(parent)
		local panel = {}

		local scroll = P.scroll(parent, {
			name = "Agents",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.md,
			padding = theme.space.md,
		})

		P.sectionHeader(scroll.instance, {
			title = "Subagents",
			description = "The agent hands self-contained work to a subagent with dispatch_agent: "
				.. "its own context, a subset of the tools, and a written report at the end. "
				.. "Everything dispatched in this session is here, whichever conversation started it.",
			layoutOrder = 1,
		})

		-- Capacity ------------------------------------------------------------

		local capacityCard = P.card(scroll.instance, { layoutOrder = 2, gap = theme.space.sm })
		local capacityRow = P.row(capacityCard, {
			name = "Capacity",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		local capacityText = P.text(capacityRow, {
			name = "CapacityText",
			text = "",
			role = "small",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			size = UDim2.new(0, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 1,
		})
		local stopAll = P.button(capacityRow, {
			name = "StopAll",
			text = "Stop all",
			variant = "danger",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				local stopped = subagent.stopAll()
				overlay.toast(stopped == 0 and "Nothing was running"
					or ("Stopping " .. util.pluralise(stopped, "subagent")), "info", 2)
			end,
		})
		stopAll.instance.LayoutOrder = 2
		local capacityBar = C.progress(capacityCard, { value = 0, layoutOrder = 2 })
		local capacityHint = P.text(capacityCard, {
			name = "CapacityHint",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 3,
		})

		-- The register --------------------------------------------------------

		local list = P.column(scroll.instance, {
			name = "Dispatches",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 3,
		})

		-- Declared here, defined with the card it draws into. The redraw covers both,
		-- and the card is built below the list it sits under.
		local renderLimits = function() end

		local function reportModal(record)
			local modal = overlay.modal({
				title = record.label,
				description = string.format("%s  \194\183  %s  \194\183  %s%s",
					(STATUS[record.status] or STATUS.done).label,
					record.ms and util.formatDuration(record.ms) or "",
					util.pluralise(record.calls or 0, "tool call"),
					(record.runs or 1) > 1
						and ("  \194\183  " .. util.pluralise(record.runs, "turn")) or ""),
				width = theme.size.modalWide,
			})
			if not modal then return end
			-- The id, because it is the handle the agent addresses a follow-up to. Reading
			-- it here is how you can tell from the transcript which dispatch a follow-up
			-- went to when three of them are open.
			C.keyValue(modal.content, {
				key = "Id",
				value = tostring(record.id),
				role = "monoSmall",
				layoutOrder = 1,
			})
			C.keyValue(modal.content, { key = "Task", value = record.task, layoutOrder = 2 })
			C.keyValue(modal.content, {
				key = "Tools",
				value = describePreset(record.preset),
				layoutOrder = 3,
			})
			if #(record.tools or {}) > 0 then
				C.keyValue(modal.content, {
					key = "Called",
					value = table.concat(record.tools, ", "),
					role = "monoSmall",
					layoutOrder = 4,
				})
			end
			C.keyValue(modal.content, {
				key = "Report",
				value = util.trim(tostring(record.report or "")) ~= "" and record.report
					or "Nothing was reported.",
				layoutOrder = 5,
			})
			P.button(modal.footer, {
				text = "Close",
				variant = "primary",
				size = "sm",
				layoutOrder = 1,
				onClick = function() modal.close() end,
			})
		end

		local function renderRecord(record, order)
			local live = isLive(record)
			local status = STATUS[record.status] or STATUS.done
			local card = P.card(list, { layoutOrder = order, gap = theme.space.xs })

			local head = P.row(card, {
				name = "Head",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = 1,
			})
			if live then
				C.spinner(head, { diameter = theme.size.icon, layoutOrder = 1 })
			else
				local slot = P.frame(head, {
					name = "DotSlot",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				P.statusDot(slot, {
					diameter = theme.size.dot,
					color = theme.color[status.colour],
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
			end
			P.text(head, {
				name = "Label",
				text = record.label,
				role = "small",
				color = theme.color.text,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.small.height),
				flex = "Fill",
				layoutOrder = 2,
			})
			local elapsed = record.ms or clock.since(record.startedAt or clock.ms())
			P.text(head, {
				name = "Elapsed",
				text = elapsed >= 1000 and util.formatDuration(elapsed) or "",
				role = "caption",
				color = theme.color.textTertiary,
				align = "Right",
				size = UDim2.fromOffset(theme.size.metaColumn, theme.text.small.height),
				layoutOrder = 3,
			})

			-- One line of provenance. Which conversation asked, how deep it sits, and
			-- what it is allowed to touch: none of that is on the transcript card, and
			-- all three decide whether a dispatch is worth stopping.
			local facts = {
				record.stopping and "stopping" or status.label,
				record.preset .. " tools",
			}
			if (record.depth or 1) > 1 then
				facts[#facts + 1] = "depth " .. tostring(record.depth)
			end
			if record.parentTitle then facts[#facts + 1] = "from " .. record.parentTitle end
			if record.unlimited then facts[#facts + 1] = "unlimited" end
			if (record.runs or 1) > 1 then
				facts[#facts + 1] = util.pluralise(record.runs, "turn")
			end
			if (record.calls or 0) > 0 then
				facts[#facts + 1] = string.format("%d of %s",
					record.finishedCalls or 0, util.pluralise(record.calls, "call"))
			end
			if record.messages then
				facts[#facts + 1] = util.pluralise(record.messages, "message")
			end
			-- Whether the agent can still talk to this one. A finished dispatch keeps its
			-- context for a while, and a follow-up into it is the cheapest thing here --
			-- so which ones are still open is worth a word.
			if not live and record.session then
				facts[#facts + 1] = "open for a follow-up"
			end
			local detail = P.text(card, {
				name = "Facts",
				text = table.concat(facts, "  \194\183  "),
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			detail.TextColor3 = live and theme.color.textSecondary or theme.color.textTertiary

			-- What it is doing now, or what it said at the end.
			local note = live and (record.currentTool
					and ("running " .. record.currentTool)
					or record.statusText)
				or util.trim(tostring(record.report or ""))
			if note and util.trim(note) ~= "" then
				P.text(card, {
					name = "Note",
					text = util.ellipsis(tostring(note):gsub("%s+", " "), 220),
					role = live and "caption" or "small",
					color = record.status == "failed" and theme.color.danger
						or theme.color.textSecondary,
					wrap = true,
					auto = "Y",
					layoutOrder = 3,
				})
			end

			local actions = P.row(card, {
				name = "Actions",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = 4,
			})
			P.spacer(actions, { grow = true, layoutOrder = 1 })
			P.button(actions, {
				name = "Open",
				text = "Details",
				variant = "ghost",
				size = "sm",
				layoutOrder = 2,
				onClick = function() reportModal(record) end,
			})
			if live then
				P.button(actions, {
					name = "Stop",
					text = record.stopping and "Stopping" or "Stop",
					variant = "danger",
					size = "sm",
					layoutOrder = 3,
					onClick = function()
						if subagent.stop(record.id) then
							-- It stops between steps, not on the instant: saying so is the
							-- difference between a slow control and a broken one.
							overlay.toast("Asked it to stop. It finishes the step it is on.",
								"info", 3)
						end
					end,
				})
			end
			return card
		end

		local function render()
			for _, child in ipairs(list:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			renderLimits()

			local records = subagent.list()
			local running = #subagent.running()
			local ceiling = subagent.concurrencyLimit()

			capacityText.Text = running == 0
				and "Nothing is delegated right now."
				or string.format("%d of %d slots in use", running, ceiling)
			capacityBar.set(ceiling > 0 and (running / ceiling) or 0)
			if subagent.unlimited() then
				capacityHint.Text = string.format(
					"Subagents run unlimited: no step limit, no clock, and the call that dispatched one "
					.. "waits as long as it takes. Anything over the ceiling waits for a slot; a subagent "
					.. "may dispatch its own up to %s deep. Stop is the bound that still applies.",
					util.pluralise(tonumber(config.get("agent.subagentDepth", 2)) or 2, "level"))
			else
				capacityHint.Text = string.format(
					"Each one may work for %s and take up to %s. Anything over the ceiling waits for a slot; "
					.. "a subagent may dispatch its own up to %s deep.",
					util.formatDuration(subagent.budgetSeconds() * 1000),
					util.pluralise(tonumber(config.get("agent.subagentTurns", 14)) or 14, "step"),
					util.pluralise(tonumber(config.get("agent.subagentDepth", 2)) or 2, "level"))
			end
			stopAll.instance.Visible = running > 0

			if #records == 0 then
				C.emptyState(list, {
					title = "No subagents yet",
					description = "When the agent delegates -- a wide search, a sweep of the instance "
						.. "tree, anything repetitive -- the dispatch shows up here while it works "
						.. "and stays afterwards with its report.",
					layoutOrder = 1,
				})
				return
			end

			for index, record in ipairs(records) do
				renderRecord(record, index)
			end
		end

		-- Limits --------------------------------------------------------------

		-- Stated here, changed in Settings. Both surfaces read the same four keys, and a
		-- slider is built with the value it had at build time -- so a second set of
		-- sliders here would sit next to the first and be able to disagree with it. The
		-- facts are redrawn with the list, so what this says is always what is in force.
		local limits = P.card(scroll.instance, { layoutOrder = 4, gap = theme.space.sm })
		P.text(limits, {
			name = "LimitsTitle",
			text = "Limits",
			role = "label",
			color = theme.color.textSecondary,
			layoutOrder = 1,
		})
		local limitFacts = P.column(limits, {
			name = "LimitFacts",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
			layoutOrder = 2,
		})
		P.button(limits, {
			name = "OpenAgentSettings",
			text = "Change these",
			variant = "secondary",
			size = "sm",
			layoutOrder = 3,
			onClick = function()
				env.require("ui/app").showSettingsDialog("agent")
			end,
		})

		local function renderLimitsInto()
			for _, child in ipairs(limitFacts:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			-- The button's own layout order is stated above; a P.card is a column, so the
			-- facts sit between the title and it.
			local unlimited = subagent.unlimited()
			local rows = {
				{
					key = "Budget",
					value = unlimited
						and "no clock -- a subagent runs until it answers, and the call that started it waits"
						or (util.formatDuration(subagent.budgetSeconds() * 1000)
							.. " of work each, then it wraps up"),
				},
				{
					key = "At once",
					value = util.pluralise(subagent.concurrencyLimit(), "subagent")
						.. " across the whole tree; the rest wait for a slot",
				},
				{
					key = "Steps",
					value = unlimited
						and "no limit -- only the repeat breaker and Stop end a run"
						or (util.pluralise(tonumber(config.get("agent.subagentTurns", 14)) or 14, "tool round")
							.. " before it has to answer with what it has"),
				},
				{
					key = "Depth",
					value = (function()
						local depth = tonumber(config.get("agent.subagentDepth", 2)) or 2
						if depth <= 0 then
							return "delegation is off -- the agent does the work in the conversation"
						end
						return util.pluralise(depth, "level") .. " of delegation"
					end)(),
				},
				{
					key = "Follow-ups",
					value = "the agent can send a finished subagent another message with agent_followup; "
						.. "the newest few keep their context for it",
				},
			}
			for index, row in ipairs(rows) do
				C.keyValue(limitFacts, {
					key = row.key,
					value = row.value,
					color = theme.color.textSecondary,
					layoutOrder = index,
				})
			end
		end

		-- Now that the card exists, the forward declaration points at the real one.
		renderLimits = renderLimitsInto

		-- Presets -------------------------------------------------------------

		local presets = P.card(scroll.instance, { layoutOrder = 5, gap = theme.space.xs })
		P.text(presets, {
			name = "PresetsTitle",
			text = "What a subagent is given",
			role = "label",
			color = theme.color.textSecondary,
			layoutOrder = 1,
		})
		P.text(presets, {
			name = "PresetsHint",
			text = "The model picks one of these per dispatch. 'read' is the default and cannot "
				.. "change anything; a delegated write is hard to attribute afterwards, which is "
				.. "why it has to be asked for.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		local presetOrder = { "read", "web", "game", "full" }
		for index, id in ipairs(presetOrder) do
			C.keyValue(presets, {
				key = id,
				value = describePreset(id),
				color = id == "full" and theme.color.warn or theme.color.textSecondary,
				layoutOrder = index + 2,
			})
		end

		render()

		-- Live. The register changes on every tool call a child makes, so the redraw is
		-- debounced rather than throttled: a leading-edge throttle drops the last change
		-- in a burst, and the last change is the one that says it finished -- the panel
		-- kept a record on screen as running after it had reported back. The clock on a
		-- running card needs a tick of its own, and stops costing anything once nothing
		-- is running.
		local redraw = clock.debounce(function()
			if not scroll.instance.Parent then return end
			render()
		end, 0.2)
		local unsubscribe = subagent.changed:connect(redraw)
		local stop = clock.interval(0.5, function()
			if not scroll.instance.Parent then return end
			if #subagent.running() == 0 then return end
			render()
		end)
		scroll.instance.Destroying:Connect(function()
			pcall(unsubscribe)
			pcall(stop)
		end)

		panel.scroll = scroll
		panel.render = render
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/cowork
-- ==========================================================================
__UAI_MODULES["ui/panels/cowork"] = (function()
-- Cowork: the browser-shared conversation.
--
-- The mode switch in the sidebar offers "Cowork" beside "Code", and in the client
-- this is modelled on that means real-time pairing. There is exactly one thing here
-- that genuinely is two people in one conversation -- the local web bridge -- so that
-- is what this panel is: its live state, its switch, and the two values it needs.
--
-- A Roblox client cannot accept a connection, so both sides dial out to a small
-- process on the same machine. That is why this panel is mostly about whether that
-- process is reachable, and why it says so in those words rather than showing a
-- spinner.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local bridge = env.require("net/bridge")
	local sessions = env.require("agent/session")

	local M = {}

	function M.new(parent)
		local panel = {}
		local scroll = P.scroll(parent, {
			name = "Cowork",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.md,
			padding = theme.space.md,
		})

		P.sectionHeader(scroll.instance, {
			title = "Cowork",
			description = "Share this conversation with a browser on the same machine. "
				.. "Run bridge/server.js, paste the token it prints, and whoever opens the page "
				.. "joins the conversation that is already open here -- a turn begun in one place "
				.. "continues in the other, and a permission prompt can be answered from either.",
			layoutOrder = 1,
		})

		M.rows(scroll.instance, { layoutOrder = 2 })

		panel.scroll = scroll
		return panel
	end

	-- The live state and the two values it needs, as cards a caller drops into its own
	-- column. Both the Cowork panel and the settings dialog's Cowork pane use this, so
	-- there is one description of the bridge rather than two that can disagree.
	function M.rows(container, props)
		props = props or {}
		local order = (props.layoutOrder or 1) - 1
		local function nextOrder()
			order = order + 1
			return order
		end

		local statusCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })

		local statusRow = P.row(statusCard, {
			name = "Status",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		local dot = P.statusDot(statusRow, {
			diameter = theme.size.dot,
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		local statusText = P.text(statusRow, {
			name = "StatusText",
			text = "",
			role = "small",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			size = UDim2.new(0, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 2,
		})

		local detail = P.text(statusCard, {
			name = "StatusDetail",
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		detail.Size = UDim2.new(1, 0, 0, 0)

		-- Everything on this row is a fact about the running bridge rather than a
		-- control, which is why it is text and not a badge: three of the four values are
		-- only interesting when something is wrong.
		local function describe()
			local status = bridge.status()
			local shared = sessions.current()
			if not status.running then
				dot.BackgroundColor3 = theme.color.textTertiary
				statusText.Text = "Off. Nothing is listening and nothing is being polled."
				detail.Text = string.format("%s\nwould share: %s", status.url, shared.title)
				return
			end
			if status.online then
				dot.BackgroundColor3 = theme.color.success
				statusText.Text = "Connected. Open the link the bridge printed in a browser."
				detail.Text = string.format("%s\nsharing: %s\nqueued: %d", status.url, shared.title, status.queued or 0)
				return
			end
			dot.BackgroundColor3 = theme.color.warn
			statusText.Text = "Polling, but nothing answered yet. Is bridge/server.js running?"
			detail.Text = string.format("%s\n%s", status.url, tostring(status.error or "no answer yet"))
		end

		local switchRow = P.row(statusCard, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 3,
		})
		local switchText = P.column(switchRow, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(switchText, { text = "Enabled", role = "small" })
		P.text(switchText, {
			text = "Off until you turn it on: it is a second way in to an agent that can run code.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local toggle = C.switch(switchRow, {
			value = config.get("bridge.enabled", false) == true,
			onChange = function(value) config.set("bridge.enabled", value) end,
		})
		toggle.instance.LayoutOrder = 2

		if not caps.has("http") then
			local warning = P.text(statusCard, {
				text = "This host has no HTTP transport, so the bridge cannot be reached from here at all.",
				role = "caption",
				color = theme.color.warn,
				wrap = true,
				auto = "Y",
				layoutOrder = 4,
			})
			warning.Size = UDim2.new(1, 0, 0, 0)
		end

		-- Every row in here states its order.
		--
		-- All six were LayoutOrder 0, so the label above the port field, the field, the
		-- label above the token field, that field, the hint and the button row were sorted
		-- by whatever the tie-break happened to produce -- which is a card whose two
		-- labels can end up over the wrong two fields.
		local settings = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
		P.text(settings, { text = "Port", role = "small", layoutOrder = 1 })
		P.field(settings, {
			name = "BridgePort",
			text = tostring(config.get("bridge.port", 8790)),
			placeholder = "8790",
			layoutOrder = 2,
			onBlur = function(text)
				local port = tonumber(util.trim(text))
				config.set("bridge.port", (port and port > 0 and port < 65536) and math.floor(port) or 8790)
			end,
		})
		P.text(settings, { text = "Token", role = "small", layoutOrder = 3 })
		P.field(settings, {
			name = "BridgeToken",
			text = tostring(config.get("bridge.token", "")),
			placeholder = "paste from the bridge console",
			layoutOrder = 4,
			onBlur = function(text) config.set("bridge.token", util.trim(text)) end,
		})
		local tokenHint = P.text(settings, {
			text = "The token is regenerated every time bridge/server.js starts, so a stale one left here grants nothing.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 5,
		})
		tokenHint.Size = UDim2.new(1, 0, 0, 0)

		local buttons = P.row(settings, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 6,
		})
		if caps.clipboard then
			P.button(buttons, {
				name = "CopyBridgeUrl",
				text = "Copy address",
				variant = "secondary",
				size = "sm",
				layoutOrder = 1,
				onClick = function()
					local ok = pcall(caps.fn.clipboard, bridge.status().url)
					overlay.toast(ok and "Address copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				end,
			})
		end
		P.button(buttons, {
			name = "Reconnect",
			text = "Reconnect",
			variant = "ghost",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				-- Stop then sync: the poller backs off up to ten seconds between
				-- attempts, and after starting the server on the other side nobody wants
				-- to wait out the backoff.
				bridge.stop()
				local ok, why = bridge.sync()
				if not ok and why then overlay.toast(tostring(why), "warn", 3) end
				describe()
			end,
		})

		describe()
		local unsubscribeBridge = bridge.changed:connect(function()
			if not statusCard.Parent then return end
			describe()
		end)
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not statusCard.Parent then return end
			describe()
		end)
		statusCard.Destroying:Connect(function()
			pcall(unsubscribeBridge)
			pcall(unsubscribeSessions)
		end)

		return statusCard
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/home
-- ==========================================================================
__UAI_MODULES["ui/panels/home"] = (function()
-- The home card: the greeting, the activity summary and the contribution grid.
--
-- Every number on this surface is read from agent/stats, which counts what the
-- client actually observed. There are no placeholders here and no sample data: a
-- figure with nothing behind it is rendered as a zero and the card says why, because
-- an invented number on a dashboard is worse than an empty one -- it cannot be told
-- from a real one.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local stats = env.require("agent/stats")

	local M = {}

	-- How much of the grid fits. Twenty-six weeks is six months and is what the card
	-- is designed around, but a cell is a fixed eleven pixels and the card is only as
	-- wide as the window: at 340 the full grid is seventy pixels wider than the space
	-- it has, and a grid that overflows is clipped rather than scaled.
	local function heatmapWeeks()
		if responsive.mode == "sheet" then return 13 end
		if responsive.mode == "panel" then return 18 end
		return 26
	end

	-- Four tiles to a row on anything with room, two on a phone. Eight tiles of a
	-- quarter width each on a 276px card leaves 53px for "Longest streak".
	local function tilesPerRow()
		if responsive.mode == "sheet" then return 2 end
		return 4
	end

	local function levelColour(level)
		if level >= 4 then return theme.color.activityBlueDark end
		if level >= 3 then return theme.color.activityBlue end
		if level >= 2 then return theme.color.activityBlueLight end
		if level >= 1 then return theme.color.accentMuted end
		return theme.color.activityCell
	end

	-- The four sentences a cell can say, all of them about a real day.
	local function describeCell(cell, todayKey)
		local when = clock.describeDay(cell.key, todayKey)
		if not cell.active then
			return when .. " -- nothing recorded", "info"
		end
		local parts = {}
		if cell.messages > 0 then parts[#parts + 1] = util.pluralise(cell.messages, "message") end
		if cell.requests > 0 then parts[#parts + 1] = util.pluralise(cell.requests, "request") end
		if cell.tokens > 0 then parts[#parts + 1] = util.formatCompact(cell.tokens) .. " tokens" end
		return when .. " -- " .. table.concat(parts, ", "), "good"
	end

	-- One metric. The tile shows the short form; the exact figure and what it counts
	-- live in the Usage pane, which is where the click goes.
	local function tile(parent, spec, order, perRow)
		local holder = P.rowButton(parent, {
			name = "Metric_" .. tostring(spec.key),
			vertical = true,
			-- The gap is shared out across the tiles rather than subtracted whole from
			-- each: n children of (W/n - g) plus (n-1) gaps comes to W - g, so the row
			-- stopped a gap short of the well it sits in and the right edge never lined up
			-- with the card above it. The share is (n-1)/n of one gap per tile.
			size = UDim2.new(1 / (perRow or 4),
				-math.floor(theme.space.hair * ((perRow or 4) - 1) / (perRow or 4)),
				0, theme.size.statTile),
			height = theme.size.statTile,
			bg = theme.color.surfaceRaised,
			radius = theme.radius.none,
			gap = theme.space.hair,
			padding = { x = theme.space.sm, y = theme.space.xs },
			alignY = "Center",
			layoutOrder = order,
			onClick = function()
				env.require("ui/app").showSettingsDialog("usage")
			end,
		})
		P.text(holder.row, {
			name = "Title",
			text = spec.label,
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			size = UDim2.new(1, 0, 0, theme.text.caption.height),
			layoutOrder = 1,
		})
		P.text(holder.row, {
			name = "Value",
			text = spec.value,
			role = "title",
			color = spec.tone or theme.color.text,
			truncate = true,
			size = UDim2.new(1, 0, 0, theme.text.title.height),
			layoutOrder = 2,
		})
		return holder
	end

	-- A small pill that is either the selected one or not. Used for both the tab pair
	-- and the range triple, because they are the same control with different contents.
	local function pill(parent, label, selected, order, onClick)
		local handle = P.rowButton(parent, {
			name = "Pill_" .. tostring(label),
			auto = "X",
			height = theme.size.chip,
			size = UDim2.fromOffset(0, theme.size.chip),
			bg = selected and theme.color.surfaceActive or nil,
			radius = theme.radius.sm,
			padding = { x = theme.space.sm },
			selected = selected,
			onClick = onClick,
		})
		P.text(handle.row, {
			text = label,
			role = "caption",
			color = selected and theme.color.text or theme.color.textTertiary,
			auto = "X",
			layoutOrder = 1,
		})
		return handle
	end

	-- The eight figures the overview shows, in the order the reference client puts
	-- them in. Each one names the window it was computed over, because "4 active days"
	-- means something different under All than under 7d.
	local function overviewTiles(window)
		local model = window.topModel
		local modelName = "--"
		if model then modelName = model.id end
		local peak = "--"
		if window.peakHour then peak = clock.describeHour(window.peakHour) end
		return {
			{ key = "sessions", label = "Sessions", value = util.formatNumber(window.sessions) },
			{ key = "messages", label = "Messages", value = util.formatNumber(window.messages) },
			{ key = "tokens", label = "Total tokens", value = util.formatCompact(window.tokens) },
			{ key = "days", label = "Active days", value = util.formatNumber(window.activeDays) },
			{ key = "streak", label = "Current streak", value = tostring(window.currentStreak) .. "d" },
			{ key = "longest", label = "Longest streak", value = tostring(window.longestStreak) .. "d" },
			{ key = "peak", label = "Peak hour", value = peak },
			{ key = "model", label = "Favorite model", value = modelName },
		}
	end

	local function buildOverview(parent, window)
		local box = P.column(parent, {
			name = "MetricsBox",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.hair,
			layoutOrder = 1,
		})
		P.stroke(box, theme.color.borderSubtle)

		local specs = overviewTiles(window)
		local perRow = tilesPerRow()
		local rows = math.ceil(#specs / perRow)
		for rowIndex = 1, rows do
			local row = P.row(box, {
				name = "MetricRow" .. tostring(rowIndex),
				size = UDim2.new(1, 0, 0, theme.size.statTile),
				gap = theme.space.hair,
				layoutOrder = rowIndex,
			})
			for column = 1, perRow do
				local spec = specs[(rowIndex - 1) * perRow + column]
				if spec then tile(row, spec, column, perRow) end
			end
		end
		return box
	end

	local function buildModels(parent, window)
		local box = P.column(parent, {
			name = "ModelsBox",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.hair,
			layoutOrder = 1,
		})
		P.stroke(box, theme.color.borderSubtle)

		if #window.models == 0 then
			local empty = P.text(box, {
				name = "NoModels",
				text = "No requests recorded in this window. A model appears here once it has answered something.",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				padding = { x = theme.space.sm, y = theme.space.sm },
				layoutOrder = 1,
			})
			empty.Size = UDim2.new(1, 0, 0, 0)
			return box
		end

		for index, row in ipairs(window.models) do
			local entry = P.column(box, {
				name = "Model_" .. tostring(index),
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				bg = theme.color.surfaceRaised,
				gap = theme.space.hair,
				padding = { x = theme.space.sm, y = theme.space.xs },
				layoutOrder = index,
			})
			local head = P.row(entry, {
				size = UDim2.new(1, 0, 0, theme.text.small.height),
				gap = theme.space.xs,
				layoutOrder = 1,
			})
			P.text(head, {
				name = "Id",
				text = row.id,
				role = "small",
				color = theme.color.text,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.small.height),
				flex = "Fill",
				layoutOrder = 1,
			})
			P.text(head, {
				name = "Share",
				text = string.format("%d%%", math.floor((row.share or 0) * 100 + 0.5)),
				role = "monoSmall",
				color = theme.color.accent,
				align = "Right",
				auto = "X",
				layoutOrder = 2,
			})

			local track = P.frame(entry, {
				name = "Bar",
				size = UDim2.new(1, 0, 0, theme.size.track),
				bg = theme.color.surfaceActive,
				radius = theme.radius.pill,
				layoutOrder = 2,
			})
			P.frame(track, {
				name = "Fill",
				size = UDim2.fromScale(util.clamp(row.share or 0, 0, 1), 1),
				bg = theme.color.accent,
				radius = theme.radius.pill,
			})

			local facts = { util.formatCompact(row.tokens) .. " tokens",
				util.pluralise(row.requests, "request") }
			local cost = env.require("agent/usage").formatCost(row.cost)
			if cost ~= "" then facts[#facts + 1] = cost end
			local detail = P.text(entry, {
				name = "Detail",
				text = table.concat(facts, "  ") .. (window.estimated and "  (some estimated)" or ""),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(1, 0, 0, theme.text.caption.height),
				layoutOrder = 3,
			})
			detail.Name = "Detail"
		end
		return box
	end

	local function buildHeatmap(parent, order)
		local map = stats.heatmap(heatmapWeeks())
		local todayKey = clock.dayKey()
		local holder = P.column(parent, {
			name = "Heatmap",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.sm,
			gap = theme.space.hair,
			layoutOrder = order,
		})
		P.stroke(holder, theme.color.borderSubtle)

		-- Rows are weekdays and columns are weeks, which is the arrangement that makes
		-- a habit visible: a column is a week of work, a row is "every Tuesday".
		for weekday = 1, 7 do
			local row = P.row(holder, {
				name = "Week_" .. clock.weekdayName(weekday),
				size = UDim2.new(1, 0, 0, theme.size.cell),
				gap = theme.space.hair,
				layoutOrder = weekday,
			})
			for column = 1, #map.columns do
				local cell = map.columns[column][weekday]
				local button = P.rowButton(row, {
					name = "Cell_" .. cell.key,
					size = UDim2.fromOffset(theme.size.cell, theme.size.cell),
					height = theme.size.cell,
					bg = cell.future and theme.color.surfaceOverlay or levelColour(cell.level),
					bgHover = theme.color.solid,
					radius = theme.radius.xs,
					padding = theme.space.none,
					layoutOrder = column,
					onClick = function()
						if cell.future then
							overlay.toast(clock.describeDay(cell.key, todayKey) .. " -- not yet", "info", 2)
							return
						end
						local text, tone = describeCell(cell, todayKey)
						overlay.toast(text, tone, 2.5)
					end,
				})
				-- A cell is eleven pixels square: the hit-target floor would make it a
				-- button the size of the whole row, so this one control opts out and the
				-- grid stays a grid.
				button.instance.Size = UDim2.fromOffset(theme.size.cell, theme.size.cell)
			end
		end
		return holder
	end

	-- The card, and the greeting above it. `order` is the layout order inside whatever
	-- column it is being dropped into -- the transcript, in practice.
	function M.card(parent, order)
		local name = "there"
		local okName, display = pcall(function()
			return env.plr and env.plr.DisplayName
		end)
		if okName and type(display) == "string" and util.trim(display) ~= "" then
			name = display
		elseif env.plr and type(env.plr.Name) == "string" and env.plr.Name ~= "" then
			name = env.plr.Name
		end

		local holder = P.column(parent, {
			name = "Home",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignX = "Center",
			gap = theme.space.xl,
			padding = { y = theme.space.lg },
			layoutOrder = order,
		})

		local greeting = P.row(holder, {
			name = "Greeting",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignX = "Center",
			gap = theme.space.md,
			layoutOrder = 1,
		})
		local sparkSlot = P.frame(greeting, {
			size = UDim2.fromOffset(theme.size.iconLarge, theme.size.iconLarge),
			layoutOrder = 1,
		})
		icons.spark(sparkSlot, theme.size.iconLarge, theme.color.accent)
		P.text(greeting, {
			name = "GreetingText",
			text = string.format("What's up next, %s?", name),
			role = "display",
			color = theme.color.text,
			auto = "XY",
			layoutOrder = 2,
		})

		if config.get("ui.showActivity", true) ~= true then return holder end

		local card = P.column(holder, {
			name = "ActivityCard",
			-- Fills the column up to the card's own width, rather than being a fixed
			-- 560 that overflows a phone.
			size = UDim2.new(1, 0, 0, 0),
			maxSize = Vector2.new(theme.size.statCard, math.huge),
			auto = "Y",
			bg = theme.color.surfaceRaised,
			radius = theme.radius.xl,
			gap = theme.space.md,
			padding = theme.space.lg,
			layoutOrder = 2,
		})
		P.stroke(card, theme.color.borderSubtle)

		local state = {
			tab = "overview",
			range = config.get("ui.activityRange", "all"),
		}
		local body = nil

		local function render()
			if body then pcall(function() body:Destroy() end) end
			body = P.column(card, {
				name = "ActivityBody",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = 2,
			})

			local window = stats.window(state.range)
			if state.tab == "models" then
				buildModels(body, window)
			else
				buildOverview(body, window)
			end
			buildHeatmap(body, 2)

			local footer = stats.comparison(window.tokens)
			if not footer then
				if window.messages == 0 and window.requests == 0 then
					footer = "Nothing recorded in this window yet. Everything here is counted from what this client does, so it fills in as you use it."
				else
					footer = string.format("%s in, %s out across %s.",
						util.formatCompact(window.tokensIn), util.formatCompact(window.tokensOut),
						util.pluralise(window.requests, "request"))
				end
			end
			local note = P.text(body, {
				name = "Comparison",
				text = footer,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 3,
			})
			note.Size = UDim2.new(1, 0, 0, 0)
		end

		local header = P.row(card, {
			name = "CardHeader",
			size = UDim2.new(1, 0, 0, math.max(theme.size.chip, theme.size.controlSmall)),
			gap = theme.space.xs,
			layoutOrder = 1,
		})

		local tabs, ranges = {}, {}

		local function repaint()
			for value, handle in pairs(tabs) do
				handle.setSelected(value == state.tab)
				handle.text.TextColor3 = (value == state.tab) and theme.color.text or theme.color.textTertiary
			end
			for value, handle in pairs(ranges) do
				handle.setSelected(value == state.range)
				handle.text.TextColor3 = (value == state.range) and theme.color.text or theme.color.textTertiary
			end
		end

		local tabRow = P.row(header, {
			name = "Tabs",
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		for index, entry in ipairs({ { value = "overview", label = "Overview" }, { value = "models", label = "Models" } }) do
			local handle = pill(tabRow, entry.label, entry.value == state.tab, index, function()
				state.tab = entry.value
				repaint()
				render()
			end)
			handle.text = handle.row:FindFirstChildOfClass("TextLabel")
			tabs[entry.value] = handle
		end

		P.spacer(header, { grow = true, layoutOrder = 2 })

		local rangeRow = P.row(header, {
			name = "Ranges",
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
			gap = theme.space.hair,
			layoutOrder = 3,
		})
		for index, entry in ipairs(stats.RANGES) do
			local handle = pill(rangeRow, entry.label, entry.value == state.range, index, function()
				state.range = entry.value
				config.set("ui.activityRange", entry.value, { quiet = true })
				repaint()
				render()
			end)
			handle.text = handle.row:FindFirstChildOfClass("TextLabel")
			ranges[entry.value] = handle
		end

		render()
		repaint()

		-- The card is built once per transcript, and a turn that finishes while it is on
		-- screen changes every number on it. Debounced because a turn records a message,
		-- a request and a tool result within the same few frames, and rebuilding the
		-- grid three times for one turn is three times the work for one result.
		local refresh = clock.debounce(function()
			if not card.Parent then return end
			render()
		end, theme.motion.slow)
		local unsubscribe = stats.changed:connect(refresh)
		card.Destroying:Connect(function() pcall(unsubscribe) end)

		return holder
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/logs
-- ==========================================================================
__UAI_MODULES["ui/panels/logs"] = (function()
-- Logs panel: the request history and the application log.
--
-- Two views over the same question -- what did this thing just do -- kept separate
-- because they answer different halves of it. Requests explain a provider failure;
-- the log explains everything else.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local http = env.require("net/http")
	local log = env.require("runtime/log")

	local M = {}

	local LEVEL_TONE = { debug = "info", info = "info", warn = "warn", error = "bad" }

	function M.new(parent)
		local panel = { view = "requests" }

		local column = P.column(parent, {
			name = "LogsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.md, top = theme.space.md, bottom = theme.space.sm },
			layoutOrder = 1,
		})

		local scroll
		local function render() end

		C.segmented(head, {
			options = {
				{ value = "requests", label = "Requests" },
				{ value = "log", label = "Log" },
			},
			value = panel.view,
			onChange = function(value)
				panel.view = value
				render()
			end,
		})

		local actions = P.row(head, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		local countLabel = P.text(actions, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		countLabel.Size = UDim2.fromOffset(0, theme.text.caption.height + theme.space.hair)
		countLabel.AutomaticSize = Enum.AutomaticSize.X
		-- A growing spacer rather than a hardcoded reserve on the label: the buttons
		-- are auto-width and grow with the text scale, so any fixed number is either
		-- short of the right edge or overlapping them.
		P.spacer(actions, { grow = true, size = UDim2.new(0, 0, 0, 1), layoutOrder = 2 })

		if caps.clipboard then
			local copy = P.button(actions, {
				text = "Copy",
				variant = "ghost",
				size = "sm",
				layoutOrder = 3,
				onClick = function()
					pcall(caps.fn.clipboard, log.export())
					overlay.toast("Log copied", "good", 2)
				end,
			})
			copy.instance.LayoutOrder = 3
		end
		local clear = P.button(actions, {
			text = "Clear",
			variant = "ghost",
			size = "sm",
			layoutOrder = 4,
			onClick = function()
				if panel.view == "requests" then http.clearHistory() else log.clear() end
				render()
			end,
		})
		clear.instance.LayoutOrder = 4

		scroll = P.scroll(column, {
			name = "LogList",
			size = UDim2.new(1, 0, 1, 0),
			-- Tight, because the rows now carry their own banding and padding; a six
			-- pixel gap between banded rows reads as a gap in the data.
			gap = theme.space.hair,
			padding = { x = theme.space.md, top = theme.space.xs, bottom = theme.space.lg },
			layoutOrder = 2,
		})
		local flex = Instance.new("UIFlexItem", scroll.instance)
		flex.FlexMode = Enum.UIFlexMode.Fill

		local function requestRow(entry, order)
			local tone = "good"
			if entry.error then
				tone = "bad"
			elseif entry.status >= 400 then
				tone = entry.status == 429 and "warn" or "bad"
			elseif entry.status == 0 then
				tone = "warn"
			end

			local card = P.card(scroll.instance, {
				layoutOrder = order,
				gap = theme.space.xxs,
				padding = theme.space.sm,
			})
			local top = P.row(card, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
			P.statusDot(top, { color = theme.toneColor(tone), diameter = theme.size.dot, layoutOrder = 1 })
			local title = P.text(top, {
				text = string.format("%s %s", entry.method, entry.tag or ""),
				role = "monoSmall",
				-- Fills rather than reserving 150 for a dot and a 96px meta column,
				-- which left thirty-five pixels stranded on every card.
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				layoutOrder = 2,
			})
			local meta = P.text(top, {
				text = string.format("%s %s", entry.status > 0 and tostring(entry.status) or "-",
					util.formatDuration(entry.ms or 0)),
				role = "caption",
				color = theme.color.textTertiary,
				align = "Right",
				layoutOrder = 3,
			})
			meta.Size = UDim2.fromOffset(theme.size.metaColumnWide + theme.space.sm, theme.text.caption.height)

			local url = P.text(card, {
				text = entry.url,
				role = "caption",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
			url.Size = UDim2.new(1, 0, 0, 0)

			local bits = {
				entry.via or "?",
				string.format("%s bytes", util.formatNumber(entry.bytes or 0)),
				entry.identity or "claude",
			}
			if entry.identity ~= "none" and not entry.uaSent then
				bits[#bits + 1] = "user-agent dropped by transport"
			end
			if entry.droppedHeaders and #entry.droppedHeaders > 0 then
				bits[#bits + 1] = "dropped: " .. table.concat(entry.droppedHeaders, ", ")
			end
			if entry.attempt and entry.attempt > 1 then
				bits[#bits + 1] = "attempt " .. tostring(entry.attempt)
			end
			-- The evidence for a bodyless refusal. `server` and a trace id say the
			-- response came from an edge rather than from the API, and `cf-mitigated`
			-- says so outright, which is the difference between a key problem and a
			-- filter problem.
			if entry.server then bits[#bits + 1] = "server " .. tostring(entry.server) end
			if entry.mitigated then bits[#bits + 1] = "mitigated " .. tostring(entry.mitigated) end
			if entry.trace then bits[#bits + 1] = tostring(entry.trace) end
			if entry.status >= 400 and (entry.bytes or 0) == 0 then
				bits[#bits + 1] = "empty body"
			end
			local detail = P.text(card, {
				text = table.concat(bits, "  |  "),
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			detail.Size = UDim2.new(1, 0, 0, 0)

			if entry.error then
				local err = P.text(card, {
					text = tostring(entry.error),
					role = "caption",
					color = theme.color.danger,
					wrap = true,
					auto = "Y",
				})
				err.Size = UDim2.new(1, 0, 0, 0)
			end
			return card
		end

		-- Column reserves, named once so the body's remainder cannot drift out of step
		-- with them. They were 58 and 74 for an eight-character timestamp and a
		-- four-letter source, which left about sixty pixels of nothing on every row.
		--
		-- Both are derived from the type rather than measured in pixels: a timestamp is
		-- eight monospaced-ish characters and a source is five, so at text scale 1.4 the
		-- columns grow with the text instead of clipping it. The dot is the token that
		-- already exists for a status dot; it was a third literal that happened to agree
		-- with it.
		local STAMP_WIDTH = math.ceil(theme.text.caption.size * 8 * 0.62)
		local SOURCE_WIDTH = math.ceil(theme.text.caption.size * 5 * 0.62)
		local DOT_WIDTH = theme.size.dot
		-- One height for all three meta columns. They were caption.size + 4 (16) beside a
		-- dot slot of caption.height (17) beside a monoSmall body (18), which is three box
		-- heights in one top-aligned row.
		local META_HEIGHT = theme.text.caption.height

		local function logRow(entry, order)
			local row = P.row(scroll.instance, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				-- Alternating bands, because twenty-four transparent rows four pixels
				-- apart read as one block of text rather than as a table.
				bg = (order % 2 == 0) and theme.color.surfaceRaised or nil,
				radius = theme.radius.sm,
				padding = { x = theme.space.xs, y = theme.space.hair },
				-- Top-aligned put the 6px dot's centre four pixels above the text's,
				-- so every dot in the list rode high. The message can wrap to a second
				-- line, so the meta columns are given the row's height and centre their
				-- own text instead.
				alignY = "Top",
				layoutOrder = order,
			})
			-- The dot gets a slot the height of one text line and centres itself in
			-- that, rather than anchoring inside the row: the row is laid out by a
			-- UIListLayout, which owns its children's positions, and a bare 6px dot
			-- against 14px labels rode four pixels high on every line in the list.
			local dotSlot = P.frame(row, {
				name = "Level",
				size = UDim2.fromOffset(DOT_WIDTH, META_HEIGHT),
				layoutOrder = 1,
			})
			P.statusDot(dotSlot, {
				color = theme.toneColor(LEVEL_TONE[entry.level] or "info"),
				diameter = DOT_WIDTH,
				anchor = Vector2.new(0.5, 0.5),
				position = UDim2.fromScale(0.5, 0.5),
			})
			local stamp = P.text(row, {
				text = entry.stamp or "",
				role = "caption",
				color = theme.color.textTertiary,
				layoutOrder = 2,
			})
			stamp.Size = UDim2.fromOffset(STAMP_WIDTH, META_HEIGHT)
			local source = P.text(row, {
				text = entry.source,
				role = "caption",
				color = theme.color.textTertiary,
				layoutOrder = 3,
				truncate = true,
			})
			source.Size = UDim2.fromOffset(SOURCE_WIDTH, META_HEIGHT)
			local body = P.text(row, {
				text = entry.message .. (entry.detail and ("  " .. entry.detail) or ""),
				role = "monoSmall",
				color = entry.level == "error" and theme.color.danger or theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				-- Fills, rather than subtracting three reserves and three gaps by hand.
				-- That remainder was correct only as long as nobody touched any of the six
				-- numbers in it.
				size = UDim2.new(0, 0, 0, 0),
				flex = "Fill",
				layoutOrder = 4,
			})
			return row
		end

		render = function()
			scroll.clear()
			if panel.view == "requests" then
				local entries = util.reverse(http.history)
				countLabel.Text = util.pluralise(#entries, "request") .. " kept"
				if #entries == 0 then
					C.emptyState(scroll.instance, {
						title = "No requests yet",
						description = "Every outbound call lands here with its status, timing and whether the client identity made it onto the wire.",
						layoutOrder = 1,
					})
					return
				end
				for index, entry in ipairs(entries) do requestRow(entry, index) end
			else
				local entries = util.reverse(log.entries)
				countLabel.Text = util.pluralise(#entries, "line") .. " kept"
				if #entries == 0 then
					C.emptyState(scroll.instance, { title = "Log is empty", layoutOrder = 1 })
					return
				end
				for index, entry in ipairs(entries) do logRow(entry, index) end
			end
		end

		render()
		panel.refresh = render
		-- Live, but throttled: a burst of log lines must not rebuild the list per
		-- line while the user is reading it.
		local clock = env.require("runtime/clock")
		local throttled = clock.throttle(render, 0.4)
		panel.unsubscribeLog = log.changed:connect(function()
			if panel.view == "log" then throttled() end
		end)
		panel.unsubscribeHttp = http.changed:connect(function()
			if panel.view == "requests" then throttled() end
		end)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/modelpicker
-- ==========================================================================
__UAI_MODULES["ui/panels/modelpicker"] = (function()
-- The model picker.
--
-- One decision from the user's point of view -- "what is answering me, and how hard is
-- it allowed to think" -- so it is one surface, and it is the surface behind the
-- composer's model chip.
--
-- It used to be an anchored menu with four unrelated kinds of row stacked in it: every
-- provider, then every model on the active one, then a fetch, then five effort levels,
-- then "Manage providers". Twenty-odd rows of one visual weight, no headings, and the
-- only way to tell a provider row from a model row was to recognise the string -- which
-- on a gateway that serves eighty ids meant scrolling a 320px menu past the thing you
-- came for. A menu is the right shape for "pick one of six"; this is not that.
--
-- What is here instead is a modal with the three parts of the decision separated and a
-- filter over the long one. Every row is a real record: a provider this client has, a
-- model the endpoint reported or the user typed, an effort level the model documents.
-- Nothing is listed that cannot be selected, which is why the model list can legitimately
-- be empty until a fetch or an id has happened.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local providers = env.require("provider/registry")
	local models = env.require("provider/models")
	local traits = env.require("provider/traits")

	local M = {}

	-- Every level the interface can ask for, cheapest first. A model that documents a
	-- shorter scale gets the shorter scale; one that documents none gets no control,
	-- because an effort picker over a model with no effort parameter is a setting that
	-- changes what is sent to nothing.
	local ALL_EFFORT = { "low", "medium", "high", "xhigh", "max" }

	-- Past this many models the list gets a filter. Below it the filter is a control
	-- that costs a line to say "there are six of these".
	local FILTER_AT = 8

	local function titleCase(text)
		return (tostring(text):gsub("^%l", string.upper))
	end

	-- What a provider row says about itself on the right: the health the registry has
	-- actually recorded, not a guess. A record nothing has been sent through says so
	-- rather than claiming to be well.
	local function healthOf(record)
		local state = record.health or {}
		if providers.cooling(record) then
			return "benched", "bad"
		end
		if (state.fail or 0) > 0 and (state.streak or 0) > 0 then
			return util.pluralise(state.streak, "failure"), "warn"
		end
		if (state.ok or 0) > 0 then
			local ms = tonumber(state.lastMs)
			if ms and ms > 0 then
				return string.format("%s  \194\183  %s", util.pluralise(state.ok, "call"),
					util.formatDuration(ms))
			end
			return util.pluralise(state.ok, "call"), "good"
		end
		return "not tried yet", "neutral"
	end

	-- Opens it. `onChange` is called after anything is selected, so the composer can
	-- repaint its chip without this module knowing what a composer is.
	function M.open(onChange)
		local modal = overlay.modal({
			title = "Model",
			description = "What answers, and how hard it is asked to think. "
				.. "Only endpoints this client has and ids they reported are listed.",
			width = theme.size.dialog,
			-- The model list is as long as the endpoint's catalogue -- eighty ids on a
			-- gateway -- so this is bounded and scrolled rather than as tall as its
			-- contents. The overlay owns the arithmetic: it knows the inset and the
			-- keyboard, which is more than this surface should have to.
			scroll = true,
		})
		if not modal then return nil end

		local function notify()
			if onChange then pcall(onChange) end
		end

		-- The three sections go in the modal's own scrolling body, which is what
		-- `scroll = true` above bought. `body` is the column inside it; `clear` empties
		-- that column, because a re-render replaces every section rather than patching
		-- rows -- selecting a provider changes which models exist, so there is nothing to
		-- patch.
		local body = modal.content
		local function clear()
			for _, child in ipairs(body:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
		end

		local filter = ""
		local render

		-- A section: a quiet heading with a count beside it, then the rows under it.
		-- The heading is what the old menu had no way to express, and it is most of the
		-- difference between this and that.
		local function section(order, title, detail)
			local column = P.column(body, {
				name = "Section_" .. title:gsub("%s+", ""),
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xxs,
				layoutOrder = order,
			})
			local head = P.row(column, {
				size = UDim2.new(1, 0, 0, theme.text.label.height),
				gap = theme.space.xs,
				padding = { x = theme.space.xxs },
				layoutOrder = 1,
			})
			P.text(head, {
				text = title,
				role = "label",
				color = theme.color.text,
				size = UDim2.new(0, 0, 1, 0),
				flex = "Fill",
				truncate = true,
				layoutOrder = 1,
			})
			if detail then
				local label = P.text(head, {
					text = tostring(detail),
					role = "caption",
					color = theme.color.textTertiary,
					align = "Right",
					auto = "X",
					layoutOrder = 2,
				})
				label.Size = UDim2.fromOffset(0, theme.text.caption.height)
			end
			-- Not named `body`: that is the modal's own column, one scope up, and shadowing
			-- it here would mean the next person to add a line to this function reaches for
			-- the section's rows and gets them.
			return P.column(column, {
				name = "Rows",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.hair,
				layoutOrder = 2,
			})
		end

		-- One selectable row: a leading mark, a title over a detail line, and an
		-- optional badge. Two lines rather than one because every row in here has a
		-- second fact worth reading -- an endpoint, a context window, what an effort
		-- level costs -- and the old menu put those in a `detail` that only showed on
		-- rows that happened to set it.
		local function pickRow(parent, props)
			local height = math.max(theme.size.controlLarge + theme.space.xs, responsive.minTarget())
			local row = P.rowButton(parent, {
				name = props.name,
				height = height,
				size = UDim2.new(1, 0, 0, height),
				bg = props.selected and theme.color.surfaceActive or nil,
				selected = props.selected,
				radius = theme.radius.md,
				gap = theme.space.sm,
				padding = { x = theme.space.sm },
				layoutOrder = props.layoutOrder,
				onClick = props.onClick,
			})

			-- The selected mark, in a slot that is there whether or not it is filled: a
			-- check that appears only on one row and shifts every other row's text by
			-- sixteen pixels is what makes a list look like it is jumping.
			local mark = P.frame(row.row, {
				name = "Mark",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 1,
			})
			if props.selected then
				icons.check(mark, theme.size.icon, theme.color.accent)
			end

			local column = P.column(row.row, {
				size = UDim2.new(0, 0, 1, 0),
				flex = "Fill",
				gap = 0,
				alignY = "Center",
				layoutOrder = 2,
			})
			P.text(column, {
				name = "Title",
				text = tostring(props.title or ""),
				role = props.mono and "monoSmall" or "small",
				color = props.tone and theme.toneColor(props.tone)
					or (props.selected and theme.color.text or theme.color.textSecondary),
				size = UDim2.new(1, 0, 0, theme.textRole(props.mono and "monoSmall" or "small").height),
				truncate = true,
				layoutOrder = 1,
			})
			if props.detail then
				P.text(column, {
					name = "Detail",
					text = tostring(props.detail),
					role = "caption",
					color = theme.color.textTertiary,
					size = UDim2.new(1, 0, 0, theme.text.caption.height),
					truncate = true,
					layoutOrder = 2,
				})
			end

			if props.badge then
				P.badge(row.row, {
					text = tostring(props.badge),
					tone = props.badgeTone or "neutral",
					layoutOrder = 3,
				})
			end
			if props.status then
				local label = P.text(row.row, {
					name = "Status",
					text = tostring(props.status),
					role = "caption",
					color = theme.toneColor(props.statusTone or "neutral"),
					align = "Right",
					auto = "X",
					layoutOrder = 4,
				})
				label.Size = UDim2.fromOffset(0, theme.text.caption.height)
			end
			return row
		end

		render = function()
			clear()
			local record = providers.active()
			local order = 0
			local function nextOrder()
				order = order + 1
				return order
			end

			-- 1. Where the request goes. Listed even when there is one, because the row is
			-- also where its health is stated and that is the thing worth seeing when a
			-- turn has just failed.
			local list = providers.list()
			if #list == 0 then
				C.emptyState(body, {
					title = "No provider configured",
					description = "Add an OpenAI-compatible endpoint to start. Anything that speaks "
						.. "/v1/chat/completions works: a hosted API, a relay, or a local server.",
					action = "Open providers",
					onAction = function()
						modal.close()
						env.require("ui/app").show("providers")
					end,
					layoutOrder = nextOrder(),
				})
			else
				local providerRows = section(nextOrder(), "Endpoint",
					util.pluralise(#list, "configured"))
				for index, entry in ipairs(list) do
					local status, tone = healthOf(entry)
					local isActive = record and record.id == entry.id
					pickRow(providerRows, {
						name = "Provider_" .. tostring(entry.id),
						title = entry.label,
						detail = entry.baseUrl,
						status = status,
						statusTone = tone,
						selected = isActive,
						layoutOrder = index,
						onClick = function()
							if isActive then return end
							providers.setActive(entry.id)
							notify()
							render()
						end,
					})
				end
			end

			if not record then
				return
			end

			-- 2. Which model on it. The filter earns its line only on a list long enough
			-- to need one, and it filters rather than searching: everything here is
			-- already local.
			local known = models.list(record)
			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end

			local shown = {}
			local needle = util.trim(filter):lower()
			for _, id in ipairs(known) do
				if needle == "" or tostring(id):lower():find(needle, 1, true) then
					shown[#shown + 1] = id
				end
			end

			local detail = #known == #shown
				and util.pluralise(#known, "model")
				or string.format("%d of %s", #shown, util.pluralise(#known, "model"))
			local modelRows = section(nextOrder(), "Model on " .. record.label, detail)

			if #known >= FILTER_AT then
				local field = P.field(modelRows, {
					name = "ModelFilter",
					placeholder = "Filter these " .. tostring(#known) .. " ids",
					text = filter,
					layoutOrder = 0,
					onChange = function(text)
						filter = text
						render()
					end,
				})
				-- Focus is restored after a re-render, because typing into the filter is
				-- what caused the re-render: without this the field loses focus on the
				-- first keystroke and the second one goes nowhere.
				if util.trim(filter) ~= "" then
					env.require("runtime/clock").delay(theme.motion.fast, function()
						pcall(field.focus)
					end)
				end
			end

			if #known == 0 then
				local note = P.text(modelRows, {
					name = "NoModels",
					text = "Nothing known yet. Ask the endpoint for its list, or add an id by hand -- "
						.. "this client never guesses one.",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = theme.space.sm, y = theme.space.xs },
					layoutOrder = 1,
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			elseif #shown == 0 then
				local note = P.text(modelRows, {
					name = "NoMatch",
					text = "Nothing matched " .. util.trim(filter) .. ".",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = theme.space.sm, y = theme.space.xs },
					layoutOrder = 1,
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end

			for index, id in ipairs(shown) do
				-- The context window is the one thing about a model worth reading at a
				-- glance and no endpoint publishes it, so where this client documents it,
				-- it rides on the row as a badge. Where it does not, there is no badge --
				-- rather than a badge that says "unknown".
				local badge = traits.badge(id)
				local where = own[id] and "added on this client" or "reported by /models"
				pickRow(modelRows, {
					name = "Model_" .. tostring(id),
					title = id,
					mono = true,
					detail = where,
					badge = badge,
					selected = id == record.model,
					layoutOrder = index,
					onClick = function()
						providers.setModel(record.id, id)
						notify()
						render()
					end,
				})
			end

			-- 3. How hard it is asked to think.
			--
			-- The levels are the model's own where it documents them, and the whole
			-- section is left out where it documents none: sending an effort a model has
			-- no parameter for is a control that does nothing, which is exactly what the
			-- old menu's five rows were on most ids.
			local levels = traits.effortLevels(record.model)
			local wanted = tostring(config.get("agent.effort", "high"))
			if levels then
				local sending = traits.nearestEffort(record.model, wanted) or wanted
				local note = (sending ~= wanted)
					and string.format("%s is the most this model has", titleCase(sending))
					or nil
				local effortRows = section(nextOrder(), "Reasoning effort", note)
				for index, level in ipairs(levels) do
					local isDefault = traits.defaultEffort(record.model) == level
					pickRow(effortRows, {
						name = "Effort_" .. level,
						title = titleCase(level),
						detail = isDefault
							and "what the API itself uses when none is sent"
							or nil,
						selected = level == sending,
						layoutOrder = index,
						onClick = function()
							config.set("agent.effort", level)
							notify()
							render()
						end,
					})
				end
			else
				local effortRows = section(nextOrder(), "Reasoning effort", "not offered")
				local note = P.text(effortRows, {
					name = "NoEffort",
					text = ("%s publishes no effort scale this client knows, so none is sent and the setting "
						.. "(%s) is not applied to it."):format(
						record.model ~= "" and record.model or "This model", titleCase(wanted)),
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = theme.space.sm, y = theme.space.xs },
					layoutOrder = 1,
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end
		end

		render()

		-- The footer is the three things that are not a selection: ask the endpoint what
		-- it serves, name an id it did not report, and go to the panel where a whole
		-- record is edited.
		local record = providers.active()
		if record then
			P.button(modal.footer, {
				name = "FetchModels",
				text = "Fetch from /models",
				variant = "ghost",
				size = "sm",
				layoutOrder = 1,
				onClick = function()
					overlay.toast("Fetching models from " .. record.label, "info", 2)
					task.spawn(function()
						local found, note = models.discover(record, { force = true })
						overlay.toast(tostring(note), #found > 0 and "good" or "warn", 3)
						notify()
						-- Only if the modal is still open: a fetch runs for as long as the
						-- endpoint takes, and rendering into a destroyed tree is the classic
						-- way an async callback takes the interface down with it.
						if not modal.closed then render() end
					end)
				end,
			})
			P.button(modal.footer, {
				name = "AddModel",
				text = "Add an id",
				variant = "ghost",
				size = "sm",
				layoutOrder = 2,
				onClick = function()
					overlay.prompt({
						title = "Add a model to " .. record.label,
						description = "Type the id exactly as the provider expects it. "
							.. "It is saved to this provider and selected.",
						placeholder = "model id",
						confirmText = "Add",
						onConfirm = function(text)
							local ok, result = models.add(record, text)
							if ok then providers.setModel(record.id, util.trim(text)) end
							overlay.toast(tostring(result), ok and "good" or "warn", 3)
							notify()
							if not modal.closed then render() end
						end,
					})
				end,
			})
		end
		P.button(modal.footer, {
			name = "ManageProviders",
			text = "Manage",
			variant = "ghost",
			size = "sm",
			layoutOrder = 3,
			onClick = function()
				modal.close()
				env.require("ui/app").show("providers")
			end,
		})
		P.button(modal.footer, {
			name = "PickerDone",
			text = "Done",
			variant = "primary",
			size = "sm",
			layoutOrder = 4,
			onClick = function() modal.close() end,
		})

		-- The list is a view of state other surfaces write: the Providers panel can add a
		-- record or change a model while this is open, and a fetch started here lands
		-- through the same signal.
		local unsubscribe = providers.changed:connect(function()
			if modal.closed then return end
			render()
		end)
		modal.scrim.Destroying:Connect(function() pcall(unsubscribe) end)

		modal.render = render
		return modal
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/permission
-- ==========================================================================
__UAI_MODULES["ui/panels/permission"] = (function()
-- The permission prompt.
--
-- The loop blocks on a thread while this is open, so it has to be reliable: one
-- prompt at a time, queued, and always resolved -- closing it counts as a refusal.
-- An unresolved prompt would park the agent until its own timeout.
--
-- It listens to every conversation rather than to the open one. It used to attach to
-- whichever session the transcript was showing, which meant a second conversation
-- left running in the background asked for permission into a stream nobody was
-- subscribed to: no prompt appeared, its three-minute deadline expired, and every
-- write it had planned came back to the model as a refusal. Since a prompt can now
-- arrive from a conversation that is not on screen, the modal says which one.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")

	local M = { queue = {}, showing = false }

	local RISK_TONE = { read = "info", write = "warn", danger = "bad" }

	local RISK_TEXT = {
		read = "This only reads. Nothing changes.",
		write = "This changes something in the game or on disk.",
		danger = "This runs code, deletes data, or reaches the server. It cannot be undone.",
	}

	local function present(request)
		M.showing = true

		local remember = false
		local resolved = false

		local function answer(allowed)
			if resolved then return end
			resolved = true
			pcall(request.resolve, allowed, remember)
			M.showing = false
			-- Drain the next prompt on the same frame so a batch of tool calls does
			-- not make the user wait between decisions.
			local next_request = table.remove(M.queue, 1)
			if next_request then present(next_request) end
		end

		local modal = overlay.modal({
			title = "Allow " .. tostring(request.name) .. "?",
			description = RISK_TEXT[request.risk or "write"] or RISK_TEXT.write,
			width = theme.size.modalWide,
			dismissable = true,
			onClose = function() answer(false) end,
		})
		if not modal then
			answer(false)
			return
		end

		local badgeRow = P.row(modal.content, {
			name = "Asking",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.badge(badgeRow, {
			text = tostring(request.risk or "write"),
			tone = RISK_TONE[request.risk or "write"] or "warn",
			layoutOrder = 1,
		})
		-- Which conversation is asking. With one prompt queue serving every open
		-- conversation, "Allow run_luau?" on its own does not say whose turn it
		-- belongs to -- and answering the wrong one is not recoverable.
		if request.sessionTitle then
			P.text(badgeRow, {
				name = "AskingIn",
				text = "in " .. tostring(request.sessionTitle),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				flex = "Fill",
				layoutOrder = 2,
			})
		end

		if request.description then
			local description = P.text(modal.content, {
				text = tostring(request.description),
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			description.Size = UDim2.new(1, 0, 0, 0)
		end

		-- The arguments are the whole point of the prompt: "allow run_luau" means
		-- nothing without seeing the code.
		local argsText = ""
		local ok, encoded = pcall(util.encode, request.args or {})
		if ok then argsText = encoded end
		if util.trim(argsText) ~= "" and argsText ~= "[]" and argsText ~= "{}" then
			local box = P.frame(modal.content, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				bg = theme.color.codeSurface,
				radius = theme.radius.md,
				padding = theme.space.sm,
				layoutOrder = 3,
			})
			P.stroke(box, theme.color.codeBorder)
			local label = P.text(box, {
				text = (util.truncate(argsText, 900)),
				role = "monoSmall",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
			label.Size = UDim2.new(1, 0, 0, 0)
		end

		local rememberRow = P.row(modal.content, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 4,
		})
		local rememberText = P.column(rememberRow, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(rememberText, { text = "Remember this answer", role = "small" })
		P.text(rememberText, {
			text = "Applies to every future " .. tostring(request.name) .. " call. Change it later in the Tools panel.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local switch = C.switch(rememberRow, {
			value = false,
			onChange = function(value) remember = value end,
		})
		switch.instance.LayoutOrder = 2

		-- Named, like every other control that decides something. Two buttons both
		-- called "Button" is unreadable from a dump and unreachable from a test, and
		-- this is the one dialog in the client where pressing the wrong one is not
		-- recoverable.
		P.button(modal.footer, {
			name = "PermissionDeny",
			text = "Deny",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			onClick = function()
				modal.close()
			end,
		})
		P.button(modal.footer, {
			name = "PermissionAllow",
			text = "Allow",
			variant = request.risk == "danger" and "danger" or "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				answer(true)
				modal.closed = true
				pcall(function() modal.scrim:Destroy() end)
			end,
		})
	end

	-- Watches every conversation in the client.
	--
	-- `attach` is kept because the app calls it whenever the open conversation changes,
	-- but it no longer decides what is heard: the subscription is to the session
	-- module's own fan-out, made once and never dropped, so a prompt from a
	-- conversation nobody is looking at still reaches the screen.
	local function onEvent(session, event)
		if event.kind ~= "permission:ask" then return end
		-- A subagent is headless and its prompts are forwarded onto its parent's
		-- stream by agent/subagent, so the child's own copy would be a second modal
		-- for one decision.
		if session and session.headless then return end
		local request = {
			id = event.id,
			name = event.name,
			risk = event.risk,
			description = event.description,
			args = event.args,
			resolve = event.resolve,
			sessionTitle = session and session.title or nil,
		}
		if M.showing then
			M.queue[#M.queue + 1] = request
		else
			present(request)
		end
	end

	function M.watch()
		if M.watching then return M end
		local sessions = env.require("agent/session")
		M.watching = env.require("runtime/dispose").add(
			sessions.anyEvent:connect(onEvent), "permission.watch")
		return M
	end

	-- Kept for the app, which calls it on every conversation switch. Starting the
	-- global watch is all it has left to do.
	function M.attach()
		return M.watch()
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/providers
-- ==========================================================================
__UAI_MODULES["ui/panels/providers"] = (function()
-- Providers panel: a list on the left, one provider's whole configuration on the
-- right.
--
-- This is the screen that makes the client universal, so it is deliberately plain: a
-- base URL, a key, an auth style and a model. Anything that speaks
-- /v1/chat/completions is a first-class citizen here, and the presets are only a way
-- to avoid typing a URL.
--
-- It was a list of cards plus one modal holding nine rows of form, and four things
-- were wrong with that beyond the density. The modal was the only way to see any of a
-- record's configuration, and it printed the API key in clear text while the hint
-- underneath said the key was redacted. Picking a different preset inside it rebuilt
-- the record from scratch and threw away whatever had been typed, with no warning. The
-- record's headers, params, query, order and note -- five fields the registry keeps,
-- two of which decide whether Azure and OpenRouter work at all -- had no
-- representation anywhere in the interface. And every completion fired a health event
-- that rebuilt the entire panel mid-turn, scroll position included.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local caps = env.require("runtime/caps")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local R = env.require("ui/settingsrows")
	local overlay = env.require("ui/overlay")
	local catalog = env.require("provider/catalog")
	local registry = env.require("provider/registry")
	local models = env.require("provider/models")
	local chat = env.require("provider/chat")
	local traits = env.require("provider/traits")

	local M = {}

	local AUTH_OPTIONS = {
		{ value = "bearer", label = "Bearer" },
		{ value = "x-api-key", label = "x-api-key" },
		{ value = "api-key", label = "api-key" },
		{ value = "both", label = "Both" },
		{ value = "none", label = "None" },
	}

	local function labelOf(options, value)
		for _, option in ipairs(options) do
			if option.value == value then return option.label end
		end
		return tostring(value)
	end

	-- Never the key itself.
	--
	-- The editor rendered record.apiKey into an ordinary field, so opening Edit on any
	-- saved provider printed the whole secret on screen -- while the hint under it said
	-- "redacted in the log", the privacy pane promised only the last four characters
	-- were kept, and the export path reduced it to exactly that.
	local function maskedKey(record)
		local key = util.trim(record.apiKey or "")
		if key == "" then return "not set", "warn" end
		if #key <= 4 then return "set", nil end
		return string.rep("\226\128\162", 4) .. " " .. key:sub(-4), nil
	end

	-- Everything the registry knows about a record and the panel never said.
	--
	-- `chat.endpointOf` and `registry.endpoint` both existed for this and both had zero
	-- call sites; the comment on endpointOf says "for the Providers panel to show".
	local function factsFor(record)
		local health = record.health or {}
		local key, keyTone = maskedKey(record)
		local out = {
			{ key = "Endpoint", value = chat.endpointOf(record) },
			{ key = "Model list", value = registry.endpoint(record, "/models") },
			{ key = "Protocol", value = labelOf(chat.STYLES, chat.styleOf(record)) },
			{ key = "Auth", value = labelOf(AUTH_OPTIONS, record.authStyle or "bearer")
				.. "  \194\183  " .. key, tone = keyTone },
			-- The one fact that decides whether a long reply can arrive at all. No Roblox
			-- HTTP transport reads a body incrementally and the host abandons a request
			-- after about a minute, so without a socket a large completion cannot land.
			{ key = "Streaming", value = util.trim(record.wsUrl or "") ~= ""
				and "socket, no length ceiling"
				or "HTTP only, replies capped near a minute" },
		}
		if (health.ok or 0) + (health.fail or 0) > 0 then
			out[#out + 1] = {
				key = "Health",
				value = string.format("%d ok, %d failed", health.ok or 0, health.fail or 0),
				tone = (health.streak or 0) > 0 and "warn" or "good",
			}
		end
		-- Recorded on every success and shown nowhere until now.
		if (health.lastMs or 0) > 0 then
			out[#out + 1] = { key = "Last reply", value = util.formatDuration(health.lastMs) }
		end
		-- The bench was a red dot with no words: no label, no remaining time, and no
		-- statement of the three-failure rule that put it there.
		if registry.cooling(record) then
			local left = math.max((health.cooldownUntil or 0) - clock.ms(), 0)
			out[#out + 1] = {
				key = "Benched",
				value = string.format("%s left, after 3 failures in a row", util.formatDuration(left)),
				tone = "bad",
			}
		end
		if record.requires == "executor" then
			local have = caps.http == "executor"
			out[#out + 1] = {
				key = "Requires",
				value = have and "an executor HTTP function, which this host has"
					or "an executor HTTP function, which this host does not have",
				tone = have and "good" or "bad",
			}
		end
		return out
	end

	-- The connection modal: preset, name, URL, protocol, auth, key. Six rows, not nine.
	--
	-- Everything else a record carries -- its models, its behaviour switches, its extra
	-- headers -- is edited in the detail pane, which is a surface that does not have to
	-- be dismissed to see the rest of the screen. This modal exists for the one moment
	-- when none of that is reachable yet: there is no record to select.
	function M.editor(record, onSaved)
		local editing = util.deepCopy(record)
		local adding = util.trim(editing.id) == ""
		local modal = overlay.modal({
			title = adding and "Add a provider" or ("Connection for " .. tostring(editing.label)),
			description = "Any endpoint that speaks /v1/chat/completions, or Anthropic's Messages API.",
			width = theme.size.modalWide,
			height = 620,
			-- Six labelled rows, two segmented pickers and a footer do not fit on a phone,
			-- and an unbounded modal is centred -- so what did not fit went off the top and
			-- the bottom at once, taking the title and the Save button with it. Bounded and
			-- scrolled, the header and the footer stay put and the form moves.
			scroll = true,
		})
		if not modal then return end

		local form = P.column(modal.content, {
			name = "Form",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.lg,
			layoutOrder = 1,
		})

		local problemLabel
		local presetButton, urlField, keyRow
		-- Assigned with the model row below, called from applyPreset above it: a preset
		-- change moves the endpoint, so anything a previous fetch turned up belongs to a
		-- different server and must not still be on offer.
		local forgetFetchedModels

		local function showProblems()
			local ok, problems = registry.validate(editing)
			problemLabel.Text = ok and "" or (problems[1]:gsub("^%l", string.upper) .. ".")
			problemLabel.Visible = not ok
			return ok
		end

		local function row(label, hint, build)
			local column = P.column(form, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
			})
			P.text(column, { text = tostring(label), role = "label", color = theme.color.text })
			local handle = build(column)
			if hint then
				local note = P.text(column, {
					text = hint,
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end
			return handle
		end

		-- Applied in place, not by rebuilding the record.
		--
		-- Choosing a preset used to call registry.blank, replace `editing` wholesale,
		-- close the modal and re-open it -- so a name typed, a key pasted and a URL
		-- corrected were all discarded the moment someone realised they had picked the
		-- wrong vendor. Only the fields the preset actually describes move; the label is
		-- carried over when it still matches the old preset's own name, which is the case
		-- where it was never edited.
		local function applyPreset(id)
			local preset = catalog.get(id)
			if not preset then return end
			local previous = catalog.get(editing.preset)
			if previous and util.trim(editing.label) == util.trim(previous.label) then
				editing.label = preset.label
			end
			if util.trim(editing.label) == "" then editing.label = preset.label end
			editing.preset = preset.id
			editing.baseUrl = preset.baseUrl or ""
			editing.authStyle = preset.authStyle or "bearer"
			editing.api = preset.api or "openai"
			editing.headers = util.deepCopy(preset.headers or {})
			editing.params = util.deepCopy(preset.params or {})
			editing.query = util.deepCopy(preset.query or {})
			editing.note = preset.note
			editing.requires = preset.requires
			if presetButton then presetButton.setText(preset.label) end
			if urlField then urlField.set(editing.baseUrl) end
			if forgetFetchedModels then forgetFetchedModels() end
			showProblems()
		end

		row("Preset", "A base URL and an auth style, nothing more. Picking one keeps the name and "
			.. "the key you have already typed.", function(column)
			presetButton = P.button(column, {
				name = "Preset",
				text = (catalog.get(editing.preset) or {}).label or "Custom endpoint",
				variant = "secondary",
				fill = true,
				align = "Left",
				onClick = function(handle)
					local options = {}
					for _, preset in ipairs(catalog.presets) do
						options[#options + 1] = {
							label = preset.label,
							value = preset.id,
							detail = (preset.baseUrl ~= "" and preset.baseUrl) or "any URL you supply",
							selected = preset.id == editing.preset,
						}
					end
					overlay.menu({
						target = handle.instance,
						width = theme.size.menuWide,
						options = options,
						onSelect = applyPreset,
					})
				end,
			})
			return presetButton
		end)

		row("Name", nil, function(column)
			return P.field(column, {
				name = "ProviderName",
				text = editing.label,
				placeholder = "My provider",
				onChange = function(text) editing.label = text end,
				onBlur = showProblems,
			})
		end)

		local normalisedNote
		row("Base URL", nil, function(column)
			urlField = P.field(column, {
				name = "BaseUrl",
				text = editing.baseUrl,
				placeholder = "https://api.example.com/v1",
				onChange = function(text)
					editing.baseUrl = text
					-- What will actually be stored, before it is stored.
					--
					-- registry.save normalises the URL *and then* validates, so a rejected
					-- save had already rewritten the value while the field still showed the
					-- old text. Saying what the rule does to the input is better than
					-- describing the rule.
					local normalised = registry.normaliseBaseUrl(text)
					if normalisedNote then
						normalisedNote.Text = (normalised ~= "" and normalised ~= util.trim(text))
							and ("Saved as " .. normalised) or ""
					end
				end,
				onBlur = showProblems,
			})
			normalisedNote = P.text(column, {
				text = "",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			normalisedNote.Size = UDim2.new(1, 0, 0, 0)
			return urlField
		end)

		row("Protocol", "Chat completions is the universal one. Anthropic's own Messages API keeps "
			.. "reasoning and tool calls in their real shape instead of translating them twice.",
			function(column)
				return C.segmented(column, {
					name = "Protocol",
					options = chat.STYLES,
					value = chat.styleOf(editing),
					onChange = function(value) editing.api = value end,
				})
			end)

		row("Auth header", nil, function(column)
			return C.segmented(column, {
				name = "AuthStyle",
				options = AUTH_OPTIONS,
				value = editing.authStyle,
				onChange = function(value)
					editing.authStyle = value
					showProblems()
				end,
			})
		end)

		-- The key goes in through a prompt and never comes back out.
		--
		-- A masked field would need a new primitive; a prompt needs none, and it has the
		-- better property that the secret is on screen only while it is being typed.
		local keyLabel
		row("API key", "Kept on this device, sent only to the endpoint above, and redacted in "
			.. "the request log.", function(column)
			local line = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm })
			local shown, tone = maskedKey(editing)
			keyLabel = P.text(line, {
				name = "KeyState",
				text = shown,
				role = "monoSmall",
				color = tone and theme.color.warn or theme.color.textSecondary,
				size = UDim2.new(0, 0, 0, math.max(theme.size.control, responsive.minTarget())),
				flex = "Fill",
				truncate = true,
				layoutOrder = 1,
			})
			local set = P.button(line, {
				name = "SetKey",
				text = util.trim(editing.apiKey or "") == "" and "Add key" or "Replace",
				variant = "secondary",
				size = "sm",
				layoutOrder = 2,
				onClick = function(handle)
					overlay.prompt({
						title = "API key",
						description = "Paste the key for " .. tostring(editing.label) ..
							". It replaces whatever is stored now.",
						placeholder = (catalog.get(editing.preset) or {}).keyHint or "sk-...",
						confirmText = "Save key",
						onConfirm = function(text)
							editing.apiKey = util.trim(text)
							local value, warn = maskedKey(editing)
							keyLabel.Text = value
							keyLabel.TextColor3 = warn and theme.color.warn or theme.color.textSecondary
							handle.setText("Replace")
							showProblems()
						end,
					})
				end,
			})
			set.instance.LayoutOrder = 2
			return keyLabel
		end)

		-- Model.
		--
		-- The one field a record cannot be saved without, and the editor had none. The
		-- picker lives on the detail pane, which you reach by selecting a provider that has
		-- already been saved -- and `registry.validate` refuses to save a record with no
		-- model. So adding a provider ended at "fetch the model list or add a model id"
		-- with nothing on screen that could do either, and Test asked the endpoint for a
		-- completion with no model named, which comes back as the provider's own wording
		-- for that and reads as a broken connection.
		local modelButton, modelNote
		local fetched = {}

		-- What the picker offers: the ids already on the record, plus whatever this
		-- editor's own fetch turned up. The session-wide discovery cache is deliberately
		-- not read here -- it is keyed by provider id and a record being added has none,
		-- so a second "Add a provider" would be offered the last endpoint's models.
		local function knownModels()
			local out, seen = {}, {}
			for _, id in ipairs(editing.models or {}) do
				if util.trim(id) ~= "" and not seen[id] then
					seen[id] = true
					out[#out + 1] = id
				end
			end
			for _, id in ipairs(fetched) do
				if not seen[id] then
					seen[id] = true
					out[#out + 1] = id
				end
			end
			return out
		end

		local DEFAULT_MODEL_NOTE = "The endpoint is the only authority on this, so nothing here "
			.. "guesses one. Fetch the list, or type the id exactly as the provider expects it."

		local function setModelNote(text, bad)
			if not modelNote then return end
			modelNote.Text = tostring(text)
			modelNote.TextColor3 = bad and theme.color.warn or theme.color.textTertiary
		end

		local function paintModel()
			local current = util.trim(editing.model)
			if modelButton then
				modelButton.setText(current ~= "" and current or "Choose a model")
			end
		end

		local openModelMenu

		-- Fetches against the record as it would be saved, not as it is typed: the URL is
		-- normalised the same way `save` normalises it, so what is asked for is the
		-- endpoint the provider will actually use.
		local function fetchModels(handle)
			local target = util.deepCopy(editing)
			target.baseUrl = registry.normaliseBaseUrl(target.baseUrl)
			if target.baseUrl == "" then
				setModelNote("Add the base URL first -- there is nothing to ask.", true)
				return
			end
			handle.setEnabled(false)
			setModelNote("Asking " .. registry.endpoint(target, "/models") .. "...", false)
			task.spawn(function()
				local found, note = models.discover(target, { force = true })
				fetched = found
				handle.setEnabled(true)
				setModelNote(note, #found == 0)
				-- Straight back into the list. Picking one is the reason to fetch, and a
				-- notice that says "42 models" while the menu stays shut makes someone press
				-- the same control twice for one decision.
				if #found > 0 then openModelMenu(handle) end
			end)
		end

		local function typeModel()
			overlay.prompt({
				title = "Model id",
				description = "Type it exactly as the provider expects it. It is saved with this "
					.. "provider and selected.",
				placeholder = "model id",
				confirmText = "Use it",
				onConfirm = function(text)
					-- Not persisted: the record is still being edited and may never be saved.
					local ok, result = models.add(editing, text, { persist = false, select = true })
					setModelNote(ok and ("Using " .. tostring(result)) or tostring(result), not ok)
					paintModel()
					showProblems()
				end,
			})
		end

		openModelMenu = function(handle)
			local options = {}
			local own = {}
			for _, id in ipairs(editing.models or {}) do own[id] = true end
			for _, id in ipairs(knownModels()) do
				local badge = traits.badge(id)
				local bits = {}
				if badge then bits[#bits + 1] = badge end
				if not own[id] then bits[#bits + 1] = "from /models" end
				options[#options + 1] = {
					label = id,
					value = "model:" .. id,
					detail = #bits > 0 and table.concat(bits, "  \194\183  ") or nil,
					selected = id == editing.model,
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = {
				label = "Fetch from /models",
				value = "fetch",
				detail = registry.endpoint(editing, "/models"),
				tone = "info",
			}
			options[#options + 1] = { label = "Type an id", value = "add", tone = "info" }
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if value == "fetch" then
						fetchModels(handle)
					elseif value == "add" then
						typeModel()
					elseif util.startsWith(tostring(value), "model:") then
						local id = tostring(value):sub(7)
						models.add(editing, id, { persist = false, select = true })
						editing.model = id
						setModelNote(DEFAULT_MODEL_NOTE, false)
						paintModel()
						showProblems()
					end
				end,
			})
		end

		row("Model", nil, function(column)
			modelButton = P.button(column, {
				name = "ActiveModel",
				text = "Choose a model",
				variant = "secondary",
				fill = true,
				align = "Left",
				onClick = openModelMenu,
			})
			modelNote = P.text(column, {
				name = "ModelNote",
				text = DEFAULT_MODEL_NOTE,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			modelNote.Size = UDim2.new(1, 0, 0, 0)
			paintModel()
			return modelButton
		end)

		forgetFetchedModels = function()
			fetched = {}
			setModelNote(DEFAULT_MODEL_NOTE, false)
		end

		-- Where the key comes from, when the preset knows. Thirteen of the seventeen
		-- presets carry a docs URL and not one of them was ever rendered.
		local presetRecord = catalog.get(editing.preset)
		if presetRecord and presetRecord.docs then
			R.paragraph(form, "Keys for this provider are issued at " .. presetRecord.docs .. ".")
		end
		if presetRecord and presetRecord.note then
			R.paragraph(form, presetRecord.note)
		end

		problemLabel = P.text(modal.content, {
			name = "Problem",
			text = "",
			role = "small",
			color = theme.color.danger,
			wrap = true,
			auto = "Y",
			visible = false,
			layoutOrder = 2,
		})
		problemLabel.Size = UDim2.new(1, 0, 0, 0)

		local testButton
		testButton = P.button(modal.footer, {
			name = "TestConnection",
			text = "Test",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			-- Through onClick, not a raw Activated connection: that is what P.button's own
			-- re-entry guard hangs off, and connecting to Activated directly meant a double
			-- tap fired two concurrent completions.
			onClick = function(handle)
				-- A completion needs a model named, so testing without one asks the endpoint
				-- a question it cannot answer -- and what comes back is that provider's own
				-- wording for "no model", which reads as a broken connection rather than as
				-- an empty field one row up.
				if editing.preset ~= "azure" and util.trim(editing.model) == "" then
					problemLabel.Text = "Choose a model first: fetch the list, or type the id."
					problemLabel.Visible = true
					return
				end
				handle.setEnabled(false)
				handle.setText("Testing")
				task.spawn(function()
					local candidate = util.deepCopy(editing)
					candidate.baseUrl = registry.normaliseBaseUrl(candidate.baseUrl)
					local result, err = chat.complete(candidate, {
						messages = { { role = "user", content = "Reply with the single word: ready" } },
						stream = false,
						maxTokens = 12,
						attempts = 1,
					})
					handle.setText("Test")
					handle.setEnabled(true)
					if result then
						overlay.toast(string.format("Reached %s in %s",
							candidate.label, util.formatDuration(result.ms)), "good")
					else
						problemLabel.Text = tostring(err)
						problemLabel.Visible = true
					end
				end)
			end,
		})

		P.button(modal.footer, {
			name = "SaveProvider",
			text = adding and "Add" or "Save",
			variant = "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				local ok, problems = registry.save(editing)
				if not ok then
					-- Sentence-cased and one per line. It was table.concat(problems, ". "),
					-- which turned two lowercase fragments into "give the provider a name.
					-- base URL is required".
					local lines = {}
					for index, problem in ipairs(problems) do
						lines[index] = problem:gsub("^%l", string.upper) .. "."
					end
					problemLabel.Text = table.concat(lines, "\n")
					problemLabel.Visible = true
					return
				end
				modal.close()
				overlay.toast("Saved " .. editing.label, "good", 2)
				if onSaved then onSaved(editing.id) end
			end,
		})

		showProblems()
		-- Nothing is wrong yet on a brand-new record; it is simply incomplete.
		if adding then problemLabel.Visible = false end
	end

	-- List and detail ---------------------------------------------------------

	function M.new(parent)
		local panel = {}
		local selected = nil

		-- Two columns where there is room for two, stacked where there is not. Same rule
		-- and same threshold as the settings dialog, which solved this first.
		local wide = responsive.mode == "window"
			and parent.AbsoluteSize.X >= (theme.size.dialogNav * 3)

		local root
		if wide then
			root = P.row(parent, { name = "ProvidersRoot", size = UDim2.fromScale(1, 1), gap = 0 })
		else
			root = P.column(parent, { name = "ProvidersRoot", size = UDim2.fromScale(1, 1), gap = 0 })
		end

		local railHolder = P.frame(root, {
			name = "ProviderRail",
			size = wide and UDim2.new(0, theme.size.dialogNav, 1, 0)
				or UDim2.new(1, 0, 0, theme.size.controlLarge + theme.space.md),
			bg = theme.color.sidebar,
			layoutOrder = 1,
		})
		local rail = P.column(railHolder, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = theme.space.xs,
		})
		local railScrollHolder = P.frame(rail, {
			size = UDim2.new(1, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 1,
		})
		local railScroll = P.scroll(railScrollHolder, {
			name = "ProviderList",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.hair,
			horizontal = not wide,
		})
		-- Under the list where there is a column to put it under, and at the end of the
		-- strip where there is not -- so there is exactly one of it either way.
		if wide then
			local addButton = P.button(rail, {
				name = "AddProvider",
				text = "Add a provider",
				variant = "secondary",
				size = "sm",
				fill = true,
				layoutOrder = 2,
				onClick = function()
					M.editor(registry.blank("custom"), function(id) panel.select(id) end)
				end,
			})
			addButton.instance.LayoutOrder = 2
		end

		P.divider(root, {
			vertical = wide,
			color = theme.color.borderSubtle,
			layoutOrder = 2,
		})

		local detailHolder = P.frame(root, {
			name = "ProviderDetail",
			size = wide and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 3,
		})
		local detail = P.scroll(detailHolder, {
			name = "DetailScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.lg,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.xl },
		})

		-- Rail -----------------------------------------------------------------

		local railRows = {}

		local function dotFor(record, isActive)
			if registry.cooling(record) then return theme.color.danger end
			if record.enabled == false then return theme.color.textDisabled end
			if isActive then return theme.color.accent end
			return theme.color.textTertiary
		end

		function panel.renderRail()
			railScroll.clear()
			railRows = {}
			local list = registry.list()
			local active = registry.active()
			for index, record in ipairs(list) do
				local isActive = active and active.id == record.id
				local row = P.rowButton(railScroll.instance, {
					name = "Provider_" .. tostring(record.id),
					size = (not wide) and UDim2.fromOffset(theme.size.menu, theme.size.controlLarge) or nil,
					height = theme.size.controlLarge,
					padding = { x = theme.space.sm },
					radius = theme.radius.md,
					selected = record.id == selected,
					layoutOrder = index,
					onClick = function() panel.select(record.id) end,
				})
				local dotSlot = P.frame(row.row, {
					name = "Health",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				local dot = P.statusDot(dotSlot, {
					diameter = theme.size.dot,
					color = dotFor(record, isActive),
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				row.label(record.label, 2,
					record.id == selected and theme.color.text or theme.color.textSecondary, "small")
				-- A badge, not text appended to the title. It used to be "  (active)"
				-- concatenated into a truncating label, so on a narrow rail the one fact
				-- that says which endpoint is in use was the first thing cut.
				if isActive then
					local badge = P.badge(row.row, { text = "Active", tone = "accent", layoutOrder = 3 })
					badge.LayoutOrder = 3
				end
				railRows[record.id] = { row = row, dot = dot }
			end
			if #list == 0 then
				local empty = P.text(railScroll.instance, {
					name = "NoProviders",
					text = "Nothing configured yet.",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = theme.space.sm, y = theme.space.xs },
					layoutOrder = 1,
				})
				empty.Size = UDim2.new(1, 0, 0, 0)
			end
			if not wide then
				-- With the rail collapsed to a strip there is no room under it for the
				-- button, so it rides at the end of the strip instead.
				local add = P.button(railScroll.instance, {
					name = "AddProvider",
					text = "Add",
					variant = "secondary",
					size = "sm",
					layoutOrder = #list + 1,
					onClick = function()
						M.editor(registry.blank("custom"), function(id) panel.select(id) end)
					end,
				})
				add.instance.LayoutOrder = #list + 1
			end
		end

		-- Detail ---------------------------------------------------------------

		local statusBox = nil

		local function order()
			panel.__order = (panel.__order or 0) + 1
			return panel.__order
		end

		local function modelMenu(record, target, onDone)
			local options = {}
			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end
			for _, id in ipairs(models.list(record)) do
				local badge = traits.badge(id)
				local bits = {}
				if badge then bits[#bits + 1] = badge end
				if not own[id] then bits[#bits + 1] = "from /models" end
				options[#options + 1] = {
					label = id,
					value = "model:" .. id,
					detail = #bits > 0 and table.concat(bits, "  \194\183  ") or nil,
					selected = id == record.model,
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = {
				label = "Fetch from /models",
				value = "fetch",
				detail = registry.endpoint(record, "/models"),
				tone = "info",
			}
			options[#options + 1] = { label = "Add a model by id", value = "add", tone = "info" }
			overlay.menu({
				target = target,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if value == "fetch" then
						overlay.toast("Fetching models from " .. record.label, "info", 2)
						task.spawn(function()
							local found, note = models.discover(record, { force = true })
							overlay.toast(tostring(note), #found > 0 and "good" or "warn", 3)
							if onDone then pcall(onDone) end
						end)
					elseif value == "add" then
						overlay.prompt({
							title = "Add a model to " .. record.label,
							description = "Type the id exactly as the provider expects it. "
								.. "It is saved to this provider and selected.",
							placeholder = "model id",
							confirmText = "Add",
							onConfirm = function(text)
								local ok, result = models.add(record, text)
								if ok then registry.setModel(record.id, util.trim(text)) end
								overlay.toast(tostring(result), ok and "good" or "warn", 3)
								if onDone then pcall(onDone) end
							end,
						})
					elseif util.startsWith(tostring(value), "model:") then
						registry.setModel(record.id, tostring(value):sub(7))
						if onDone then pcall(onDone) end
					end
				end,
			})
		end

		function panel.renderDetail()
			detail.clear()
			statusBox = nil
			panel.__order = 0
			local record = selected and registry.get(selected) or nil
			if not record then
				C.emptyState(detail.instance, {
					title = registry.count() == 0 and "No provider configured"
						or "Pick a provider on the left",
					description = registry.count() == 0
						and "Add an endpoint to start. Anything that speaks /v1/chat/completions works: "
							.. "a hosted API, a relay, or a local server reachable from this host."
						or "Its endpoint, key, model and health are all edited here.",
					action = registry.count() == 0 and "Add a provider" or nil,
					onAction = function()
						M.editor(registry.blank("custom"), function(id) panel.select(id) end)
					end,
					layoutOrder = order(),
				})
				return
			end

			local active = registry.active()
			local isActive = active and active.id == record.id

			-- Header. The window chrome already names the panel and the active provider, so
			-- this names the record being edited instead of repeating either.
			local head = P.row(detail.instance, {
				name = "DetailHead",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = order(),
			})
			local titleColumn = P.column(head, {
				size = UDim2.new(0, 0, 0, 0),
				auto = "Y",
				flex = "Fill",
				gap = theme.space.hair,
				layoutOrder = 1,
			})
			local title = P.text(titleColumn, {
				name = "ProviderTitle",
				text = record.label,
				role = "display",
				color = theme.color.text,
				wrap = true,
				auto = "Y",
			})
			title.Size = UDim2.new(1, 0, 0, 0)
			local subtitle = P.text(titleColumn, {
				text = record.baseUrl,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			subtitle.Size = UDim2.new(1, 0, 0, 0)
			if isActive then
				local badge = P.badge(head, { text = "Active", tone = "accent", layoutOrder = 2 })
				badge.LayoutOrder = 2
			end

			-- Status ------------------------------------------------------------
			local status = R.section(detail.instance, {
				name = "Status",
				title = "Status",
				description = "What this client will actually send, and how the endpoint has "
					.. "been answering.",
				layoutOrder = order(),
			})
			statusBox = R.facts(status, factsFor(record), { name = "StatusFacts", layoutOrder = 1 })

			local health = record.health or {}
			if util.trim(health.lastError or "") ~= "" then
				R.paragraph(status, health.lastError, { color = theme.color.danger, layoutOrder = 2 })
			end
			-- The preset's own guidance, which the registry copies onto every record and
			-- nothing has ever rendered: Azure's deployment-path rule, Ollama's loopback
			-- warning, DeepSeek's reasoning field.
			if util.trim(record.note or "") ~= "" then
				R.paragraph(status, record.note, { layoutOrder = 3 })
			end
			-- Fallback is a global switch, and the old header claimed the chain was always
			-- in use. Saying which it is beats asserting one of them.
			R.paragraph(status, config.get("agent.fallback", true)
				and "Requests try the active provider first, then every other enabled one."
				or "Fallback is off under Settings, so only the active provider is tried.",
				{ layoutOrder = 4 })

			local actions = {}
			if not isActive then
				actions[#actions + 1] = {
					name = "UseProvider",
					text = "Use this provider",
					variant = "primary",
					onClick = function()
						registry.setActive(record.id)
						overlay.toast(record.label .. " is now the active provider", "good", 2)
					end,
				}
			end
			actions[#actions + 1] = {
				name = "EditConnection",
				text = "Connection",
				variant = "secondary",
				onClick = function() M.editor(record, function() panel.select(record.id) end) end,
			}
			if caps.clipboard then
				actions[#actions + 1] = {
					name = "CopyEndpoint",
					text = "Copy endpoint",
					variant = "ghost",
					onClick = function()
						pcall(caps.fn.clipboard, chat.endpointOf(record))
						overlay.toast("Copied", "good", 1.5)
					end,
				}
			end
			R.actions(status, actions, { name = "StatusActions", layoutOrder = 5 })

			-- Model -------------------------------------------------------------
			local modelSection = R.section(detail.instance, {
				name = "Model",
				title = "Model",
				description = "Only what the endpoint reported and what you added -- never a guess, "
					.. "so this can legitimately be empty until one of those has happened.",
				layoutOrder = order(),
			})
			local known = models.list(record)
			R.select(modelSection, {
				name = "ActiveModel",
				label = "Active model",
				hint = #known == 0 and "Nothing known yet. Fetch the list, or add an id by hand."
					or (traits.badge(record.model) and ("Context window " .. traits.badge(record.model))
						or "No published context window for this id."),
				options = (function()
					local out = {}
					for _, id in ipairs(known) do out[#out + 1] = { value = id, label = id } end
					if #out == 0 then
						out[#out + 1] = { value = record.model, label = record.model ~= "" and record.model or "none" }
					end
					return out
				end)(),
				value = record.model ~= "" and record.model or (known[1] or ""),
				width = theme.size.menu,
				onChange = function(value) registry.setModel(record.id, value) end,
			})
			R.actions(modelSection, {
				{
					name = "ManageModels",
					text = #known == 0 and "Fetch or add a model" or "Fetch, add or remove",
					variant = "secondary",
					onClick = function(handle)
						modelMenu(record, handle.instance, function() panel.select(record.id) end)
					end,
				},
			}, { name = "ModelActions" })

			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end
			for index, id in ipairs(known) do
				local row = P.rowButton(modelSection, {
					name = "Model_" .. tostring(index),
					height = theme.size.rowSmall,
					padding = { x = theme.space.sm },
					radius = theme.radius.sm,
					selected = id == record.model,
					layoutOrder = 100 + index,
					onClick = function()
						registry.setModel(record.id, id)
						panel.select(record.id)
					end,
				})
				local slot = P.frame(row.row, {
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				P.statusDot(slot, {
					diameter = theme.size.dot,
					color = id == record.model and theme.color.accent or theme.color.borderStrong,
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				row.label(id, 2, id == record.model and theme.color.text or theme.color.textSecondary,
					"monoSmall")
				if not own[id] then
					local mark = P.badge(row.row, { text = "fetched", layoutOrder = 3 })
					mark.LayoutOrder = 3
				end
				if own[id] and #known > 1 then
					local remove = P.iconButton(row.row, {
						name = "RemoveModel",
						icon = "close",
						diameter = theme.size.rowSmall,
						variant = "ghost",
						layoutOrder = 4,
						onClick = function()
							models.remove(record, id)
							panel.select(record.id)
						end,
					})
					remove.instance.LayoutOrder = 4
				end
			end

			-- Behaviour ---------------------------------------------------------
			local behaviour = R.section(detail.instance, {
				name = "Behaviour",
				title = "Behaviour",
				description = "Per-provider switches. Each one can only narrow what the matching "
					.. "global setting allows: turning one off always takes effect, turning it on "
					.. "needs the global on as well.",
				layoutOrder = order(),
			})
			R.toggle(behaviour, {
				name = "Enabled",
				label = "Enabled",
				hint = "A disabled provider is skipped by the fallback chain. Disabling the active "
					.. "one leaves it flagged active while requests go elsewhere.",
				value = record.enabled ~= false,
				layoutOrder = 1,
				onChange = function(value)
					record.enabled = value
					registry.save(record, { force = true })
				end,
			})
			R.toggle(behaviour, {
				name = "Stream",
				label = "Ask for a stream",
				hint = "Streamed replies carry reasoning text and token counts. Turning this off "
					.. "always takes effect; turning it on only does while Settings has streaming on.",
				value = record.stream ~= false,
				layoutOrder = 2,
				onChange = function(value)
					record.stream = value
					registry.save(record, { force = true })
				end,
			})
			R.toggle(behaviour, {
				name = "ClaudeUa",
				label = "Send the Claude Code identity",
				hint = "The claude-cli User-Agent and its client headers. Turning this off suppresses "
					.. "the whole set for this endpoint whatever the global switch says, which is the "
					.. "one lever this client has when a CDN in front of an API refuses the request.",
				value = record.claudeUa ~= false,
				layoutOrder = 3,
				onChange = function(value)
					record.claudeUa = value
					registry.save(record, { force = true })
				end,
			})

			-- Transport and the three invisible maps -----------------------------
			local advanced = R.section(detail.instance, {
				name = "Advanced",
				title = "Transport",
				description = "The socket URL, and the extra headers, body fields and query "
					.. "parameters this record sends. All three were stored and none were shown, "
					.. "which is why Azure's api-version and OpenRouter's attribution headers "
					.. "could not be inspected or corrected from here.",
				layoutOrder = order(),
			})
			R.field(advanced, {
				name = "SocketUrl",
				label = "Socket URL",
				hint = "Optional. A wss:// endpoint for streamed completions, which is what lifts "
					.. "the one-minute ceiling on a long reply.",
				value = record.wsUrl or "",
				placeholder = "wss://api.example.com/v1",
				layoutOrder = 1,
				onChange = function(text)
					record.wsUrl = util.trim(text)
					registry.save(record, { force = true })
				end,
			})

			local extras = {}
			for _, group in ipairs({
				{ field = "headers", label = "header" },
				{ field = "params", label = "body field" },
				{ field = "query", label = "query" },
			}) do
				for _, key in ipairs(util.keys(record[group.field] or {}, true)) do
					extras[#extras + 1] = {
						key = group.label .. " " .. tostring(key),
						value = tostring(record[group.field][key]),
					}
				end
			end
			if #extras > 0 then
				R.facts(advanced, extras, { name = "ExtraFacts", layoutOrder = 4 })
			else
				R.paragraph(advanced, "No extra headers, body fields or query parameters.",
					{ layoutOrder = 4 })
			end

			-- Fallback order ----------------------------------------------------
			local list = registry.list()
			if #list > 1 then
				local position = 1
				for index, entry in ipairs(list) do
					if entry.id == record.id then position = index end
				end
				local ordering = R.section(detail.instance, {
					name = "Order",
					title = "Fallback order",
					description = string.format(
						"Position %d of %d. When the active provider fails, the chain walks this list "
						.. "in order. registry.reorder has existed since the beginning with no control "
						.. "attached to it.", position, #list),
					layoutOrder = order(),
				})
				local moves = {}
				if position > 1 then
					moves[#moves + 1] = {
						name = "MoveUp",
						text = "Move up",
						variant = "secondary",
						onClick = function() registry.reorder(record.id, -1) end,
					}
				end
				if position < #list then
					moves[#moves + 1] = {
						name = "MoveDown",
						text = "Move down",
						variant = "secondary",
						onClick = function() registry.reorder(record.id, 1) end,
					}
				end
				R.actions(ordering, moves, { name = "OrderActions" })
			end

			-- Removal -----------------------------------------------------------
			local danger = R.section(detail.instance, {
				name = "Remove",
				title = "Remove",
				description = "The endpoint and its key are deleted from this device. This cannot "
					.. "be undone.",
				layoutOrder = order(),
			})
			R.actions(danger, {
				{
					name = "RemoveProvider",
					text = "Remove " .. record.label,
					-- The danger variant, which exists for exactly this and which every other
					-- destructive control in the app already uses. This one was a ghost button
					-- sitting between Edit and nothing.
					variant = "danger",
					onClick = function()
						-- Says what happens next. registry.remove silently promotes the first
						-- remaining record when the active one goes, and the old confirmation
						-- did not mention it.
						local successor = nil
						for _, entry in ipairs(registry.list()) do
							if entry.id ~= record.id and not successor then successor = entry end
						end
						local description = "The endpoint and its key are deleted from this device."
						if isActive and successor then
							description = description .. " " .. successor.label
								.. " becomes the active provider."
						elseif isActive then
							description = description .. " No provider will be configured afterwards."
						end
						overlay.confirm({
							title = "Remove " .. record.label .. "?",
							description = description,
							confirmText = "Remove",
							danger = true,
							onConfirm = function()
								registry.remove(record.id)
								panel.select(successor and successor.id or nil)
							end,
						})
					end,
				},
			}, { name = "DangerActions" })
		end

		-- Wiring ---------------------------------------------------------------

		function panel.select(id)
			local list = registry.list()
			if id and registry.get(id) then
				selected = id
			else
				local active = registry.active()
				selected = (active and active.id) or (list[1] and list[1].id) or nil
			end
			panel.renderRail()
			panel.renderDetail()
			detail.instance.CanvasPosition = Vector2.new(0, 0)
		end

		-- Health arrives on every single completion, and the panel used to rebuild
		-- itself from scratch each time -- header, rail, detail, scroll position, and the
		-- enable switch mid-animation. Only the facts block and the rail dots can change
		-- for a health event, so only those are repainted.
		local function repaintHealth()
			local record = selected and registry.get(selected) or nil
			local active = registry.active()
			for id, entry in pairs(railRows) do
				local candidate = registry.get(id)
				if candidate and entry.dot.Parent then
					entry.dot.BackgroundColor3 = dotFor(candidate, active and active.id == id)
				end
			end
			if record and statusBox and statusBox.Parent then
				local replacement = R.facts(statusBox.Parent, factsFor(record),
					{ name = "StatusFacts", layoutOrder = 1 })
				pcall(function() statusBox:Destroy() end)
				statusBox = replacement
			end
		end

		panel.select(nil)

		panel.unsubscribe = registry.changed:connect(function(reason)
			if not root.Parent then return end
			if reason == "health" then
				repaintHealth()
			else
				panel.select(selected)
			end
		end)
		root.Destroying:Connect(function() pcall(panel.unsubscribe) end)

		panel.root = root
		panel.scroll = detail
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settings
-- ==========================================================================
__UAI_MODULES["ui/panels/settings"] = (function()
-- The Settings panel: every pane, stacked in one scroll.
--
-- The panes themselves live in ui/settingspanes, because the settings dialog the
-- sidebar opens shows the same ones behind a category list. This surface is the one
-- that shows all of them at once, which is what a panel in a five-panel client is
-- for -- and it means a setting cannot exist in one place and not the other.
return function(env)
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local panes = env.require("ui/settingspanes")

	local M = {}

	function M.new(parent)
		local panel = {}
		local scroll = P.scroll(parent, {
			name = "Settings",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.lg,
			padding = theme.space.md,
		})

		for index, entry in ipairs(panes.PANES) do
			local column = P.column(scroll.instance, {
				name = "Pane_" .. entry.id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = index,
			})
			panes.render(entry.id, column)
		end

		panel.scroll = scroll
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settingsdialog
-- ==========================================================================
__UAI_MODULES["ui/panels/settingsdialog"] = (function()
-- The settings dialog: a category list on the left, one pane on the right.
--
-- The same panes the Settings panel stacks, shown one at a time -- so this is a
-- different arrangement of the same settings rather than a second set. The one it is
-- modelled on opens from the profile menu and from Customize, and both of those land
-- here on a named category.
return function(env)
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local panes = env.require("ui/settingspanes")

	local M = {}

	function M.open(initial)
		local dialog = overlay.dialog({ name = "SettingsDialog" })
		if not dialog then return nil end

		-- On a phone the two panes do not fit side by side, so the list collapses to a
		-- row of categories above the pane rather than being cut off.
		local narrow = dialog.width < (theme.size.dialogNav * 3)
		local navWidth = narrow and dialog.width or theme.size.dialogNav
		-- The height of the collapsed category strip, and therefore the offset of
		-- everything under it. It was this same sum written out four times.
		local stripHeight = theme.size.controlLarge + theme.space.md
		-- The corner the dialog's own close button occupies. Reserved rather than drawn
		-- under: with the strip spanning the full width, the button sat on top of the last
		-- category and nothing could reach it.
		local closeInset = dialog.closeInset or theme.space.xxl

		local navHolder = P.frame(dialog.card, {
			name = "DialogNav",
			size = narrow and UDim2.new(1, 0, 0, stripHeight)
				or UDim2.new(0, navWidth, 1, 0),
			bg = theme.color.sidebar,
		})
		local nav = P.scroll(navHolder, {
			name = "Categories",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.hair,
			padding = {
				left = theme.space.xs,
				right = narrow and closeInset or theme.space.xs,
				y = theme.space.xs,
			},
			horizontal = narrow,
		})

		P.frame(dialog.card, {
			name = "DialogDivider",
			size = narrow and UDim2.new(1, 0, 0, theme.stroke.hair) or UDim2.new(0, theme.stroke.hair, 1, 0),
			position = narrow and UDim2.new(0, 0, 0, stripHeight)
				or UDim2.new(0, navWidth, 0, 0),
			bg = theme.color.borderSubtle,
		})

		local bodyHolder = P.frame(dialog.card, {
			name = "DialogBody",
			size = narrow and UDim2.new(1, 0, 1, -(stripHeight + theme.stroke.hair))
				or UDim2.new(1, -(navWidth + theme.stroke.hair), 1, 0),
			position = narrow and UDim2.new(0, 0, 0, stripHeight + theme.stroke.hair)
				or UDim2.new(0, navWidth + theme.stroke.hair, 0, 0),
		})
		local body = P.scroll(bodyHolder, {
			name = "PaneScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.md,
			padding = {
				left = theme.space.lg,
				-- Wide layouts put the close button over the top of this pane, so the first
				-- row's right edge has to clear it.
				right = narrow and theme.space.lg or closeInset,
				top = theme.space.lg,
				bottom = theme.space.xl,
			},
		})

		local rows = {}
		local active = nil

		local function select(id)
			if not panes.pane(id) then return end
			active = id
			for key, row in pairs(rows) do
				row.setSelected(key == id)
				row.text.TextColor3 = (key == id) and theme.color.text or theme.color.textSecondary
			end
			body.clear()
			local column = P.column(body.instance, {
				name = "Pane_" .. id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = 1,
			})
			panes.render(id, column)
			body.instance.CanvasPosition = Vector2.new(0, 0)
		end

		local order = 0
		local function nextOrder()
			order = order + 1
			return order
		end

		for _, section in ipairs(panes.sections()) do
			-- The section headings are the list's own structure and are not clickable, so
			-- on a narrow layout -- where the list is one horizontal strip -- they are
			-- left out rather than turned into unreachable furniture.
			if not narrow then
				local heading = P.text(nav.instance, {
					name = "Section_" .. section.title,
					text = section.title,
					role = "caption",
					color = theme.color.textTertiary,
					truncate = true,
					size = UDim2.new(1, 0, 0, theme.text.caption.height + theme.space.xs),
					padding = { x = theme.space.xs, top = theme.space.xs },
					layoutOrder = nextOrder(),
				})
				heading.Name = "Section_" .. section.title
			end
			for _, entry in ipairs(section.panes) do
				local row = P.rowButton(nav.instance, {
					name = "Category_" .. entry.id,
					size = narrow and UDim2.fromOffset(theme.size.menu, theme.size.rowSmall) or nil,
					layoutOrder = nextOrder(),
					onClick = function()
						select(entry.id)
					end,
				})
				row.icon(entry.icon, 1, theme.color.textSecondary, theme.size.icon)
				row.text = row.label(entry.label, 2, theme.color.textSecondary, "small")
				rows[entry.id] = row
			end
		end

		select(panes.pane(initial) and initial or panes.PANES[1].id)

		dialog.select = select
		dialog.activeCategory = function() return active end
		return dialog
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/tools
-- ==========================================================================
__UAI_MODULES["ui/panels/tools"] = (function()
-- Tools panel: what the agent can do here, and what it is allowed to do.
--
-- Permission rules live next to the tool they govern rather than in a separate
-- list, because "can it delete files" is a question about file_delete, not about a
-- rules table.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local registry = env.require("agent/registry")
	local permissions = env.require("agent/permissions")
	local schema = env.require("agent/schema")

	local M = {}

	local RULE_OPTIONS = {
		{ value = "default", label = "Default" },
		{ value = "allow", label = "Allow" },
		{ value = "ask", label = "Ask" },
		{ value = "deny", label = "Deny" },
	}

	local GROUP_LABELS = registry.GROUP_LABELS

	function M.new(parent)
		local panel = {}
		local filter = ""

		local column = P.column(parent, {
			name = "ToolsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.md, top = theme.space.md, bottom = theme.space.sm },
			layoutOrder = 1,
		})

		local stats = registry.stats()
		P.text(head, {
			text = string.format("%d tools in %d groups", stats.total, util.count(stats.byGroup)),
			role = "heading",
			layoutOrder = 1,
		})
		local summary = P.text(head, {
			text = string.format("%d unavailable on this host: %s",
				#stats.unavailable,
				#stats.unavailable > 0 and caps.summary() or "everything is available"),
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		summary.Size = UDim2.new(1, 0, 0, 0)

		local scroll

		local function rebuild()
			scroll.clear()
			local needle = filter:lower()
			local grouped = {}
			for _, tool in ipairs(registry.list()) do
				if needle == ""
					or tool.name:lower():find(needle, 1, true)
					or tostring(tool.description):lower():find(needle, 1, true) then
					grouped[tool.group] = grouped[tool.group] or {}
					table.insert(grouped[tool.group], tool)
				end
			end

			local order = util.keys(grouped, true)
			if #order == 0 then
				C.emptyState(scroll.instance, {
					title = "No tool matches",
					description = "Try a shorter search.",
					layoutOrder = 1,
				})
				return
			end

			local position = 0
			for _, group in ipairs(order) do
				position = position + 1
				-- The group header carries its own switch: turning a family off removes it
				-- from the list the model is sent, which is a different thing from denying
				-- a call and belongs next to the family rather than in a settings pane.
				local header = P.row(scroll.instance, {
					name = "Group_" .. tostring(group),
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.sm,
					-- The same inset a card gives its own contents, so a group's name lines up
					-- with the tool names under it instead of sitting sixteen pixels to their
					-- left, and its switch lines up with theirs.
					padding = { x = theme.space.lg },
					layoutOrder = position,
				})
				local headText = P.column(header, {
					size = UDim2.new(0, 0, 0, 0),
					auto = "Y",
					flex = "Fill",
					gap = 0,
					layoutOrder = 1,
				})
				P.text(headText, {
					text = GROUP_LABELS[group] or group,
					role = "label",
					color = theme.color.text,
					auto = "Y",
					wrap = true,
				})
				local groupNote = P.text(headText, {
					text = "",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				local function describeGroup()
					groupNote.Text = registry.groupEnabled(group)
						and util.pluralise(#grouped[group], "tool")
						or (util.pluralise(#grouped[group], "tool") .. ", not offered to the model")
				end
				describeGroup()
				local groupSwitch = C.switch(header, {
					value = registry.groupEnabled(group),
					onChange = function(value)
						registry.setGroupEnabled(group, value)
						describeGroup()
					end,
				})
				groupSwitch.instance.LayoutOrder = 2

				for _, tool in ipairs(grouped[group]) do
					position = position + 1
					local missing = registry.missingCapability(tool)
					local card = P.card(scroll.instance, {
						name = tool.name,
						layoutOrder = position,
						gap = theme.space.xs,
					})

					local top = P.row(card, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						gap = theme.space.xs,
						layoutOrder = 1,
					})
					local name = P.text(top, {
						text = tool.name,
						role = "monoSmall",
						color = missing and theme.color.textDisabled or theme.color.text,
						layoutOrder = 1,
					})
					name.Size = UDim2.fromOffset(0, theme.text.monoSmall.height)
					name.AutomaticSize = Enum.AutomaticSize.X

					P.badge(top, {
						text = tool.risk,
						tone = tool.risk == "read" and "info" or (tool.risk == "danger" and "bad" or "warn"),
						layoutOrder = 2,
					})
					if missing then
						P.badge(top, { text = "unavailable", tone = "warn", layoutOrder = 3 })
					end

					local description = P.text(card, {
						text = tostring(tool.description),
						role = "caption",
						color = theme.color.textSecondary,
						wrap = true,
						auto = "Y",
						layoutOrder = 2,
					})
					description.Size = UDim2.new(1, 0, 0, 0)

					local params = P.text(card, {
						text = schema.describe(tool.parameters),
						role = "caption",
						color = theme.color.textTertiary,
						wrap = true,
						auto = "Y",
						layoutOrder = 3,
					})
					params.Size = UDim2.new(1, 0, 0, 0)

					if missing then
						local reason = P.text(card, {
							text = caps.reason(missing),
							role = "caption",
							color = theme.color.warn,
							wrap = true,
							auto = "Y",
							layoutOrder = 4,
						})
						reason.Size = UDim2.new(1, 0, 0, 0)
					else
						C.segmented(card, {
							options = RULE_OPTIONS,
							value = permissions.ruleFor(tool.name) or "default",
							layoutOrder = 4,
							onChange = function(value)
								permissions.setRule(tool.name, value)
							end,
						})
					end
				end
			end
		end

		-- Third in the head block, stated rather than left to the tie-break: the two
		-- labels above it are constructed earlier but neither of them sets an order.
		P.field(head, {
			name = "ToolSearch",
			placeholder = "Search tools",
			layoutOrder = 3,
			onChange = function(text)
				filter = util.trim(text)
				rebuild()
			end,
		})

		scroll = P.scroll(column, {
			name = "ToolList",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.sm,
			-- Top padding as well. Without it the first group header butted against the
			-- head block above it while the bottom of the list had twelve pixels of air.
			padding = { x = theme.space.md, top = theme.space.sm, bottom = theme.space.lg },
			layoutOrder = 2,
		})
		local flex = Instance.new("UIFlexItem", scroll.instance)
		flex.FlexMode = Enum.UIFlexMode.Fill

		rebuild()
		panel.refresh = rebuild
		panel.unsubscribe = permissions.changed:connect(rebuild)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/primitives
-- ==========================================================================
__UAI_MODULES["ui/primitives"] = (function()
-- Layout and interaction primitives.
--
-- Everything visible is built from these, and they all take the same shape of
-- props table, so a panel reads as a description of what it is rather than a
-- hundred lines of instance plumbing. Three rules are enforced here rather than
-- left to each caller: nothing is positioned by hand-computed offsets, every
-- interactive element has a full state set, and every hit target respects the
-- platform minimum.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")

	local P = {}

	-- Shared helpers ---------------------------------------------------------

	function P.corner(instance, radius)
		local corner = Instance.new("UICorner", instance)
		corner.CornerRadius = UDim.new(0, radius == nil and theme.radius.md or radius)
		return corner
	end

	function P.stroke(instance, colour, thickness)
		local stroke = Instance.new("UIStroke", instance)
		stroke.Color = colour or theme.color.borderSubtle
		stroke.Thickness = thickness or theme.stroke.hair
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		return stroke
	end

	function P.pad(instance, spec)
		local padding = Instance.new("UIPadding", instance)
		if type(spec) == "number" then
			padding.PaddingTop = UDim.new(0, spec)
			padding.PaddingBottom = UDim.new(0, spec)
			padding.PaddingLeft = UDim.new(0, spec)
			padding.PaddingRight = UDim.new(0, spec)
		elseif type(spec) == "table" then
			local x = spec.x or spec.horizontal
			local y = spec.y or spec.vertical
			padding.PaddingTop = UDim.new(0, spec.top or y or 0)
			padding.PaddingBottom = UDim.new(0, spec.bottom or y or 0)
			padding.PaddingLeft = UDim.new(0, spec.left or x or 0)
			padding.PaddingRight = UDim.new(0, spec.right or x or 0)
		end
		return padding
	end

	local AUTO = {
		X = Enum.AutomaticSize.X,
		Y = Enum.AutomaticSize.Y,
		XY = Enum.AutomaticSize.XY,
	}

	-- Applies the props every visual element shares. Kept in one place so adding a
	-- shared concern (a token, an accessibility flag) is one edit.
	local function base(instance, props)
		props = props or {}
		if props.name then instance.Name = props.name end
		instance.BorderSizePixel = 0
		if props.size then instance.Size = props.size end
		if props.position then instance.Position = props.position end
		if props.anchor then instance.AnchorPoint = props.anchor end
		if props.auto then instance.AutomaticSize = AUTO[props.auto] or Enum.AutomaticSize.None end
		if props.zIndex then instance.ZIndex = props.zIndex end
		if props.layoutOrder then instance.LayoutOrder = props.layoutOrder end
		if props.clip ~= nil then instance.ClipsDescendants = props.clip == true end
		if props.visible ~= nil then instance.Visible = props.visible == true end
		if props.rotation then instance.Rotation = props.rotation end

		if props.bg then
			instance.BackgroundColor3 = props.bg
			instance.BackgroundTransparency = props.bgTransparency or 0
		else
			instance.BackgroundTransparency = 1
		end
		if props.radius ~= nil then P.corner(instance, props.radius) end
		if props.stroke then P.stroke(instance, props.strokeColor, props.strokeWidth) end
		if props.padding then P.pad(instance, props.padding) end
		if props.minSize or props.maxSize then
			local constraint = Instance.new("UISizeConstraint", instance)
			if props.minSize then constraint.MinSize = props.minSize end
			if props.maxSize then constraint.MaxSize = props.maxSize end
		end
		if props.aspect then
			Instance.new("UIAspectRatioConstraint", instance).AspectRatio = props.aspect
		end
		if props.flex then
			local item = Instance.new("UIFlexItem", instance)
			item.FlexMode = Enum.UIFlexMode[props.flex] or Enum.UIFlexMode.Fill
		end
		return instance
	end

	function P.frame(parent, props)
		local frame = Instance.new("Frame", parent)
		return base(frame, props)
	end

	local function stack(parent, props, direction)
		props = props or {}
		local frame = P.frame(parent, props)
		local layout = Instance.new("UIListLayout", frame)
		layout.FillDirection = direction
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX or "Left"]
		layout.VerticalAlignment = Enum.VerticalAlignment[props.alignY or "Top"]
		if props.wrap then layout.Wraps = true end
		if props.stretch then layout.ItemLineAlignment = Enum.ItemLineAlignment.Stretch end
		return frame, layout
	end

	function P.column(parent, props)
		return stack(parent, props, Enum.FillDirection.Vertical)
	end

	function P.row(parent, props)
		props = props or {}
		props.alignY = props.alignY or "Center"
		return stack(parent, props, Enum.FillDirection.Horizontal)
	end

	-- A gap, or -- with `grow` -- whatever is left over on the line.
	--
	-- A growing spacer starts at nothing. UIFlexItem.Grow only ever hands out the
	-- space a line has left, and it never shrinks a child below its own size, so a
	-- spacer that began at full width left nothing over and pushed every sibling
	-- after it past the parent's edge. That is how a profile row loses its chevron
	-- and a card header loses its right-hand pills.
	function P.spacer(parent, props)
		props = props or {}
		local size = props.size
		if not size then
			if props.grow then
				size = UDim2.fromOffset(0, 0)
			else
				size = UDim2.new(1, 0, 0, props.height or theme.space.sm)
			end
		end
		local frame = P.frame(parent, {
			name = "Spacer",
			size = size,
			layoutOrder = props.layoutOrder,
		})
		if props.grow then
			local item = Instance.new("UIFlexItem", frame)
			item.FlexMode = Enum.UIFlexMode.Grow
		end
		return frame
	end

	function P.divider(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Divider",
			size = props.vertical and UDim2.new(0, 1, 1, 0) or UDim2.new(1, 0, 0, 1),
			bg = props.color or theme.color.borderSubtle,
			layoutOrder = props.layoutOrder,
		})
	end

	-- Text -------------------------------------------------------------------

	-- `size` is the UDim2 every element shares; the font size comes from the role,
	-- or from `textSize` when one label genuinely has to differ. Overloading `size`
	-- for both would assign a number to Size, which Roblox rejects outright.
	--
	-- Two font properties, applied in order. `Font` is the legacy enum and always
	-- takes; `FontFace` is the modern family-plus-weight pair and is layered over it
	-- only when the theme resolved one, so a client without the newer type stack keeps
	-- rendering rather than being assigned nil. Assigning Font *after* FontFace would
	-- undo it -- the two are the same underlying property with different resolutions --
	-- which is why the order here is not arbitrary.
	local function applyFont(label, role, props)
		label.Font = props.font or role.font
		if props.font then return end
		local face = props.face or role.face
		if face then pcall(function() label.FontFace = face end) end
	end

	function P.text(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local label = Instance.new("TextLabel", parent)
		base(label, props)
		label.Text = tostring(props.text or "")
		label.TextColor3 = props.color or theme.color.text
		applyFont(label, role, props)
		label.TextSize = props.textSize or role.size
		label.LineHeight = props.line or role.line
		label.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		label.TextYAlignment = Enum.TextYAlignment[props.alignY or "Center"]
		label.TextWrapped = props.wrap == true
		label.RichText = props.rich == true
		if props.transparency then label.TextTransparency = props.transparency end
		if props.truncate then label.TextTruncate = Enum.TextTruncate.AtEnd end
		-- A label with no explicit size collapses to nothing inside a list layout,
		-- which is the single most common way an interface silently loses text.
		-- `auto` only covers the axes it names, so it does not save us here: with
		-- `auto = "Y"` the width is still ours to set, and a zero-width label does
		-- not vanish so much as wrap to one character per line -- the same bug
		-- wearing a costume that reads as a rendering glitch instead of a layout one.
		-- The caller owns the width only when `auto` includes X.
		if not props.size then
			if props.auto == "XY" then
				label.Size = UDim2.fromOffset(0, 0)
			elseif props.auto == "X" then
				-- Width from the text, height from the role. A zero on both axes is what
				-- `auto = "X"` used to produce, and AutomaticSize.X grows the width only --
				-- so the label came out one rendered line wide and no pixels tall, which
				-- is a label that is not there at all. Twenty-odd call sites papered over
				-- it by assigning Size on the next line; the ones that forgot simply
				-- vanished.
				label.Size = UDim2.fromOffset(0, role.height or (role.size + 4))
			elseif props.auto == "Y" then
				label.Size = UDim2.new(1, 0, 0, 0)
			else
				-- One rendered line plus a little slack. Sized from the role's line
				-- height, not its font size: at a 1.5 line height the two differ by
				-- seven pixels and the descenders go missing.
				local single = props.textSize and math.ceil(props.textSize * (props.line or role.line))
					or role.height or (role.size + 4)
				label.Size = UDim2.new(1, 0, 0, single + 4)
			end
		end
		return label
	end

	-- A heading with an optional trailing description, which is the pattern every
	-- settings group uses.
	--
	-- Sentence case, not upper. Small-caps headings were doing the work of separating
	-- groups, and spacing does that better: SHOUTED LABELS every hundred pixels are
	-- what makes an interface read as a control panel rather than as a page.
	function P.sectionHeader(parent, props)
		local holder = P.column(parent, {
			name = "Section",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = props.layoutOrder,
		})
		P.text(holder, {
			text = tostring(props.title or ""),
			role = "label",
			color = theme.color.text,
			auto = "Y",
			wrap = true,
		})
		if props.description then
			P.text(holder, {
				text = props.description,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
		end
		return holder
	end

	-- Interaction ------------------------------------------------------------

	-- Button variants.
	--
	-- `primary` is a cream fill with dark text rather than an accent fill. There is
	-- normally one of them per view -- send, save, confirm -- and making it the
	-- brightest thing on the page rather than the most colourful is what leaves the
	-- accent free to mean something: inline code, a running turn, a risk level. Use
	-- `accent` when the colour itself is the message.
	local VARIANTS = {
		primary = function()
			return {
				bg = theme.color.solid, bgHover = theme.color.solidHover, bgPress = theme.color.solidPress,
				text = theme.color.onSolid, stroke = nil, font = "bodyStrong",
			}
		end,
		accent = function()
			return {
				bg = theme.color.accent, bgHover = theme.color.accentHot, bgPress = theme.color.accentMuted,
				text = theme.color.textOnAccent, stroke = nil, font = "bodyStrong",
			}
		end,
		-- No fill at rest, only a hairline. A dark-grey fill on a dark-grey panel adds
		-- a rectangle without adding contrast; the outline is what says "control".
		secondary = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.text, stroke = theme.color.border, font = "bodyStrong",
			}
		end,
		ghost = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.textSecondary, stroke = nil, font = "body",
			}
		end,
		-- Text and outline only until it is pressed. A pre-filled danger button reads
		-- as already-dangerous and gets clicked past; the fill arriving on hover is the
		-- moment it is worth noticing.
		danger = function()
			return {
				bg = nil, bgHover = theme.color.dangerSurface, bgPress = theme.color.danger,
				text = theme.color.danger, textHover = theme.color.danger,
				stroke = theme.color.dangerBorder, font = "bodyStrong",
			}
		end,
	}

	local HEIGHTS = { sm = "controlSmall", md = "control", lg = "controlLarge" }

	-- One button implementation with a full state set: rest, hover, press, focus,
	-- disabled and loading. Roblox gives none of that, and a project that hand-rolls
	-- it per call site ends up with buttons that behave differently from each other.
	function P.button(parent, props)
		props = props or {}
		local variant = (VARIANTS[props.variant or "secondary"])()
		local height = math.max(theme.size[HEIGHTS[props.size or "md"]], responsive.minTarget())
		-- A button with neither a fixed width nor fill sizes to its label. That means
		-- the content row has to size to its own children too: AutomaticSize ignores
		-- a child whose width is a scale, so a (1, 0) row inside an auto-width button
		-- collapses the button to nothing.
		local autoWidth = not props.width and not props.fill

		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Button",
			size = props.width and UDim2.new(0, props.width, 0, height)
				or (props.fill and UDim2.new(1, 0, 0, height) or UDim2.new(0, 0, 0, height)),
			auto = autoWidth and "X" or nil,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			bg = variant.bg,
			radius = props.radius or theme.radius.md,
			zIndex = props.zIndex,
		})
		if variant.stroke then P.stroke(button, variant.stroke) end
		if not variant.bg then button.BackgroundTransparency = 1 end

		local content, layout = P.row(button, {
			name = "Content",
			size = autoWidth and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 1, 0),
			auto = autoWidth and "X" or nil,
			gap = theme.space.xs,
			alignX = props.align or "Center",
			alignY = "Center",
			-- `padX` for the caller that has to line this button's label up with something
			-- outside it: a full-width ghost row under a block of code has to start where
			-- the code starts, and the default is the button's own inset, not that block's.
			padding = { x = props.padX or (props.tight and theme.space.xs or theme.space.md) },
		})
		layout.SortOrder = Enum.SortOrder.LayoutOrder

		local icons = env.require("ui/icons")
		local iconHolder
		if props.icon then
			iconHolder = P.frame(content, {
				name = "IconSlot",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 1,
			})
			icons.draw(props.icon, iconHolder, theme.size.icon, props.iconColor or variant.text, props.iconDirection)
		end

		local label
		if props.text and props.text ~= "" then
			label = P.text(content, {
				text = props.text,
				role = variant.font,
				color = variant.text,
				align = "Center",
				auto = "XY",
				layoutOrder = 2,
			})
			label.Size = UDim2.fromOffset(0, 0)
		end

		local handle = { instance = button, label = label, enabled = true, busy = false }

		local function paint(state)
			local target = variant.bg
			local textColour = variant.text
			if not handle.enabled then
				target = theme.color.surfaceRaised
				textColour = theme.color.textDisabled
			elseif state == "hover" then
				target = variant.bgHover or variant.bg
				textColour = variant.textHover or variant.text
			elseif state == "press" then
				target = variant.bgPress or variant.bgHover or variant.bg
				textColour = variant.textHover or variant.text
			end
			if target then
				button.BackgroundTransparency = 0
				env.tween:Create(button, theme.tween("hover"), { BackgroundColor3 = target }):Play()
			else
				env.tween:Create(button, theme.tween("hover"), { BackgroundTransparency = 1 }):Play()
			end
			if label then
				env.tween:Create(label, theme.tween("hover"), { TextColor3 = textColour }):Play()
			end
		end

		button.MouseEnter:Connect(function() if handle.enabled then paint("hover") end end)
		button.MouseLeave:Connect(function() paint("rest") end)
		button.MouseButton1Down:Connect(function() if handle.enabled then paint("press") end end)
		button.MouseButton1Up:Connect(function() if handle.enabled then paint("hover") end end)
		-- Gamepad focus has to look like hover or a console user cannot see where
		-- they are.
		button.SelectionGained:Connect(function() if handle.enabled then paint("hover") end end)
		button.SelectionLost:Connect(function() paint("rest") end)

		button.Activated:Connect(function()
			if not handle.enabled or handle.busy then return end
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then
					env.require("runtime/log").warn("ui", "button handler failed", err)
				end
			end
		end)

		function handle.setEnabled(value)
			handle.enabled = value ~= false
			button.Active = handle.enabled
			button.Selectable = handle.enabled
			paint("rest")
		end

		function handle.setText(text)
			if label then label.Text = tostring(text) end
		end

		function handle.setVariant(name)
			variant = (VARIANTS[name] or VARIANTS.secondary)()
			paint("rest")
		end

		paint("rest")
		return handle
	end

	function P.iconButton(parent, props)
		props = props or {}
		local size = math.max(props.diameter or theme.size.control, responsive.minTarget())
		-- Shallow, deliberately. `util.merge` deep-copies, and a deep copy of a UDim2 or
		-- a Vector2 is a plain table with the same fields and none of the type -- so an
		-- icon button given a position lost it, silently, on the way through.
		local merged = util.copy(props)
		merged.variant = props.variant or "ghost"
		merged.text = nil
		merged.width = size
		merged.tight = true
		merged.radius = props.radius or theme.radius.md
		local handle = P.button(parent, merged)
		handle.instance.Size = UDim2.fromOffset(size, size)
		handle.instance.AutomaticSize = Enum.AutomaticSize.None
		return handle
	end

	-- A whole row that is one hit target, with the row's own layout inside it.
	--
	-- The wrong way to make a row clickable -- and the way most of the rows in the
	-- sidebar, the composer and the settings dialog were built -- is to drop a
	-- transparent full-size TextButton into the row alongside its contents. A
	-- UIListLayout does not layer its children, it lays them out: the button takes a
	-- full-width slot of its own and pushes the icon and the label it was meant to
	-- cover out past the row's right edge, where they are still drawn because nothing
	-- clips them. What that renders as is an empty pill with its contents floating
	-- beside it, and the only part that answers a click is the empty part.
	--
	-- So the button *is* the row: the layout goes inside it. Which is what P.button
	-- has always done, and what the transcript's own rows already did correctly.
	function P.rowButton(parent, props)
		props = props or {}
		local height = math.max(props.height or theme.size.rowSmall, responsive.minTarget())
		-- The content row is as tall as the button actually is, not as tall as the
		-- floored minimum.
		--
		-- A caller that states its own `size` -- every chip in the composer, every pill on
		-- the home card, both segments of the sidebar's mode switch -- takes that size for
		-- the button while the row inside it kept the floored one. A 22px chip therefore
		-- held a 28px content row, 44 on a touch device, top-anchored: the icon and label
		-- centred three pixels below the chip's own centre line and drew through its
		-- bottom border. The hit-target floor still applies to any button that did not
		-- state a size, which is the case it exists for.
		local stated = props.size and props.size.Y.Scale == 0 and props.size.Y.Offset > 0
		local contentHeight = stated and props.size.Y.Offset or height
		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Row",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			zIndex = props.zIndex,
			bg = props.bg,
			radius = props.radius == nil and theme.radius.sm or props.radius,
			clip = props.clip,
			flex = props.flex,
		})
		if props.stroke then P.stroke(button, props.strokeColor) end

		local inner = P.row
		if props.vertical then inner = P.column end
		local row = inner(button, {
			name = "Content",
			size = props.auto and UDim2.new(0, 0, 0, contentHeight) or UDim2.fromScale(1, 1),
			auto = props.auto,
			gap = props.gap or theme.space.xs,
			padding = props.padding or { x = theme.space.xs },
			alignX = props.alignX,
			alignY = props.alignY or "Center",
		})

		local handle = { instance = button, row = row, selected = props.selected == true }

		local function paint(state)
			local target = props.bg
			if handle.selected then target = props.bgSelected or theme.color.surfaceActive end
			if state == "hover" and not handle.selected then target = props.bgHover or theme.color.surfaceHover end
			if state == "press" then target = props.bgPress or theme.color.surfaceActive end
			if target then
				button.BackgroundColor3 = target
				button.BackgroundTransparency = 0
			else
				button.BackgroundTransparency = 1
			end
		end

		button.MouseEnter:Connect(function() paint("hover") end)
		button.MouseLeave:Connect(function() paint("rest") end)
		button.MouseButton1Down:Connect(function() paint("press") end)
		button.MouseButton1Up:Connect(function() paint("hover") end)
		button.SelectionGained:Connect(function() paint("hover") end)
		button.SelectionLost:Connect(function() paint("rest") end)
		button.Activated:Connect(function()
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then env.require("runtime/log").warn("ui", "row handler failed", err) end
			end
		end)

		function handle.setSelected(value)
			handle.selected = value == true
			paint("rest")
		end

		-- The two things every one of these rows puts in itself, so a caller does not
		-- have to remember that an auto-width label needs a height and that an icon
		-- needs a square to be drawn into.
		function handle.icon(name, order, colour, size)
			local diameter = size or theme.size.icon
			local slot = P.frame(row, {
				name = "IconSlot",
				size = UDim2.fromOffset(diameter, diameter),
				layoutOrder = order or 1,
			})
			local icons = env.require("ui/icons")
			icons.draw(name, slot, diameter, colour or theme.color.textSecondary)
			return slot
		end

		function handle.label(text, order, colour, role)
			return P.text(row, {
				name = "Label",
				text = text,
				role = role or "caption",
				color = colour or theme.color.textSecondary,
				size = UDim2.new(0, 0, 0, theme.textRole(role or "caption").height),
				flex = "Fill",
				truncate = true,
				layoutOrder = order or 2,
			})
		end

		paint("rest")
		return handle
	end

	-- Input -----------------------------------------------------------------

	-- A text field with a real focus state. The reference client's prompt box gave
	-- no sign it had focus at all, which on a dark panel means typing into nothing;
	-- the border picking up the accent is the whole fix.
	--
	-- `bare` drops the field's own background, outline and corner so it can sit
	-- inside a container that owns them -- the composer puts the field and the send
	-- button in one bordered box, which is one control to look at rather than two.
	-- In that mode the caller paints focus itself, from onFocus and onBlur.
	function P.field(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local multiline = props.multiline == true
		local bare = props.bare == true
		-- `height` is honoured on a single line too, not only when multiline.
		--
		-- It used to be ignored there, so a caller that wanted a composer rather than a
		-- search box got the 32px control token and had no way to say otherwise -- which
		-- is why the prompt field and the search field were the same height even though
		-- one of them is the primary surface of the app. The platform floor still
		-- applies: it is a minimum, not the value.
		local height = multiline
			and (props.height or theme.size.control * 2)
			or math.max(props.height or theme.size.control, responsive.minTarget())

		local shell = P.frame(parent, {
			name = props.name or "Field",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			layoutOrder = props.layoutOrder,
			bg = (not bare) and (props.bg or theme.color.surfaceRaised) or nil,
			radius = (not bare) and (props.radius or theme.radius.md) or nil,
			clip = true,
			flex = props.flex,
		})
		local stroke = (not bare) and P.stroke(shell, theme.color.border) or nil

		local box = Instance.new("TextBox", shell)
		box.BackgroundTransparency = 1
		box.Size = UDim2.new(1, 0, 1, 0)
		box.Text = tostring(props.text or "")
		box.PlaceholderText = tostring(props.placeholder or "")
		box.PlaceholderColor3 = theme.color.textTertiary
		box.TextColor3 = theme.color.text
		box.Font = role.font
		if role.face then pcall(function() box.FontFace = role.face end) end
		box.TextSize = role.size
		box.LineHeight = role.line
		box.ClearTextOnFocus = false
		box.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		box.TextYAlignment = multiline and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
		box.MultiLine = multiline
		box.TextWrapped = multiline
		box.ClipsDescendants = true
		box.Selectable = true
		P.pad(box, {
			x = props.padX or (bare and theme.space.none or theme.space.md),
			y = multiline and theme.space.sm or 0,
		})

		local handle = { instance = box, shell = shell, stroke = stroke }

		box.Focused:Connect(function()
			if stroke then
				env.tween:Create(stroke, theme.tween("hover"), { Color = theme.color.accentBorder }):Play()
				env.tween:Create(shell, theme.tween("hover"), { BackgroundColor3 = theme.color.surfaceOverlay }):Play()
			end
			if props.onFocus then pcall(props.onFocus, handle) end
		end)

		box.FocusLost:Connect(function(enterPressed)
			if stroke then
				env.tween:Create(stroke, theme.tween("hover"), { Color = theme.color.border }):Play()
				env.tween:Create(shell, theme.tween("hover"), {
					BackgroundColor3 = props.bg or theme.color.surfaceRaised,
				}):Play()
			end
			-- On a multiline box Enter inserts a newline, so submit is the caller's
			-- job there; on a single line it means "go".
			if enterPressed and not multiline and props.onSubmit then
				pcall(props.onSubmit, box.Text, handle)
			end
			if props.onBlur then pcall(props.onBlur, box.Text, handle) end
		end)

		if props.onChange then
			box:GetPropertyChangedSignal("Text"):Connect(function()
				pcall(props.onChange, box.Text, handle)
			end)
		end

		function handle.get() return box.Text end
		function handle.set(value) box.Text = tostring(value or "") end
		function handle.focus() pcall(function() box:CaptureFocus() end) end
		function handle.clear() box.Text = "" end

		return handle
	end

	-- Containers -------------------------------------------------------------

	-- A group of related controls. One step above the surface it sits on plus a
	-- hairline, and nothing else -- no shadow, no heavier fill. `stroke = false`
	-- drops the outline for a card that is only there to hold padding.
	function P.card(parent, props)
		props = props or {}
		local card, layout = P.column(parent, {
			name = props.name or "Card",
			size = props.size or UDim2.new(1, 0, 0, 0),
			auto = props.auto or "Y",
			layoutOrder = props.layoutOrder,
			bg = props.bg or theme.color.surfaceRaised,
			radius = props.radius or theme.radius.lg,
			gap = props.gap or theme.space.md,
			padding = props.padding or theme.space.lg,
			clip = props.clip,
		})
		if props.stroke ~= false then
			P.stroke(card, props.strokeColor or theme.color.borderSubtle)
		end
		return card, layout
	end

	-- A small label for a fact or a status. Neutral unless it is given a tone: most
	-- of these are a model id or an auth style, and colouring those blue because
	-- "info" was the default made a row of plain facts look like a row of warnings.
	function P.badge(parent, props)
		props = props or {}
		local tone = props.tone or "neutral"
		local holder = P.row(parent, {
			name = "Badge",
			size = UDim2.fromOffset(0, theme.size.controlSmall - theme.space.xs),
			auto = "X",
			bg = props.bg or theme.toneSurface(tone),
			radius = theme.radius.sm,
			gap = theme.space.xxs,
			padding = { x = theme.space.xs },
			layoutOrder = props.layoutOrder,
		})
		if props.dot then
			local dot = P.frame(holder, {
				name = "Dot",
				size = UDim2.fromOffset(theme.space.xs, theme.space.xs),
				bg = props.dotColor or theme.toneColor(tone),
				radius = theme.radius.pill,
			})
			dot.LayoutOrder = 1
		end
		local label = P.text(holder, {
			text = tostring(props.text or ""),
			role = "caption",
			color = props.color or theme.toneColor(tone),
			auto = "XY",
			layoutOrder = 2,
		})
		label.Size = UDim2.fromOffset(0, 0)
		return holder, label
	end

	-- A scroll region with the two things Roblox does not give you: a canvas that
	-- sizes itself from its contents, and edge fades so a long list reads as
	-- continuing rather than as ending at a hard line.
	function P.scroll(parent, props)
		props = props or {}
		local scroll = Instance.new("ScrollingFrame", parent)
		base(scroll, {
			name = props.name or "Scroll",
			size = props.size or UDim2.new(1, 0, 1, 0),
			position = props.position,
			layoutOrder = props.layoutOrder,
			bg = props.bg,
			-- Forwarded like every other layout prop. It was not, so a scroll region asked
			-- to fill its line kept whatever size it was given -- which for the intended
			-- `UDim2.new(0, 0, 1, 0)` is no width at all. Three call sites had already
			-- worked around it by attaching a UIFlexItem by hand afterwards.
			flex = props.flex,
			clip = true,
		})
		scroll.ScrollBarThickness = props.bar or theme.size.scrollbar
		scroll.ScrollBarImageColor3 = theme.color.border
		scroll.ScrollBarImageTransparency = theme.opacity.scrollbar
		scroll.BorderSizePixel = 0
		scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		scroll.AutomaticCanvasSize = props.horizontal and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
		scroll.ScrollingDirection = props.horizontal and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
		scroll.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		scroll.Selectable = false

		local layout = Instance.new("UIListLayout", scroll)
		layout.FillDirection = props.horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		if props.alignX then layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX] end

		if props.padding then P.pad(scroll, props.padding) end

		local handle = { instance = scroll, layout = layout }

		function handle.toBottom()
			scroll.CanvasPosition = Vector2.new(0, math.max(scroll.AbsoluteCanvasSize.Y, 1e6))
		end

		function handle.atBottom(slack)
			local visible = scroll.AbsoluteWindowSize.Y
			local total = scroll.AbsoluteCanvasSize.Y
			if total <= visible then return true end
			return (total - visible - scroll.CanvasPosition.Y) <= (slack or theme.space.huge)
		end

		function handle.clear()
			for _, child in ipairs(scroll:GetChildren()) do
				if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
			end
		end

		if props.fade then
			for _, spec in ipairs({
				{ name = "FadeTop", anchor = Vector2.new(0, 0), position = UDim2.fromScale(0, 0), rotation = 90 },
				{ name = "FadeBottom", anchor = Vector2.new(0, 1), position = UDim2.fromScale(0, 1), rotation = -90 },
			}) do
				local fade = P.frame(parent, {
					name = spec.name,
					size = UDim2.new(1, 0, 0, theme.space.xl),
					anchor = spec.anchor,
					position = spec.position,
					bg = props.fadeColor or theme.color.surface,
					zIndex = (props.zIndex or 1) + 5,
				})
				local gradient = Instance.new("UIGradient", fade)
				gradient.Rotation = spec.rotation
				gradient.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0),
					NumberSequenceKeypoint.new(1, 1),
				})
			end
		end

		return handle
	end

	-- A small coloured dot used for provider health and busy state. Separate from
	-- badge because it is used inline in dense rows where a pill is too heavy.
	function P.statusDot(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Status",
			size = UDim2.fromOffset(props.diameter or theme.size.dot, props.diameter or theme.size.dot),
			bg = props.color or theme.color.textTertiary,
			radius = theme.radius.pill,
			layoutOrder = props.layoutOrder,
			anchor = props.anchor,
			position = props.position,
		})
	end

	return P
end
end)()

-- ==========================================================================
-- ui/quickchat
-- ==========================================================================
__UAI_MODULES["ui/quickchat"] = (function()
-- Quick chat: one keypress, one message, gone again.
--
-- The window is the place to read a conversation; this is the place to start one
-- without leaving what you were doing. It floats in the middle of the screen, takes
-- a single line, sends to the same session the Chat panel shows -- so whatever is
-- typed here appears there -- and dismisses itself. Nothing about it is a second
-- transcript.
--
-- The key is captured rather than typed into a field: a user thinks "this key", not
-- "Enum.KeyCode.Semicolon", and capturing it also sidesteps mapping characters to
-- key codes across keyboard layouts.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")
	local sessions = env.require("agent/session")

	local M = { visible = false, mounted = false }

	local DEFAULT_KEY = "Semicolon"

	-- The bound key as an EnumItem, or nil when the stored name no longer exists.
	function M.keyCode()
		local name = tostring(config.get("ui.quickKey", DEFAULT_KEY))
		local ok, item = pcall(function() return Enum.KeyCode[name] end)
		if ok and item then return item end
		return Enum.KeyCode.Semicolon
	end

	function M.keyName()
		return tostring(config.get("ui.quickKey", DEFAULT_KEY))
	end

	function M.setKey(keyCode)
		local name = keyCode and keyCode.Name or DEFAULT_KEY
		config.set("ui.quickKey", name)
		return name
	end

	function M.mount(layer)
		if M.mounted and M.root and M.root.Parent then return M.root end

		M.root = P.frame(layer, {
			name = "QuickChat",
			size = UDim2.fromScale(1, 1),
			zIndex = theme.z.quick,
			visible = false,
		})
		M.root.Active = false

		-- A scrim, so the rest of the screen recedes and a click outside dismisses.
		local scrim = Instance.new("TextButton", M.root)
		scrim.Name = "QuickScrim"
		scrim.Text = ""
		scrim.AutoButtonColor = false
		scrim.BorderSizePixel = 0
		scrim.Size = UDim2.fromScale(1, 1)
		scrim.BackgroundColor3 = theme.color.scrim
		scrim.BackgroundTransparency = 1
		scrim.ZIndex = theme.z.quick
		M.scrim = scrim

		local card = P.column(M.root, {
			name = "QuickCard",
			size = UDim2.new(0, math.min(math.max(responsive.viewport.X * 0.5, theme.size.modal), theme.size.reading * 0.6), 0, 0),
			auto = "Y",
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.42),
			bg = theme.color.surface,
			radius = theme.radius.xl,
			gap = theme.space.xs,
			padding = theme.space.md,
			zIndex = theme.z.quick + 1,
		})
		P.stroke(card, theme.color.accentBorder)
		M.card = card
		M.scale = Instance.new("UIScale", card)
		M.scale.Scale = theme.scale.enter

		M.field = P.field(card, {
			name = "QuickPrompt",
			placeholder = "Ask, or tell it what to change",
			layoutOrder = 1,
			onSubmit = function(text) M.submit(text) end,
		})

		M.hint = P.text(card, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			layoutOrder = 2,
		})

		M.mounted = true
		return M.root
	end

	local function refreshHint()
		if not M.hint then return end
		local providers = env.require("provider/registry")
		local record = providers.active()
		M.hint.Text = record
			and string.format("Enter to send to %s  ·  Esc to close  ·  %s reopens",
				tostring(record.label), M.keyName())
			or "No provider configured yet -- open the window and add one."
	end

	function M.show()
		if not M.mounted or M.visible then return end
		M.visible = true
		refreshHint()
		M.field.set("")
		M.root.Visible = true
		if responsive.reduceMotion then
			M.scale.Scale = 1
			M.scrim.BackgroundTransparency = theme.opacity.scrim
		else
			M.scale.Scale = theme.scale.enter
			M.scrim.BackgroundTransparency = 1
			-- Snapped on completion: a card left mid-tween keeps its field laid out at
			-- 98% of its metrics until the next time it opens.
			local grow = env.tween:Create(M.scale, theme.tween("enter"), { Scale = 1 })
			grow.Completed:Connect(function()
				if M.visible then M.scale.Scale = 1 end
			end)
			grow:Play()
			env.tween:Create(M.scrim, theme.tween("enter"), { BackgroundTransparency = theme.opacity.scrim }):Play()
		end
		-- One frame late: capturing focus in the same frame the surface becomes
		-- visible is unreliable.
		clock.delay(theme.motion.fast, function()
			if M.visible then M.field.focus() end
		end)
	end

	function M.hide()
		if not M.mounted or not M.visible then return end
		M.visible = false
		pcall(function() M.field.instance:ReleaseFocus() end)
		if responsive.reduceMotion then
			M.root.Visible = false
			return
		end
		env.tween:Create(M.scale, theme.tween("exit"), { Scale = theme.scale.enter }):Play()
		local out = env.tween:Create(M.scrim, theme.tween("exit"), { BackgroundTransparency = 1 })
		out.Completed:Connect(function()
			-- Only hide if nothing reopened it while the tween ran.
			if not M.visible and M.root then M.root.Visible = false end
		end)
		out:Play()
	end

	function M.toggle()
		if M.visible then M.hide() else M.show() end
	end

	function M.submit(text)
		local message = util.trim(tostring(text or ""))
		M.hide()
		if message == "" then return end
		-- The same session the Chat panel is bound to, so the message and its reply
		-- land in the transcript rather than in a parallel conversation.
		local ok, reason = sessions.current().send(message)
		if not ok then
			env.require("ui/overlay").toast(tostring(reason), "warn", 3)
		end
	end

	-- Bound once, on the service, because the point of the shortcut is that it works
	-- when nothing of this interface has focus.
	function M.bind()
		if M.bound then return end
		M.bound = true

		dispose.connection(env.uis.InputBegan:Connect(function(input, processed)
			if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

			if M.visible then
				if input.KeyCode == Enum.KeyCode.Escape then M.hide() end
				return
			end

			-- `processed` means the keystroke already went somewhere -- a text box, a
			-- CoreGui field. Opening on it would fire every time the bound character is
			-- typed into the composer, which is the one thing that would make this
			-- feature intolerable.
			if processed then return end
			local focused = nil
			pcall(function() focused = env.uis:GetFocusedTextBox() end)
			if focused then return end

			if M.capture then
				local pending = M.capture
				M.capture = nil
				pending(input.KeyCode)
				return
			end

			if input.KeyCode == M.keyCode() then M.show() end
		end))

		-- Clicking the scrim dismisses without sending.
		if M.scrim then
			M.scrim.Activated:Connect(function() M.hide() end)
		end
	end

	-- Settings asks for the next keypress rather than parsing a typed character.
	function M.captureNext(callback)
		M.capture = function(keyCode)
			local name = M.setKey(keyCode)
			if callback then pcall(callback, name) end
		end
	end

	function M.cancelCapture()
		M.capture = nil
	end

	return M
end
end)()

-- ==========================================================================
-- ui/responsive
-- ==========================================================================
__UAI_MODULES["ui/responsive"] = (function()
-- Responsiveness.
--
-- The reference client decided phone-or-desktop once at boot from
-- TouchEnabled-and-not-KeyboardEnabled, and baked two tables of pixel metrics off
-- that. It gets the common cases right and everything else wrong: a tablet, a
-- phone that rotates, a desktop window resized to half width, a console, a device
-- with both touch and a keyboard.
--
-- This module holds no metrics. It reports what the viewport is right now and
-- republishes when that changes, so a surface either adapts continuously (scale
-- based layout, list layouts, automatic sizing) or rebuilds itself when the layout
-- mode genuinely changes -- and the second is debounced, because a desktop window
-- drag fires viewport changes every frame.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local log = env.require("runtime/log")

	local BREAKPOINTS = {
		{ name = "xs", max = 520 },
		{ name = "sm", max = 900 },
		{ name = "md", max = 1280 },
		{ name = "lg", max = 1700 },
		{ name = "xl", max = math.huge },
	}

	local M = {
		viewport = Vector2.new(1280, 720),
		breakpoint = "md",
		mode = "window",
		orientation = "landscape",
		touch = false,
		pointer = true,
		gamepad = false,
		console = false,
		reduceMotion = false,
		transparency = 1,
		keyboardHeight = 0,
		inset = Vector2.new(0, 0),
		bottomInset = 0,
		changed = signal.new("responsive"),
		modeChanged = signal.new("responsive:mode"),
		ready = false,
	}

	local function breakpointFor(width)
		for _, entry in ipairs(BREAKPOINTS) do
			if width < entry.max then return entry.name end
		end
		return "xl"
	end

	-- Layout mode is the only thing surfaces branch on, and it is derived rather
	-- than configured: a console is gamepad-first regardless of resolution, a
	-- narrow viewport is a sheet whether it is a phone or a small window, and the
	-- user can still pin it by hand in settings.
	--
	-- Orientation matters as much as width. A tablet held portrait is 834 points
	-- wide and 1112 tall; a floating window in that space is a tall thin box, while
	-- a full-height dock reads properly.
	local function modeFor(breakpoint, forced)
		if forced and forced ~= "auto" then return forced end
		if M.console then return "tv" end
		if breakpoint == "xs" then return "sheet" end
		if breakpoint == "sm" then return "panel" end
		if M.orientation == "portrait" then return "panel" end
		return "window"
	end

	local function sample()
		local width, height = 1280, 720

		-- The camera's viewport is the honest number: a ScreenGui's AbsoluteSize is
		-- zero until it renders, and IgnoreGuiInset changes it underneath you.
		local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
		if okCamera and camera and camera.ViewportSize and camera.ViewportSize.Y > 0 then
			width, height = camera.ViewportSize.X, camera.ViewportSize.Y
		elseif M.screen and M.screen.AbsoluteSize and M.screen.AbsoluteSize.Y > 0 then
			width, height = M.screen.AbsoluteSize.X, M.screen.AbsoluteSize.Y
		end

		M.viewport = Vector2.new(width, height)
		M.orientation = (height > width) and "portrait" or "landscape"

		local okInput = pcall(function()
			M.touch = env.uis.TouchEnabled == true
			M.pointer = env.uis.MouseEnabled == true
			M.gamepad = env.uis.GamepadEnabled == true
		end)
		if not okInput then M.touch, M.pointer = false, true end

		pcall(function()
			M.console = env.guisvc:IsTenFootInterface() == true
		end)
		pcall(function()
			M.reduceMotion = env.guisvc.ReducedMotionEnabled == true
		end)
		-- The platform preference is the default, not the last word: someone who wants
		-- the motion off in this client and on everywhere else has to be able to say so,
		-- and someone whose platform reports it wrongly has to be able to say the
		-- opposite. "auto" is the setting that defers.
		do
			local wanted = tostring(env.require("runtime/config").get("ui.reduceMotion", "auto"))
			if wanted == "on" then
				M.reduceMotion = true
			elseif wanted == "off" then
				M.reduceMotion = false
			end
		end
		pcall(function()
			local value = tonumber(env.guisvc.PreferredTransparency)
			M.transparency = value and util.clamp(value, 0, 1) or 1
		end)

		-- The topbar overlaps the top of the screen; GetGuiInset reports by how much.
		pcall(function()
			local top = env.guisvc:GetGuiInset()
			if top then M.inset = Vector2.new(top.X, top.Y) end
		end)

		-- Mobile chat and the jump button sit at the bottom on a touch device.
		M.bottomInset = M.touch and 24 or 0

		pcall(function()
			if env.uis.OnScreenKeyboardVisible then
				local size = env.uis.OnScreenKeyboardSize
				M.keyboardHeight = (size and size.Y or 0)
			else
				M.keyboardHeight = 0
			end
		end)

		local config = env.require("runtime/config")
		local previousBreakpoint, previousMode = M.breakpoint, M.mode
		M.breakpoint = breakpointFor(width)
		M.mode = modeFor(M.breakpoint, config.get("ui.layout", "auto"))

		return previousBreakpoint ~= M.breakpoint or previousMode ~= M.mode
	end

	-- Continuous changes fire `changed`; a real mode switch also fires
	-- `modeChanged`, which is the only one that triggers a rebuild.
	local function refresh(reason)
		local switched = sample()
		M.changed:fire({ reason = reason, mode = M.mode, breakpoint = M.breakpoint, viewport = M.viewport })
		if switched then
			log.debug("responsive", string.format("%s -> %s at %dx%d (%s)",
				M.breakpoint, M.mode, M.viewport.X, M.viewport.Y, tostring(reason)))
			M.modeChanged:fire({ mode = M.mode, breakpoint = M.breakpoint })
		end
	end

	local debouncedRefresh

	function M.init(screenGui)
		M.screen = screenGui
		sample()
		M.ready = true

		debouncedRefresh = clock.debounce(function() refresh("viewport") end, 0.12)

		local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
		if okCamera and camera then
			camera:GetPropertyChangedSignal("ViewportSize"):Connect(debouncedRefresh)
		end
		-- The camera instance itself is replaced on respawn in some games, so the
		-- workspace is watched too.
		pcall(function()
			env.services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
				local okNew, newCamera = pcall(function() return env.services.Workspace.CurrentCamera end)
				if okNew and newCamera then
					newCamera:GetPropertyChangedSignal("ViewportSize"):Connect(debouncedRefresh)
				end
				refresh("camera")
			end)
		end)

		-- The on-screen keyboard is not a resize: the viewport does not change, so
		-- it has to be watched separately or the composer ends up behind it.
		for _, property in ipairs({ "OnScreenKeyboardVisible", "OnScreenKeyboardSize" }) do
			pcall(function()
				env.uis:GetPropertyChangedSignal(property):Connect(function()
					sample()
					M.changed:fire({ reason = "keyboard", mode = M.mode, breakpoint = M.breakpoint })
				end)
			end)
		end

		for _, property in ipairs({ "ReducedMotionEnabled", "PreferredTransparency" }) do
			pcall(function()
				env.guisvc:GetPropertyChangedSignal(property):Connect(function() refresh(property) end)
			end)
		end

		pcall(function()
			env.uis.LastInputTypeChanged:Connect(function(inputType)
				local name = tostring(inputType and inputType.Name or "")
				local wasGamepad = M.gamepad
				if name:find("Gamepad") then M.gamepad = true end
				if wasGamepad ~= M.gamepad then refresh("input") end
			end)
		end)

		local config = env.require("runtime/config")
		config.changed:connect(function(path)
			if path == "ui.layout" or path == "ui.reduceMotion" then refresh("setting") end
		end)

		log.info("responsive", string.format("%s / %s at %dx%d, touch %s, gamepad %s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "yes" or "no", M.gamepad and "yes" or "no"))
		return M
	end

	function M.refresh(reason)
		refresh(reason or "manual")
	end

	-- Hit targets. Apple and Google both land on ~44pt for touch; a pointer can be
	-- served by much less, and cramming a mouse interface to 44px wastes the space
	-- a desktop is buying us.
	function M.minTarget()
		if M.console then return 48 end
		return M.touch and 44 or 28
	end

	function M.isNarrow()
		return M.mode == "sheet"
	end

	function M.isCompactHeight()
		return M.viewport.Y < 520 or M.keyboardHeight > 0
	end

	-- Default geometry per mode, in pixels, clamped to the viewport so the window
	-- can never open larger than the screen it is on.
	function M.geometry()
		local width, height = M.viewport.X, M.viewport.Y
		if M.mode == "sheet" then
			return {
				width = width,
				height = math.floor(height * (M.orientation == "portrait" and 0.72 or 0.9)),
				anchored = "bottom",
			}
		end
		if M.mode == "panel" then
			return {
				width = math.floor(util.clamp(width * 0.52, 320, 460)),
				height = math.floor(height - M.inset.Y - 24),
				anchored = "right",
			}
		end
		if M.mode == "tv" then
			return {
				width = math.floor(util.clamp(width * 0.62, 720, 1200)),
				height = math.floor(util.clamp(height * 0.7, 420, 760)),
				anchored = "center",
			}
		end
		return {
			width = math.floor(util.clamp(width * 0.44, 460, 780)),
			height = math.floor(util.clamp(height * 0.68, 360, 620)),
			anchored = "center",
		}
	end

	-- How much of the bottom of the screen is unusable: the on-screen keyboard when
	-- it is up, otherwise the platform's own bottom furniture.
	function M.bottomObstruction()
		if M.keyboardHeight > 0 then return M.keyboardHeight end
		return M.bottomInset
	end

	function M.describe()
		return string.format("%s / %s  %dx%d  %s%s%s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "touch " or "",
			M.gamepad and "gamepad " or "",
			M.reduceMotion and "reduced-motion" or "")
	end

	return M
end
end)()

-- ==========================================================================
-- ui/settingspanes
-- ==========================================================================
__UAI_MODULES["ui/settingspanes"] = (function()
-- What is in the settings, as a list of panes.
--
-- Two surfaces render these: the Settings panel stacks every pane in one scroll, and
-- the settings dialog the sidebar opens shows one at a time behind a category list.
-- Declaring them once is what keeps the two from drifting -- the dialog used to hold
-- its own copy of three appearance rows, none of which were wired to anything, while
-- the panel held the real ones.
--
-- A pane is `{ id, section, label, icon, build(container) }`. `build` is handed a
-- column to fill and returns nothing; everything it puts there reads and writes
-- config, so nothing has to be re-read when it is shown again.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local fsx = env.require("runtime/fsx")
	local place = env.require("runtime/place")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local quickchat = env.require("ui/quickchat")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local R = env.require("ui/settingsrows")
	local permissions = env.require("agent/permissions")
	local state = env.require("agent/state")
	local usage = env.require("agent/usage")
	local stats = env.require("agent/stats")
	local registry = env.require("agent/registry")
	local sessions = env.require("agent/session")
	local providers = env.require("provider/registry")
	local ua = env.require("net/ua")
	local http = env.require("net/http")
	local bridgeModule = env.require("net/bridge")

	local M = {}

	-- The token budgets. They stop where the widest models of the moment do -- a
	-- million in, a hundred and twenty-eight thousand out -- rather than where a
	-- default conversation needs, because a ceiling that cannot reach the model is
	-- indistinguishable from the model not having it.
	local BUDGET_STOPS = {
		4000, 8000, 12000, 16000, 24000, 32000, 48000, 64000, 96000,
		128000, 160000, 200000, 256000, 320000, 400000, 512000, 750000, 1000000,
	}
	local REPLY_STOPS = { 256, 512, 1024, 2048, 4096, 8192, 16000, 24000, 32000, 64000, 96000, 128000 }
	local RESULT_STOPS = { 1000, 2000, 4000, 6000, 8000, 12000, 16000, 24000, 32000, 48000, 64000, 96000, 128000 }

	-- Each pane builds into a fresh column, so the layout order it needs is just a
	-- running count. This is the only bookkeeping a pane does.
	local function builder(container)
		local order = 0
		local api = {}
		function api.order()
			order = order + 1
			return order
		end
		-- A heading and its card go in one wrapper with a tight gap.
		--
		-- They used to be two siblings of the pane's own column, which means the distance
		-- from a heading to the card it labels was the pane's uniform gap -- exactly the
		-- distance from that heading to the card *above* it. Nothing in the layout said
		-- which block a heading belonged to, and a pane of six sections read as twelve
		-- unrelated things.
		function api.section(title, description)
			local group = P.column(container, {
				name = "Group",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = api.order(),
			})
			P.sectionHeader(group, { title = title, description = description, layoutOrder = 1 })
			return P.card(group, { layoutOrder = 2, gap = theme.space.md })
		end
		function api.note(text, colour)
			return R.paragraph(container, text, { color = colour, layoutOrder = api.order() })
		end
		return api
	end

	local function accentOptions()
		local out = {}
		for key, entry in pairs(theme.ACCENTS) do
			out[#out + 1] = { value = key, label = entry.label }
		end
		table.sort(out, function(a, b) return a.label < b.label end)
		return out
	end

	-- General -----------------------------------------------------------------

	local function paneGeneral(container)
		local build = builder(container)

		local appearance = build.section("Appearance",
			"Layout follows the viewport by default. Pin it if you would rather it did not.")

		P.text(appearance, { text = "Accent", role = "small" })
		C.segmented(appearance, {
			options = accentOptions(),
			value = config.get("ui.accent", "claude"),
			onChange = function(value) config.set("ui.accent", value) end,
		})

		P.text(appearance, { text = "Density", role = "small" })
		C.segmented(appearance, {
			options = {
				{ value = "comfortable", label = "Comfortable" },
				{ value = "compact", label = "Compact" },
			},
			value = config.get("ui.density", "comfortable"),
			onChange = function(value) config.set("ui.density", value) end,
		})

		P.text(appearance, { text = "Layout", role = "small" })
		C.segmented(appearance, {
			options = {
				{ value = "auto", label = "Auto" },
				{ value = "sheet", label = "Sheet" },
				{ value = "panel", label = "Panel" },
				{ value = "window", label = "Window" },
			},
			value = config.get("ui.layout", "auto"),
			onChange = function(value) config.set("ui.layout", value) end,
		})

		R.number(appearance, "Text scale", "Multiplies every type size.", "ui.fontScale", 0.85, 1.4, 0.05)
		R.segmented(appearance, {
			name = "ReduceMotion",
			label = "Reduce motion",
			hint = "Auto follows the platform's own accessibility preference.",
			path = "ui.reduceMotion",
			options = {
				{ value = "auto", label = "Auto" },
				{ value = "on", label = "On" },
				{ value = "off", label = "Off" },
			},
		})
		R.toggle(appearance, {
			label = "Show reasoning",
			hint = "Display the model's chain of thought when it sends one. Applies to the conversation already on screen.",
			path = "ui.showReasoning",
		})
		R.toggle(appearance, {
			label = "Show the code a tool was given",
			hint = "Draws the Luau, the file body or the property map a tool call carries under its "
				.. "row, outside the fold. Off, it is still there behind the row's own caret.",
			path = "ui.showToolCode",
		})
		R.toggle(appearance, {
			label = "Expand tool detail",
			hint = "Open the remaining arguments and the result by default, rather than on the first click.",
			path = "ui.showToolDetail",
		})
		R.toggle(appearance, {
			label = "Show token counts",
			hint = "The running token and cost line under the composer.",
			path = "ui.showUsage",
		})
		R.toggle(appearance, {
			label = "Show the activity card",
			hint = "The greeting and the counters an empty conversation opens with.",
			path = "ui.showActivity",
		})

		-- Built here rather than after the section below it, because nothing in this
		-- card sets a layout order: the rows appear in the order they are created, and a
		-- note constructed later landed wherever the tie-break put it.
		local viewportNote = P.text(appearance, {
			text = "Now: " .. responsive.describe(),
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		viewportNote.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = responsive.changed:connect(function()
			if not viewportNote.Parent then return end
			viewportNote.Text = "Now: " .. responsive.describe()
		end)
		viewportNote.Destroying:Connect(function() pcall(unsubscribe) end)

		local shortcuts = build.section("Shortcuts",
			"Quick chat opens in the middle of the screen, takes one message to the conversation the Chat panel shows, and closes itself.")
		local row = P.row(shortcuts, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm })
		local text = P.column(row, {
			size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
		})
		P.text(text, { text = "Quick chat key", role = "small" })
		local keyHint = P.text(text, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local keyButton
		local function describeKey()
			keyHint.Text = "Currently " .. quickchat.keyName()
				.. ". Press the button, then the key you want it to be."
		end
		keyButton = P.button(row, {
			name = "QuickKey",
			text = quickchat.keyName(),
			variant = "secondary",
			size = "sm",
			width = theme.size.keyColumn + theme.space.xxl,
			layoutOrder = 2,
			onClick = function()
				keyButton.setText("press a key")
				-- Captured rather than typed: a user thinks "this key", and a character
				-- would not survive a different keyboard layout.
				quickchat.captureNext(function(name)
					keyButton.setText(name)
					describeKey()
				end)
			end,
		})
		keyButton.instance.LayoutOrder = 2
		describeKey()
	end

	-- Privacy -----------------------------------------------------------------

	local function paneprivacy(container)
		local build = builder(container)

		local where = build.section("Where your data goes",
			"This client has no telemetry and no home to call. The only outbound requests it "
			.. "makes are the ones listed here, and every one of them is somewhere you added.")

		local list = {}
		for _, record in ipairs(providers.list()) do
			if record.enabled ~= false then
				list[#list + 1] = {
					key = record.label,
					value = record.baseUrl,
					tone = record.id == (providers.active() or {}).id and "good" or nil,
				}
			end
		end
		if config.get("bridge.enabled", false) == true then
			list[#list + 1] = { key = "Web bridge", value = bridgeModule.status().url }
		end
		if #list == 0 then
			build.note("Nothing is configured, so nothing leaves this machine at all.")
		else
			R.facts(container, list, { name = "Endpoints", layoutOrder = build.order() })
		end

		local secrets = build.section("Keys and logs",
			"An API key is stored in the settings file so a request can be signed with it. "
			.. "Everywhere else -- the request log, the diagnostics, an exported copy of the "
			.. "settings -- only the last four characters are kept.")
		R.toggle(secrets, {
			label = "Mirror the log to the console",
			hint = "Also print every entry with print/warn, which a developer console can read.",
			path = "logs.mirror",
			onChange = function(value) log.mirror = value == true end,
		})
		P.text(secrets, { text = "Level", role = "small" })
		C.segmented(secrets, {
			options = {
				{ value = "debug", label = "Debug" },
				{ value = "info", label = "Info" },
				{ value = "warn", label = "Warn" },
				{ value = "error", label = "Error" },
			},
			value = config.get("logs.level", "info"),
			onChange = function(value)
				config.set("logs.level", value)
				log.setLevel(value)
			end,
		})

		local clear = build.section("Clear what is stored",
			"Each of these is immediate and cannot be undone.")
		R.actions(clear, {
			{
				name = "ClearRequests",
				text = "Request history",
				variant = "ghost",
				onClick = function()
					http.clearHistory()
					overlay.toast("Request history cleared", "good", 2)
				end,
			},
			{
				name = "ClearLog",
				text = "Log",
				variant = "ghost",
				onClick = function()
					log.clear()
					overlay.toast("Log cleared", "good", 2)
				end,
			},
			{
				name = "ClearConversations",
				text = "All conversations",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Delete every conversation?",
						description = "Every transcript on disk is removed. The activity counters are kept.",
						confirmText = "Delete",
						danger = true,
						onConfirm = function()
							for _, session in ipairs(sessions.list()) do
								sessions.remove(session.id)
							end
							overlay.toast("Conversations deleted", "good", 2)
						end,
					})
				end,
			},
			{
				name = "ClearActivity",
				text = "Activity history",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Reset the activity history?",
						description = "Every day, model and token count this client has recorded is discarded. "
							.. "The conversations themselves are kept.",
						confirmText = "Reset",
						danger = true,
						onConfirm = function()
							stats.reset()
							overlay.toast("Activity history reset", "good", 2)
						end,
					})
				end,
			},
		})
	end

	-- Usage -------------------------------------------------------------------

	local function paneUsage(container)
		local build = builder(container)

		local live = build.section("This session",
			"What the client has spent since it started, as the provider reported it.")
		local liveText = P.text(live, {
			name = "UsageLine",
			text = usage.line(),
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		liveText.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = usage.changed:connect(function()
			if not liveText.Parent then return end
			liveText.Text = usage.line()
		end)
		liveText.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(live, { {
			name = "ResetCounters",
			text = "Reset counters",
			variant = "ghost",
			onClick = function() usage.reset() end,
		} })

		local window = stats.window("all")
		local totals = build.section("Everything recorded",
			"Counted from what this client observed and kept on disk, so it survives a restart.")
		local facts = {
			{ key = "Conversations", value = util.formatNumber(window.sessions) },
			{ key = "Messages", value = util.formatNumber(window.messages) },
			{ key = "Requests", value = util.formatNumber(window.requests) },
			{ key = "Tokens in", value = util.formatNumber(window.tokensIn) },
			{ key = "Tokens out", value = util.formatNumber(window.tokensOut) },
			{ key = "Tool calls", value = util.formatNumber(window.toolCalls) },
			{ key = "Active days", value = util.formatNumber(window.activeDays) },
		}
		local cost = usage.formatCost(window.cost)
		if cost ~= "" then
			facts[#facts + 1] = { key = "Cost", value = cost .. (window.estimated and " (some estimated)" or "") }
		end
		if window.tokensFrom then
			facts[#facts + 1] = { key = "Tokens since", value = clock.describeDay(clock.dayKey(window.tokensFrom)) }
		end
		R.facts(totals, facts, { name = "Totals" })
		if not window.tokensFrom then
			R.paragraph(totals,
				"No request has been recorded yet, so there are no token counts. Messages and "
				.. "conversations from before counting began were read back out of the transcripts "
				.. "already on disk; tokens could not be, because nothing recorded them.")
		end

		if #window.models > 0 then
			local models = build.section("By model", "Which model spent what.")
			for index, row in ipairs(window.models) do
				C.keyValue(models, {
					key = row.id,
					value = string.format("%s tokens  %s  %d%%",
						util.formatCompact(row.tokens), util.pluralise(row.requests, "request"),
						math.floor((row.share or 0) * 100 + 0.5)),
					layoutOrder = index,
				})
			end
		end

		local tools = stats.topTools(8)
		if #tools > 0 then
			local toolCard = build.section("Most used tools", "Across every conversation.")
			for index, entry in ipairs(tools) do
				C.keyValue(toolCard, {
					key = entry.name,
					value = util.formatNumber(entry.count),
					layoutOrder = index,
				})
			end
		end
	end

	-- Claude Code -------------------------------------------------------------

	-- A live sample of one code palette, drawn in that palette's own colours rather
	-- than the active one -- which is what lets both be shown side by side and picked
	-- by pressing the one you want, the way the reference client does it.
	local function codePreview(parent, name, order, onPick)
		local palette = theme.CODE_THEMES[name] or theme.CODE_THEMES.dark
		local selected = theme.codeThemeName == name
		local lineHeight = theme.text.monoSmall.height + theme.space.hair
		-- Four sample lines, a bar, and the two hair-thin paddings around them. Stated
		-- once and passed as the card's own size: P.rowButton takes `size` when it is
		-- given one and ignores `height` unless the button is auto-sizing, so passing
		-- both -- with a zero height in the size -- gave the card no height at all and
		-- spilled a hundred pixels of preview over the control below it.
		local cardHeight = lineHeight * 4 + theme.size.rowTight + theme.space.hair * 2
		local card = P.rowButton(parent, {
			name = "CodePreview_" .. name,
			vertical = true,
			size = UDim2.new(0.5, -theme.space.sm, 0, cardHeight),
			height = cardHeight,
			bg = palette.surface,
			radius = theme.radius.md,
			gap = 0,
			padding = theme.space.hair,
			alignY = "Top",
			clip = true,
			stroke = true,
			strokeColor = selected and theme.color.accent or palette.border,
			bgHover = palette.surface,
			bgPress = palette.surface,
			bgSelected = palette.surface,
			selected = selected,
			layoutOrder = order,
			onClick = function()
				config.set("ui.codeTheme", name)
				if onPick then pcall(onPick, name) end
			end,
		})

		local head = P.row(card.row, {
			name = "PreviewBar",
			size = UDim2.new(1, 0, 0, theme.size.rowTight),
			bg = palette.bar,
			padding = { x = theme.space.xs },
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.text(head, {
			text = palette.label,
			role = "caption",
			color = palette.gutter,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		if selected then
			local mark = P.frame(head, {
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 2,
			})
			icons.check(mark, theme.size.icon, theme.color.accent)
		end

		local lines = {
			{ number = 1, prefix = " ", text = "local function greet(name)" },
			{ number = 2, prefix = "-", text = 'return "Hello, " .. name', tone = "remove" },
			{ number = 2, prefix = "+", text = 'return string.format("Hi %s!", name)', tone = "add" },
			{ number = 3, prefix = " ", text = "end" },
		}
		for index, line in ipairs(lines) do
			local fill, ink = nil, palette.text
			if line.tone == "add" then
				fill, ink = palette.addSurface, palette.addText
			elseif line.tone == "remove" then
				fill, ink = palette.removeSurface, palette.removeText
			end
			local row = P.row(card.row, {
				name = "Line" .. tostring(index),
				size = UDim2.new(1, 0, 0, lineHeight),
				bg = fill,
				gap = theme.space.xs,
				padding = { x = theme.space.xs },
				layoutOrder = index + 1,
			})
			P.text(row, {
				text = tostring(line.number),
				role = "monoSmall",
				color = palette.gutter,
				align = "Right",
				size = UDim2.fromOffset(theme.space.md, theme.text.monoSmall.height),
				layoutOrder = 1,
			})
			P.text(row, {
				text = line.prefix,
				role = "monoSmall",
				color = ink,
				size = UDim2.fromOffset(theme.space.sm, theme.text.monoSmall.height),
				layoutOrder = 2,
			})
			P.text(row, {
				text = line.text,
				role = "monoSmall",
				color = ink,
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				truncate = true,
				layoutOrder = 3,
			})
		end
		return card
	end

	local function paneClaudeCode(container)
		local build = builder(container)

		local appearance = build.section("Code appearance",
			"How a fenced code block is drawn, in the transcript and everywhere else. "
			.. "Press one to use it.")
		local row = P.row(appearance, {
			name = "CodeThemes",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
			alignY = "Top",
		})
		for index, key in ipairs(theme.CODE_THEME_ORDER) do
			codePreview(row, key, index)
		end

		local fontOptions = {}
		for _, key in ipairs(theme.CODE_ORDER) do
			fontOptions[#fontOptions + 1] = { value = key, label = theme.CODE_FONTS[key].label }
		end
		R.segmented(appearance, {
			name = "CodeFont",
			label = "Code font",
			hint = "The monospace family for code and diagnostics. Roblox renders from a fixed "
				.. "set of families, so this offers the ones that exist rather than a box to type "
				.. "a font name into that could not be loaded.",
			path = "ui.codeFont",
			options = fontOptions,
		})

		local interface = build.section("Appearance",
			"The type the interface itself is set in.")
		local interfaceOptions = {}
		for _, key in ipairs(theme.INTERFACE_ORDER) do
			interfaceOptions[#interfaceOptions + 1] = { value = key, label = theme.INTERFACE_FONTS[key].label }
		end
		R.select(interface, {
			name = "InterfaceFont",
			label = "Interface font",
			hint = "Menus, the sidebar and the transcript. Only the families this client can "
				.. "actually load are listed -- the list is probed against the engine rather than "
				.. "declared, so it is shorter on an older client than a longer one.",
			path = "ui.interfaceFont",
			options = interfaceOptions,
		})
		-- What is being rendered, as opposed to what is selected. Two clients can resolve
		-- the same setting differently: the weight axis needs the modern type stack, and
		-- without it every "medium" role falls back to whichever legacy member pairs that
		-- family with a heavier weight. Saying so is cheaper than someone wondering why
		-- their headings look the same as their body text.
		R.paragraph(interface, string.format("Now: %s, %s.",
			theme.interfaceFontName,
			theme.hasFontFace and "with the regular/medium/semibold weight axis"
				or "weights from the legacy font set on this client"))

		-- Text size is the same setting as the scale slider under General, expressed the
		-- way the reference client expresses it. One value, two controls: the segmented
		-- one reads the scale back rather than keeping a second copy of it.
		local scale = tonumber(config.get("ui.fontScale", 1)) or 1
		local currentSize = "medium"
		if scale < 0.95 then currentSize = "small" end
		if scale > 1.08 then currentSize = "large" end
		R.segmented(interface, {
			name = "TranscriptSize",
			label = "Transcript text size",
			hint = "The same value as the text scale under General.",
			value = currentSize,
			options = {
				{ value = "small", label = "Small" },
				{ value = "medium", label = "Medium" },
				{ value = "large", label = "Large" },
			},
			onChange = function(value)
				local scales = { small = 0.9, medium = 1, large = 1.15 }
				config.set("ui.fontScale", scales[value] or 1)
			end,
		})

		R.segmented(interface, {
			name = "TranscriptWidth",
			label = "Transcript width",
			hint = "The widest the transcript and the composer will grow on a large screen.",
			path = "ui.transcriptWidth",
			options = {
				{ value = "narrow", label = "Narrow" },
				{ value = "medium", label = "Medium" },
				{ value = "wide", label = "Wide" },
			},
		})
	end

	-- Cowork ------------------------------------------------------------------

	local function paneCowork(container)
		local build = builder(container)
		build.section("Cowork",
			"A browser on this machine can join the conversation that is open here. Both sides "
			.. "dial out to a small local process, because a Roblox client cannot accept a "
			.. "connection.")
		env.require("ui/panels/cowork").rows(container, { layoutOrder = build.order() })
		build.order()
	end

	-- Import and export -------------------------------------------------------

	local EXPORT_DIR = "export"

	-- What an export contains, and what it deliberately does not.
	local function exportPayload()
		local settings = util.deepCopy(config.data)
		-- The keys are the one thing that must not be copied into a second file. Kept as
		-- their last four characters so an exported provider list is still readable as a
		-- list of providers.
		for _, record in ipairs(util.get(settings, "providers.list", {}) or {}) do
			local key = tostring(record.apiKey or "")
			if key ~= "" then record.apiKey = "..." .. key:sub(-4) end
		end
		settings.bridge = settings.bridge or {}
		if util.trim(tostring(settings.bridge.token or "")) ~= "" then
			settings.bridge.token = "(removed)"
		end
		return {
			exportedAt = clock.ms(),
			version = env.info and env.info.version or "",
			place = place.facts(),
			settings = settings,
			activity = stats.data,
		}
	end

	local function paneImportExport(container)
		local build = builder(container)

		local out = build.section("Export",
			"Writes a copy of your settings and the activity history into the client's own "
			.. "folder. API keys are reduced to their last four characters and the bridge token "
			.. "is dropped, so the file can be shared.")
		local outPath = EXPORT_DIR .. "/uai-export.json"
		local result = P.text(out, {
			name = "ExportResult",
			text = fsx.enabled and ("Will write " .. fsx.root .. "/" .. outPath)
				or "This host has no filesystem, so an export can only go to the clipboard.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		result.Size = UDim2.new(1, 0, 0, 0)

		local actions = {}
		if fsx.enabled then
			actions[#actions + 1] = {
				name = "ExportFile",
				text = "Export to a file",
				variant = "secondary",
				onClick = function()
					local ok, err = fsx.writeJson(outPath, exportPayload())
					result.Text = ok and ("Written to " .. fsx.root .. "/" .. outPath)
						or ("Could not write it: " .. tostring(err))
					overlay.toast(ok and "Exported" or "Export failed", ok and "good" or "warn", 2)
				end,
			}
		end
		if caps.clipboard then
			actions[#actions + 1] = {
				name = "ExportClipboard",
				text = "Copy to clipboard",
				variant = "ghost",
				onClick = function()
					local okEncode, body = pcall(util.encode, exportPayload())
					if not okEncode then
						overlay.toast("Could not encode the export", "warn", 2)
						return
					end
					local ok = pcall(caps.fn.clipboard, body)
					overlay.toast(ok and "Copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				end,
			}
		end
		if #actions > 0 then R.actions(out, actions) end

		local inbound = build.section("Import",
			"Reads a file from the client's folder and applies the settings in it. Providers, "
			-- Being explicit about this: an import that silently replaced a working key
			-- with "...abcd" from an export would break the client in a way that looks
			-- like the provider rejecting you.
			.. "keys and the bridge token are never imported, because an export does not "
			.. "contain them.")
		local importResult = P.text(inbound, {
			name = "ImportResult",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		importResult.Size = UDim2.new(1, 0, 0, 0)
		R.actions(inbound, { {
			name = "ImportFile",
			text = "Import from a file",
			variant = "secondary",
			onClick = function()
				overlay.prompt({
					title = "Import settings",
					description = "A path inside " .. fsx.root .. ", as it appears in the folder.",
					placeholder = EXPORT_DIR .. "/uai-export.json",
					value = outPath,
					confirmText = "Import",
					onConfirm = function(path)
						local data = fsx.readJson(path, nil)
						local incoming = type(data) == "table" and (data.settings or data) or nil
						if type(incoming) ~= "table" then
							importResult.Text = "Nothing readable at " .. tostring(path)
							return
						end
						local applied = 0
						for _, section in ipairs({ "ui", "agent", "logs", "identity" }) do
							if type(incoming[section]) == "table" then
								config.set(section, util.merge(config.get(section, {}), incoming[section]))
								applied = applied + 1
							end
						end
						importResult.Text = applied > 0
							and (util.pluralise(applied, "section") .. " imported")
							or "That file had no settings in it"
						overlay.toast(importResult.Text, applied > 0 and "good" or "warn", 2)
					end,
				})
			end,
		} })
	end

	-- Desktop app -------------------------------------------------------------

	local function paneDesktop(container)
		local build = builder(container)

		local shell = build.section("Window",
			"Where the interface opens and how much of the screen it takes.")
		R.segmented(shell, {
			name = "OpenPanel",
			label = "Open on",
			hint = "Which surface the interface shows when it is opened.",
			path = "ui.panel",
			options = {
				{ value = "chat", label = "Chat" },
				{ value = "cowork", label = "Cowork" },
				{ value = "providers", label = "Providers" },
				{ value = "tools", label = "Tools" },
				{ value = "logs", label = "Logs" },
			},
		})
		R.toggle(shell, {
			label = "Start with the sidebar collapsed",
			hint = "The conversation list can always be brought back with the toggle in the header.",
			path = "ui.sidebarCollapsed",
		})
		R.toggle(shell, {
			label = "Keep the panel list open",
			hint = "Whether the sidebar's More section starts expanded.",
			path = "ui.sidebarExpanded",
		})
		R.actions(shell, {
			{
				name = "ResetWindow",
				text = "Reset window position",
				variant = "ghost",
				onClick = function()
					config.set("ui.window", util.deepCopy(util.get(config.defaults, "ui.window")))
					overlay.toast("Window position reset", "good", 2)
				end,
			},
			{
				name = "ResetLauncher",
				text = "Reset the launcher",
				variant = "ghost",
				onClick = function()
					config.set("ui.launcher", util.deepCopy(util.get(config.defaults, "ui.launcher")))
					overlay.toast("Launcher reset", "good", 2)
				end,
			},
		})

		local host = build.section("This host",
			"What the client found when it started. None of it is configurable; all of it "
			.. "decides what works.")
		local facts = {
			{ key = "Client", value = tostring(env.info and env.info.version or "") },
			{ key = "Transport", value = caps.http .. (caps.requestName and (" (" .. caps.requestName .. ")") or "") },
			{ key = "Identity", value = caps.uaSupported and "can be sent" or "cannot be sent here", tone = caps.uaSupported and "good" or "warn" },
			{ key = "Filesystem", value = caps.fs and "yes" or "no", tone = caps.fs and "good" or "warn" },
			{ key = "Executor", value = caps.executor },
			{ key = "Viewport", value = responsive.describe() },
		}
		if caps.studio then facts[#facts + 1] = { key = "Studio", value = "yes" } end
		for _, entry in ipairs(place.facts()) do facts[#facts + 1] = entry end
		R.facts(host, facts, { name = "HostFacts" })
	end

	-- Developer ---------------------------------------------------------------

	local function paneDeveloper(container)
		local build = builder(container)

		local logs = build.section("Diagnostics",
			"Every request and every log line the client has kept, and what it keeps them for.")
		local counts = P.text(logs, {
			name = "LogCounts",
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		counts.Size = UDim2.new(1, 0, 0, 0)
		local function describeCounts()
			counts.Text = string.format("%s in the request history\n%s in the log\n%s registered for cleanup",
				util.pluralise(#http.history, "entry"),
				util.pluralise(#log.entries, "line"),
				util.pluralise(env.require("runtime/dispose").count(), "handle"))
		end
		describeCounts()
		R.actions(logs, {
			{
				name = "OpenLogs",
				text = "Open the log",
				variant = "secondary",
				onClick = function()
					env.require("ui/app").show("logs")
				end,
			},
			{
				name = "RefreshCounts",
				text = "Refresh",
				variant = "ghost",
				onClick = describeCounts,
			},
			{
				name = "CopyDiagnostics",
				text = "Copy diagnostics",
				variant = "ghost",
				onClick = function()
					local report = table.concat({
						"UAI " .. tostring(env.info and env.info.version or ""),
						caps.summary(),
						responsive.describe(),
						place.describe(),
						ua.describe(),
						usage.line(),
						log.export(),
					}, "\n")
					if caps.clipboard then
						local ok = pcall(caps.fn.clipboard, report)
						overlay.toast(ok and "Diagnostics copied" or "Could not reach the clipboard",
							ok and "good" or "warn", 2)
					else
						log.info("diagnostics", report)
						overlay.toast("No clipboard here, so it went to the log", "info", 3)
					end
				end,
			},
		})

		local identity = build.section("Client identity",
			"Requests are sent as the Claude Code CLI. Gateways that gate on it accept them; "
			.. "others ignore the extra headers.")
		R.toggle(identity, {
			label = "Send the Claude Code identity",
			hint = "Applies to every inference request.",
			path = "identity.claudeUa",
		})
		R.field(identity, {
			name = "IdentityVersion",
			path = "identity.version",
			placeholder = ua.DEFAULT_VERSION,
			transform = function(text)
				if util.trim(text) == "" then return ua.DEFAULT_VERSION end
				return util.trim(text)
			end,
		})
		local identityBox = P.frame(identity, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			padding = theme.space.sm,
		})
		P.stroke(identityBox, theme.color.codeBorder)
		local identityText = P.text(identityBox, {
			text = ua.describe(),
			role = "monoSmall",
			color = theme.color.codeText,
			wrap = true,
			auto = "Y",
		})
		identityText.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = config.changed:connect(function(path)
			if not identityText.Parent then return end
			if path == nil or util.startsWith(tostring(path), "identity.") then
				identityText.Text = ua.describe()
			end
		end)
		identityText.Destroying:Connect(function() pcall(unsubscribe) end)
		if not caps.uaSupported then
			R.paragraph(identity,
				"This host has no executor HTTP function, so Roblox sends its own User-Agent and "
				.. "drops ours. Everything else still works.", { color = theme.color.warn })
		end

		local danger = build.section("Reset",
			"Providers, permission rules and memory are kept unless you say otherwise.")
		R.actions(danger, {
			{
				name = "ResetSettings",
				text = "Reset all settings",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Reset every setting?",
						description = "Appearance and agent settings go back to defaults. Providers, rules and memory are kept.",
						confirmText = "Reset",
						danger = true,
						onConfirm = function()
							config.reset("ui")
							config.reset("agent")
							overlay.toast("Settings reset", "good")
						end,
					})
				end,
			},
			{
				name = "UnloadUai",
				text = "Unload UAI",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Unload UAI?",
						description = "Stops the current turn, drains every timer and input handler, saves your settings and removes the interface. Run the loader again to come back.",
						confirmText = "Unload",
						danger = true,
						onConfirm = function()
							-- The handle the bootstrap published, which is the only thing
							-- holding the disposer registry and the ScreenGui together.
							local globals = (type(getgenv) == "function") and getgenv() or nil
							local live = globals and globals.UAI
							if live and live.destroy then
								live.destroy()
							else
								env.require("runtime/dispose").drain()
								pcall(function() env.require("ui/app").screen:Destroy() end)
							end
						end,
					})
				end,
			},
		})
	end

	-- Agent -------------------------------------------------------------------

	local function paneAgent(container)
		local build = builder(container)

		local agent = build.section("Agent", "How hard it works before it stops and answers.")
		R.number(agent, "Step limit", "Tool rounds allowed in one turn, unless the switch below removes it.",
			"agent.maxTurns", 4, 60, 1)
		R.toggle(agent, {
			label = "Unlimited tool calls",
			hint = "Ignore the step limit and the fifteen-minute turn deadline, and keep calling tools until the answer is written. The repeat breaker, each tool's own timeout and Stop still apply, and subagents keep their own budgets.",
			path = "agent.unlimitedTurns",
		})
		R.number(agent, "Parallel tools", "Tool calls run at once within one step.",
			"agent.toolConcurrency", 1, 8, 1)
		R.number(agent, "Tool timeout",
			"Seconds before a tool is abandoned. Subagents are exempt: they run to their own budget below.",
			"agent.toolTimeout", 5, 60, 1)
		R.number(agent, "Subagent budget",
			"Seconds one subagent may work for before it wraps up. The call that dispatched it waits this long plus a minute, so a finished report is never thrown away. Ignored while the switch below is on.",
			"agent.subagentBudget", 30, 900, 30)
		-- The switch the step-limit message asks for. A subagent that stops mid-job and
		-- says "I reached this session's step limit" has spent the whole dispatch and
		-- answered nothing, and until this existed the only way past it was to edit
		-- config.json -- `Unlimited tool calls` deliberately stops at the conversation the
		-- user is watching.
		R.toggle(agent, {
			label = "Unlimited subagents",
			hint = "Let a dispatched subagent run with no step limit and no clock, and make the call that dispatched it wait as long as the child takes. The repeat breaker, each tool's own timeout, the two ceilings below and Stop still apply -- and the Subagents panel can stop one on its own without ending the turn.",
			path = "agent.subagentUnlimited",
		})
		R.number(agent, "Parallel subagents",
			"Subagents alive at once across the whole tree. Several dispatched in one step run together; this is the ceiling on how many, including the ones a subagent starts itself. Anything over it waits for a slot.",
			"agent.subagentConcurrency", 1, 12, 1)
		-- Two ceilings that had no control anywhere: the only way to change either was
		-- to edit config.json, which for the depth cap means the only switch that can
		-- turn delegation off entirely was unreachable.
		R.number(agent, "Subagent steps",
			"Tool rounds one subagent may take before it has to answer the parent with what it has. Ignored while Unlimited subagents is on.",
			"agent.subagentTurns", 1, 30, 1)
		R.number(agent, "Delegation depth",
			"How many levels of subagent are allowed. A subagent given the full tool set can dispatch its own; at 0 the agent cannot dispatch at all and does the work in the conversation instead. The Subagents panel lists what is running under these limits.",
			"agent.subagentDepth", 0, 4, 1)
		R.number(agent, "Context budget",
			"Estimated tokens kept before older turns are summarised. Set it against the model's own window, not this client: a million-token model can hold the whole session.",
			"agent.contextTokens", BUDGET_STOPS)
		R.number(agent, "Reply ceiling",
			"max_tokens sent with each request. A value above the model's own limit is lowered to whatever the provider names in its refusal, once, and remembered.",
			"agent.maxTokens", REPLY_STOPS)
		R.number(agent, "Tool result cap",
			"Characters kept from one tool result, roughly four per token. This is the floor on how much a file read or a page fetch can actually return, whatever the tool's own limit says.",
			"agent.resultCap", RESULT_STOPS)
		R.choice(agent, "Effort",
			"How hard a reasoning model works before it answers. Sent as the provider's "
			.. "effort level and clamped to what the chosen model offers; models without one ignore it.",
			"agent.effort",
			{ "low", "medium", "high", "xhigh", "max" },
			{ "Low", "Medium", "High", "Very high", "Max" },
			{ "Faster", "Smarter" })
		R.number(agent, "Temperature",
			"Lower is steadier; 0 is as deterministic as the provider allows. The current Claude models reject it, and it is not sent to them.",
			"agent.temperature", 0, 1.5, 0.05)
		R.number(agent, "Retries", "Attempts per provider before moving to the next.",
			"agent.retries", 1, 6, 1)
		R.toggle(agent, {
			label = "Ask for streams",
			hint = "Streamed replies carry reasoning text and usage counts.",
			path = "agent.stream",
		})
		R.toggle(agent, {
			label = "Summarise old turns",
			hint = "Keeps a long conversation inside the context budget.",
			path = "agent.compaction",
		})
		R.toggle(agent, {
			label = "Provider fallback",
			hint = "Try the next enabled provider when one fails.",
			path = "agent.fallback",
		})
		-- One field, and the only half of the old language picker that was ever wired to
		-- anything. That control was a grid of eleven tiles behind a modal behind a menu
		-- entry, and it advertised two effects: the language the agent answers in, which
		-- src/agent/prompt.lua does read, and the locale dates are formatted with, which
		-- nothing reads at all. What survives is the effect that exists.
		R.field(agent, {
			name = "ReplyLanguage",
			label = "Reply language",
			hint = "Added to the system prompt as one line: answer in this language, leaving code "
				.. "and identifiers alone. Empty means whatever the conversation is already in, "
				.. "which is what a model does by default.",
			path = "agent.replyLanguage",
			placeholder = "Japanese",
		})
	end

	-- Permissions -------------------------------------------------------------

	local function panePermissions(container)
		local build = builder(container)
		local card = build.section("Permissions", permissions.MODE_HINTS[permissions.mode()])

		local modeOptions = {}
		for _, mode in ipairs(permissions.MODES) do
			modeOptions[#modeOptions + 1] = { value = mode, label = permissions.MODE_LABELS[mode] or mode }
		end
		local modeHint
		C.segmented(card, {
			options = modeOptions,
			value = permissions.mode(),
			onChange = function(value)
				permissions.setMode(value)
				if modeHint then modeHint.Text = permissions.MODE_HINTS[value] or "" end
			end,
		})
		modeHint = P.text(card, {
			text = permissions.MODE_HINTS[permissions.mode()] or "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		modeHint.Size = UDim2.new(1, 0, 0, 0)

		R.toggle(card, {
			label = "Offer to remember",
			hint = "Show the remember switch on each prompt.",
			path = "permissions.remember",
		})

		local rulesLabel = P.text(card, {
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		rulesLabel.Size = UDim2.new(1, 0, 0, 0)
		local function refreshRules()
			local rules = permissions.listRules()
			if #rules == 0 then
				rulesLabel.Text = "No per-tool rules saved."
				return
			end
			local parts = {}
			for _, rule in ipairs(rules) do
				parts[#parts + 1] = rule.pattern .. " = " .. rule.verdict
			end
			rulesLabel.Text = util.pluralise(#rules, "saved rule") .. ": " .. table.concat(parts, ", ")
		end
		refreshRules()
		local unsubscribe = permissions.changed:connect(function()
			if not rulesLabel.Parent then return end
			refreshRules()
		end)
		rulesLabel.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(card, { {
			name = "ClearRules",
			text = "Clear saved rules",
			variant = "ghost",
			onClick = function()
				permissions.clearRules()
				refreshRules()
			end,
		} })
	end

	-- Skills ------------------------------------------------------------------

	local function paneSkills(container)
		local build = builder(container)

		local memory = build.section("Memory",
			"Facts the agent has chosen to keep between sessions. It writes these itself, with "
			.. "the memory tool; this is where they can be read and removed.")
		R.toggle(memory, {
			label = "Enabled",
			hint = "When off, nothing new is stored and nothing is injected.",
			path = "memory.enabled",
		})
		local memoryText = P.text(memory, {
			name = "MemoryList",
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		memoryText.Size = UDim2.new(1, 0, 0, 0)
		local function refreshMemory()
			local list = state.memoryList()
			if #list == 0 then
				memoryText.Text = "Nothing stored."
				return
			end
			local lines = {}
			for _, entry in ipairs(list) do
				lines[#lines + 1] = entry.key .. ": " .. util.ellipsis(entry.value, 120)
			end
			memoryText.Text = table.concat(lines, "\n")
		end
		refreshMemory()
		local unsubscribe = state.memoryChanged:connect(function()
			if not memoryText.Parent then return end
			refreshMemory()
		end)
		memoryText.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(memory, { {
			name = "ForgetEverything",
			text = "Forget everything",
			variant = "ghost",
			onClick = function()
				overlay.confirm({
					title = "Clear memory?",
					description = "Every stored fact is deleted.",
					confirmText = "Clear",
					danger = true,
					onConfirm = function()
						state.clearMemory()
						refreshMemory()
					end,
				})
			end,
		} })

		local host = build.section("Host instructions",
			"A script that embeds this client can add its own instructions and hooks. This is "
			.. "what the current host provided.")
		local hostPrompt = env.context and env.context.prompt
		local hooks = env.require("agent/hooks")
		local hookCounts = {}
		for kind in pairs(hooks.KINDS) do
			local count = hooks.count(kind)
			if count > 0 then hookCounts[#hookCounts + 1] = { key = kind, value = tostring(count) } end
		end
		if type(hostPrompt) == "string" and util.trim(hostPrompt) ~= "" then
			R.paragraph(host, util.ellipsis(hostPrompt, 600), { role = "small", color = theme.color.text })
		else
			R.paragraph(host, "No host instructions: this client was loaded on its own.")
		end
		if #hookCounts > 0 then
			table.sort(hookCounts, function(a, b) return a.key < b.key end)
			R.facts(host, hookCounts, { name = "Hooks" })
		end
	end

	-- Connectors --------------------------------------------------------------

	local function paneConnectors(container)
		local build = builder(container)

		local card = build.section("Inference",
			"Where requests go. A provider is a base URL, an auth style, a key and a model.")
		local list = providers.list()
		if #list == 0 then
			R.paragraph(card, "Nothing configured yet.")
		else
			local facts = {}
			for _, record in ipairs(list) do
				local detail = record.baseUrl
				if util.trim(tostring(record.model or "")) ~= "" then
					detail = record.model .. "  " .. record.baseUrl
				end
				facts[#facts + 1] = {
					key = record.label,
					value = detail,
					tone = (providers.active() or {}).id == record.id and "good" or nil,
				}
			end
			R.facts(card, facts, { name = "Providers" })
		end
		R.actions(card, { {
			name = "OpenInference",
			text = "Configure third-party inference",
			variant = "secondary",
			onClick = function()
				env.require("ui/app").show("providers")
			end,
		} })

		local bridgeCard = build.section("Web bridge",
			"The one connector that is not a model: a browser on this machine sharing the "
			.. "conversation.")
		local status = bridgeModule.status()
		R.facts(bridgeCard, {
			{ key = "State", value = status.running and (status.online and "connected" or "polling") or "off",
				tone = status.running and (status.online and "good" or "warn") or nil },
			{ key = "Address", value = status.url },
		}, { name = "BridgeFacts" })
		R.actions(bridgeCard, { {
			name = "OpenCowork",
			text = "Open Cowork",
			variant = "ghost",
			onClick = function()
				env.require("ui/app").show("cowork")
			end,
		} })
	end

	-- Plugins -----------------------------------------------------------------

	local function panePlugins(container)
		local build = builder(container)
		local card = build.section("Tool groups",
			"A family of tools can be withheld from the model entirely. That is a different "
			.. "thing from denying a call: a tool that is not offered is one the model will not "
			.. "spend a turn discovering it cannot use.")

		for _, group in ipairs(registry.groups()) do
			local row = P.row(card, {
				name = "Group_" .. group.id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
			})
			local text = P.column(row, {
				size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
			})
			P.text(text, { text = group.label, role = "small" })
			local detail = util.pluralise(group.total, "tool")
			if group.unavailable > 0 then
				detail = detail .. ", " .. tostring(group.unavailable) .. " unavailable on this host"
			end
			P.text(text, {
				text = detail,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			local switch = C.switch(row, {
				value = group.enabled,
				onChange = function(value)
					registry.setGroupEnabled(group.id, value)
				end,
			})
			switch.instance.LayoutOrder = 2
		end

		R.actions(card, { {
			name = "OpenTools",
			text = "See every tool",
			variant = "secondary",
			onClick = function()
				env.require("ui/app").show("tools")
			end,
		} })
	end

	-- The list -----------------------------------------------------------------

	-- Grouped the way the reference client groups them. "Agent" is the one section it
	-- does not have, and it is not optional here: the step limit, the context budget
	-- and the permission mode are the settings this client is actually about, and
	-- filing them under Developer to preserve a menu shape would hide them.
	M.PANES = {
		{ id = "general", section = "Settings", label = "General", icon = "gear", build = paneGeneral },
		{ id = "privacy", section = "Settings", label = "Privacy", icon = "worktree", build = paneprivacy },
		{ id = "usage", section = "Settings", label = "Usage", icon = "sliders", build = paneUsage },
		{ id = "claude_code", section = "Settings", label = "Claude Code", icon = "code", build = paneClaudeCode },
		{ id = "cowork", section = "Settings", label = "Cowork", icon = "terminal", build = paneCowork },
		{ id = "import_export", section = "Settings", label = "Import & export", icon = "document", build = paneImportExport },
		{ id = "agent", section = "Agent", label = "Behaviour", icon = "spark", build = paneAgent },
		{ id = "permissions", section = "Agent", label = "Permissions", icon = "check", build = panePermissions },
		{ id = "desktop_general", section = "Desktop app", label = "General", icon = "windowMaximize", build = paneDesktop },
		{ id = "developer", section = "Desktop app", label = "Developer", icon = "terminal", build = paneDeveloper },
		{ id = "skills", section = "Customize", label = "Skills", icon = "book", build = paneSkills },
		{ id = "connectors", section = "Customize", label = "Connectors", icon = "branch", build = paneConnectors },
		{ id = "plugins", section = "Customize", label = "Plugins", icon = "worktree", build = panePlugins },
	}

	function M.pane(id)
		for _, entry in ipairs(M.PANES) do
			if entry.id == id then return entry end
		end
		return nil
	end

	-- The dialog's nav, in declaration order, with the section headings kept.
	function M.sections()
		local out, seen = {}, {}
		for _, entry in ipairs(M.PANES) do
			if not seen[entry.section] then
				seen[entry.section] = { title = entry.section, panes = {} }
				out[#out + 1] = seen[entry.section]
			end
			local group = seen[entry.section]
			group.panes[#group.panes + 1] = entry
		end
		return out
	end

	-- One pane into a container of its own. Used by the dialog when a category is
	-- chosen, and by the Settings panel for every pane in turn.
	function M.render(id, container)
		local entry = M.pane(id)
		if not entry then return false end
		local ok, err = pcall(entry.build, container)
		if not ok then
			log.warn("settings", "the " .. tostring(id) .. " pane failed to build", err)
			R.paragraph(container, "This pane could not be built: " .. tostring(err),
				{ color = theme.color.danger })
		end
		return ok
	end

	return M
end
end)()

-- ==========================================================================
-- ui/settingsrows
-- ==========================================================================
__UAI_MODULES["ui/settingsrows"] = (function()
-- The rows a settings surface is made of.
--
-- There are two of those surfaces now -- the Settings panel and the settings dialog
-- the sidebar opens -- and they have to agree about what a toggle looks like, how a
-- token budget is expressed as a track, and which config path a control writes. So
-- the rows live here and both surfaces call them, rather than the dialog growing a
-- second, subtly different set.
--
-- Every builder takes the config path it writes and nothing else about where the
-- value goes: the row reads the current value itself and writes it back itself, which
-- is why none of these return a handle to be wired up afterwards.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")

	local R = {}

	-- A heading with an optional description, followed by the card its rows go in.
	--
	-- Both go inside one wrapper with a tight gap between them, so the heading is
	-- visibly closer to the card it labels than to whatever is above it. As two loose
	-- siblings the two distances were the same number -- the parent's gap -- and a
	-- column of sections read as an alternating stack with no grouping in it.
	function R.section(parent, props)
		props = props or {}
		local group = P.column(parent, {
			name = props.name and (props.name .. "Group") or "Group",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = props.layoutOrder,
		})
		P.sectionHeader(group, {
			title = props.title,
			description = props.description,
			layoutOrder = 1,
		})
		return P.card(group, {
			name = props.name,
			layoutOrder = 2,
			gap = theme.space.md,
		})
	end

	function R.paragraph(parent, text, props)
		props = props or {}
		local label = P.text(parent, {
			name = props.name,
			text = tostring(text or ""),
			role = props.role or "caption",
			color = props.color or theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = props.layoutOrder,
		})
		label.Size = UDim2.new(1, 0, 0, 0)
		return label
	end

	function R.toggle(parent, props)
		local row = P.row(parent, {
			name = props.name,
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		local text = P.column(row, {
			size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
		})
		P.text(text, { text = props.label, role = "small" })
		if props.hint then
			P.text(text, {
				text = props.hint,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
		end
		local switch = C.switch(row, {
			value = (props.value ~= nil) and props.value or (config.get(props.path, false) == true),
			onChange = function(value)
				if props.path then config.set(props.path, value) end
				if props.onChange then pcall(props.onChange, value) end
			end,
		})
		switch.instance.LayoutOrder = 2
		return switch
	end

	-- A million in a 66px monospace field is a wall of zeroes, and the exact digit
	-- is never what the reader is checking at that size.
	local function formatCount(number)
		number = math.floor(number)
		if number >= 1000000 and number % 100000 == 0 then
			local millions = number / 1000000
			return (millions % 1 == 0) and string.format("%dM", millions) or string.format("%.1fM", millions)
		end
		if number >= 1000 and number % 1000 == 0 then return string.format("%dk", number / 1000) end
		return tostring(number)
	end

	R.formatCount = formatCount

	-- `min` may be a list of allowed values rather than a bound. Every row that
	-- counts tokens uses one: the range those rows have to cover is three orders of
	-- magnitude, and a linear track across it cannot resolve the low end where the
	-- useful settings are.
	function R.number(parent, label, hint, path, min, max, step)
		local stops
		if type(min) == "table" then
			stops, min, max, step = min, min[1], min[#min], nil
		end
		local function display(number)
			return (step and step < 1) and string.format("%.2f", number) or formatCount(number)
		end
		local column = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xxs })
		local head = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(head, {
			text = label,
			role = "small",
			-- Fills rather than reserving 70 for a 66px value plus a 6px gap, which
			-- overlapped it by two pixels.
			size = UDim2.new(0, 0, 0, theme.text.small.height),
			flex = "Fill",
			layoutOrder = 1,
		})
		local value = P.text(head, {
			text = display(tonumber(config.get(path, min)) or min),
			role = "monoSmall",
			color = theme.color.accent,
			align = "Right",
			layoutOrder = 2,
		})
		value.Size = UDim2.fromOffset(theme.size.metaColumn, theme.text.small.height)
		C.slider(column, {
			-- Named after the setting it writes, so the tree says which slider is
			-- which -- eight of them called "Slider" is unreadable from a dump and
			-- unreachable from a test.
			name = "Slider_" .. tostring(path),
			min = min,
			max = max,
			step = step,
			stops = stops,
			value = tonumber(config.get(path, min)) or min,
			onChange = function(number)
				value.Text = display(number)
			end,
			onCommit = function(number)
				config.set(path, (step and step < 1) and util.round(number, 2) or math.floor(number))
			end,
		})
		if hint then
			P.text(column, { text = hint, role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y" })
		end
		return column
	end

	-- A row whose stops are words rather than numbers.
	--
	-- A track is still the right control when the values are not numeric: the stops
	-- are ordered and the reader is picking a position on a scale, which a row of
	-- buttons states less clearly. The value reads in the label's own type rather
	-- than numberRow's monospace, because a word set in code font looks like an
	-- identifier, and both ends are named above the track -- what the scale *means*
	-- is the part neither the numbers nor the level names carry.
	function R.choice(parent, label, hint, path, values, labels, ends)
		local index, stored = 1, tostring(config.get(path, values[1]))
		for position, value in ipairs(values) do
			if value == stored then index = position end
		end
		local stops = {}
		for position = 1, #values do stops[position] = position end

		local column = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xxs })
		local head = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(head, {
			text = label,
			role = "small",
			size = UDim2.new(0, 0, 0, theme.text.small.height),
			flex = "Fill",
			layoutOrder = 1,
		})
		local value = P.text(head, {
			text = labels[index],
			role = "label",
			color = theme.color.accent,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})

		local feet = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(feet, {
			text = ends[1],
			role = "caption",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height),
			flex = "Fill",
			layoutOrder = 1,
		})
		P.text(feet, {
			text = ends[2],
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})
		C.slider(column, {
			name = "Slider_" .. tostring(path),
			stops = stops,
			value = index,
			onChange = function(number)
				value.Text = labels[math.floor(number)] or value.Text
			end,
			onCommit = function(number)
				local position = math.max(math.min(math.floor(number), #values), 1)
				value.Text = labels[position]
				config.set(path, values[position])
			end,
		})
		if hint then
			P.text(column, { text = hint, role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y" })
		end
		return column
	end

	-- Label and description on the left, one control on the right. The dialog's
	-- appearance pane is a column of these.
	--
	-- The right-hand slot states a width. It used to size itself to its contents,
	-- which for a segmented control -- whose own width is a scale when it is not given
	-- one -- resolved to zero: three controls in that pane were invisible and
	-- unclickable, and nothing about the props said so.
	function R.setting(parent, props)
		local row = P.row(parent, {
			name = props.name,
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignY = "Center",
			gap = theme.space.md,
			layoutOrder = props.layoutOrder,
		})
		local left = P.column(row, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		P.text(left, {
			text = props.label,
			role = "bodyStrong",
			color = theme.color.text,
			auto = "Y",
			wrap = true,
			layoutOrder = 1,
		})
		if props.hint then
			P.text(left, {
				text = props.hint,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
		end
		local right = P.frame(row, {
			name = "Control",
			size = UDim2.fromOffset(props.width or theme.size.menu, 0),
			auto = "Y",
			layoutOrder = 2,
		})
		return right, row
	end

	-- A setting row whose control is a segmented picker over a config path.
	function R.segmented(parent, props)
		local width = C.segmentedWidth(props.options)
		local slot = R.setting(parent, {
			name = props.name,
			label = props.label,
			hint = props.hint,
			width = width,
			layoutOrder = props.layoutOrder,
		})
		local control = C.segmented(slot, {
			name = props.name and ("Segmented_" .. props.name) or nil,
			options = props.options,
			width = width,
			value = (props.value ~= nil) and props.value or config.get(props.path, props.options[1].value),
			onChange = function(value)
				if props.path then config.set(props.path, value) end
				if props.onChange then pcall(props.onChange, value) end
			end,
		})
		return control
	end

	-- A setting row whose control is a menu rather than a row of segments.
	--
	-- Segments stop working somewhere around four options. The interface font list is
	-- eight families wide, and eight segments in a 530px pane give each label sixty
	-- pixels -- which "Titillium Web" does not fit into, and C.segmented neither
	-- truncates nor clips, so the labels would simply run into each other. Same
	-- decision, a control that does not have to show every option at once.
	function R.select(parent, props)
		local options = props.options or {}
		local current = (props.value ~= nil) and props.value
			or config.get(props.path, options[1] and options[1].value)

		local function labelFor(value)
			for _, option in ipairs(options) do
				if option.value == value then return option.label or tostring(value) end
			end
			return tostring(value)
		end

		local slot = R.setting(parent, {
			name = props.name,
			label = props.label,
			hint = props.hint,
			width = props.width or theme.size.menu,
			layoutOrder = props.layoutOrder,
		})

		local control
		control = P.rowButton(slot, {
			name = props.name and ("Select_" .. props.name) or "Select",
			height = math.max(theme.size.control, responsive.minTarget()),
			radius = theme.radius.md,
			stroke = true,
			strokeColor = theme.color.border,
			padding = { x = theme.space.sm },
			onClick = function(handle)
				local menuOptions = {}
				for _, option in ipairs(options) do
					menuOptions[#menuOptions + 1] = {
						label = option.label or tostring(option.value),
						value = option.value,
						detail = option.detail,
						selected = option.value == current,
					}
				end
				env.require("ui/overlay").menu({
					target = handle.instance,
					width = math.max(props.menuWidth or theme.size.menuWide,
						math.floor(handle.instance.AbsoluteSize.X)),
					options = menuOptions,
					onSelect = function(value)
						current = value
						control.text.Text = labelFor(value)
						if props.path then config.set(props.path, value) end
						if props.onChange then pcall(props.onChange, value) end
					end,
				})
			end,
		})
		control.text = control.label(labelFor(current), 1, theme.color.text, "small")
		local caret = P.frame(control.row, {
			name = "Caret",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 2,
		})
		env.require("ui/icons").chevron(caret, theme.size.icon, theme.color.textTertiary, "down")
		return control
	end

	-- A field bound to a config path, written on blur rather than per keystroke: a
	-- port typed one digit at a time would otherwise restart the bridge four times.
	function R.field(parent, props)
		if props.label then
			P.text(parent, { text = props.label, role = "small", layoutOrder = props.layoutOrder })
		end
		local field = P.field(parent, {
			name = props.name,
			text = tostring(props.value ~= nil and props.value or config.get(props.path, "")),
			placeholder = props.placeholder,
			size = props.size,
			layoutOrder = props.layoutOrder and (props.layoutOrder + 1) or nil,
			onBlur = function(text)
				local clean = util.trim(text)
				if props.transform then clean = props.transform(clean) end
				if props.path then config.set(props.path, clean) end
				if props.onChange then pcall(props.onChange, clean) end
			end,
		})
		if props.hint then R.paragraph(parent, props.hint) end
		return field
	end

	-- A row of buttons. Actions rather than settings: a reset, a clear, an unload.
	function R.actions(parent, list, props)
		props = props or {}
		local row = P.row(parent, {
			name = props.name or "Actions",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		for index, entry in ipairs(list) do
			local button = P.button(row, {
				name = entry.name,
				text = entry.text,
				variant = entry.variant or "secondary",
				size = "sm",
				layoutOrder = index,
				onClick = entry.onClick,
			})
			button.instance.LayoutOrder = index
		end
		return row
	end

	-- Key/value facts. Read-only by definition: these are things the client observed,
	-- not things it can be told.
	function R.facts(parent, list, props)
		props = props or {}
		local box = P.frame(parent, {
			name = props.name or "Facts",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.canvas,
			radius = theme.radius.md,
			padding = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		P.stroke(box, theme.color.borderSubtle)
		local column = P.column(box, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
		})
		for index, entry in ipairs(list) do
			C.keyValue(column, {
				key = entry.key,
				value = entry.value,
				layoutOrder = index,
				color = entry.tone and theme.toneColor(entry.tone) or theme.color.text,
			})
		end
		return box
	end

	return R
end
end)()

-- ==========================================================================
-- ui/sidebar
-- ==========================================================================
__UAI_MODULES["ui/sidebar"] = (function()
-- The sidebar: navigation, the mode switch, and the real conversation list.
--
-- Everything in here reads from `agent/session`. The list used to be three hardcoded
-- project names with eleven invented titles under them, copied from a screenshot --
-- which looked exactly right and told you nothing, and whose rows typed their own
-- label into the composer instead of opening anything. What is here now is the
-- threads the client actually has, grouped by the place they happened in, and
-- clicking one switches to it.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local sessions = env.require("agent/session")
	local subagent = env.require("agent/subagent")
	local providers = env.require("provider/registry")
	local place = env.require("runtime/place")

	local M = {}

	-- The panels the "More" row reveals. Chat is not in it: the mode switch above is
	-- what selects between the conversation and the shared session.
	local MORE_PANELS = {
		{ id = "agents", label = "Subagents", icon = "spark" },
		{ id = "providers", label = "Providers", icon = "sliders" },
		{ id = "tools", label = "Tools", icon = "worktree" },
		{ id = "logs", label = "Logs & traces", icon = "document" },
		{ id = "settings", label = "Settings", icon = "gear" },
	}

	function M.new(parent, host)
		local handle = {}

		-- One inset and one icon size for every row in here.
		--
		-- There were six of each. Row padding ran xxs, xs and md depending on which row
		-- it was, and the icon slot -- whose width is what decides where the label starts
		-- -- was written three different ways as `icon`, `icon - hair` and `icon - xxs`.
		-- The result was six different left text edges down one 240px column, two of them
		-- two pixels apart on adjacent rows. Both are also dimensionally wrong to
		-- subtract from each other: `space` scales by 0.78 under compact density and
		-- `size` by 0.86, so the gaps drifted rather than holding.
		local ROW_INSET = theme.space.xs
		local ROW_ICON = theme.size.icon

		local sidebar = P.column(parent, {
			name = "Sidebar",
			size = UDim2.fromScale(1, 1),
			-- One step of air between groups rather than the same six pixels used inside
			-- them: the nav strip, the mode switch, the new-conversation button, the action
			-- rows and the history are five separate things, and at a uniform xs they read
			-- as one undifferentiated stack.
			gap = theme.space.md,
			padding = { x = theme.space.sm, y = theme.space.sm },
		})

		-- Top row: the app menu, the collapse toggle, search, and the two history
		-- arrows. Every one of them does something; the pair that used to announce
		-- "Navigated to previous session" in a toast now actually goes there.
		--
		-- It wraps because on a touch device every one of these is forced to 44px by the
		-- hit-target floor, and five of those plus their gaps are wider than the sidebar.
		local topNav = P.row(sidebar, {
			name = "TopNav",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.xxs,
			layoutOrder = 1,
		})

		local function navButton(name, icon, order, onClick, enabled)
			local button = P.iconButton(topNav, {
				name = name,
				icon = icon,
				diameter = theme.size.controlSmall,
				layoutOrder = order,
				onClick = onClick,
			})
			button.instance.LayoutOrder = order
			if enabled == false then button.setEnabled(false) end
			return button
		end

		navButton("Nav_menu", "bars", 1, function()
			host.showAppMenu(topNav)
		end)
		navButton("Nav_sidebar", "sidebarToggle", 2, function()
			host.toggleSidebar()
		end)
		navButton("Nav_search", "search", 3, function()
			host.showSearch()
		end)
		handle.back = navButton("Nav_back", "arrowLeft", 4, function()
			host.back()
		end, host.canBack())
		handle.forward = navButton("Nav_forward", "arrowRight", 5, function()
			host.forward()
		end, host.canForward())

		-- Mode switch. "Cowork" is the browser-shared session -- the local bridge, which
		-- is the one thing in this client that is genuinely two people in one
		-- conversation -- and "Code" is the conversation itself. Both are real surfaces,
		-- so this selects a panel rather than setting a flag nothing reads.
		local modeRow = P.row(sidebar, {
			name = "ModeSwitcher",
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget())),
			bg = theme.color.surface,
			radius = theme.radius.pill,
			padding = theme.space.hair,
			gap = theme.space.hair,
			layoutOrder = 2,
			stretch = true,
		})

		local modes = {}
		local function modeButton(id, label, icon, order)
			local selected = host.panel == id
			local button = P.rowButton(modeRow, {
				name = "Segment_" .. id,
				size = UDim2.new(0.5, -theme.space.hair, 1, 0),
				height = theme.size.controlSmall,
				radius = theme.radius.pill,
				bg = selected and theme.color.surfaceActive or nil,
				selected = selected,
				alignX = "Center",
				gap = theme.space.xxs,
				padding = theme.space.none,
				onClick = function()
					host.show(id)
				end,
			})
			button.icon(icon, 1, selected and theme.color.text or theme.color.textTertiary,
				theme.size.icon - theme.space.xxs)
			local label2 = P.text(button.row, {
				text = label,
				role = "caption",
				color = selected and theme.color.text or theme.color.textTertiary,
				auto = "X",
				layoutOrder = 2,
			})
			modes[id] = { button = button, label = label2 }
			return button
		end
		modeButton("cowork", "Cowork", "terminal", 1)
		modeButton("chat", "Code", "code", 2)

		-- New conversation. A real thread rather than a wipe of the current one: the
		-- list below is what makes the difference visible, and clearing in place is what
		-- the composer's own clear control is for.
		local newButton = P.button(sidebar, {
			name = "NewChat",
			text = "+ New",
			variant = "secondary",
			size = "sm",
			fill = true,
			layoutOrder = 3,
			onClick = function()
				host.openSession(sessions.newThread().id)
			end,
		})
		newButton.instance.LayoutOrder = 3

		local actions = P.column(sidebar, {
			name = "ActionRows",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 4,
		})

		local customize = P.rowButton(actions, {
			name = "Customize",
			bg = nil,
			padding = { x = ROW_INSET },
			layoutOrder = 1,
			onClick = function()
				host.showSettingsDialog("claude_code")
			end,
		})
		customize.icon("sliders", 1, theme.color.textSecondary, ROW_ICON)
		customize.label("Customize", 2, theme.color.textSecondary)

		local expanded = config.get("ui.sidebarExpanded", false) == true
		local more = P.rowButton(actions, {
			name = "More",
			padding = { x = ROW_INSET },
			layoutOrder = 2,
			onClick = function()
				expanded = not expanded
				config.set("ui.sidebarExpanded", expanded, { quiet = true })
				handle.renderMore()
			end,
		})
		local moreIcon = more.icon("chevron", 1, theme.color.textSecondary, ROW_ICON)
		more.label("More", 2, theme.color.textSecondary)

		local moreList = P.column(actions, {
			name = "MorePanels",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 3,
		})

		function handle.renderMore()
			for _, child in ipairs(moreList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			-- The chevron points at what pressing it will do.
			for _, child in ipairs(moreIcon:GetChildren()) do child:Destroy() end
			icons.chevron(moreIcon, ROW_ICON, theme.color.textSecondary,
				expanded and "up" or "down")
			if not expanded then return end
			for index, entry in ipairs(MORE_PANELS) do
				local selected = host.panel == entry.id
				local row = P.rowButton(moreList, {
					name = "NavRow_" .. entry.id,
					padding = { x = ROW_INSET },
					selected = selected,
					layoutOrder = index,
					onClick = function()
						host.show(entry.id)
					end,
				})
				row.icon(entry.icon, 1, selected and theme.color.text or theme.color.textTertiary, ROW_ICON)
				-- How many subagents are working, on the row that leads to them. A
				-- dispatch runs for minutes with nothing on screen once its card has
				-- scrolled away, so the count is the only standing sign of it.
				local label = entry.label
				if entry.id == "agents" then
					local running = #subagent.running()
					if running > 0 then label = label .. "  " .. tostring(running) end
				end
				row.label(label, 2, selected and theme.color.text or theme.color.textSecondary)
			end
		end

		-- Same guard as the history, for the same reason: this rebuilds five rows and it
		-- is called from refresh, which runs on every status event of every turn. The
		-- three things it can show are which panel is selected, whether it is open, and
		-- how many subagents are running.
		local function moreSignature()
			return string.format("%s|%s|%d", tostring(host.panel),
				expanded and "+" or "-", #subagent.running())
		end

		function handle.syncMore(force)
			local signature = moreSignature()
			if not force and signature == handle.moreSignature then return false end
			handle.moreSignature = signature
			handle.renderMore()
			return true
		end

		handle.renderMore()
		handle.moreSignature = moreSignature()

		-- The conversation list, which takes whatever height is left rather than a
		-- hand-summed remainder: the stack above it changes height with density, with
		-- the platform's hit-target floor and with whether More is open, and a fixed
		-- offset was wrong in all three directions at once.
		local historyHolder = P.frame(sidebar, {
			name = "HistoryHolder",
			size = UDim2.new(1, 0, 0, 0),
			layoutOrder = 5,
		})
		local historyFlex = Instance.new("UIFlexItem", historyHolder)
		historyFlex.FlexMode = Enum.UIFlexMode.Fill

		local history = P.scroll(historyHolder, {
			name = "HistoryScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = { y = theme.space.xxs },
		})

		-- Which place groups are folded, by placeId.
		--
		-- Stored rather than kept in a local: the list is rebuilt from scratch on every
		-- new thread, rename, delete, place change and busy transition, so a local would
		-- unfold everything several times a minute. Quiet writes, because this is a
		-- record of what the user folded and not a token anything derives from -- a noisy
		-- one would reach the theme's subscription and rebuild the whole interface.
		local function collapsedKey(placeId)
			return "ui.placeCollapsed." .. tostring(placeId)
		end

		local function isCollapsed(placeId)
			return config.get(collapsedKey(placeId), false) == true
		end

		local function setCollapsed(placeId, value)
			config.set(collapsedKey(placeId), value == true, { quiet = true })
		end

		local function sessionMenu(session, target)
			overlay.menu({
				target = target,
				width = theme.size.menu,
				options = {
					{ isHeader = true, title = session.title, subtitle = session.placeName },
					{ label = "Open", value = "open", icon = "arrowRight" },
					{ label = "Rename", value = "rename", icon = "document" },
					{ label = "Delete", value = "delete", icon = "trash", tone = "bad" },
				},
				onSelect = function(value)
					if value == "open" then
						host.openSession(session.id)
					elseif value == "rename" then
						overlay.prompt({
							title = "Rename this conversation",
							description = "The transcript is untouched; only what the list calls it changes.",
							placeholder = "a short title",
							value = session.title,
							confirmText = "Rename",
							onConfirm = function(text)
								local ok, why = session.rename(text)
								if not ok then overlay.toast(tostring(why), "warn", 2) end
							end,
						})
					elseif value == "delete" then
						overlay.confirm({
							title = "Delete this conversation?",
							description = "The transcript and its file are both removed. This cannot be undone.",
							confirmText = "Delete",
							danger = true,
							onConfirm = function()
								sessions.remove(session.id)
								host.openSession(sessions.current().id)
							end,
						})
					end
				end,
			})
		end

		function handle.renderHistory()
			history.clear()
			local active = sessions.current()
			local groups = sessions.groups()
			local order = 0

			for _, group in ipairs(groups) do
				order = order + 1
				local column = P.column(history.instance, {
					name = "Place_" .. tostring(group.placeId),
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.hair,
					layoutOrder = order,
				})

				-- The group header is the fold control, so the whole line answers a click
				-- rather than a chevron nobody can hit. The count rides on it because a
				-- folded group has to say how much it is hiding -- otherwise folding one
				-- loses the only sign those conversations exist.
				local collapsed = isCollapsed(group.placeId)
				local head = P.rowButton(column, {
					name = "PlaceHead",
					height = theme.size.rowTight,
					-- The same inset as the rows it heads. It was xxs against their xs, so
					-- a group's name sat two pixels left of every conversation under it.
					padding = { x = ROW_INSET },
					gap = theme.space.xxs,
					layoutOrder = 1,
					onClick = function()
						setCollapsed(group.placeId, not isCollapsed(group.placeId))
						-- Through the signature, so the fold state it just wrote becomes the
						-- baseline the next change is compared against.
						handle.syncHistory()
					end,
				})
				-- Points at what pressing it will do, like the More row above.
				local caret = P.frame(head.row, {
					name = "PlaceCaret",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				icons.chevron(caret, theme.size.icon, theme.color.textTertiary,
					collapsed and "right" or "down")
				P.text(head.row, {
					name = "PlaceName",
					text = group.label,
					role = "overline",
					color = theme.color.textTertiary,
					size = UDim2.new(0, 0, 0, theme.text.overline.height),
					flex = "Fill",
					truncate = true,
					layoutOrder = 2,
				})
				-- How many are in there, and how many of those are working. The second
				-- number is the reason a fold is safe to leave shut: a group with a turn
				-- running in it still says so from the header.
				local busyCount = 0
				for _, session in ipairs(group.sessions) do
					if session.busy then busyCount = busyCount + 1 end
				end
				if busyCount > 0 then
					local slot = P.frame(head.row, {
						name = "PlaceBusy",
						size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
						layoutOrder = 3,
					})
					C.spinner(slot, {
						diameter = theme.size.icon,
						anchor = Vector2.new(0.5, 0.5),
						position = UDim2.fromScale(0.5, 0.5),
					})
				end
				local countLabel = P.text(head.row, {
					name = "PlaceCount",
					text = tostring(#group.sessions),
					role = "caption",
					color = theme.color.textTertiary,
					align = "Right",
					auto = "X",
					layoutOrder = 4,
				})
				countLabel.Size = UDim2.fromOffset(0, theme.text.caption.height)
				-- The place the client is in now is the only one a new conversation can
				-- be started in, so it is the only one that offers.
				if group.current then
					local plus = P.iconButton(head.row, {
						name = "NewInPlace",
						icon = "plus",
						diameter = theme.size.rowTight,
						layoutOrder = 5,
						onClick = function()
							host.openSession(sessions.newThread().id)
						end,
					})
					plus.instance.LayoutOrder = 5
				end

				-- The rows go in a holder of their own so folding hides one frame rather
				-- than each row: a hidden child still takes its slot in a list layout only
				-- if the layout can see it, and hiding thirty of them one at a time is
				-- thirty writes where one will do.
				local body = P.column(column, {
					name = "PlaceSessions",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.hair,
					layoutOrder = 2,
					visible = not collapsed,
				})

				for index, session in ipairs(group.sessions) do
					local selected = session.id == active.id
					local row = P.rowButton(body, {
						name = "SessionRow",
						height = theme.size.rowSmall,
						padding = { x = ROW_INSET },
						selected = selected,
						layoutOrder = index,
						onClick = function()
							host.openSession(session.id)
						end,
					})
					-- The leading slot is always there and usually empty.
					--
					-- It used to hold a hollow circle per row and a filled dot on the active
					-- one: a column of bullets down a 240px list whose only job was to say
					-- which row was selected, which the row's own highlight already says and
					-- says better. The slot itself stays, at the icon's width, because it is
					-- what puts every title on the same left edge as the group name above it
					-- -- and because a spinner has to be able to appear in a row without
					-- moving that row's text.
					--
					-- The spinner is the one thing here that survived: a conversation you are
					-- not looking at can still be working, leaving one does not stop it, and
					-- that is the one fact a row cannot state any other way. It is also the
					-- reason the list refreshes on every busy transition.
					local slot = P.frame(row.row, {
						name = "IconSlot",
						size = UDim2.fromOffset(ROW_ICON, ROW_ICON),
						layoutOrder = 1,
					})
					if session.busy then
						C.spinner(slot, {
							diameter = ROW_ICON,
							anchor = Vector2.new(0.5, 0.5),
							position = UDim2.fromScale(0.5, 0.5),
						})
					end
					local titleText = session.title
					if session.ephemeral then titleText = titleText .. "  (not saved)" end
					row.label(titleText, 2,
						selected and theme.color.text or theme.color.textSecondary,
						selected and "label" or nil)
					local menuButton = P.iconButton(row.row, {
						name = "SessionMenu",
						icon = "ellipsis",
						diameter = theme.size.rowTight,
						layoutOrder = 3,
						onClick = function(button)
							sessionMenu(session, button.instance)
						end,
					})
					menuButton.instance.LayoutOrder = 3
				end
			end

			if order == 0 then
				local empty = P.text(history.instance, {
					name = "NoHistory",
					text = "No conversations yet. Anything you send here is kept, grouped by the place it happened in.",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = ROW_INSET },
					layoutOrder = 1,
				})
				empty.Size = UDim2.new(1, 0, 0, 0)
			end
		end

		handle.renderHistory()

		P.divider(sidebar, { color = theme.color.borderSubtle, layoutOrder = 6 })

		-- The pinned profile row. The subtitle is the provider actually in use, which is
		-- what the reference client puts there and what someone looking at this wants to
		-- know -- it was a literal "Gateway" before, true only by coincidence.
		local profileName = "you"
		local okName, display = pcall(function() return env.plr and env.plr.DisplayName end)
		if okName and type(display) == "string" and util.trim(display) ~= "" then
			profileName = display
		elseif env.plr and type(env.plr.Name) == "string" and env.plr.Name ~= "" then
			profileName = env.plr.Name
		end

		local profile
		profile = P.rowButton(sidebar, {
			name = "ProfileBar",
			height = theme.size.bar,
			bg = theme.color.sidebar,
			padding = { x = ROW_INSET },
			layoutOrder = 7,
			onClick = function()
				host.showProfileMenu(profile.instance)
			end,
		})
		profile.icon("spark", 1, theme.color.accent, ROW_ICON)
		P.text(profile.row, {
			name = "ProfileName",
			text = profileName,
			role = "bodyStrong",
			line = theme.line.tight,
			color = theme.color.text,
			auto = "X",
			layoutOrder = 2,
		})
		local profileDetail = P.text(profile.row, {
			name = "ProfileProvider",
			text = "",
			role = "caption",
			line = theme.line.tight,
			color = theme.color.textTertiary,
			auto = "X",
			layoutOrder = 3,
		})
		P.spacer(profile.row, { grow = true, layoutOrder = 4 })
		local chevronSlot = P.frame(profile.row, {
			size = UDim2.fromOffset(ROW_ICON, ROW_ICON),
			layoutOrder = 5,
		})
		icons.chevron(chevronSlot, ROW_ICON, theme.color.textTertiary, "up")

		local function describeProvider()
			local record = providers.active()
			if not record then return "no provider" end
			local model = util.trim(tostring(record.model or ""))
			if model == "" then return record.label end
			return record.label
		end

		-- What the list currently shows, as a string.
		--
		-- The list is rebuilt from destroyed instances, and everything that can change it
		-- -- a new thread, a rename, a delete, a switch, a busy transition, a place
		-- resolving -- arrives as the same signal with no description of what moved. So
		-- the cheap thing is to ask whether the answer would differ before spending
		-- thirty instances per row finding out that it would not.
		--
		-- This is the stutter. `session.emit` fires listChanged on send, and app.syncNav
		-- runs on every status event -- of which a turn emits one per step plus one per
		-- request -- and each of those was tearing down and rebuilding every row in the
		-- sidebar. A twelve-conversation client spent about 1800 instance constructions
		-- per turn redrawing a list whose contents had not changed since the first one.
		local function listSignature()
			local parts = { tostring(sessions.activeId) }
			for _, group in ipairs(sessions.groups()) do
				parts[#parts + 1] = string.format("%s|%s|%s",
					tostring(group.placeId), tostring(group.label),
					isCollapsed(group.placeId) and "-" or "+")
				for _, session in ipairs(group.sessions) do
					parts[#parts + 1] = string.format("%s\1%s\1%s\1%s",
						tostring(session.id), tostring(session.title),
						session.busy and "b" or "-", session.ephemeral and "e" or "-")
				end
			end
			return table.concat(parts, "\2")
		end

		-- The list, only if it would look different. `force` is for the paths that know
		-- it changed for a reason the signature cannot see -- a fold, a theme rebuild.
		function handle.syncHistory(force)
			local signature = listSignature()
			if not force and signature == handle.signature then return false end
			handle.signature = signature
			handle.renderHistory()
			return true
		end

		function handle.refresh()
			profileDetail.Text = "\194\183 " .. describeProvider()
			for id, entry in pairs(modes) do
				local selected = host.panel == id
				entry.button.setSelected(selected)
				entry.label.TextColor3 = selected and theme.color.text or theme.color.textTertiary
			end
			handle.back.setEnabled(host.canBack())
			handle.forward.setEnabled(host.canForward())
			handle.syncMore()
			handle.syncHistory()
		end

		handle.signature = listSignature()

		-- The list is the app's own state: a new thread, a rename, a delete or a switch
		-- all have to show up here without the panel knowing this exists.
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not sidebar.Parent then return end
			handle.syncHistory()
		end)
		local unsubscribeProviders = providers.changed:connect(function()
			if not sidebar.Parent then return end
			profileDetail.Text = "\194\183 " .. describeProvider()
		end)
		local unsubscribePlace = place.changed:connect(function()
			if not sidebar.Parent then return end
			-- The place decides a group's label, which the signature covers.
			handle.syncHistory()
		end)
		-- The count on the Subagents row. Debounced, because the register changes on
		-- every tool call a child makes and this rebuilds a list of rows -- and
		-- debounced rather than throttled so the last change in a burst, which is the
		-- one that drops the count back to nothing, is not the one that gets dropped.
		local unsubscribeAgents = subagent.changed:connect(clock.debounce(function()
			if not sidebar.Parent then return end
			handle.syncMore()
		end, 0.3))

		sidebar.Destroying:Connect(function()
			pcall(unsubscribeSessions)
			pcall(unsubscribeProviders)
			pcall(unsubscribePlace)
			pcall(unsubscribeAgents)
		end)

		handle.instance = sidebar
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/theme
-- ==========================================================================
__UAI_MODULES["ui/theme"] = (function()
-- Design tokens.
--
-- Every colour, size, radius, weight and duration in the interface comes from
-- here. No use site writes a literal, which is the only way a project this size
-- stays coherent -- and it is what lets density, accent and text scale change at
-- runtime without hunting through forty files.
--
-- The palette is a warm neutral, not a cool one, and not pure black. Warm because
-- the whole ramp is one hue family with the accent -- a coral -- so a page of prose
-- with two inline code spans in it reads as one material rather than as grey with
-- orange stuck on. Not pure black because on an OLED phone pure black next to a 1px
-- hairline reads as a seam, and a slight lift keeps the surface hierarchy legible at
-- low brightness.
--
-- The lightness steps are deliberately close together at the dark end. The interface
-- it is modelled on separates a sidebar from a canvas from a card by two or three
-- percent of lightness and a hairline, never by a shadow or a heavy fill, and that is
-- what makes it read as flat rather than as a stack of boxes.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local signal = env.require("runtime/signal")

	local M = { changed = signal.new("theme") }

	local function rgb(r, g, b)
		return Color3.fromRGB(r, g, b)
	end

	-- Roblox has no alpha on Color3, so anything that would be a translucent
	-- overlay is pre-blended against the surface it sits on.
	function M.mix(from, to, alpha)
		return from:Lerp(to, util.clamp(alpha, 0, 1))
	end

	local NEUTRAL = {
		[0] = rgb(19, 19, 18),
		[1] = rgb(26, 26, 24),
		[2] = rgb(31, 30, 29),
		[3] = rgb(38, 38, 36),
		[4] = rgb(47, 47, 44),
		[5] = rgb(58, 58, 55),
		[6] = rgb(74, 74, 71),
		[7] = rgb(92, 91, 86),
		[8] = rgb(108, 107, 102),
		[9] = rgb(152, 150, 142),
		[10] = rgb(176, 174, 166),
		[11] = rgb(245, 244, 238),
	}

	-- Accents, all landing in the same lightness band so switching one does not
	-- change how loud the interface feels. The coral is the default and the one the
	-- rest of the palette is tuned around; the others are kept because someone who
	-- picked teal a version ago should not have it silently taken away.
	local ACCENTS = {
		claude = { base = rgb(217, 119, 87), hot = rgb(232, 146, 117), label = "Coral" },
		aurora = { base = rgb(58, 205, 186), hot = rgb(96, 226, 208), label = "Aurora" },
		indigo = { base = rgb(122, 136, 255), hot = rgb(153, 165, 255), label = "Indigo" },
		amber = { base = rgb(226, 160, 74), hot = rgb(243, 184, 108), label = "Amber" },
		rose = { base = rgb(240, 108, 138), hot = rgb(249, 142, 166), label = "Rose" },
	}

	M.ACCENTS = ACCENTS

	-- Type resolution, in two layers.
	--
	-- `Enum.Font` is the legacy pairing of a family with one baked-in weight --
	-- BuilderSansMedium is a member, and there is no way to ask that family for
	-- anything else. `FontFace` is the modern one: a family asset plus an independent
	-- weight axis, so a single family yields Regular, Medium and SemiBold rather than
	-- whichever pairs somebody happened to enumerate. Having the weight axis is most
	-- of the difference between type that reads as an application and type that reads
	-- as a 2016 forum: hierarchy comes from 400/500/600 at one or two sizes, not from
	-- jumping the size every level because only two weights exist.
	--
	-- The family string is never written here. It is read back off the engine with
	-- Font.fromEnum, so a family this client cannot load can never be named. A
	-- hardcoded rbxasset path has the opposite failure mode: it constructs fine and
	-- renders nothing, and there is no way to detect that from Lua.
	local function enumFont(name)
		local ok, item = pcall(function() return Enum.Font[name] end)
		if ok and item then return item end
		return nil
	end

	local function fontOr(name, fallback)
		return enumFont(name) or fallback
	end

	local function familyOf(name)
		local item = enumFont(name)
		if not item then return nil end
		local ok, face = pcall(function() return Font.fromEnum(item) end)
		if ok and face and type(face.Family) == "string" and face.Family ~= "" then
			return face.Family
		end
		return nil
	end

	-- Which point on the weight axis each role asks for. `strong` is SemiBold rather
	-- than Bold: at 15 and 16 pixels Bold on a dark ground blooms and reads as shouting,
	-- and 600 is what the interface this follows uses for a title.
	local WEIGHTS = { regular = "Regular", medium = "Medium", strong = "SemiBold" }

	local function faceFor(family, weight)
		if not family then return nil end
		local ok, face = pcall(function()
			return Font.new(family,
				Enum.FontWeight[WEIGHTS[weight] or "Regular"],
				Enum.FontStyle.Normal)
		end)
		if ok and face then return face end
		return nil
	end

	local SANS = fontOr("BuilderSans", Enum.Font.Gotham)
	local SANS_MEDIUM = fontOr("BuilderSansMedium", Enum.Font.GothamMedium)

	-- The interface and code families a person can actually pick from.
	--
	-- A free-text font field is the one control in the reference client that cannot be
	-- honest here: Roblox renders from a fixed set of families and cannot load a name it
	-- was handed, so naming JetBrains Mono in a box would change nothing. What is
	-- offered instead is the set that exists *on this client*, discovered rather than
	-- declared -- every candidate below is probed against the engine and dropped if it
	-- does not resolve, so an older client shows a shorter list instead of a list with
	-- dead entries in it.
	--
	-- Every name here is a real member of Enum.Font. That is not a stylistic point: an
	-- invented one would be silently dropped by the probe on a real client and silently
	-- *accepted* by the test harness, whose Enum proxy resolves anything asked of it --
	-- so a typo would surface as a font option that exists only in the tests.
	local INTERFACE_CANDIDATES = {
		{ id = "builder", label = "Builder Sans", regular = "BuilderSans", medium = "BuilderSansMedium" },
		{ id = "arimo", label = "Arimo", regular = "Arimo", medium = "ArimoBold" },
		{ id = "roboto", label = "Roboto", regular = "Roboto", medium = "Roboto" },
		{ id = "nunito", label = "Nunito", regular = "Nunito", medium = "Nunito" },
		{ id = "titillium", label = "Titillium Web", regular = "TitilliumWeb", medium = "TitilliumWeb" },
		{ id = "ubuntu", label = "Ubuntu", regular = "Ubuntu", medium = "Ubuntu" },
		{ id = "source", label = "Source Sans", regular = "SourceSans", medium = "SourceSansSemibold" },
		{ id = "gotham", label = "Gotham", regular = "Gotham", medium = "GothamMedium" },
	}

	-- Two, because Enum.Font has two monospace families and no more. Anything else a
	-- code editor would reach for -- JetBrains Mono, Inconsolata, Fira -- is not in the
	-- engine, and offering it would be offering nothing.
	local CODE_CANDIDATES = {
		{ id = "code", label = "Source Code Pro", regular = "Code" },
		{ id = "roboto", label = "Roboto Mono", regular = "RobotoMono" },
	}

	-- Resolution happens once, at load. Probing is a dozen pcalls; doing it per rebuild
	-- would repeat them on every accent change.
	local function resolveFamilies(candidates, fallbackEnum)
		local byId, order = {}, {}
		for _, entry in ipairs(candidates) do
			local regular = enumFont(entry.regular)
			local family = familyOf(entry.regular)
			-- Kept when either layer works: the family gives the weight axis, the enum
			-- alone still renders. Dropped only when the client has neither.
			if regular or family then
				byId[entry.id] = {
					id = entry.id,
					label = entry.label,
					family = family,
					enumName = entry.regular,
					regular = regular or fallbackEnum,
					medium = fontOr(entry.medium or entry.regular, regular or fallbackEnum),
					faces = {
						regular = faceFor(family, "regular"),
						medium = faceFor(family, "medium"),
						strong = faceFor(family, "strong"),
					},
				}
				order[#order + 1] = entry.id
			end
		end
		return byId, order
	end

	local INTERFACE_FONTS, INTERFACE_ORDER = resolveFamilies(INTERFACE_CANDIDATES, SANS)
	local CODE_FONTS, CODE_ORDER = resolveFamilies(CODE_CANDIDATES, Enum.Font.Code)

	M.INTERFACE_FONTS = INTERFACE_FONTS
	M.INTERFACE_ORDER = INTERFACE_ORDER
	M.CODE_FONTS = CODE_FONTS
	M.CODE_ORDER = CODE_ORDER

	-- The first candidate that resolved, which is the most contemporary family this
	-- client has. Named rather than assumed: on a client old enough to be missing
	-- Builder Sans the default has to move, and a stored setting naming a family that
	-- is not here has to fall back to something rather than to nil.
	M.defaultInterfaceFont = INTERFACE_ORDER[1] or "gotham"
	M.defaultCodeFont = CODE_ORDER[1] or "code"

	-- The two code palettes the appearance pane previews and the transcript uses.
	--
	-- Light is a real option rather than a swatch: a code block on a light card in a
	-- dark interface is what the reference client does, and the setting has to change
	-- what a fenced block in the transcript looks like or it is decoration.
	local CODE_THEMES = {
		dark = {
			label = "Claude Dark",
			surface = NEUTRAL[0],
			border = NEUTRAL[4],
			bar = NEUTRAL[2],
			text = NEUTRAL[11],
			-- Line numbers and the language label. It has to clear 3:1 on the bar it
			-- sits on: a gutter nobody can read is a column of noise down the left.
			gutter = NEUTRAL[9],
			addSurface = rgb(24, 54, 34),
			addText = rgb(126, 217, 148),
			removeSurface = rgb(64, 28, 32),
			removeText = rgb(240, 138, 132),
		},
		light = {
			label = "Claude Light",
			surface = rgb(250, 249, 245),
			border = rgb(214, 211, 202),
			bar = rgb(237, 235, 228),
			text = rgb(38, 38, 36),
			gutter = rgb(112, 110, 103),
			addSurface = rgb(219, 245, 226),
			addText = rgb(21, 105, 55),
			removeSurface = rgb(252, 226, 226),
			removeText = rgb(163, 32, 32),
		},
	}
	local CODE_THEME_ORDER = { "dark", "light" }

	M.CODE_THEMES = CODE_THEMES
	M.CODE_THEME_ORDER = CODE_THEME_ORDER

	-- Line heights, named. Four of them were loose numbers inside the type table and
	-- three more were repeated at use sites that needed a label to sit on a control's
	-- centre line -- a title at the reading measure of 1.6 is 40px of box around 16px
	-- of glyph, which is why the window header's two lines had one pixel of air above
	-- and below them.
	-- `code` is the loosest of them on purpose. A block of output is read one line at
	-- a time, looking for the one that matters, and at the 1.5 the rest of the mono
	-- text uses, eleven lines of `key: value` arrive as a solid slab -- the gaps
	-- between the lines are what the eye scans down.
	M.line = { tight = 1.2, snug = 1.35, normal = 1.5, reading = 1.6, code = 1.85 }

	-- Body text is the one thing in here a person actually reads, so it gets the
	-- room: 14 on a 1.6 line, which is a reading measure rather than a UI measure.
	-- Everything that is not prose is quieter and tighter than it used to be --
	-- headings a step down, labels one weight rather than bold-and-uppercase --
	-- because the interface this follows gets its hierarchy from spacing and colour,
	-- not from size. A 22px bold display over 13px body is a dashboard; this is a
	-- document with controls at the edges.
	--
	-- `weight` names a point on the family's weight axis rather than a font, because
	-- the family is a setting: the interface font and the code font are both pickable,
	-- and a resolved Enum.Font baked in here could not follow them.
	local BASE_TEXT = {
		display = { size = 19, weight = "strong", line = M.line.tight },
		title = { size = 16, weight = "strong", line = M.line.tight },
		heading = { size = 15, weight = "medium", line = M.line.snug },
		body = { size = 14, weight = "regular", line = M.line.reading },
		bodyStrong = { size = 14, weight = "medium", line = M.line.reading },
		small = { size = 13, weight = "regular", line = M.line.normal },
		label = { size = 12, weight = "medium", line = M.line.tight },
		caption = { size = 12, weight = "regular", line = M.line.snug },
		overline = { size = 11, weight = "medium", line = M.line.tight },
		mono = { size = 13, weight = "mono", line = M.line.normal },
		monoSmall = { size = 12, weight = "mono", line = M.line.normal },
	}

	local BASE_SPACE = {
		none = 0, hair = 2, xxs = 4, xs = 6, sm = 8, md = 12, lg = 16, xl = 20, xxl = 28, huge = 40,
	}

	local BASE_SIZE = {
		control = 32,      -- default button / field height
		controlSmall = 26,
		controlLarge = 38,
		icon = 16,
		iconLarge = 20,
		row = 34,
		-- Tall enough for two lines of chrome plus air. At 42 the window header's title
		-- and subtitle -- 40px of type between them at the reading measure -- had a
		-- single pixel above and below, so the title touched the window's top edge.
		header = 48,
		rail = 52,
		tab = 30,
		launcher = 44,
		scrollbar = 4,
		avatar = 26,
		-- The switch. `switchWide` is the width, kept as a token because it was a
		-- hardcoded 38 that four panels each reserved a hand-summed 46 for -- every one
		-- of which would have gone wrong the moment either number moved. Those rows now
		-- fill instead of reserving, but the size still belongs here.
		switch = 20,
		switchWide = 34,
		-- Slider and progress geometry.
		track = 3,
		knob = 12,
		-- The label column in a key/value list, wide enough for the longest key any
		-- panel in here uses.
		keyColumn = 104,
		-- Status dots, and the right-hand column a transcript row puts a duration or a
		-- progress count in. Both were literals repeated at five and three sites
		-- respectively, with two of the dot sizes disagreeing by a pixel.
		dot = 6,
		dotSmall = 4,
		metaColumn = 52,
		metaColumnWide = 88,
		-- Overlay widths. Twelve independent literals between 160 and 420 used to
		-- decide how wide a menu, a dropdown or a dialog was, which is why no two
		-- dialogs in here were the same width.
		menu = 200,
		menuMin = 160,
		menuWide = 320,
		menuMax = 320,
		modal = 380,
		modalWide = 480,
		modalMin = 260,
		-- The reading column. Past roughly this width a line of prose becomes a single
		-- sentence a foot long, which is unreadable however correct the layout is.
		-- Overridden by the transcript-width setting, which is why the three widths it
		-- offers are tokens too rather than numbers in a panel.
		reading = 1180,
		readingNarrow = 760,
		readingMedium = 980,
		sidebar = 240,
		-- Dense list furniture: a session row in the sidebar, a group header above it,
		-- the pinned profile bar at the bottom, a chip in the composer.
		rowSmall = 26,
		rowTight = 22,
		bar = 36,
		chip = 22,
		-- The home card: its column, one metric tile, and one cell of the activity
		-- grid. All three were literals in the surface that drew them.
		statCard = 560,
		statTile = 56,
		cell = 11,
		-- The settings dialog, which is a window of its own rather than a modal card.
		dialog = 760,
		dialogTall = 520,
		dialogNav = 190,
	}

	-- Corners are tighter than they were. A 16px radius on a card reads as a mobile
	-- widget; 6 to 10 reads as a document panel, which is what this is.
	M.radius = { none = 0, xs = 2, sm = 4, md = 6, lg = 10, xl = 14, pill = 999 }
	M.stroke = { hair = 1, focus = 2 }

	-- The visual constants that are neither a colour nor a size. They were literals
	-- at half a dozen use sites, which is how the modal scrim ended up at 0.45 and the
	-- quick-chat scrim -- the same effect, one layer up -- at 0.5.
	M.opacity = { scrollbar = 0.4, scrim = 0.5, dim = 0.6 }

	-- How far a surface is scaled down as it enters. Small on purpose: a panel that
	-- springs in from 0.9 is a phone app, and three surfaces here were each doing it
	-- by a slightly different amount.
	M.scale = { enter = 0.98 }

	M.motion = {
		-- Durations, in seconds, for a caller that needs a number rather than a tween.
		fast = 0.12,
		base = 0.18,
		slow = 0.3,
		-- Tweens. `instant` is a real TweenInfo rather than a zero, because the thing
		-- callers actually want from it is "apply this now" through the same
		-- TweenService path as every other paint -- a bare 0 is not a TweenInfo and
		-- cannot be passed to Create at all.
		instant = TweenInfo.new(0.01, Enum.EasingStyle.Linear),
		enter = TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		exit = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
		hover = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		press = TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		slide = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		-- The repeating pair. These are the only tweens here with a negative repeat
		-- count, and they deliberately do not go through M.tween: collapsing the
		-- duration to 0.01s for reduced motion would spin them at a hundred hertz
		-- rather than stop them. Callers check responsive.reduceMotion themselves and
		-- skip the tween entirely.
		spin = TweenInfo.new(0.9, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1),
		pulse = TweenInfo.new(0.85, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut, -1, true),
	}

	-- A dropdown is always opened from something, so it has to sit above whatever
	-- opened it -- including a modal. It used to rank below one, which is why the
	-- preset menu in the Add provider dialog opened behind the dialog.
	M.z = { base = 1, raised = 10, header = 20, overlay = 100, modal = 160, dropdown = 200, quick = 210, toast = 240 }

	-- Recomputed whenever density, accent or text scale changes.
	function M.rebuild()
		local accentName = config.get("ui.accent", "claude")
		local accent = ACCENTS[accentName] or ACCENTS.claude
		local density = config.get("ui.density", "comfortable")
		local compact = density == "compact"
		local textScale = util.clamp(tonumber(config.get("ui.fontScale", 1)) or 1, 0.85, 1.4)
		local spaceScale = compact and 0.78 or 1
		local sizeScale = compact and 0.86 or 1

		M.accentName = accentName
		M.density = density

		-- Families. Both layers resolve here: `enum` is what gets assigned to Font and
		-- always works, `face` is the FontFace that carries the weight axis and is
		-- applied over the top when the client has one. A stored id naming a family this
		-- client does not have falls back to the first that resolved rather than to nil.
		local family = INTERFACE_FONTS[config.get("ui.interfaceFont", M.defaultInterfaceFont)]
			or INTERFACE_FONTS[M.defaultInterfaceFont]
			or INTERFACE_FONTS[INTERFACE_ORDER[1]]
		local monoFamily = CODE_FONTS[config.get("ui.codeFont", M.defaultCodeFont)]
			or CODE_FONTS[M.defaultCodeFont]
			or CODE_FONTS[CODE_ORDER[1]]

		local enums = {
			regular = (family and family.regular) or SANS,
			medium = (family and family.medium) or SANS_MEDIUM,
			-- No legacy member is a semibold of anything except Source Sans, so `strong`
			-- degrades to medium rather than to bold: one step too heavy is louder than
			-- one step too light, and this is the fallback path.
			strong = (family and family.medium) or SANS_MEDIUM,
			mono = (monoFamily and monoFamily.regular) or Enum.Font.Code,
		}
		local faces = {
			regular = family and family.faces.regular or nil,
			medium = family and family.faces.medium or nil,
			strong = family and family.faces.strong or nil,
			mono = monoFamily and monoFamily.faces.regular or nil,
		}

		M.interfaceFontName = (family and family.label) or "Gotham"
		M.codeFontName = (monoFamily and monoFamily.label) or "Source Code Pro"
		-- The legacy enum name, for RichText's `face` attribute -- which takes an
		-- Enum.Font name string and knows nothing about FontFace. Inline code in a reply
		-- goes through it, so it has to follow the code-font setting rather than saying
		-- "Code" forever.
		M.codeFontEnumName = (monoFamily and monoFamily.enumName) or "Code"
		-- Whether the weight axis is live, so the appearance pane can say so instead of
		-- claiming a weight the client is not rendering.
		M.hasFontFace = faces.regular ~= nil

		local codeThemeName = config.get("ui.codeTheme", "dark")
		local code = CODE_THEMES[codeThemeName] or CODE_THEMES.dark
		M.codeThemeName = CODE_THEMES[codeThemeName] and codeThemeName or "dark"
		M.code = code

		M.color = {
			-- Surfaces, darkest to lightest. The canvas sits one step above the
			-- deepest tone rather than on it, so a code block can go *below* the page
			-- it is on -- which is how the interface this follows separates verbatim
			-- text from prose, and it needs a step in hand to do it.
			canvas = NEUTRAL[1],
			sidebar = NEUTRAL[0],
			sidebarActive = NEUTRAL[2],
			surface = NEUTRAL[2],
			surfaceRaised = NEUTRAL[3],
			surfaceOverlay = NEUTRAL[4],
			surfaceHover = NEUTRAL[4],
			surfaceActive = NEUTRAL[5],
			scrim = NEUTRAL[0],

			activityBlue = rgb(59, 130, 246),
			activityBlueLight = rgb(96, 165, 250),
			activityBlueDark = rgb(37, 99, 235),
			activityCell = NEUTRAL[2],

			-- Lines.
			-- Outlines sit three to five steps above the surface they are drawn on.
			-- borderSubtle used to be NEUTRAL[3], one step above surfaceRaised, which
			-- is a contrast ratio of about 1.05 to 1 -- every card edge, every
			-- segmented outline and the header rule were all invisible, and the
			-- interface read as untitled blocks of near-black rather than as panels.
			borderSubtle = NEUTRAL[5],
			border = NEUTRAL[6],
			borderStrong = NEUTRAL[7],

			-- Type. Secondary and tertiary each moved a step brighter: on a warm dark
			-- ramp the old pair sat at 3.1 and 2.4 to 1 against the canvas, and a
			-- caption nobody can read is a caption that may as well not be there.
			text = NEUTRAL[11],
			textSecondary = NEUTRAL[10],
			textTertiary = NEUTRAL[9],
			textDisabled = NEUTRAL[8],
			textOnAccent = NEUTRAL[0],

			-- The one loud action. A cream fill with dark text, which is what the
			-- interface this follows uses for its single primary control per view --
			-- and it is deliberately not the accent: reserving colour for meaning
			-- (inline code, a running turn, a risk) is what keeps the accent readable
			-- as meaning rather than as decoration.
			solid = NEUTRAL[11],
			solidHover = M.mix(NEUTRAL[11], rgb(255, 255, 255), 0.5),
			solidPress = NEUTRAL[10],
			onSolid = NEUTRAL[0],

			-- Accent and its quiet variants.
			accent = accent.base,
			accentHot = accent.hot,
			accentMuted = M.mix(NEUTRAL[2], accent.base, 0.4),
			accentSurface = M.mix(NEUTRAL[3], accent.base, 0.14),
			accentBorder = M.mix(NEUTRAL[5], accent.base, 0.5),

			-- Status. Saturated enough to read at caption size against a warm dark
			-- ramp, and pulled away from the coral in hue so a danger row and an
			-- accented row are not the same colour with a different label on it.
			success = rgb(94, 200, 124),
			successSurface = M.mix(NEUTRAL[3], rgb(94, 200, 124), 0.13),
			warn = rgb(226, 170, 78),
			warnSurface = M.mix(NEUTRAL[3], rgb(226, 170, 78), 0.13),
			danger = rgb(219, 82, 76),
			dangerSurface = M.mix(NEUTRAL[3], rgb(219, 82, 76), 0.13),
			dangerBorder = M.mix(NEUTRAL[5], rgb(219, 82, 76), 0.45),
			info = rgb(120, 162, 226),
			infoSurface = M.mix(NEUTRAL[3], rgb(120, 162, 226), 0.13),

			-- The one message surface. The agent's turn is the canvas itself -- a reply
			-- is the page, not an object on it -- and tool rows, subagent cards and
			-- reasoning are all flat now too, so the only fill left in a transcript is
			-- the user's own turn.
			--
			-- Tinted a few percent toward the accent rather than left on surfaceRaised.
			-- surfaceRaised is what a text field is filled with, so the user's own turn
			-- and the composer below it were the same colour with the same corner radius
			-- -- which is why a sent question read as an input box someone had typed into
			-- and not submitted.
			bubbleUser = M.mix(NEUTRAL[3], accent.base, 0.07),
			bubbleUserBorder = M.mix(NEUTRAL[5], accent.base, 0.18),
			-- The code palette, which is a setting: a fenced block in the transcript,
			-- the diff preview in the appearance pane and the identity readout all draw
			-- from these, so switching the code theme changes what code looks like
			-- rather than only what the preview looks like.
			codeSurface = code.surface,
			codeBorder = code.border,
			codeBar = code.bar,
			codeText = code.text,
			codeGutter = code.gutter,
			codeAddSurface = code.addSurface,
			codeAddText = code.addText,
			codeRemoveSurface = code.removeSurface,
			codeRemoveText = code.removeText,
		}

		M.text = {}
		for role, spec in pairs(BASE_TEXT) do
			local size = math.max(math.floor(spec.size * textScale + 0.5), 8)
			M.text[role] = {
				size = size,
				font = enums[spec.weight] or enums.regular,
				-- May be nil, and a nil FontFace is never assigned -- P.text applies the
				-- enum first and only layers the face over it when there is one.
				face = faces[spec.weight],
				weight = spec.weight,
				line = spec.line,
				-- One rendered line, rounded up. A fixed-height label sized from `size`
				-- alone clips its descenders the moment the line height goes past 1.3,
				-- so the height a caller needs is published rather than recomputed.
				height = math.ceil(size * spec.line),
			}
		end

		M.space = {}
		for name, value in pairs(BASE_SPACE) do
			M.space[name] = (value == 0) and 0 or math.max(math.floor(value * spaceScale + 0.5), 1)
		end

		M.size = {}
		for name, value in pairs(BASE_SIZE) do
			-- Floored at one, not at eight. The old floor predated the small tokens and
			-- silently clamped every one of them: a 3px slider track, a 4px scrollbar and
			-- a 6px status dot all came out as 8, which is why the scrollbar had never
			-- been the width it said it was.
			M.size[name] = math.max(math.floor(value * sizeScale + 0.5), 1)
		end

		-- The transcript column is the one size a setting names directly. Resolved after
		-- the ramp so the chosen width is the chosen width rather than the chosen width
		-- times the density scale.
		local widths = {
			narrow = M.size.readingNarrow,
			medium = M.size.readingMedium,
			wide = M.size.reading,
		}
		M.readingName = config.get("ui.transcriptWidth", "wide")
		if not widths[M.readingName] then M.readingName = "wide" end
		M.size.reading = widths[M.readingName]

		M.changed:fire(M)
		return M
	end

	-- Convenience accessors so a use site reads as prose.
	function M.textRole(role)
		return M.text[role] or M.text.body
	end

	function M.riskColor(risk)
		if risk == "read" then return M.color.textSecondary end
		if risk == "danger" then return M.color.danger end
		return M.color.warn
	end

	function M.toneColor(tone)
		if tone == "good" then return M.color.success end
		if tone == "warn" then return M.color.warn end
		if tone == "bad" then return M.color.danger end
		if tone == "accent" then return M.color.accent end
		-- "neutral" is a fact rather than a status -- a model id, an auth style -- and
		-- it is the default, because most chips in here are labels that happened to be
		-- given a colour by a tone system that had no way to say "no tone".
		if tone == "neutral" then return M.color.textSecondary end
		return M.color.info
	end

	function M.toneSurface(tone)
		if tone == "good" then return M.color.successSurface end
		if tone == "warn" then return M.color.warnSurface end
		if tone == "bad" then return M.color.dangerSurface end
		if tone == "accent" then return M.color.accentSurface end
		if tone == "neutral" then return M.color.surfaceOverlay end
		return M.color.infoSurface
	end

	-- Motion respects the platform preference: GuiService.ReducedMotionEnabled is
	-- a real accessibility setting, and an interface that ignores it is the sort of
	-- thing that makes people close it.
	function M.tween(name)
		local responsive = env.require("ui/responsive")
		if responsive.reduceMotion then
			return M.motion.instant
		end
		local info = M.motion[name]
		-- Only a TweenInfo may come back. The table also holds plain durations, and
		-- returning 0.18 to a caller about to pass it to TweenService is a crash a
		-- typo away.
		if typeof(info) == "TweenInfo" then return info end
		return M.motion.hover
	end

	function M.duration(name)
		local responsive = env.require("ui/responsive")
		if responsive.reduceMotion then return 0.01 end
		local value = M.motion[name]
		if type(value) == "number" then return value end
		return M.motion.base
	end

	M.rebuild()

	-- Density, accent and scale live in config, so the theme rebuilds itself when any
	-- of them is written rather than every panel having to remember to.
	--
	-- Only the keys that decide a token, though. A rebuild fires theme.changed, which
	-- the app answers by destroying and reconstructing every panel, the window and the
	-- launcher -- so accepting the whole `ui.` namespace meant that maximising the
	-- window, moving the launcher, switching panel or pinning the layout each tore the
	-- interface down and built it again. Anything not in this table cannot change a
	-- token, and so has no business rebuilding anything.
	local TOKEN_KEYS = {
		["ui.accent"] = true,
		["ui.density"] = true,
		["ui.fontScale"] = true,
		["ui.interfaceFont"] = true,
		["ui.codeFont"] = true,
		["ui.codeTheme"] = true,
		["ui.transcriptWidth"] = true,
	}

	config.changed:connect(function(path)
		-- nil is a whole-file load; "ui" is a namespace reset, which startsWith("ui.")
		-- does not match and which used to leave the interface on the old tokens.
		if path == nil or path == "ui" or TOKEN_KEYS[tostring(path)] then
			M.rebuild()
		end
	end)

	return M
end
end)()

-- ==========================================================================
-- ui/window
-- ==========================================================================
__UAI_MODULES["ui/window"] = (function()
-- The window shell: chrome, drag, resize, snap, maximise, and the three layout
-- modes it has to be able to become.
--
-- On a phone it is a bottom sheet that lifts above the on-screen keyboard. On a
-- small viewport it docks to the right edge full height. On a desktop it is a
-- floating window whose geometry is remembered. On a console it is a large centred
-- panel with no drag, because there is no pointer to drag with.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")

	local DRAG_SLOP = 6
	local SNAP_MARGIN = 18
	local RESIZE_GRIP = 18

	local M = {}

	function M.new(parent, props)
		props = props or {}
		local minWidth = props.minWidth or 320
		local minHeight = props.minHeight or 280

		local root = Instance.new("CanvasGroup", parent)
		root.Name = props.name or "Window"
		root.BackgroundColor3 = theme.color.canvas
		root.BorderSizePixel = 0
		root.GroupTransparency = 1
		root.Visible = false
		root.Active = true
		root.ZIndex = theme.z.raised
		P.corner(root, theme.radius.xl)
		local outline = P.stroke(root, theme.color.border)

		-- No UIScale on this, deliberately.
		--
		-- A CanvasGroup renders every child into one offscreen texture and then draws
		-- that texture. Drawing it at anything other than 1:1 resamples it -- so a
		-- UIScale of 0.98 on the way in did not make the window 2% smaller, it made
		-- every glyph in the entire interface soft for the length of the animation. And
		-- the scale only returned to 1 when the tween finished: interrupt it by hiding,
		-- rebuilding for a theme change, or opening twice inside a quarter of a second,
		-- and the window stayed at 0.98 for the rest of the session, blurry, with
		-- nothing on screen to explain why. A 2% zoom nobody can see is not worth that;
		-- the fade below is what a CanvasGroup is actually good at, because it
		-- composites the whole group at one alpha for free.

		local handle = {
			root = root,
			visible = false,
			maximised = config.get("ui.window.maximised", false) == true,
		}

		-- Everything this window leaves running outside its own instance tree, released
		-- together by handle.destroy.
		--
		-- A rebuild destroys the window and builds another, and the app now rebuilds for a
		-- sidebar toggle as well as for a mode or token change. Each of the three
		-- subscriptions below used to outlive its window: two InputChanged handlers
		-- registered with the global disposer and never unregistered, and a
		-- responsive.changed handler whose unsubscribe was discarded outright -- so after
		-- five rebuilds five dead handlers were still laying out five destroyed windows on
		-- every viewport change.
		local releases = {}

		-- Geometry ------------------------------------------------------------

		local function saveGeometry()
			if responsive.mode == "panel" then
				config.set("ui.mobilePanel.width", math.floor(root.AbsoluteSize.X), { quiet = true })
				config.set("ui.mobilePanel.height", math.floor(root.AbsoluteSize.Y), { quiet = true })
				config.set("ui.mobilePanel.x", math.floor(root.Position.X.Offset), { quiet = true })
				config.set("ui.mobilePanel.y", math.floor(root.Position.Y.Offset), { quiet = true })
				config.set("ui.mobilePanel.placed", true, { quiet = true })
				return
			end
			if responsive.mode ~= "window" then return end
			config.set("ui.window.width", math.floor(root.AbsoluteSize.X), { quiet = true })
			config.set("ui.window.height", math.floor(root.AbsoluteSize.Y), { quiet = true })
			config.set("ui.window.x", math.floor(root.Position.X.Offset), { quiet = true })
			config.set("ui.window.y", math.floor(root.Position.Y.Offset), { quiet = true })
			config.set("ui.window.placed", true, { quiet = true })
		end

		local persistGeometry = clock.debounce(saveGeometry, 0.6)

		-- A size that leaves the window on whole pixels when it is centred.
		--
		-- The same texture problem as the scale, from the other direction: this window is
		-- centred with a 0.5 anchor, so its left edge lands at (available - width) / 2 --
		-- a half pixel whenever that difference is odd. Roblox then draws the group's
		-- texture at a half-pixel offset and resamples it, and the whole interface goes
		-- soft. Nothing about the window changed to cause it, which is what makes it
		-- baffling from the outside: one pixel of viewport, one drag of the resize grip
		-- or a restored size with the wrong parity is enough, and it stays that way.
		--
		-- So a centred dimension is nudged by one pixel to keep the space around it even.
		-- Nobody can see the pixel; everybody can see the blur.
		local function centred(available, wanted, floor)
			local value = math.floor(wanted)
			if (math.floor(available) - value) % 2 ~= 0 then
				if value - 1 >= (floor or 1) then value = value - 1 else value = value + 1 end
			end
			return value
		end
		handle.centred = centred

		-- Applies the layout for the current mode. Called on open, on a mode change,
		-- and when the on-screen keyboard appears.
		function handle.layout(reason)
			local geometry = responsive.geometry()
			local mode = responsive.mode
			local viewport = responsive.viewport
			local topInset = responsive.inset.Y
			local keyboard = responsive.bottomObstruction()
			-- The ScreenGui does not ignore the top inset, so the height the window is
			-- centred inside is the viewport minus it.
			local availableY = viewport.Y - topInset

			if mode == "sheet" then
				local available = viewport.Y - topInset - keyboard - theme.space.sm
				local height = math.min(geometry.height, math.max(available, 220))
				root.AnchorPoint = Vector2.new(0.5, 1)
				-- Width is the full measure less a fixed inset on both sides, so the space
				-- around it is that inset doubled -- even by construction.
				root.Size = UDim2.new(1, -theme.space.sm * 2, 0, math.floor(height))
				root.Position = UDim2.new(0.5, 0, 1, -(keyboard + theme.space.sm))
			elseif mode == "panel" then
				local placed = config.get("ui.mobilePanel.placed", false)
				local maxPanelWidth = math.max(minWidth, viewport.X - theme.space.sm * 2)
				local maxPanelHeight = math.max(240, viewport.Y - topInset - keyboard - theme.space.sm * 2)
				local defaultWidth = math.min(geometry.width, maxPanelWidth)
				local defaultHeight = math.min(math.max(geometry.height - keyboard, 240), maxPanelHeight)
				local width = defaultWidth
				local height = defaultHeight
				if placed then
					width = util.clamp(config.get("ui.mobilePanel.width", defaultWidth), minWidth, maxPanelWidth)
					height = util.clamp(config.get("ui.mobilePanel.height", defaultHeight), 240, maxPanelHeight)
				end
				root.AnchorPoint = Vector2.new(0, 0)
				root.Size = UDim2.fromOffset(math.floor(width), math.floor(height))
				if placed then
					local defaultX = viewport.X - width - theme.space.sm
					local defaultY = topInset + theme.space.sm
					root.Position = UDim2.fromOffset(
						math.floor(config.get("ui.mobilePanel.x", defaultX)),
						math.floor(config.get("ui.mobilePanel.y", defaultY)))
					handle.clampIntoView()
				else
					root.Position = UDim2.fromOffset(
						math.floor(viewport.X - width - theme.space.sm),
						math.floor(topInset + theme.space.sm))
				end
			elseif mode == "tv" then
				root.AnchorPoint = Vector2.new(0.5, 0.5)
				root.Size = UDim2.fromOffset(
					centred(viewport.X, geometry.width, minWidth),
					centred(availableY, geometry.height, minHeight))
				root.Position = UDim2.fromScale(0.5, 0.5)
			elseif handle.maximised then
				root.AnchorPoint = Vector2.new(0.5, 0)
				root.Size = UDim2.new(1, -theme.space.md * 2, 1, -(topInset + theme.space.md * 2 + keyboard))
				root.Position = UDim2.new(0.5, 0, 0, topInset + theme.space.md)
			else
				local width = util.clamp(config.get("ui.window.width", 0), 0, viewport.X - theme.space.md * 2)
				local height = util.clamp(config.get("ui.window.height", 0), 0, viewport.Y - theme.space.md * 2)
				if width < minWidth then width = geometry.width end
				if height < minHeight then height = geometry.height end
				root.AnchorPoint = Vector2.new(0.5, 0.5)
				root.Size = UDim2.fromOffset(
					centred(viewport.X, width, minWidth),
					centred(availableY, height, minHeight))
				if config.get("ui.window.placed", false) then
					root.Position = UDim2.new(0.5, config.get("ui.window.x", 0), 0.5, config.get("ui.window.y", 0))
					handle.clampIntoView()
				else
					root.Position = UDim2.fromScale(0.5, 0.5)
				end
			end

			if handle.onLayout then pcall(handle.onLayout, mode, reason) end
		end

		-- Keeps at least a corner of the window reachable after a viewport change,
		-- so a window dragged to the edge of a large screen does not become
		-- unreachable on a small one.
		function handle.clampIntoView()
			local viewport = responsive.viewport
			local size = root.AbsoluteSize
			if responsive.mode == "panel" then
				local keyboard = responsive.bottomObstruction()
				local topInset = responsive.inset.Y
				local minX = theme.space.xs
				local maxX = math.max(minX, viewport.X - size.X - theme.space.xs)
				local minY = topInset + theme.space.xs
				local maxY = math.max(minY, viewport.Y - keyboard - size.Y - theme.space.xs)
				root.Position = UDim2.fromOffset(
					math.floor(util.clamp(root.Position.X.Offset, minX, maxX)),
					math.floor(util.clamp(root.Position.Y.Offset, minY, maxY)))
				return
			end
			if responsive.mode ~= "window" then return end
			local keep = math.min(56, size.X, size.Y)
			local halfX = size.X * 0.5
			local halfY = size.Y * 0.5
			local maxX = viewport.X * 0.5 - keep + halfX
			local minX = -(viewport.X * 0.5) + keep - halfX
			local maxY = viewport.Y * 0.5 - keep + halfY
			local minY = -(viewport.Y * 0.5) + halfY
			root.Position = UDim2.new(
				0.5, math.floor(util.clamp(root.Position.X.Offset, math.min(minX, maxX), math.max(minX, maxX))),
				0.5, math.floor(util.clamp(root.Position.Y.Offset, math.min(minY, maxY), math.max(minY, maxY))))
		end

		-- Chrome --------------------------------------------------------------

		-- Tall enough for the controls it holds. The window buttons are sized to
		-- max(control, minTarget()), which is 44 on a touch device, so a header fixed at
		-- the 42px token clipped two pixels off every one of them there. Published so
		-- the shell that fills the header uses the same number instead of the token.
		local headerHeight = math.max(theme.size.header, responsive.minTarget() + theme.space.sm)
		handle.headerHeight = headerHeight

		-- The header is a transparent top bar across the active pane that provides
		-- the drag handle and holds window controls.
		handle.header = P.row(root, {
			name = "Header",
			size = UDim2.new(1, 0, 0, headerHeight),
			gap = theme.space.sm,
			padding = { x = theme.space.sm },
			zIndex = theme.z.header,
		})
		handle.header.BackgroundTransparency = 1

		handle.body = P.frame(root, {
			name = "Body",
			size = UDim2.fromScale(1, 1),
			position = UDim2.new(0, 0, 0, 0),
		})

		-- Drag ----------------------------------------------------------------

		-- Bound to the header only. Making the whole surface a drag handle -- which
		-- Frame.Draggable did -- means the transcript cannot be dragged to scroll and
		-- text cannot be swiped to select, because both gestures move the window.
		local dragging, moved, origin, startPosition = false, false, nil, nil

		local function draggableNow()
			return (responsive.mode == "window" or responsive.mode == "panel") and not handle.maximised
		end

		handle.header.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			if not draggableNow() then return end
			dragging, moved = true, false
			origin = input.Position
			startPosition = root.Position
			local connection
			connection = input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
					if connection then connection:Disconnect() end
					if moved then
						handle.snap()
						persistGeometry()
					end
				end
			end)
		end)

		releases[#releases + 1] = dispose.connection(env.uis.InputChanged:Connect(function(input)
			if not dragging or not startPosition then return end
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then return end
			local delta = input.Position - origin
			if math.abs(delta.X) > DRAG_SLOP or math.abs(delta.Y) > DRAG_SLOP then moved = true end
			root.Position = UDim2.new(
				startPosition.X.Scale, math.floor(startPosition.X.Offset + delta.X),
				startPosition.Y.Scale, math.floor(startPosition.Y.Offset + delta.Y))
			handle.clampIntoView()
		end))

		-- Snapping to an edge is what makes a floating window feel placed rather than
		-- dropped. Only the near edge snaps, and only within a small margin.
		function handle.snap()
			if not draggableNow() then return end
			local viewport = responsive.viewport
			local size = root.AbsoluteSize
			if responsive.mode == "panel" then
				local keyboard = responsive.bottomObstruction()
				local topInset = responsive.inset.Y
				local x, y = root.Position.X.Offset, root.Position.Y.Offset
				local leftGap = x
				local rightGap = viewport.X - (x + size.X)
				local topGap = y - topInset
				local bottomGap = (viewport.Y - keyboard) - (y + size.Y)

				if leftGap < SNAP_MARGIN then x = theme.space.sm end
				if rightGap < SNAP_MARGIN then x = viewport.X - size.X - theme.space.sm end
				if topGap < SNAP_MARGIN then y = topInset + theme.space.sm end
				if bottomGap < SNAP_MARGIN then y = viewport.Y - keyboard - size.Y - theme.space.sm end

				env.tween:Create(root, theme.tween("hover"), {
					Position = UDim2.fromOffset(math.floor(x), math.floor(y)),
				}):Play()
				return
			end
			local x, y = root.Position.X.Offset, root.Position.Y.Offset
			local halfViewportX, halfViewportY = viewport.X * 0.5, viewport.Y * 0.5
			local leftGap = (x - size.X * 0.5) + halfViewportX
			local rightGap = halfViewportX - (x + size.X * 0.5)
			local topGap = (y - size.Y * 0.5) + halfViewportY - responsive.inset.Y
			local bottomGap = halfViewportY - (y + size.Y * 0.5)

			if leftGap < SNAP_MARGIN then x = x - leftGap + theme.space.sm end
			if rightGap < SNAP_MARGIN then x = x + rightGap - theme.space.sm end
			if topGap < SNAP_MARGIN then y = y - topGap + theme.space.sm end
			if bottomGap < SNAP_MARGIN then y = y + bottomGap - theme.space.sm end

			env.tween:Create(root, theme.tween("hover"), {
				Position = UDim2.new(0.5, math.floor(x), 0.5, math.floor(y)),
			}):Play()
		end

		-- Resize --------------------------------------------------------------

		local grip = Instance.new("TextButton", root)
		grip.Name = "ResizeGrip"
		grip.Text = ""
		grip.AutoButtonColor = false
		grip.BackgroundTransparency = 1
		grip.AnchorPoint = Vector2.new(1, 1)
		grip.Position = UDim2.fromScale(1, 1)
		local gripSize = responsive.touch and math.max(RESIZE_GRIP, responsive.minTarget()) or RESIZE_GRIP
		grip.Size = UDim2.fromOffset(gripSize, gripSize)
		grip.ZIndex = theme.z.header + 2
		grip.Selectable = false

		local function updateGrip()
			local currentGripSize = responsive.touch and math.max(RESIZE_GRIP, responsive.minTarget()) or RESIZE_GRIP
			grip.Size = UDim2.fromOffset(currentGripSize, currentGripSize)
			grip.Visible = draggableNow()
		end

		for index = 1, 2 do
			local line = P.frame(grip, {
				name = "Grip" .. index,
				size = UDim2.fromOffset(index * 5 + 1, 1),
				anchor = Vector2.new(1, 1),
				position = UDim2.new(1, -4, 1, -(index * 4)),
				bg = theme.color.borderStrong,
				radius = theme.radius.pill,
			})
			line.Rotation = -45
		end

		local resizing, resizeOrigin, startSize = false, nil, nil

		grip.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			if not draggableNow() then return end
			resizing = true
			resizeOrigin = input.Position
			startSize = root.AbsoluteSize
			local connection
			connection = input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					resizing = false
					if connection then connection:Disconnect() end
					persistGeometry()
					if handle.onLayout then pcall(handle.onLayout, responsive.mode, "resize") end
				end
			end)
		end)

		releases[#releases + 1] = dispose.connection(env.uis.InputChanged:Connect(function(input)
			if not resizing or not startSize then return end
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseMovement and kind ~= Enum.UserInputType.Touch then return end
			local delta = input.Position - resizeOrigin
			local viewport = responsive.viewport
			if responsive.mode == "panel" then
				local keyboard = responsive.bottomObstruction()
				local topInset = responsive.inset.Y
				local maxWidth = math.max(minWidth, viewport.X - theme.space.sm * 2)
				local maxHeight = math.max(240, viewport.Y - topInset - keyboard - theme.space.sm * 2)
				root.Size = UDim2.fromOffset(
					math.floor(util.clamp(startSize.X + delta.X, minWidth, maxWidth)),
					math.floor(util.clamp(startSize.Y + delta.Y, 240, maxHeight)))
				handle.clampIntoView()
			else
				-- Through `centred` for the same reason the layout is: the window is centred
				-- while it is being resized, so a width one pixel out of parity puts the
				-- group's texture on a half pixel and softens every glyph in it. Dragging the
				-- grip was the easiest way to land there.
				root.Size = UDim2.fromOffset(
					centred(viewport.X,
						util.clamp(startSize.X + delta.X * 2, minWidth, viewport.X - theme.space.md * 2), minWidth),
					centred(viewport.Y - responsive.inset.Y,
						util.clamp(startSize.Y + delta.Y * 2, minHeight, viewport.Y - theme.space.md * 2), minHeight))
			end
		end))

		function handle.setMaximised(value)
			handle.maximised = value == true
			-- Quiet, like every other geometry write here: this is a record of where
			-- the window is, not a setting anything else derives from, and a noisy
			-- write used to reach the theme's config subscription and rebuild the
			-- entire interface a fifth of a second after the maximise animation.
			config.set("ui.window.maximised", handle.maximised, { quiet = true })
			updateGrip()
			handle.layout("maximise")
		end

		function handle.toggleMaximised()
			handle.setMaximised(not handle.maximised)
		end

		-- Visibility ----------------------------------------------------------

		function handle.show()
			if handle.visible then return end
			handle.visible = true
			handle.layout("show")
			root.Visible = true
			-- Snapped to the goal on completion. An interrupted fade on a CanvasGroup
			-- leaves the whole window part-transparent, and the group is the only thing
			-- between the interface and the game behind it.
			local fade = env.tween:Create(root, theme.tween("enter"), { GroupTransparency = 0 })
			fade.Completed:Connect(function()
				if handle.visible then root.GroupTransparency = 0 end
			end)
			fade:Play()
			if handle.onShow then pcall(handle.onShow) end
		end

		function handle.hide()
			if not handle.visible then return end
			handle.visible = false
			local fade = env.tween:Create(root, theme.tween("exit"), { GroupTransparency = 1 })
			fade.Completed:Connect(function()
				if not handle.visible then root.Visible = false end
			end)
			fade:Play()
			if handle.onHide then pcall(handle.onHide) end
		end

		function handle.toggle()
			if handle.visible then handle.hide() else handle.show() end
		end

		-- Everything this window leaves running outside its own tree, released together.
		function handle.destroy()
			for _, release in ipairs(releases) do pcall(release) end
			releases = {}
			handle.visible = false
			pcall(function() root:Destroy() end)
		end

		-- Re-layout on every viewport change. Continuous changes only move and
		-- resize; a mode change is what asks the contents to rebuild, and that is
		-- signalled separately by responsive.modeChanged.
		releases[#releases + 1] = responsive.changed:connect(function(info)
			if not handle.visible then return end
			updateGrip()
			handle.layout(info and info.reason or "viewport")
		end)

		updateGrip()
		handle.outline = outline
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- bootstrap
-- ==========================================================================
--!globals __UAI_MODULES
-- Bootstrap.
--
-- Everything above this file is a factory of the form `return function(env)`. This
-- is the one chunk that is not: it builds the env, wires the module loader, and
-- mounts the interface. The bundler emits it last, after the module table, so
-- `__UAI_MODULES` is a local in the finished artifact.
--
-- Run it as:
--     loadstring(game:HttpGet("<url>/dist/uai.lua"))()
-- or, when embedding it in a host script, pass a context table:
--     loadstring(...)({ prompt = "You also control X", hooks = { preTool = fn } })

local MODULES = __UAI_MODULES
if type(MODULES) ~= "table" then
	warn("[uai] no module table -- run the bundled dist/uai.lua, not src/init.lua")
	return nil
end

local hostContext = ...

local VERSION = "1.0.0"
local FOLDER = "UAI"

-- An existing instance is toggled rather than duplicated: running the loader twice
-- is the normal way people re-open a script, and two copies would fight over the
-- same config file and stack two interfaces.
local globalTable = (type(getgenv) == "function") and getgenv() or nil
if globalTable and type(globalTable.UAI) == "table" and globalTable.UAI.alive then
	local existing = globalTable.UAI
	if existing.toggle then
		local ok = pcall(existing.toggle)
		if ok then return existing end
	end
end

-- Services are resolved lazily and memoised. GetService is the correct accessor
-- even for Workspace and Players: a game may have renamed the instance, and
-- indexing `game.Workspace` would then miss.
local services = setmetatable({}, {
	__index = function(cache, name)
		local ok, service = pcall(function() return game:GetService(name) end)
		if not ok or not service then return nil end
		cache[name] = service
		return service
	end,
})

local env = {
	info = { name = "UAI", version = VERSION, folder = FOLDER },
	services = services,
	context = (type(hostContext) == "table" and hostContext)
		or (globalTable and type(globalTable.UAI_CONTEXT) == "table" and globalTable.UAI_CONTEXT)
		or {},
}

env.hs = services.HttpService
env.uis = services.UserInputService
env.tween = services.TweenService
env.run = services.RunService
env.guisvc = services.GuiService
env.players = services.Players
env.plr = env.players and env.players.LocalPlayer or nil

-- The loader. Cycles are an error rather than a hang: a module that is already
-- loading has been reached again, and returning a half-built table would fail
-- somewhere far away from the cause.
local loaded, loading = {}, {}

-- How many modules this artifact carries, counted rather than written down: the
-- bundler decides it, and a literal here would go stale on the next build. It is the
-- only denominator available to the boot indicator, and it is deliberately *not*
-- treated as a target -- a normal boot loads about four fifths of it and never
-- reaches the rest, because a panel's module is loaded the first time that panel is
-- opened.
env.moduleTotal = 0
for _ in pairs(MODULES) do env.moduleTotal = env.moduleTotal + 1 end
env.moduleCount = 0

function env.require(id)
	local cached = loaded[id]
	if cached ~= nil then return cached end
	if loading[id] then
		error("[uai] circular require: " .. tostring(id), 2)
	end
	local factory = MODULES[id]
	if type(factory) ~= "function" then
		error("[uai] no module '" .. tostring(id) .. "'", 2)
	end
	loading[id] = true
	local ok, result = pcall(factory, env)
	loading[id] = nil
	if not ok then
		error("[uai] module '" .. tostring(id) .. "' failed to load: " .. tostring(result), 2)
	end
	if result == nil then
		error("[uai] module '" .. tostring(id) .. "' returned nothing", 2)
	end
	loaded[id] = result
	env.moduleCount = env.moduleCount + 1
	-- The one hook in the loader, and it exists for the boot indicator: the count is
	-- real work finishing, which is the only progress this client can honestly report
	-- before the interface is up. pcall because a watcher must never be able to stop a
	-- module from loading.
	if env.onModuleLoaded then pcall(env.onModuleLoaded, id, env.moduleCount, env.moduleTotal) end
	return result
end

env.loadedModules = loaded

-- Startup order matters in exactly one place: config has to be read before
-- anything derives from it, because the theme and the provider list are both
-- built from stored values.
local function start()
	local caps = env.require("runtime/caps")
	local log = env.require("runtime/log")
	local config = env.require("runtime/config")

	config.load()
	log.mirror = config.get("logs.mirror", false) == true
	log.info("boot", string.format("UAI %s starting -- %s", VERSION, caps.summary()))

	-- The boot indicator, mounted before the work it reports rather than after.
	--
	-- After config, because the theme it draws with is built from stored values, and
	-- before everything else: the tool registry, the session restore, the stats seed
	-- and the interface itself are the seconds this is covering. It is only a pcall
	-- deep because a client that cannot draw it must still boot -- a progress bar is
	-- not worth failing a start over.
	local boot
	pcall(function()
		boot = env.require("ui/boot").show()
		env.onModuleLoaded = function(id, count, total) boot.step(id, count, total) end
	end)

	-- Asked for early and answered in the background: the place name is what the
	-- conversation list groups by, and it is a web call.
	env.require("runtime/place").resolve()

	env.require("agent/hooks").adoptContext()
	env.require("agent/registry").load()

	local sessions = env.require("agent/session")
	sessions.restore()

	-- After the restore, because the first run recovers the real message history out
	-- of whatever transcripts are already on disk, and before the interface, because
	-- the home card reads it as soon as it builds.
	env.require("agent/stats").init()

	local app = env.require("ui/app")
	app.mount()
	app.show(config.get("ui.panel", "chat"))

	-- The interface is up, so the indicator has nothing left to report. The count is
	-- what it closes on: the rest of the artifact is the panels nobody has opened yet.
	env.onModuleLoaded = nil
	if boot then
		pcall(boot.done, string.format("%d of %d modules loaded -- the rest load with the panel that needs them",
			env.moduleCount, env.moduleTotal))
	end

	-- After the interface, because the bridge attaches to whichever thread is
	-- active and the interface is what establishes that on a fresh install. A
	-- no-op unless the setting has been turned on.
	local bridge = env.require("net/bridge")
	local bridgeOk, bridgeWhy = bridge.sync()
	if not bridgeOk and bridgeWhy then log.warn("bridge", "not started", bridgeWhy) end

	-- The handle a host script (or the user, from a console) can drive.
	-- Declared before it is populated: `local handle = { ... }` does not put `handle`
	-- in scope inside its own initialiser, so every closure below that reaches for
	-- `handle` would have captured a nil global instead. `destroy` did exactly that,
	-- which is why unloading raised rather than unloading.
	local handle
	handle = {
		alive = true,
		version = VERSION,
		env = env,
		app = app,
		sessions = sessions,
		config = config,
		log = log,
		caps = caps,
		bridge = bridge,
		providers = env.require("provider/registry"),
		tools = env.require("agent/registry"),
		toggle = function() app.toggle() end,
		show = function(panel) app.show(panel) end,
		hide = function() app.hide() end,
		ask = function(text)
			local session = sessions.current()
			return session.send(text)
		end,
		-- The kill switch. Destroying the ScreenGui is not unloading: timers keep
		-- ticking, input handlers keep firing on the service, and a config write
		-- would rebuild an interface that is no longer on screen. Everything that
		-- outlives the instance tree registers a cleanup in runtime/dispose, and
		-- this is what drains it.
		--
		--     getgenv().UAI.destroy()
		destroy = function()
			if not handle.alive then return 0 end
			handle.alive = false
			-- Every turn in flight is stopped, not just the one on screen: conversations
			-- run on their own threads and more than one can be working, so aborting the
			-- active session alone left the others to finish into a transcript that had
			-- already been destroyed.
			for _, session in ipairs(sessions.list()) do
				pcall(session.abort)
			end
			-- Anything delegated is stopped with them. A subagent outlives the step that
			-- dispatched it by design, and its budget is measured in minutes.
			pcall(function() env.require("agent/subagent").stopAll() end)
			local ran, failed = env.require("runtime/dispose").drain()
			pcall(function() app.screen:Destroy() end)
			pcall(function() config.saveNow() end)
			if globalTable then globalTable.UAI = nil end
			log.info("boot", string.format("unloaded -- %d cleanups run", ran or 0))
			for _, problem in ipairs(failed or {}) do
				log.warn("boot", "cleanup failed", problem)
			end
			return ran
		end,
		unload = function() return handle.destroy() end,
	}

	if globalTable then globalTable.UAI = handle end
	log.info("boot", "ready")
	return handle
end

local ok, result = pcall(start)
if not ok then
	warn("[uai] failed to start: " .. tostring(result))
	-- A visible failure beats a silent one: the log module may not even have
	-- loaded, so this goes to the console directly.
	--
	-- And on screen too, where the indicator already is: a boot that dies at module
	-- forty leaves a bar stopped at forty and no explanation, which is worse than
	-- never having drawn one. Both the flag and the notice are cleared here, so a
	-- half-loaded client leaves nothing of itself behind.
	env.onModuleLoaded = nil
	pcall(function() env.require("ui/boot").fail(result) end)
	return nil
end
return result
